/** /thimble's description and argument hint (the command.describe hook). */
export const THIMBLE_DESCRIPTION =
  "Opens thimble's panel in this terminal. `/thimble browser` opens the browser workbench; `coverage`, `citations`, `checks`, `threads`, `labels`, `cite <n>`, `card <n>`, `files <path[:line]>` and `documents` open those."
export const THIMBLE_ARGS = '[browser | coverage | citations | checks | threads | labels | cite <n> | card <n> | files <path[:line]> | documents]'
/** What `/thimble` says (the model reads it too; logged in PROMPT-CHANGES.md): thimble is on, its panel is open, and how
 *  to reach the browser workbench. */
export const HOME_LINE = 'thimble is on in this folder. Its panel is open in the terminal; /thimble browser opens the browser workbench.'
/** The /thimble arguments the skill answers (fresh, restore, status, fix, feedback): the mod passes them on. */
const SKILL_ARGS = new Set(['fresh', 'restore', 'status', 'fix', 'feedback'])

// the text Claude Code stores as the reply of a turn that ended with none (its `<synthetic>` model's)
const SYNTHETIC_RE = /^\s*No response requested\.\s*$/
const THIMBLE_TOOL = /^mcp__(plugin_thimble_thimble|thimble-[a-z-]+)__/ // main's shim's tools, and an agent's own shim's
// what Claude Code's row of a thimble event's wake-up says: the waker hook's rewakeSummary (plugin/hooks/hooks.json)
const REWAKE_SUMMARY = 'thimble'
// a message of another agent's as main reads it (a subagent's hand-back)
const AGENT_MESSAGE = /<agent-message from="([^"]+)"/
// a check's agent type, which names the sender of its hand-back's row (a check's Agent call gives it no name)
const CHECK_TYPE = 'thimble:check'
/** What main reads beside the report of a check it started with run_check (bug hunt I7). */
export const CHECK_REPORT = 'This is the report of the check you started with run_check. Tell the analyst in one line what it found.'
// how long a check's dropped hand-back waits for its run's record (checkDone)
const CHECK_READ_MS = 5000
const CARD_TOOL = /^mcp__plugin_thimble_thimble__(add_card|edit_card|apply_label)$/
const DELETE_TOOL = /^mcp__plugin_thimble_thimble__(delete_card|delete_cell)$/
const VIEW_TOOL = /^mcp__plugin_thimble_thimble__propose_view$/

/** Why a check's hand-back is dropped, which Claude Code shows in its row for the drop: what the check did, by the record of
 *  the run its agent ran (`thimble state checks`): `Judgment calls added 2 comments`, `Judgment calls found nothing to
 *  flag`, or `Judgment calls finished` when the record cannot be read in time. */
async function checkDone(cx: Ctx, agentId: string, name: string): Promise<string> {
  const got = rt.sc ? await bounded(cx, readState(cx, rt.sc, 'checks'), CHECK_READ_MS) : null
  const runs = got?.ok && Array.isArray(got.value) ? got.value.flatMap(c => Object.values((c as { runs?: object } | null)?.runs ?? {})) : []
  const n = (runs.find(r => (r as { agent_id?: unknown } | null)?.agent_id === agentId) as { comments?: unknown } | undefined)?.comments
  if (typeof n !== 'number') return `${name} finished`
  return n === 0 ? `${name} found nothing to flag` : `${name} added ${n} comment${n === 1 ? '' : 's'}`
}

/** The text of a tool's result as the transcript holds it: a string, or content blocks. */
function resultText(output: unknown): string {
  if (typeof output === 'string') return output
  const blocks = Array.isArray(output) ? output : (output as { content?: unknown } | undefined)?.content
  return Array.isArray(blocks) ? blocks.map(b => (b && typeof b === 'object' && 'text' in b ? String((b as { text: unknown }).text) : '')).join('\n') : ''
}
const paneTurns = turns()

// the state values this file reads and writes itself (types/index.d.ts; ctx.ts cxOf has the rest): a module names a
// value by literals in the file that reads it
const TURN_CARDS = { plugin: 'thimble', key: 'turnCards' } as const
const THREAD_ROWS = { plugin: 'thimble', key: 'threadRows' } as const
const ANSWERS = { plugin: 'thimble', key: 'answers' } as const
const VIEW_ROWS = { plugin: 'thimble', key: 'viewRows' } as const
const panelA = { plugin: 'thimble', key: 'panel' } as const
const pendingRef = { plugin: 'thimble', key: 'pending' } as const
const panelTickRef = { plugin: 'thimble', key: 'panelTick' } as const
const panelTickA = atom(panelTickRef, 0)

/** `/thimble <what>`, a keyboard way to what the chat and the panel draw: `browser` (the browser workbench; `open`
 *  too), `coverage`,
 *  `citations`, `checks`, `threads`, `labels`, `cite [n]` (the n-th citation of the last reply), `card [n|id]` (the n-th card of
 *  the last turn, or a card by its id), `files <path[:line]>`, `documents`. What it says, or null for plain `/thimble`
 *  (home). */
async function thimbleCommand(cx: Ctx, args: string): Promise<string | null> {
  const [what = '', ...rest] = args.trim().split(/\s+/)
  const arg = rest.join(' ')
  const plural = (n: number, w: string) => `${n.toLocaleString('en-US')} ${w}${n === 1 ? '' : 's'}`
  switch (what.toLowerCase()) {
    case '':
      return null
    case 'browser':
    case 'open': {
      // what happened, in plain words: where no browser opens (SSH, no display), what to run and how to get the link
      // (bug hunt F11)
      const how = await openInBrowser(cx, 'home')
      const links = await cx.links()
      if ((how === 'remote' || how === 'again') && links) return remoteReply(links, classicScreen())
      if (how === 'failed') return "thimble: thimble's page did not open: the notice above the prompt says why and how to fix it"
      if (how === 'shown') return "thimble: thimble's page is already open in a tab of your browser"
      return "thimble: opening thimble's page in the browser"
    }
    case 'coverage':
      await openCoverage(cx, arg || undefined)
      return 'thimble: the Coverage view is open'
    case 'citations':
      await openCitations(cx)
      return 'thimble: the Citations view is open'
    case 'checks':
      await openChecks(cx)
      return 'thimble: the Checks view is open'
    case 'threads': {
      await openPanel(cx, { view: 'threads', title: 'Threads' })
      return `thimble: ${plural((await cx.threads()).length, 'side thread')}`
    }
    case 'labels': {
      // the thimble line's `labels` by keys, for a screen that takes no clicks (bug hunt F1)
      await openSection(cx, 'labels')
      const got = await surfaceValue(cx, 'labels')
      return `thimble: ${plural(got?.ok ? labelsOf(got.value).length : 0, 'label')}`
    }
    case 'documents':
    case 'docs':
    case 'reports': {
      await readSurface(cx, 'docs', 'docs')
      const got = await surfaceValue(cx, 'docs')
      await openPanel(cx, { view: 'docs', title: 'Documents' })
      return `thimble: ${plural(got?.ok ? docsOf(got.value).length : 0, 'document')}`
    }
    case 'cite': {
      const cs = citations(rt.lastReply)
      const n = Number(arg)
      if (!cs.length) return 'thimble: the last reply cites nothing'
      if (!Number.isInteger(n) || n < 1 || n > cs.length) return `thimble: the last reply has ${plural(cs.length, 'citation')}: \`/thimble cite <1-${cs.length}>\` opens one`
      const c = cs[n - 1]!
      await openCite(cx, c.ref, c.display)
      return `thimble: citation ${n} of ${cs.length}`
    }
    case 'card': {
      const ids = rt.lastCards
      const n = Number(arg)
      if (arg && !Number.isInteger(n)) {
        const id = arg.replace(/^(?:card|cell):/, '')
        await loadCards(cx, [id])
        if (!(await cx.card(id))?.data) return 'thimble: no such card in this workspace'
        await openCard(cx, id)
        return 'thimble: the card is open'
      }
      if (!ids.length) return 'thimble: the last turn made no card'
      if (!Number.isInteger(n) || n < 1 || n > ids.length) return `thimble: the last turn has ${plural(ids.length, 'card')}: \`/thimble card <1-${ids.length}>\` opens one`
      await openCard(cx, ids[n - 1]!)
      return `thimble: card ${n} of ${ids.length}`
    }
    case 'files': {
      // the terminal has no file browser (Matt, 10-16): Coverage lists the files; a path opens its lines at a place
      if (!arg) {
        await openCoverage(cx)
        return 'thimble: Coverage lists the files; `/thimble files <path[:line]>` opens one at a line'
      }
      const m = /^(.*?)(?::(\d+))?$/.exec(arg)
      const path = (m?.[1] ?? arg).replace(/^\.\//, '')
      const line = m?.[2] ? Number(m[2]) : undefined
      await openFile(cx, path, line ? Math.max(1, line - 5) : 1, line)
      return `thimble: ${path}${line ? ` line ${line}` : ''} is open`
    }
    default:
      return `thimble: \`/thimble\` opens home; \`/thimble browser\` opens the browser; \`coverage\`, \`citations\`, \`checks\`, \`threads\`, \`labels\`, \`cite [n]\`, \`card [n]\`, \`files <path[:line]>\` and \`documents\` open those`
  }
}

// a text block as Claude Code was handed it while it streamed -> as the model wrote it
const asWritten = new Map<string, string>()

/** The part of a turn that is its answer: the last that cites or embeds a card, else the last with text. Earlier parts
 *  are what main wrote while it worked ("Reading the files…"). */
function answerPart(parts: { uuid: string; text: string }[][]): { uuid: string; text: string }[] | undefined {
  const full = parts.filter(p => p.some(r => r.text.trim()))
  return [...full].reverse().find(p => needsDrawing(p.map(r => r.text).join('\n\n'))) ?? full.at(-1)
}

function hasText(content: unknown): boolean {
  return Array.isArray(content) && content.some(b => b && typeof b === 'object' && (b as { type?: unknown }).type === 'text' && String((b as { text?: unknown }).text ?? '').trim() !== '')
}

/** The rows a side thread's answer leaves under a row of main's chat (signal.ts, SPEC.md "Main's chat"), one
 *  blank row above the first: `↳` at column 0 and its words at 2, dim (`thread · "<the turn's question>" · answered`,
 *  `failed` in red), `new` in green until it is read; a press on the question opens the thread. Each turn once. */
async function signalRows(cx: Ctx, e: ResolveInput & { requestId: string; viewport?: { columns: number } }): Promise<RenderElement | null> {
  const rows = await cx.threadRows(e.requestId)
  if (!rows.length) return null
  const { Box, Text, Button } = cx.els(e)
  const threads = await cx.threads()
  const seen = new Set<string>()
  const out: RenderElement[] = []
  const n = Math.max(16, Math.min(60, (e.viewport?.columns ?? 100) - 30))
  for (const s of rows) {
    const k = `${s.thread}:${s.turn}`
    if (seen.has(k)) continue
    seen.add(k)
    const row = threads.find(x => x.id === s.thread)
    const tt = await cx.thread(s.thread)
    const th = tt?.events.length ? threadOf(tt.meta, tt.events) : null
    const label = row?.anchorText || (row?.anchor ? await anchorName(cx, row.anchor) : '') || row?.title || 'the side thread'
    const q = th ? signalQuestion({ turns: th.turns, label }, s.turn, n) : quoted(clip(row?.question || row?.title || label, n))
    const end = th ? signalEnd(th, s.turn) ?? 'answered' : 'answered'
    // `new` while the thread holds an answer the analyst has not opened (thimble's `unread`), on its latest answer's row
    const latest = th ? th.turns.map((x, i) => (x.state === 'done' ? i + 1 : 0)).reduce((a, b) => Math.max(a, b), 0) : s.turn
    const fresh = Boolean(row?.unread) && s.turn >= latest
    out.push(
      <Box key={`signal-${k}`} flexDirection="row" {...(out.length ? {} : { marginTop: 1 })}>
        <Text dimColor>{'↳ '}</Text>
        <Text dimColor>{'thread · '}</Text>
        <Button key={`signal-open-${s.thread}`} label={q} plain dimColor onPress={() => openThread(cx, s.thread)} />
        {end === 'failed' ? <Text color={COLORS.problem}>{' · failed'}</Text> : <Text dimColor>{' · answered'}</Text>}
        {fresh && end !== 'failed' ? <Text color={COLORS.fresh}>{' · new'}</Text> : null}
      </Box>,
    )
  }
  return <Box flexDirection="column">{out}</Box>
}

/** What a thread's anchor names, in words: a card by its question, a citation's place in words. */
async function anchorName(cx: Ctx, anchor: string): Promise<string> {
  const id = /^(?:card|cell):([A-Za-z0-9_-]+)/.exec(anchor)?.[1]
  if (id) {
    const q = ((await cx.card(id))?.data as CardData | null | undefined)?.question
    return q ? cardWords(q) : 'a card'
  }
  return anchor
}

/** An Agent call's stored result with a thread's fork named by the thread's first question where its `prompt` or
 *  `description` names the fork's slug (`thread:<slug>`, what ctrl+o shows under `Prompt:`); the result itself when it
 *  names none. */
function forkOutput(output: unknown, threads: Parameters<typeof namedForks>[1]): unknown {
  if (!output || typeof output !== 'object' || Array.isArray(output)) return output
  const o = output as Record<string, unknown>
  const named = (v: unknown) => (typeof v === 'string' && /\bthread:/.test(v) ? namedForks(v, threads) : v)
  const prompt = named(o.prompt)
  const description = named(o.description)
  return prompt === o.prompt && description === o.description ? output : { ...o, prompt, description }
}

/** A Bash command that runs `thimble-run`, as its row shows it (model.ts runShown), the cards it names by their
 *  questions as read. */
async function runWords(cx: Ctx, command: string): Promise<string> {
  const questions = new Map<string, string>()
  for (const id of runIds(command)) {
    const q = ((await cx.card(id))?.data as CardData | null | undefined)?.question
    if (q) questions.set(id, q)
  }
  return runShown(command, id => questions.get(id))
}

/** The `↳ view` rows under a row of main's chat (SPEC.md, "Main's chat"): a view main proposed, `↳` dim at 0,
 *  `view · <name> · building|built|proposed` dim, `failed` in red, then `new` in green once built and not yet opened;
 *  a press on its name opens its line in the panel. */
async function viewRowsEl(cx: Ctx, e: ResolveInput & { requestId: string }): Promise<RenderElement | null> {
  const slugs = await cx.viewRows(e.requestId)
  if (!slugs.length) return null
  const { Box, Text, Button } = cx.els(e)
  const views = await homeViews(cx)
  const out: RenderElement[] = []
  for (const slug of [...new Set(slugs)]) {
    const v = views.find(x => x.slug === slug)
    const state = v?.state ?? 'proposed'
    out.push(
      <Box key={`view-row-${slug}`} flexDirection="row" {...(out.length ? {} : { marginTop: 1 })}>
        <Text dimColor>{'↳ view · '}</Text>
        <Button key={`view-open-${slug}`} label={v?.name ?? slug} plain dimColor onPress={() => openView(cx, slug, v?.name ?? slug)} />
        {state === 'failed' ? <Text color={COLORS.problem}>{' · failed'}</Text> : <Text dimColor>{` · ${state === 'built' ? 'built' : state === 'building' ? 'building' : 'proposed'}`}</Text>}
        {v?.fresh ? <Text color={COLORS.fresh}>{' · new'}</Text> : null}
      </Box>,
    )
  }
  return <Box flexDirection="column">{out}</Box>
}

/** The footer under a turn's answer (SPEC.md, "Main's chat"; MATT-NOTES "Classic display: no new row"), one blank row
 *  under it at column 2: `N citations · N cards` dim, ` · ◌ checking N` dim while checks run on its citations, then
 *  ` · N failed` in red for the ones that failed for good (none when 0; a press opens the panel's Citations view), then
 *  `ask about this answer ›`. The citations are those drawn in the answer, its words' and its cards' takeaways', a chip
 *  too, counted as the thimble line and the Citations view count them (citesview.tsx answerItems). The facts are cut
 *  first; the counts stay whole. */
async function footerEl(cx: Ctx, e: ResolveInput & { requestId: string }): Promise<RenderElement | null> {
  const ans = await cx.answer(e.requestId)
  if (!ans) return null
  const { Box, Text, Button } = cx.els(e)
  const cards = liveCards(ans.cards)
  const counts = citeCounts(await answerItems(cx, ans.text, cards))
  // "Citation marks" off: nothing checks them
  const marks = featureOn('citationMarks')
  const checking = marks ? counts.pending : 0
  const failed = marks ? counts.bad : 0
  const num = (n: number) => n.toLocaleString('en-US')
  const plural = (n: number, w: string) => `${num(n)} ${w}${n === 1 ? '' : 's'}`
  const facts = [...(counts.all ? [plural(counts.all, 'citation')] : []), ...(cards.length ? [plural(cards.length, 'card')] : [])].join(' · ')
  return (
    <Box key={`footer-${e.requestId}`} marginTop={1} marginLeft={MARGIN} flexDirection="row" columnGap={2}>
      <Box flexShrink={1} flexDirection="row">
        <Box flexShrink={1}>
          <Text dimColor wrap="truncate-end">{facts}</Text>
        </Box>
        {checking ? (
          <Box flexShrink={0}>
            <Text dimColor>{` · ${SPIN} checking ${num(checking)}`}</Text>
          </Box>
        ) : null}
        {failed ? (
          <Box flexShrink={0} flexDirection="row">
            <Text dimColor>{' · '}</Text>
            <Button key={`failed-${e.requestId}`} plain onPress={() => openCitations(cx)}>
              <Text color={COLORS.problem}>{`${num(failed)} failed`}</Text>
            </Button>
          </Box>
        ) : null}
      </Box>
      <Box flexShrink={0}>
        <Button key={`ask-answer-${e.requestId}`} label="ask about this answer ›" plain onPress={() => openAsk(cx, { kind: 'sentence', text: withoutNotes(ans.text).slice(0, 6000), label: 'this answer' }, { element: ANSWER_ELEMENT })} />
      </Box>
    </Box>
  )
}

/** The line under the row that says a writer's end (main's `↳ The writer finished …`, the first row that says it): the
 *  document it wrote, a press away in the browser workbench, where it is read whole, edited, and its figures and history
 *  shown; the terminal reads documents only (Matt, 10-16). The writer's document by its name (`writer: <slug>`), else
 *  the one written last, as the documents were read when the writer ended (band.tsx noteWriters); its slug alone when
 *  they were not read. None while the writer writes, or after it failed or stopped. */
async function writtenEl(cx: Ctx, e: ResolveInput & { requestId: string }, text: string): Promise<RenderElement | null> {
  if (!saysWriter(text)) return null
  const chat = rt.writerOf.get(e.requestId)
  const agents = (await cx.agents()) ?? []
  const agent = chat ? agents.find(a => a.chat === chat) : agents.filter(a => a.role === 'writer').sort((a, b) => a.started.localeCompare(b.started)).at(-1)
  if (agent?.state === 'running' || /fail|error|stop/i.test(agent?.state ?? '')) return null
  // drawing reads only: the documents as read when the writer ended
  const got = await surfaceValue(cx, 'docs')
  const docs = got?.ok ? docsOf(got.value) : []
  const named = (agent?.label ?? '').replace(/^writer:\s*/i, '').trim()
  const written = docs.filter(d => d.status !== 'generating' && d.status !== 'error')
  const doc = (named ? written.find(d => d.slug === named || d.title === named) : undefined) ?? written.sort((a, b) => (Date.parse(b.at) || 0) - (Date.parse(a.at) || 0))[0] ?? (named && /^[\w-]+$/.test(named) && !got ? { slug: named, title: named } : undefined)
  if (!doc) return null
  const { Box, Text, Button } = cx.els(e)
  return (
    <Box key={`written-${e.requestId}`} marginLeft={MARGIN} marginTop={1} flexDirection="row">
      {/* the label never shrinks: a narrow column wraps the link, not `document` (bug hunt 0.9.0, B13) */}
      <Box flexShrink={0}>
        <Text dimColor>{'↳ document '}</Text>
      </Box>
      <Box flexShrink={1}>
        <Button key={`written-open-${e.requestId}`} label={`${quoted(clip(clean(doc.title), 60))} · read and edit it in the browser ↗`} plain onPress={() => void openInBrowser(cx, `report:${doc.slug}`)} />
      </Box>
    </Box>
  )
}

/** A row of main's chat without its `↳ The writer …` line when an earlier row said that writer run's end (the run: the
 *  writer whose chat began last when the row was first drawn, kept with the row so a resumed session decides the same). */
async function withoutSaidWriter(cx: Ctx, row: string, text: string): Promise<string> {
  if (!row || !saysWriter(text)) return text
  let chat = rt.writerOf.get(row)
  if (!chat) {
    // the writer that began last: its chat's start, the newest
    const latest = (await cx.agents()).filter(a => a.role === 'writer' && a.chat).sort((a, b) => a.started.localeCompare(b.started)).at(-1)
    if (!latest) return text
    chat = latest.chat
    rt.writerOf.set(row, chat)
    if (!rt.writerSaid.has(chat)) rt.writerSaid.set(chat, row)
    if (rt.sc) await keepRow(cx, rt.sc.ws, row, { writer: { chat, first: rt.writerSaid.get(chat) === row } })
  }
  return rt.writerSaid.get(chat) === row || !rt.writerSaid.has(chat) ? text : withoutWriterLines(text)
}

/** A prompt of main's: when it reports on a subagent run (model.ts reportOf), one of the reports main answers next, and
 *  whether it is the run's second report after a first that main answered with a `↳` line. Reports that come before
 *  main's next text row are answered together, also when another prompt comes between: a task notification that comes
 *  right after main answered the run's hand-back may start no turn of its own, and main then answers it atop its reply
 *  to the analyst's next prompt (live check on 0.7.0). */
function heard(text: string): void {
  const r = reportOf(text)
  if (!r) return
  rt.answering ??= { reports: [] }
  const first = rt.reports.get(r.agent)
  let again = false
  if (first && first.kind !== r.kind && !first.paired) {
    first.paired = true
    again = first.said
  } else rt.reports.set(r.agent, { kind: r.kind, said: false, paired: false })
  rt.answering.reports.push({ agent: r.agent, again })
}

/** Main's first text row after reports, which answers them: which of its `↳` lines are said and which repeat a run's
 *  end said already (live QA on 0.7.0: `↳ The view builder finished` once for its hand-back and again for Claude Code's
 *  task notification, which the browser's chat hides). For one report its lines answer it; for several, main writes a
 *  line for each in their order, so where the row has one line per report each line answers its report; where that is
 *  unclear, no line is hidden. Later rows answer something else, such as a fork that returned. */
async function noteAnswer(cx: Ctx, row: string, text: string): Promise<void> {
  const a = rt.answering
  if (!a) return
  rt.answering = null
  const lines = noteLines(text)
  const one = a.reports.length === 1
  const mapped = !one && lines.length === a.reports.length
  if (!lines.length) return
  a.reports.forEach(r => {
    const first = rt.reports.get(r.agent)
    if (!r.again && (one || mapped) && first && !first.paired) first.said = true
  })
  const hide = one ? (a.reports[0]!.again ? lines : []) : mapped ? lines.filter((_, i) => a.reports[i]!.again) : []
  if (!hide.length) return
  rt.repeats.set(row, [...new Set([...(rt.repeats.get(row) ?? []), ...hide])])
  if (rt.sc) await keepRow(cx, rt.sc.ws, row, { repeat: rt.repeats.get(row)! })
}

/** A row of main's chat with what thimble-term draws under it: the turn's cards (when no reply row carries them) and
 *  the side threads' rows. */
async function underRow(cx: Ctx, drawn: ResolveInput & { requestId: string; viewport?: { columns: number } }, next: () => Promise<RenderElement>): Promise<RenderElement> {
  const e = storedAs(drawn)
  const ids = liveCards(await cx.turnCards(e.requestId))
  const told = await signalRows(cx, e)
  const views = await viewRowsEl(cx, e)
  if (!ids.length && !told && !views) return next()
  const { Box } = cx.els(e)
  const cards = await drawCards(cx, e, ids, (e.viewport?.columns ?? 100) - 2, t => openAsk(cx, t), id => openThread(cx, id))
  return (
    <Box flexDirection="column">
      {await next()}
      {cards}
      {told}
      {views}
    </Box>
  )
}

/** A drawing's event with the uuid of the stored row it stands for as its `requestId` (term.ts rowAs). */
function storedAs<T extends { requestId: string }>(e: T): T {
  const row = rowAs(e.requestId)
  return row === e.requestId ? e : { ...e, requestId: row }
}

/** The text a stored row holds: its text blocks, and a tool result's text. */
function rowText(message: { content?: unknown } | undefined): string {
  const blocks = Array.isArray(message?.content) ? (message.content as { type?: unknown; text?: unknown; content?: unknown }[]) : []
  return blocks.map(b => (typeof b?.text === 'string' ? b.text : b?.type === 'tool_result' ? resultText(b.content) : '')).join('\n')
}

/** Whether a classic (main screen) answer tints late comments (LC9): Claude Code reprinted the whole transcript when a
 *  row taller than the screen changed, so a tall answer keeps no tint on the main screen and its comments show in the
 *  panel and the summary line only. */
const TALL_TINT_CLASSIC = false

/** The open comments of the checks on this row (`requestId`), each located in the text drawn; none with "Checks" off,
 *  and none on the main screen for an answer taller than the screen (TALL_TINT_CLASSIC). */
async function commentsFor(cx: Ctx, e: ResolveInput & { requestId: string; viewport?: { columns?: number; rows?: number; isFullscreen?: boolean } }, text: string, cols: number, cards: number): Promise<AnswerComment[]> {
  if (!featureOn('checks') || !text.trim()) return []
  const mine = (await cx.answerComments()).filter(c => c.row === e.requestId && c.status === 'open')
  if (!mine.length) return []
  if (!TALL_TINT_CLASSIC && e.viewport && e.viewport.isFullscreen === false && answerRows(text, cols) + cards * 12 > (e.viewport.rows ?? Infinity)) return []
  return mine
}

/** About how many rows a reply's text takes at `cols` columns. */
function answerRows(text: string, cols: number): number {
  return text.split('\n').reduce((n, l) => n + Math.max(1, Math.ceil(lineWidth([{ s: l }]) / Math.max(10, cols))), 0)
}

/** The chat citations of an answer kept for the panel's Citations view, by their row (C13 citeIndex), the newest 2000. */
async function indexCitations(cx: Ctx, text: string, row: string): Promise<void> {
  if (!row) return
  const at = await cx.now()
  const have = await cx.citeIndex()
  const known = new Set(have.map(r => `${r.id}|${r.row}`))
  const add: CiteRow[] = citations(text)
    .filter(c => !labelRef(c.ref))
    .map(c => ({ id: cid(c.raw), raw: c.raw, display: c.display, ref: c.ref, row, at }))
    .filter(r => !known.has(`${r.id}|${r.row}`))
  if (add.length) await cx.setCiteIndex([...have, ...add].slice(-2000))
}

export const register: Register = (on, options) => {
  // the /config values of the seven switches (settings.ts): a /config change reloads the module with new ones; a flip of
  // labels or checks changes the guide, which is then owed if thimble says so
  setOptions(options)
  onFlip.run = (before, after) => {
    if (before && (before.labels !== after.labels || before.checks !== after.checks) && act.owed === false) act.owed = null
  }
  // a click on an empty part of a list hands the keys back to the pane (term.ts takeKeys)
  onListClick(takeKeys)
  on('session.start', { cwd: /^/ }, async ($, e, next) => {
    const started = await next(e)
    const cx = cxOf($)
    // a fresh session, or a fresh copy of the module: nothing on, nothing held
    resetActivation(e)
    resetSettings()
    resetTracker()
    rt.sc = null
    rt.timers = false
    rt.turn = null
    // when this conversation began: its first launch, so a thread asked before a `--continue` is not an earlier one's
    rt.startedAt = await $.session
      .usage()
      .then(u => u.startedAt)
      .catch(() => $.clock.now())
      .catch(() => Date.now())
    // the `thimble` command's start (THIMBLE_OPEN), `thimble -c` included
    const launched = (await cx.env('THIMBLE_OPEN').catch(() => undefined)) === '1'
    // the session's values outlive a module reload but not the process: none yet is a new `claude` process
    const reloaded = (await cx.activated()) !== null
    // a module reload (a /config change) or a resumed session where thimble is on: restored quietly from the
    // session's marker, with no push and the guide only if it is owed
    if (await restoreFromMarker(cx)) {
      // a pane that waited undrawn before the module loaded again (its state is the session's)
      rt.waiting = (await cx.pending()) !== null
      // `thimble -c` opens the browser on home as `thimble` does, which starts the server and moves the continued
      // session to it (bug hunt H8); a module reload in the same process opens nothing again
      if (launched && !reloaded) await openInBrowser(cx, 'home')
      return started
    }
    // the `thimble` command: thimble on at once, and the browser opened on home. Neither start calls load_thimble, which
    // Claude Code would ask about in Manual mode before the person typed anything (bug hunt F3): the first prompt
    // carries the guide
    if (launched) {
      const turned = await activateNow(cx, 'launcher', false)
      if (turned.ok) await openInBrowser(cx, 'home')
      return started
    }
    // as a regular Claude Code plugin: on from the start of every interactive session where the plugin is enabled
    // (the owner, 10-16 22:45); a folder thimble refuses (the home folder, `/`) stays off without a notice. Beside a
    // live main it is a peer (`start` takes no main): only an explicit /thimble, `thimble` or a press does (bug hunt 7,
    // H13: a second plain `claude` in the folder took main, though the browser kept following the first)
    if (act.interactive && act.surface === 'terminal') {
      act.refusedSaid = true
      await activateNow(cx, 'start', false)
      act.refusedSaid = false
    }
    return started
  })

  // /thimble: thimble on in this folder (a refused folder is asked again: the person asked) and this session thimble's
  // main, in place of another session in the folder that is main (takeMain: bug hunt 7, H14, the refusal says "type
  // /thimble in this terminal to take it back"), then the home panel or the view its argument names, with no model turn;
  // the guide goes with its answer when it is owed. The skill's own arguments (fresh, restore, status, fix, feedback)
  // go to the skill.
  on('command.run', async ($, e, next) => {
    if (e.command !== 'thimble:thimble' && e.command !== 'thimble') return next(e)
    const args = String(e.args ?? '').trim()
    if (SKILL_ARGS.has((args.split(/\s+/)[0] ?? '').toLowerCase())) return next(e)
    const cx = cxOf($)
    if (e.presentation?.columns > 0) rt.termColumns = e.presentation.columns
    noteScreen(undefined, e.presentation?.isFullscreen)
    const wasOn = isActive()
    if (!wasOn) {
      const turned = await activateNow(cx, 'command')
      if (!turned.ok) return { text: `thimble: ${turned.error ?? 'thimble could not turn on in this folder'}` }
    }
    await followConversation(cx)
    if (wasOn) await takeMain(cx)
    await navOrigin(cx, false)
    const said = await thimbleCommand(cx, args)
    // the guide goes into main's conversation as a hidden row now: a command's `context` did not reach the model in
    // 2.1.301, so a /thimble before the first question left main with no guidance and its answers cited nothing
    const guide = await owedGuide(cx)
    if (guide) await appendGuide(cx, guide)
    if (said !== null) return { text: said }
    await openHome(cx)
    return { text: HOME_LINE }
  })
  // /thimble as the typeahead and /help describe it once thimble is on: what it does here
  on('command.describe', async ($, e, next) => {
    if (!rt.sc || (e.command !== 'thimble:thimble' && e.command !== 'thimble')) return next(e)
    return next({ ...e, description: THIMBLE_DESCRIPTION })
  })

  // the feature switches: a person's /config change of a thimble row reaches thimble's config at once (settings.ts),
  // from `e.value` (this fires before the write, while `options` holds the old value); before thimble is on it waits
  // for the sync at activation. A theme change repaints the cards in that theme's palette and the passages' tints.
  on('config.set', { key: /^thimble\.|^theme$/ }, async ($, e, next) => {
    if (e.key === 'theme') {
      const r = await next(e)
      if (!r.deny) setTheme(await cxOf($).theme(r.value))
      return r
    }
    if (e.origin.kind === 'composer' && isActive()) await pushChange(cxOf($), e.key, e.value)
    return next(e)
  })

  // a prompt carries thimble's guide when it is owed (after /clear, a switch that changed it, a resumed session).
  // The hand-back of a check thimble's module started never reaches main: thimble shows its comments as the passage's
  // tint and flag (SPEC-v2 J7). thimble's hand-back hook (plugin/bin/.thimble-watch --handback) takes the report of a
  // check's or a model call's agent that thimble's module started and refuses the call, so it never enters main's queue
  // and Claude Code prints no row. One that still arrives (the hook failed) is dropped here, as it enters, since Claude
  // Code queues a hand-back for main with no session.receive: the reason says what the check did (the owner, 10-17), or
  // for a model call's agent, whose answer went to thimble through its tools, the line the server gave its start
  // (`thimble checked the card "…"`, backend/app/agent_call.py). Claude Code's task notification of such an agent is
  // dropped the same way (ownNotice): it too is queued with no session.receive (enqueueAgentNotification), and a check's
  // notice that it waits on its own background work, or ended with no report, is about thimble's plumbing (bug hunt
  // E10); .thimble-watch --foreground keeps a check from starting such work, so none is sent. A check that main's own
  // Agent call started (run_check, typedCheck) reports to main as main's other subagents do, and main answers its
  // report in one line: dropped, its row read `Prompt dropped by a hook: …` in a warning's color, and main, told only
  // by Claude Code's notice that the report had reached it, made up what the check found (bug hunt I7)
  on('prompt.submit', async ($, e, next) => {
    const from = e.origin.kind === 'peer' ? AGENT_MESSAGE.exec(e.text)?.[1] : e.origin.kind === 'task-notification' ? ownNotice(e.text) : undefined
    const done = from === undefined ? undefined : callDone(from)
    if (done !== undefined) return { drop: done }
    const check = from === undefined || typedCheck(from) ? undefined : checkName(from)
    if (from !== undefined && check !== undefined) return { drop: await checkDone(cxOf($), from, check) }
    // the report of a check main started with run_check, which main answers in one line (backend/app/checks.py)
    const sent = from !== undefined && e.origin.kind === 'peer' && typedCheck(from) ? { ...e, context: [...(e.context ?? []), CHECK_REPORT] } : e
    if (!isActive()) return next(sent)
    const cx = cxOf($)
    await followConversation(cx)
    // a delivery still in flight when the person sends the next prompt never reached the conversation: owe it again
    if (act.pending) deliveryLost()
    const guide = await owedGuide(cx)
    if (!guide) return next(sent)
    deliverStarts(guide)
    const r = await next({ ...sent, context: [...(sent.context ?? []), guide] })
    if (r.drop !== undefined) deliveryLost()
    return r
  }).catch(($, e, next) => next(e))

  // after a compaction of main's conversation: the guide appended whole as a hidden row, once the compaction is in
  on('session.compact', async ($, e, next) => {
    const r = await next(e)
    if (!isActive() || e.agentId !== undefined || r.skip !== undefined) return r
    const cx = cxOf($)
    cx.later(0, () => void guideAfterCompact(cx).catch(err => cx.log(`thimble: the guide was not given again after the compaction: ${String(err).slice(0, 200)}`)))
    return r
  })

  // /clear and /resume end this conversation (no session.start follows): the next call of the new one rekeys thimble,
  // and after /clear its next prompt carries the guide
  on('session.end', { reason: /^/ }, async ($, e, next) => {
    conversationEnded(e.sessionId, e.reason)
    return next(e)
  })

  // whether the prompt box holds text: when that changes the panel is drawn again, so its hint row says how to give it
  // the keys (panel.tsx DRAFT_HINT)
  const noteDraft = (cx: ReturnType<typeof cxOf>, text: string) => {
    const held = Boolean(text.trim())
    if (held === rt.draftHeld) return
    rt.draftHeld = held
    void cx.bumpPanel().catch(() => undefined)
  }
  on('prompt.change', async ($, e, next) => {
    if (rt.sc) noteDraft(cxOf($), String(e.text ?? ''))
    return next(e)
  })

  // a citation typed or pasted into the prompt is painted there as the reply's are, purple and underlined
  on('prompt.edit', async ($, e, next) => {
    const r = await next(e)
    if (!rt.sc) return r
    noteDraft(cxOf($), String(r.text ?? ''))
    const d = citeSpans(r.text).map(sp => ({ start: sp.at, end: sp.end, underline: true, color: COLORS.cite }))
    return d.length ? { ...r, decorations: [...(r.decorations ?? []), ...d] } : r
  })

  // ---------------------------------------------------------------------------------------------- main's turn

  // main's turn only: a subagent's turn (a check, an orientation's helper) starting meanwhile would start main's over and
  // lose the cards made before it (README capture 10-17: a card made before four checks started was never drawn)
  on('turn.start', { turnId: /^/ }, async ($, e, next) => {
    if (rt.sc && e.agentId === undefined) {
      const own = rt.own.has(e.text)
      rt.own.delete(e.text)
      rt.turn = { id: e.turnId, at: new Date(await $.clock.now()).toISOString(), cards: [], row: '', parts: [[]], views: [], own }
    }
    return next(e)
  })

  // thimble on at the first data-file read, and what Claude's calls read of the data files (activate.ts, tracker.ts).
  // Registered with `.catch` replaying `next`: a hook that throws or outruns its budget still leaves the call's own
  // result, and the call never runs twice.
  on('tool.call', { tool: /^(?:Read|Bash|Grep|Glob|mcp__plugin_thimble_thimble__load_thimble)$/ }, async ($, e, next) => {
    const tool = String(e.tool)
    const input = e as unknown as Record<string, unknown>
    if (tool.endsWith(`__${LOAD_TOOL}`)) {
      const res = await next(e)
      if (res.deny === undefined && !res.isError) await sawLoadThimble(cxOf($), String(res.text ?? ''))
      return res
    }
    if (isActive()) {
      const res = await next(e)
      const cx = cxOf($)
      if (featureOn('coverage')) keepFacts(await factsOf(cx, await preScope(cx), { tool, input, ...(e.agentId !== undefined ? { agentId: e.agentId } : {}), result: res.result, ...(res.text !== undefined ? { text: res.text } : {}), ...(res.deny !== undefined ? { deny: res.deny } : {}), ...(res.isError ? { isError: true } : {}) }))
      if (e.agentId !== undefined || res.deny !== undefined) return res
      await followConversation(cx)
      const guide = await owedGuide(cx)
      if (!guide) return res
      deliverStarts(guide)
      return { ...res, context: [...(res.context ?? []), guide] } as typeof res
    }
    // thimble off in this session (a folder it refuses, a headless run, or the plugin turned off): a call passes as it
    // is; reading data never turns thimble on (the owner, 10-16 22:45: a regular plugin, on from the session's start)
    return next(e)
  }).catch(($, e, next) => next(e))

  // main's fork of a side thread runs with the thread's question as its description, which Claude Code's agent tray and
  // its exit dialog show beside the fork's name (never `thread:<slug>`); the prompt keeps `thread:<name>`, by which
  // thimble knows the fork (backend threads.fork_ref)
  on('tool.call', { tool: /^/ }, async ($, e, next) => {
    let call = e
    try {
      if (rt.sc && e.agentId === undefined && e.tool === 'Agent') {
        const input = e as unknown as Record<string, unknown>
        const rows = await cxOf($).threads()
        const description = forkDescription(input, rows) ?? (input.subagent_type === 'fork' ? forkDescription(input, await threadsNow(cxOf($))) : null)
        if (description) call = { ...e, description } as typeof e
      }
    } catch {
      // the call runs as main wrote it
    }
    const ran = await next(call)
    try {
      if (!rt.sc || e.agentId !== undefined || ran.deny !== undefined) return ran
      // a card main deleted is no card of the turn's, and no answer draws or counts it (bug hunt C16: one made and
      // deleted in the same turn drew `× card 1 cannot be drawn` and counted in the footer)
      if (DELETE_TOOL.test(String(e.tool)) && !ran.isError) {
        const input = e as unknown as Record<string, unknown>
        const id = String(input.card ?? input.cell ?? '').trim().replace(/^(?:card|cell):/, '')
        if (id) cardDeleted(id)
      }
      const ids = cardsOfCall(String(e.tool), e, String(ran.text ?? ''))
      if (ids.length) {
        for (const id of ids) {
          cardMade(id)
          rt.mainCards.add(id)
        }
        if (rt.turn) for (const id of ids) if (!rt.turn.cards.includes(id)) rt.turn.cards.push(id)
        void loadCards(cxOf($), ids)
      }
      // a view main proposed: its `↳ view` row under the turn's answer
      if (VIEW_TOOL.test(String(e.tool)) && rt.turn) {
        const name = String((e as { name?: unknown }).name ?? '')
        const slug = /\bview:([a-z0-9][a-z0-9-]*)/.exec(String(ran.text ?? ''))?.[1] ?? name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')
        if (slug && !rt.turn.views.includes(slug)) rt.turn.views.push(slug)
      }
    } catch {
      // the call's answer stands whatever thimble-term makes of it
    }
    return ran
  })

  // main's reply as it streams: each citation handed to Claude Code as a Markdown link (never its raw spelling) and a
  // card's line as a placeholder naming the card; a citation, code span or card line not yet closed waits. The row is
  // stored as the model wrote it (session.append), and drawn by AssistantMessage once it is whole.
  on('turn.step', { turnId: /^/ }, async function* ($, e, next) {
    if (!rt.sc || e.agentId !== undefined) return yield* next(e)
    const cx = cxOf($)
    const blocks = new Map<number, Streaming>()
    const urls = new Map<string, string>()
    const questions = new Map<string, string>()
    const look: StreamLook = {
      link: c => streamLink(c, urls.get(c.ref) ?? ''),
      card: id => `◌ ${(questions.get(id) || 'drawing the card').replace(/[\\[\]*_`<>]/g, m => `\\${m}`)}`,
    }
    const end = (i: number, st: Streaming) => {
      const out = streamStep(st, '', true, look)
      if (st.shown !== st.raw) {
        asWritten.set(st.shown, st.raw)
        if (asWritten.size > 50) asWritten.delete(asWritten.keys().next().value!)
      }
      return out ? [{ kind: 'text' as const, index: i, text: out }] : []
    }
    for await (const ch of next(e)) {
      if (ch.kind === 'text') {
        const st = blocks.get(ch.index) ?? streaming()
        blocks.set(ch.index, st)
        const ahead = `${st.raw.slice(st.done)}${ch.text}`
        try {
          const cs = citations(ahead)
          // each citation checked as soon as it has streamed whole (the next 250 ms batch), not when its block is drawn,
          // so most checks end while the answer is still on screen; main's own, so a failed one is told to main
          queueCitations(cs, '')
          for (const c of cs) if (!urls.has(c.ref)) urls.set(c.ref, await placeUrl(cx, c.ref))
          for (const m of ahead.matchAll(/\[\[card:([A-Za-z0-9_-]+)\]\]/g)) if (!questions.has(m[1]!)) questions.set(m[1]!, ((await cx.card(m[1]!))?.data as CardData | null | undefined)?.question ?? '')
        } catch {
          // a link without its file still hides the raw spelling
        }
        const out = streamStep(st, ch.text, false, look)
        if (out === ch.text) yield ch
        else if (out) yield { ...ch, text: out }
        continue
      }
      // a block ends before anything else of the response passes: what it held back is handed over
      for (const [i, st] of blocks) yield* end(i, st)
      blocks.clear()
      yield ch
    }
    for (const [i, st] of blocks) yield* end(i, st)
  })

  // the rows of main's chat a drawing stands under, by the uuid they are stored under (their `requestId`): the
  // latest row a line can stand under, and the turn's latest text row; each text row of the turn in its part (a tool
  // call starts the next part), for the turn's answer. A block of main's reply is stored as the model wrote it, not as
  // it showed while it streamed.
  on('session.append', async ($, e, next) => {
    let msg = e.message
    try {
      if (rt.sc && e.agentId === undefined) {
        if (msg.type === 'user' && (e.door === 'prompt' || e.door === 'delivery')) heard(resultText(msg.content))
        if (e.door === 'response' && Array.isArray(msg.content)) {
          const shown = msg.content as { type?: string; text?: string }[]
          const blocks = shown.map(b => (b.type === 'text' && typeof b.text === 'string' && asWritten.has(b.text) ? { ...b, text: asWritten.get(b.text)! } : b))
          if (blocks.some((b, i) => b !== shown[i])) msg = { ...msg, content: blocks as typeof msg.content }
          const texts = blocks.flatMap(b => (b.type === 'text' && typeof b.text === 'string' && b.text.trim() ? [b.text] : []))
          if (rt.turn) {
            if (texts.length) rt.turn.parts.at(-1)!.push({ uuid: e.uuid, text: texts.join('\n\n') })
            if (blocks.some(b => b.type === 'tool_use')) rt.turn.parts.push([])
          }
          if (rt.answering && texts.length) await noteAnswer(cxOf($), e.uuid, texts.join('\n'))
          // the cards a reply embeds, read so they draw
          const embeds = texts.flatMap(t => embeddedCards(t))
          if (embeds.length) void loadCards(cxOf($), embeds)
        }
        if (isAnchor({ ...e, message: msg } as unknown as AppendedRow)) rt.anchor = e.uuid
        if (e.door === 'response' && rt.turn && hasText(msg.content)) rt.turn.row = e.uuid
      }
    } catch {
      // the row is stored whatever the terminal UI makes of it
    }
    const stored = await next(msg === e.message ? e : { ...e, message: msg })
    // the row's uuid and its blocks, by which a drawing's id finds the row again (term.ts rowAs)
    const kept = stored.message ?? msg
    if (e.agentId === undefined && stored.uuid && (kept.type === 'user' || kept.type === 'assistant')) rowSeen(stored.uuid, Array.isArray(kept.content) ? kept.content.length : 1)
    // the guide a delivery sent is marked sent once the row that carries it is stored in main's conversation
    if (act.pending && e.agentId === undefined && stored.deny === undefined) await rowStored(cxOf($), { text: rowText(stored.message ?? msg) })
    return stored
  }).catch(($, e, next) => next(e))

  on('turn.complete', { turnId: /^/ }, async ($, e, next) => {
    const done = await next(e)
    let lineRow = ''
    if (rt.sc && e.agentId === undefined && rt.turn) {
      const t = rt.turn
      rt.turn = null
      const row = t.row || rt.anchor
      const cx = cxOf($)
      lineRow = row
      if (t.cards.length && row) {
        const cur = await cx.turnCards(row)
        await cx.setTurnCards(row, [...cur, ...t.cards.filter(id => !cur.includes(id))])
      }
      // what `/thimble cite` and `/thimble card` open: the turn's citations and cards
      const all = t.parts.flat().map(r => r.text).join('\n\n')
      if (all.trim()) rt.lastReply = all
      if (all.trim() || t.cards.length) rt.lastCards = [...new Set([...embeddedCards(all), ...t.cards])]
      if ((all.trim() || t.cards.length) && rt.sc) await keepLast(cx, rt.sc.ws, rt.lastReply, rt.lastCards)
      // the answer: its last part that cites or embeds a card, else its last; the footer stands under its last row
      const part = answerPart(t.parts)
      const last = part?.at(-1)?.uuid ?? ''
      if (part && last && !t.own) {
        const text = part.map(r => r.text).join('\n\n')
        const shows = [...new Set([...embeddedCards(text), ...(last === row ? t.cards : [])])]
        if (citations(text).length || shows.length) await cx.setAnswer(last, { rows: part.map(r => r.uuid), text, cards: shows })
      }
      // the views this turn proposed: their rows under the answer
      const vrow = last || row
      if (t.views.length && vrow) {
        const cur = await cx.viewRows(vrow)
        await cx.setViewRows(vrow, [...cur, ...t.views.filter(v => !cur.includes(v))])
        for (const v of t.views) rt.viewsTold.add(v)
      }
      lineRow = vrow
      // the chat citations the answer drew, for the panel's Citations view (C13 citeIndex)
      if (featureOn('citationMarks') && all.trim() && !t.own) await indexCitations(cx, all, last || row)
      // the failed checks of main's citations found while the turn ran, told to main for its next reply
      await tellFailed(cx)
    }
    // what the turn's calls saw of the data, sent once: the session's summary, which the thimble line's coverage and the
    // Coverage view read (no line under the answer: coverage lives in the thimble line, the owner's live test, 10-17)
    if (isActive() && e.agentId === undefined && featureOn('coverage') && factsHeld()) {
      const cx = cxOf($)
      const summary = await flushFacts(cx, await cx.sessionId(), lineRow || rt.anchor)
      if (summary) await cx.setCoverageSummary(summary)
    }
    return done
  })

  // ---------------------------------------------------------------------------------------------- main's chat

  on('ui.render', { component: 'AssistantMessage' }, async ($, drawn, next) => {
    if (!rt.sc) return next(drawn)
    const cx = cxOf($)
    // the drawing by the stored row it stands for, whose uuid what it carries is kept under (rowAs); `drawn` for the rest
    const e = storedAs(drawn)
    const ids = liveCards(await cx.turnCards(e.requestId))
    const told = await signalRows(cx, e)
    const views = await viewRowsEl(cx, e)
    const footer = await footerEl(cx, e)
    // without main's end token, and a `↳ thread` line naming its thread by its first question, not its fork's slug; no
    // such line for a thread whose `↳ thread` row the terminal UI drew, which says the same
    const rows = await cx.threads()
    // Claude Code's own stand-in for a reply that never came (its `<synthetic>` text, as after a quit stopped a thread),
    // which main never wrote: not drawn (live check term-fix9, quirk 13)
    const said = SYNTHETIC_RE.test(e.props.text) ? '' : e.props.text
    // and none of main's `↳` lines that answer a subagent run's second report, whose first an earlier row answered
    const repeats = rt.repeats.get(e.requestId)
    const text = await withoutSaidWriter(cx, e.requestId, namedThreads(withoutToldThreads(withoutEnd(repeats ? withoutLines(said, repeats) : said), rows, rt.told), rows))
    // the document a writer finished, linked out to the browser workbench under the row that says so
    const written = await writtenEl(cx, e, text)
    const live = e.surface === 'terminal' || e.surface === 'desktop'
    if (!ids.length && !told && !views && !footer && !written && text === e.props.text && !live && !needsDrawing(text)) return next(drawn)
    const { Box } = $.ui.resolve(drawn)
    // the reply fills the terminal's width, less 2, its cards as wide as its prose
    const cols = (e.viewport?.columns ?? 100) - 2
    // the checks' comments on this row's passages: each passage tinted in its check's color, a flag in the margin
    const checked = await commentsFor(cx, e, text, cols - MARGIN, ids.length)
    // a sentence that cites a card whole keeps its chip (`[ card ]`) though the card is drawn under the reply
    const body = text.trim() ? await drawReply(cx, e, text, cols - MARGIN, { first: Boolean(e.props.isFirstOfReply), skipCards: new Set(ids), ask: t => openAsk(cx, t), open: id => openThread(cx, id), ...(checked.length ? { comments: checked, lit: await cx.checksOpen(), check: id => openChecks(cx, id) } : {}) }) : []
    const cards = await drawCards(cx, e, ids, cols, t => openAsk(cx, t), id => openThread(cx, id))
    // a block that held only a line the terminal UI hides: nothing (ctrl+o's view still draws the reply's time and model
    // above it, which no hook reaches; the engine's own block with no text draws the same)
    if (!body.length && !cards && !told && !views && !footer && !written) return <Box />
    // one blank row above, as above Claude Code's own reply rows: the engine's row carries that margin itself, and this
    // tree takes the row's place, so without it the reply sits right under the person's message
    return (
      <Box flexDirection="column" marginTop={1}>
        {body}
        {written}
        {cards}
        {footer}
        {told}
        {views}
      </Box>
    )
  })

  on('ui.render', { component: 'UserMessage', props: { origin: { kind: 'composer' } } }, async ($, e, next) => (rt.sc ? underRow(cxOf($), e, () => next(e)) : next(e)))
  on('ui.render', { component: 'TurnDuration' }, async ($, e, next) => (rt.sc ? underRow(cxOf($), e, () => next(e)) : next(e)))
  // /thimble's line as thimble says it, not under the plugin's name, which Claude Code puts before a hook's answer
  on('ui.render', { component: 'CommandOutput' }, async ($, e, next) => {
    if (!rt.sc) return next(e)
    // `/thimble …` answers as thimble, not under the plugin's name, which Claude Code puts before a hook's answer
    const own = (e.props.command === 'thimble:thimble' || e.props.command === 'thimble') && /^\s*thimble:\s*thimble\b/.test(e.props.text)
    const shown = own ? { ...e, props: { ...e.props, text: e.props.text.replace(/^\s*thimble:\s*(?=thimble\b)/, '') } } : e
    return underRow(cxOf($), e, () => next(shown))
  })

  // a thimble tool's row, and a card's run in Bash, name the card by its question, never by its id, and a citation by
  // its words (in the row and in ctrl+o's detailed view); a side thread's fork is named by the thread's first question,
  // never its slug
  on('ui.render', { component: 'ToolUse' }, async ($, e, next) => {
    if (!rt.sc) return next(e)
    const cx = cxOf($)
    const tool = String(e.props.tool)
    const input = e.props.input as Record<string, unknown> | undefined
    if (!input || typeof input !== 'object') return next(e)
    if (THIMBLE_TOOL.test(tool)) {
      let changed = false
      const out: Record<string, unknown> = {}
      for (const [k, v] of Object.entries(input)) {
        const s = typeof v === 'string' ? await toolWords(cx, k, v) : v
        if (s !== v) changed = true
        out[k] = s
      }
      return changed ? next({ ...e, props: { ...e.props, input: out } }) : next(e)
    }
    if (tool === 'Bash' && typeof input.command === 'string' && /thimble-run\b/.test(input.command)) {
      return next({ ...e, props: { ...e.props, input: { ...input, command: await runWords(cx, input.command) } } })
    }
    if (tool === 'Agent' || tool === 'Task') {
      // a fork's description and its prompt (ctrl+o's `Prompt:`) name the thread by its first question, never its slug
      const threads = await cx.threads()
      const named = (v: unknown) => (typeof v === 'string' && /\bthread:/.test(v) ? namedForks(v, threads) : v)
      const description = named(input.description)
      const prompt = named(input.prompt)
      const output = forkOutput(e.props.output, threads)
      if (description !== input.description || prompt !== input.prompt || output !== e.props.output) return next({ ...e, props: { ...e.props, input: { ...input, description, prompt }, ...(output !== undefined ? { output } : {}) } })
    }
    return next(e)
  })

  // the hand-back of a check main started with run_check is no row: main's `↳` line under it says what the check found,
  // and thimble shows its comments (bug hunt I7); ctrl+o's full view still draws it. Only a check main started hands
  // back to main (the others' hand-backs are taken or dropped, above), so its type names it
  on('ui.render', { component: 'UserMessage', props: { origin: { kind: 'peer' } } }, async ($, e, next) => {
    if (!rt.sc || e.props.isExpanded || e.props.from?.name !== CHECK_TYPE) return next(e)
    const { Box } = $.ui.resolve(e)
    return <Box />
  })

  // the row saying a side thread's fork finished names the thread by its first question, never the fork's slug. A
  // thimble event's wake-up (.thimble-watch's asyncRewake, summary `thimble`, no task) is no row: a bare `● thimble`
  // says nothing, and what came in shows in the line the held hook prints with the turn (`› ` the analyst's words; bug
  // hunt B5) or in the chat's own rows; ctrl+o's full view still draws it
  on('ui.render', { component: 'UserMessage', props: { origin: { kind: 'task-notification' } } }, async ($, e, next) => {
    // nor is Claude Code's notice that points at the hand-back of one of thimble's agents, kept as the bridge's note
    // (thimble.ts ownPointer, bug hunt I6)
    if (rt.sc && !e.props.isExpanded && e.props.text.includes(POINTER_NOTE)) {
      const { Box } = $.ui.resolve(e)
      return <Box />
    }
    if (rt.sc && e.props.text.trim() === REWAKE_SUMMARY && !e.props.task && !e.props.isExpanded) {
      const { Box } = $.ui.resolve(e)
      return <Box />
    }
    if (!rt.sc || !/\bthread:/.test(e.props.text)) return next(e)
    const text = namedForks(e.props.text, await cxOf($).threads())
    return text === e.props.text ? next(e) : next({ ...e, props: { ...e.props, text } })
  })

  // a card tool's result row: the card by its question, since the card itself is drawn under the turn's last reply; a
  // label's, its name and each value's count. An error stays Claude Code's row.
  on('ui.render', { component: 'ToolResult' }, async ($, e, next) => {
    if (!rt.sc || e.props.isErrored) return next(e)
    // a fork's result (`Backgrounded agent`, and in ctrl+o its `Prompt:`) names the thread by its first question
    if (e.props.tool === 'Agent' || e.props.tool === 'Task') {
      const output = forkOutput(e.props.output, await cxOf($).threads())
      return output === e.props.output ? next(e) : next({ ...e, props: { ...e.props, output } })
    }
    if (!CARD_TOOL.test(String(e.props.tool))) return next(e)
    const ids = cardsOfCall(String(e.props.tool), {}, resultText(e.props.output))
    const tc = ids[0] ? await cxOf($).card(ids[0]) : undefined
    const data = tc?.data as CardData | null | undefined
    const q = data?.question
    if (!q) return next(e)
    const { Text } = $.ui.resolve(e)
    // the row cut at a word, as every cut, to the terminal's width
    const room = Math.max(20, (e.viewport?.columns ?? 100) - 2)
    if (data.kind === 'label' && data.label) {
      const counts = ((data.rows ?? []) as { label: string; value: number }[]).map(r => `${r.label} ${r.value.toLocaleString('en-US')}`).join(' · ')
      return <Text dimColor wrap="truncate-end">{cut(`  ⎿  label ${quoted(data.label.name)}${counts ? ` · ${counts}` : ''}${tc?.busy ? ` · ${tc.busy}` : ''}`, room)}</Text>
    }
    return <Text dimColor wrap="truncate-end">{cut(`  ⎿  card ${quoted(q)}${tc?.busy ? ` · ${tc.busy}` : ''}`, room)}</Text>
  })

  // ---------------------------------------------------------------------------------------------- above the prompt

  // the rows above the prompt (band.tsx), and the panel's views drawn by modules of their own (views.ts)
  registerBand(on)
  registerPanelViews(on)

  // ---------------------------------------------------------------------------------------------- the panel

  // the panel's drawings run one at a time (turns.ts, two seconds at most each); one that settles after a later one
  // began, or that Claude Code abandoned, draws once more 50 ms after, so the shown panel's buttons and fields work
  const paneDraws = { draws: 0, settled: 0, redrawing: false }
  on('ui.render', { component: 'Pane', requestId: PANEL }, async ($, e, next) => {
    if (!rt.sc) return next(e)
    const pe = e as PaneEvent
    const cx = cxOf($)
    noteScreen(pe.surface, (pe.viewport as { isFullscreen?: unknown } | undefined)?.isFullscreen)
    // a pane that waited undrawn is drawn now (Claude Code placed it once the terminal was wide enough): the row above
    // the prompt that offered it goes
    if (rt.waiting) {
      rt.waiting = false
      $.clock.after(0, () => void placedLater(cx))
    }
    if (pe.surface === 'terminal' && pe.viewport?.columns && (pe.props.placement === 'dock' || pe.props.placement === 'inline')) {
      rt.termColumns = pe.props.placement === 'dock' ? pe.viewport.columns + pe.props.bodyColumns + 1 : pe.viewport.columns
      // a resize keeps the dock at the width it was opened with: it opens again at the panel's width for the terminal
      // now (a width the person dragged still wins)
      if (pe.props.placement === 'dock' && rt.termColumns !== rt.fittedFor && rt.termColumns >= 110) {
        rt.fittedFor = rt.termColumns
        if (panelColumns() !== pe.props.bodyColumns) {
          $.clock.after(0, () => {
            void (async () => {
              const placed = (await cx.panes()).some(p => p.id === PANEL && p.isPlaced)
              const p = await cx.panel()
              if (placed && p) await cx.open({ id: PANEL, title: paneTitle(p), columns: panelColumns() }).catch(() => undefined)
            })()
          })
        }
      }
    }
    return paneTurns.run(async () => {
      const n = ++paneDraws.draws
      await read($, panelTickA)
      const tree = await drawPanel(cx, pe)
      const late = paneDraws.settled > n
      paneDraws.settled = Math.max(paneDraws.settled, n)
      if ((late || next.signal.aborted) && !paneDraws.redrawing) {
        paneDraws.redrawing = true
        $.clock.after(50, () => {
          paneDraws.redrawing = false
          // an aborted drawing draws again only when no drawing began since; drawing again regardless would abort a
          // drawing slower than 50 ms each time, and the panel would never show
          if (late || paneDraws.draws === n) void update($, panelTickA, k => (k ?? 0) + 1)
        })
      }
      return tree
    }, fire => $.clock.after(2000, fire))
  })

  on('ui.close', async ($, e, next) => {
    const closed = await next(e)
    if (e.id === PANEL) {
      rt.panelFocus = ''
      // typing that went to the prompt ends with the pane: opened again, the panel has its keys
      keysBack()
      rt.waiting = false
      await $.state.set(pendingRef, null).catch(() => undefined)
      await $.state.set(panelA, null).catch(() => undefined)
      // a terminal view's program ends with its pane
      closeView()
    }
    return closed
  })

  // the panel's focus ring: while a text field holds it the hint row names Enter and Esc alone (panel.tsx endHints),
  // since a letter goes into the field; off every element, NO_FOCUS (not '', which is a view just opened)
  const NO_FOCUS = '-'
  // A list's keys reach it through the relay's three Buttons (panel.tsx RELAY): a move of the ring from the middle one
  // onto a neighbour (↑, ↓, Tab) is that key for the list, and the ring stays unless the key moved it off the list
  // (relayMoveKey); a move onto a neighbour from elsewhere lands on the middle one. Every move draws the panel again, so its hint row names the keys where the ring is.
  on('ui.focus', { requestId: PANEL }, async ($, e, next) => {
    // the person moving the ring while the panel's typing went to the prompt (panel.tsx typeThrough), or the relay's
    // field taking it as the pane takes the keys from the prompt (a click on the pane): the panel has its keys again
    if (rt.sc && rt.typeThrough && (e.origin.kind === 'person' || rt.typeAway)) keysBack()
    const how = rt.sc ? relayMove(rt.panelFocus, e.element) : ''
    if (how === 'up' || how === 'down') {
      const to = await relayMoveKey(how).catch(() => '')
      // the key moved the ring off the list (↓ past the labels list's last label): the person's move lands there
      if (to) {
        const moved = await next({ ...e, element: to })
        if (!moved.deny) rt.panelFocus = to
        void cxOf($).bumpPanel()
        return moved
      }
      void cxOf($).bumpPanel()
      // a document's comment the key chose, scrolled into view once the panel is drawn again
      scrollPending(cxOf($))
      return {}
    }
    // a ring put back on a text field the panel no longer draws (the new thread's form left by back, live check
    // term-fix9, quirk 1) is on none of its elements: onto the list's keys when it draws a list
    const stale = Boolean(rt.sc && e.element && focusedField(e.element) && !rt.fields.has(e.element))
    const park = how === 'park' || (stale && hasList())
    const moved = await next(park ? { ...e, element: RELAY.pick } : e)
    try {
      if (rt.sc && !moved.deny) {
        rt.panelFocus = park ? RELAY.pick : stale ? NO_FOCUS : (e.element ?? NO_FOCUS)
        void cxOf($).bumpPanel()
      }
    } catch {
      // the ring moves whatever thimble-term makes of it
    }
    return moved
  })

  // the wheel over a list the panel cut to its rows (panel.tsx windowList) moves the list's rows, the choice where it is;
  // over any other panel the pane scrolls
  on('ui.scroll', { requestId: PANEL }, async ($, e, next) => {
    if (!rt.sc || !e.pointer || e.origin.kind !== 'person') return next(e)
    // over a terminal view the wheel is the view's: the list under the pointer moves its rows, so it goes with the
    // frame's cell there
    if (openViewState()?.id && (await cxOf($).panel())?.view === 'view') {
      void sendEvent(cxOf($), { t: 'wheel', by: e.by, ...viewWheelAt(e.pointer) })
      return {}
    }
    if (!wheelWindow(e.by)) return next(e)
    void cxOf($).bumpPanel()
    return {}
  })

  // ---------------------------------------------------------------------------------------------- clicks

  // "ask" beside a selection (para.tsx): its press is the person's own (a press on a card's title is a gesture,
  // card.tsx, which asks a side thread about the card)
  on('ui.press', async ($, e, next) => {
    if (!rt.sc) return next(e)
    const cx = cxOf($)
    const inPanel = e.component === 'Pane' && e.requestId === PANEL
    // a press on the panel once the prompt had the keys is a click, as no hotkey presses there: the panel has its keys
    // again, and the Button acts rather than typing its letter into the prompt (panel.tsx typedOr)
    if (inPanel && rt.typeThrough && rt.typeAway) keysBack()
    await navOrigin(cx, inPanel)
    // a press on one of the panel's own acts keeps the panel's keys (bug hunt B28; term.ts keepKeys)
    if (inPanel) keepKeys(cx)
    if (e.element === 'sel-ask' && rt.selection) await openAsk(cx, { kind: 'sentence', text: rt.selection.slice(0, 1200) })
    return next(e)
  })

  on('ui.message', async ($, e, next) => {
    if (!rt.sc) return next(e)
    const cx = cxOf($)
    const d = (e.data ?? {}) as Record<string, unknown>
    const inPanel = e.component === 'Pane' && e.requestId === PANEL
    // every post of a Client that uses hooks/gestures.tsx carries its recent gestures; each is handled once
    if (Array.isArray(d.gestures) && typeof d.origin === 'string') {
      const last = rt.seenGestures.get(d.origin) ?? 0
      const fresh = (d.gestures as Sent[]).filter(g => typeof g?.seq === 'number' && g.seq > last)
      if (fresh.length) rt.seenGestures.set(d.origin, Math.max(...fresh.map(g => g.seq)))
      // a click in the panel (a card's mark, a passage's link) keeps the panel's keys, as a press there does
      if (inPanel && fresh.some(g => g.gesture && g.target)) keepKeys(cx)
      for (const g of fresh) {
        if (!g.gesture || !g.target) continue
        // a click on a passage a check commented on: the panel at Checks on that comment (the ref is its id)
        if (g.target.kind === 'check') {
          await openChecks(cx, g.target.ref ?? '')
          continue
        }
        await navOrigin(cx, inPanel)
        try {
          await onGesture(cx, g.gesture, g.target)
        } catch (err) {
          $.ui.log(`thimble-term: the ${g.gesture} gesture failed: ${String(err).slice(0, 200)}`)
        }
      }
    }
    if (d.type === 'home') {
      await navOrigin(cx, inPanel)
      // a click on a part drawn from lines (a link, `↳`, a row) keeps the panel's keys
      if (inPanel) keepKeys(cx)
      await linesMessage(cx, d.horigin, d.hacts)
    } else if (d.type === 'view') {
      // a click or a drag in a terminal view (viewclient.tsx); like a click on a list, it gives the pane its keys back
      await navOrigin(cx, inPanel)
      if (await viewMessage(cx, d)) await takeKeys(cx)
    } else if (d.type === 'copy' && typeof d.text === 'string') {
      const text = d.text.slice(0, 100000)
      rt.selection = text
      const r = await $.ui.copy({ text, surface: e.surface })
      $.ui.toast(r.isCopied ? `copied ${text.length} characters` : `could not copy: ${r.reason}`)
    } else if (d.type === 'label-open' && typeof d.slug === 'string') {
      // a press on a card's label row (its name or its ↗): the label's panel, under its name
      await navOrigin(cx, inPanel)
      if (inPanel) keepKeys(cx)
      const find = async () => {
        const got = await surfaceValue(cx, 'labels')
        return got?.ok ? labelsOf(got.value).find(l => l.id === d.slug || l.name === d.slug) : undefined
      }
      // the labels as last read may be older than the label (home read them before main made it): read them again
      let hit = await find()
      if (!hit) {
        await readSurface(cx, 'labels', 'labels')
        hit = await find()
      }
      if (!hit) cx.toast('that label is no longer in this workspace')
      else await openLabel(cx, hit.id, hit.name ?? hit.id)
    } else if (d.type === 'field' && typeof d.name === 'string' && typeof d.text === 'string') {
      // a field's words (field.tsx): a draft, or a save
      await fieldMessage(cx, d.name, d.text.slice(0, 20000), d.save === true)
    } else if (d.type === 'files-open' && typeof d.path === 'string') {
      await openFile(cx, d.path)
    }
    return next(e)
  })

  // a Client of thimble-term that could not draw (its tree did not validate, its module threw): why goes to the debug
  // log, never to main's chat; the open view's own says so in the panel, dim, in its place (panel.tsx drawView), as
  // the engine draws the panel again once this answers
  on('ui.fault', async ($, e, next) => {
    $.ui.log(`thimble-term: ${e.module} could not draw in ${e.component} (${e.phase}): ${e.reason}`, { to: 'debug' })
    if (e.component === 'Pane' && e.requestId === PANEL && /(^|\/)viewclient\.tsx$/.test(e.module)) viewFault(e.reason)
    return next(e)
  })
}

files.hooks/thimble.ts:
// thimble's hooks module: how a click in thimble's browser starts, messages and stops one of thimble's subagents in
// the analyst's Claude Code session with no turn of main, how a typed start runs on exactly the model and effort its
// request names, and how thimble's model calls run through the session's own API client. The server's side is
// backend/app/module_bridge.py; the tests are thimble.test.ts beside this file.
//
// Scope. It acts only in a session thimble is on in, and checks that before its first fetch or registration:
// `isInteractive` (an open long poll would hold every `claude -p` run open), THIMBLE_NO_MODULE unset, then the session's
// marker, <home>/up/<session>.active, which activation writes (app/activate.py). The terminal UI, which register.ts
// registers after this file in the plugin's one hooks module, tells it of an activation at once (bridgeActivated: right
// after the activation answer, and after a load_thimble call it saw), so thimble's agent types are registered in that
// turn. For an activation made outside the terminal UI (the /thimble skill where the terminal UI does not run, a shell),
// it looks for the marker at session.start and once at the end of each of main's turns. Anywhere else it registers
// nothing and fetches nothing. It starts no process: $.fs and $.http.fetch only.
//
// Transport. The workspace's trusted/launch.json says how the session reaches thimble (app/subagent_files.py
// transport): through the workspace's files until a press of the browser workbench (`transport: local`, below), and
// through thimble's server for the rest of the session once the press made main's transport the server's. A peer (a
// session turned on beside a live main) and a session another took main from always use the files, and as a peer it
// registers the agent types but takes no requests and writes no module.json. It reads launch.json again whenever the
// file changes and at the end of each of main's turns; at the switch it takes the requests still waiting in
// subagents.json, then goes on over HTTP. Over HTTP, once the server asks for its hello again or refuses it, a session
// that launch.json no longer makes main on the server's transport (main continued after a quit, which runs locally; a
// session another took main from) goes on through the files again (toFiles). Over HTTP every request proves the token of
// server.json and every answer proves it back (app/hook_auth.py), so a process on the port can neither hand it requests
// nor read them.
//
// The file guard (tool.call), in every session from session.start, thimble on in it or not: it refuses a call of a file
// tool (Read, Edit, Write, MultiEdit, NotebookEdit, Grep, Glob) on thimble's token files, a call of an edit tool on
// thimble's records or,
// when the analyst turned corpus edits off, on the corpus, and WebFetch and WebSearch when the analyst turned the web
// off, with the reason each rule names. The rules come with the roles (GET /api/module/roles, or roles.json in terminal
// mode: app/userconf.py module_rules); until they come, or when they cannot be fetched, only the token files in
// thimble's home are refused. The path is compared as spelled and as resolved ($.fs.stat with resolve), so a link to a
// token file is refused too; Grep and Glob are refused at thimble's home itself. Bash it leaves to the permission mode,
// except that once thimble is on in the session it refuses a Bash command that names a token file under thimble's home
// literally (BASH_PRIVATE).
//
// What it does once it is on (over HTTP; through the files the same, below):
// - registers thimble's roles and thimble:orient-helper from GET /api/module/roles (each with a full model id and an
//   explicit effort, from Settings); when the server is up at session start this happens inside session.start, so the
//   types are registered before main's first request (agent.offer keeps them out of its listing, below);
// - asks Claude Code's permission decision for a write it never makes every PLAN_POLL_MS and tells the server when main
//   went into plan mode or out of it (POST /api/module/mode), which no event of Claude Code's says while main is idle;
// - holds GET /api/module/next and handles the requests one at a time, in order, so a role's registration and the
//   spawn that needs it are never split by another request: register (all roles again), spawn (register the role with
//   the run's values if they differ, $.agent.spawn with no `model`, then the one-line note the server rendered), send
//   (register if needed, then SendMessage), stop (TaskStop of the agent and of the shells the server names), abort
//   (the analyst's Stop of main: $.turn.abort of main's running turn, by the id its turn.start carried, answered once
//   that turn completed or ABORT_WAIT_MS passed, after a TaskStop of each command of that turn the abort moved to the
//   background, where Esc would have ended it), note ($.session.append). It never starts, sends or stops anything the
//   server did not ask for. A spawn of the call role, the card check's agent (backend/app/agent_call.py), carries
//   `drop`, the reason the terminal UI gives when it drops a hand-back of the agent's that the hand-back hook did not
//   take (callDone; plugin/bin/.thimble-watch --handback), or a task notification of it (ownNotice), and its type is
//   never offered;
// - model calls (backend/app/model_call.py), which run at once, beside that queue, so many run together (BESIDE):
//   complete, one tool-less completion through the session's own API client and sign-in ($.model.complete, with an
//   AbortController that a later cancel aborts), and fork, one tool-less completion over main's own transcript
//   ($.model.fork). Neither is a subagent: no row in main, no tools, no permission asks. Each answers with the reply's
//   text and usage, or why there is none (modelAnswer); a request Claude Code refuses to send is an error. On local
//   transport the request's arguments and the answer are files of their own in the trusted folder (completions/<id>.json
//   and <id>.answer.json), so neither subagents.json nor module.json carries a prompt;
// - agent.offer and tool.call: thimble's types stay out of every model's agent listing, whose line for each spelled its
//   "All tools except …" list, until an agent of the type has started in the session. A type is offered while an Agent
//   call that names it runs, so main's typed starts and the orientation's own starts of its critic and helpers run as
//   before ($.agent.spawn is no offer), and while a SendMessage call runs. Once an agent of a type has started, the
//   type stays offered, since Claude Code checks the offer again when it resumes an agent: the orientation its critic
//   reports to, an agent a SendMessage continues;
// - agent.spawn: an Agent call for one of thimble's roles whose prompt's first line names a typed request, main's or a
//   subagent's (a subagent of main's own may start thimble's agents, as Claude Code lets a subagent start subagents;
//   a thread's fork makes none: main makes the call for it, tools._ask_main), gets that request's full model id, and
//   the agent it starts that request's effort, which turn.step sets on its every request, and, when the request keeps
//   one in the trusted folder (inline/<id>.md), the whole prompt its agent gets in place of the short one main typed;
//   a child of such an agent whose type is not thimble's gets the same effort (its model it inherits already). These
//   hooks never see a run of an agent this module started, which is why clicks register instead;
// - prompt.attachment: Claude Code's `task_status` rows that name a check's or the card check's agent this module knows
//   (checkName, callDone) are left out of main's requests (ownTask): after a compaction Claude Code lists each
//   background agent for main again ("Task … (description: check: Important details · answers) … completed"), and
//   main then reported on thimble's checks in its answer (bug hunt H12). The transcript keeps Claude Code's record,
//   and its row on the screen (`Task "…" completed in background`) stays: no hook draws or drops that row;
// - session.append: Claude Code's task notification of one of thimble's agents whose report already reached main as its
//   hand-back ("This agent's report was delivered to you as a message …", ownPointer) is kept as POINTER_NOTE alone,
//   which the terminal UI draws no row for. Claude Code writes such a notification to main's transcript without a turn
//   of its own, after the hand-back of an agent whose end it owes main: one main's Agent call started, or one this
//   module resumed with SendMessage, such as a view's builder sent back for the terminal page; main read it with its
//   next request and wrote "↳ The view builder finished. I covered its report above." (bug hunt I6). Neither
//   prompt.submit nor prompt.attachment sees it: it is a stored row, and only session.append reaches its content, which
//   it can rewrite but not drop. Kept empty, Claude Code stores it as "(no content)" inside its notice's frame, and
//   main still wrote a line about the agent (live check of I6);
// - turn.start and turn.complete of main's own turns: the id of main's running turn, which abort names;
// - turn.complete: posts the end of each run of an agent it started (POST /api/module/ended), with why it ended and,
//   for a refusal, what the API said of it, since its other hooks skip those agents;
// - session.end: on /clear and /resume keeps its poll, waits for the new session id, says hello again under it,
//   refetches what the workspace's record holds and appends to the new main one note per running thimble agent; on
//   any other reason it stops polling.
// Its state lives in this module's memory, which /clear and /resume keep, with subagents.json as the record it
// refetches at session start and after a change of session; never in $.state, which both commands reset. /plugin off
// and on loads the module afresh (session.start again, no session.end): the record gives it the agents still running,
// and their types are offered again (offerAgain).
//
// Local transport (launch.json `transport: local`, module note) has no server, and the module makes no HTTP request
// there, even when server.json names a live server. It is main's when launch.json names its session, or one --rekey
// moved it to (the moves subagents.json records). It reads the roles from trusted/roles.json and registers them again
// whenever that file changes; as main it takes the requests addressed to it from subagents.json (entries of `requests`
// of kind `module` whose `module` is pending, for its session, not past `expires_at`), polling every FILE_POLL_MS, and
// handles them one at a time as it handles the long poll's; and it writes everything it says to trusted/module.json,
// which only main's module writes: its heartbeat every FILE_BEAT_MS, the requests it took, its answers, the ends of the
// runs it started, main's plan mode as its poll sees it, and what it could not register (backend/app/module_bridge.py
// has the file's form). After /clear it appends the notes --rekey left for the new main in subagents.json
// (`module.notes`).
import type { EngineInterface, Register } from 'claude-code'

import type { Activated } from './term/types'

type Engine = EngineInterface
type Json = Record<string, unknown>
type Effort = string | number
type Values = { model?: string; effort?: Effort | null }
type Spec = { name: string; description: string; prompt: string; model?: string; effort?: Effort } & Json
type Answer = Json
type Request = { id: string; op: string; args: Json; expires_in?: number }
type Server = { base: string; token: string }
type Reply = { status: number; data: Json }
type Hello = 'ok' | 'wait' | 'refused'
// what the file guard refuses (userconf.module_rules): absolute paths, each as spelled and as resolved
type Rules = { private: string[]; records: string[]; corpus: string | null; web_off: boolean; reasons: Record<string, string> }

export const PLUGIN = 'thimble'
// thimble's roles: each names its own model and effort, so a typed run's effort never goes to one of them
export const ROLES = ['orientation', 'critic', 'writer', 'view-builder', 'view-reviewer', 'check', 'dev-ticket', 'call']
// the card check's agent (backend/app/agent_call.py): never offered to a model, and its hand-back dropped (callDone)
const CALL = 'call'
/** A dropped hand-back's reason when the server named none (agent_call.DONE_DEFAULT). */
export const CALL_DONE = 'thimble finished a task'
/** The requests that run at once, beside the queue of the others: thimble's model calls and their cancel (module note). */
export const BESIDE = new Set(['complete', 'fork', 'cancel'])
// a model call's id on local transport, which names its files in the trusted folder (module_bridge.COMPLETIONS)
const CALL_ID = /^[0-9a-f]{8,64}$/
export const RETRY_MS = 2000 // between hellos while no server accepts one, and after a failed poll
export const SESSION_WAIT_MS = 10000 // how long /clear's new session id is waited for
export const SESSION_TICK_MS = 25
const QUICK_MS = 1000 // a poll answered sooner than this with nothing is a server that is stopping
// how long abort waits for main's turn to complete after $.turn.abort, so that its answer comes once Claude Code has
// ended the turn
export const ABORT_WAIT_MS = 3000
// $.turn.abort's refusal when main's turn had ended already, or was ending (no turn runs, another turn runs, or this
// one is ending)
const NO_TURN = /no turn is running|is not the running turn|is already ending/i
// Claude Code's text when it runs as many subagents as it allows: the Agent tool's, and $.agent.spawn's when as many of
// this plugin's spawns run as CLAUDE_CODE_MAX_CONCURRENT_SUBAGENTS allows ("thimble: $.agent.spawn refused: 2 spawns are
// running at once", which it throws; live check L19)
const LIMIT = /concurrent subagent limit|spawns are running at once/i
const GONE = /is not running|no task found|could not be resumed|no transcript found/i
const QUEUED = /queued for delivery/i
const REQUEST_WORD = /[A-Za-z0-9_-]{8,64}/g // a request id on the first line of a typed start's prompt
const OFF = new Set(['', '0', 'false', 'no', 'off'])
// Claude Code tells no plugin of a mode change, so the module asks its permission decision for a write it never makes
// every PLAN_POLL_MS, and plan mode says so in the reason ("Cannot write to … while in plan mode"); the server hears a
// change at once, not at main's next turn (live check L21)
export const PLAN_POLL_MS = 2000
// never written; outside main's folder and every rule of thimble's, whose ask or deny would decide first and say nothing
// of plan mode
const PLAN_PROBE = '/tmp/.thimble-plan-probe'
const PLAN_REASON = /\bplan mode\b/i

// local transport (module note)
export const FILE_POLL_MS = 500 // how often subagents.json and roles.json are looked at
export const FILE_BEAT_MS = 2000 // the heartbeat in module.json; module_bridge counts a module live while it is fresh
const KEPT = 64 // the requests taken, the answers and the ends module.json keeps, the newest
const TYPED_LIVE = new Set(['', 'pending', 'claimed']) // module_bridge.TYPED_LIVE
// an agent of subagents.json with one of these statuses has ended (module_bridge.ENDED_STATES)
const ENDED_STATES = new Set(['ended', 'stopped', 'killed', 'completed', 'failed', 'done', 'refused', 'expired'])
const MODULE_KIND = 'module' // subagent_files.MODULE_KIND

// the file guard (module note): the tools whose path it reads, those of them that edit, those that search a folder
// (their `path`, else the working directory), and the web tools
const FILE_TOOLS = new Set(['Read', 'Edit', 'Write', 'MultiEdit', 'NotebookEdit', 'Grep', 'Glob'])
const EDIT_TOOLS = new Set(['Edit', 'Write', 'MultiEdit', 'NotebookEdit'])
const SEARCH_TOOLS = new Set(['Grep', 'Glob'])
const WEB_TOOLS = new Set(['WebFetch', 'WebSearch'])
// in thimble's home (userconf.private_paths): the token files, the press's sign-in files and one-time links, and the
// sessions' activation files with their guide markers
const PRIVATE_NAMES = ['server.json', 'session.key', 'paired.json', 'open', 'links', 'up']
// what a Bash command may not name under thimble's home once thimble is on in the session (build spec S5)
const BASH_PRIVATE = ['server.json', 'session.key', 'paired.json', 'links', 'open']
// what a refusal of a token file says before the server's rules came: prompts/tools.md's module-deny-private
export const PRIVATE_FALLBACK = "thimble refused this call, since it keeps its token files (server.json, session.key, paired.json and the links folder in thimble's home) out of reach of the file tools of its sessions. Do the task without them."
const REFUSED = 'thimble refused this call.' // a refusal whose reason the rules lack

const isObj = (v: unknown): v is Json => typeof v === 'object' && v !== null && !Array.isArray(v)
const text = (v: unknown): string => (typeof v === 'string' ? v : '')
const roleOf = (type: string): string => (type.startsWith(`${PLUGIN}:`) && ROLES.includes(type.slice(PLUGIN.length + 1)) ? type.slice(PLUGIN.length + 1) : '')

// --------------------------------------------------------------------------------------------------- the proof

const encoder = new TextEncoder()

async function sha256(data: Uint8Array): Promise<Uint8Array> {
  return new Uint8Array(await crypto.subtle.digest('SHA-256', data))
}

function hex(bytes: Uint8Array): string {
  return Array.from(bytes, b => b.toString(16).padStart(2, '0')).join('')
}

/** HMAC-SHA256 as hex, built on crypto.subtle.digest, the one digest this environment offers (app/hook_auth.py sign). */
export async function hmac(key: string, message: string): Promise<string> {
  let k = encoder.encode(key)
  if (k.length > 64) k = await sha256(k)
  const block = new Uint8Array(64)
  block.set(k)
  const body = encoder.encode(message)
  const inner = new Uint8Array(64 + body.length)
  inner.set(block.map(b => b ^ 0x36))
  inner.set(body, 64)
  const innerHash = await sha256(inner)
  const outer = new Uint8Array(64 + innerHash.length)
  outer.set(block.map(b => b ^ 0x5c))
  outer.set(innerHash, 64)
  return hex(await sha256(outer))
}

/** thimble's home: THIMBLE_HOME, else ~/.thimble. */
async function thimbleHome($: Engine): Promise<string> {
  const homeDir = (await $.env.get('HOME')) ?? ''
  const home = (await $.env.get('THIMBLE_HOME')) || `${homeDir}/.thimble`
  return home.startsWith('~/') ? `${homeDir}${home.slice(1)}` : home
}

/** <THIMBLE_HOME>/server.json's API base and token (`api`, then `port`, as bin/thimble-mcp reads it); null without. */
async function findServer($: Engine): Promise<Server | null> {
  const home = await thimbleHome($)
  let data: unknown
  try {
    data = JSON.parse(await $.fs.read(`${home}/server.json`))
  } catch {
    return null
  }
  if (!isObj(data) || !text(data.token)) return null
  const port = Number(data.port)
  const base = text(data.api) ? text(data.api).replace(/\/+$/, '') : Number.isInteger(port) && port > 0 ? `http://127.0.0.1:${port}` : ''
  return base ? { base, token: text(data.token) } : null
}

// --------------------------------------------------------------------------------------------------- the module
// One State per load of the module (register runs once per load); the functions below take `$` and it. Claude Code's
// check of a module (claude plugin validate) allows `$` to pass only to plain functions, never to a method.

type Ended = { n: number; agentId: string; answer: string; reason: string; refusal?: Json; at: number }
type Out = {
  session: string; version: string; load: string; beat: number; plan: boolean | null; plan_at: number; problem: string
  taken: string[]; answers: Record<string, Answer>; ended: Ended[]; gone?: boolean
}

type State = {
  active: boolean // thimble is on in this interactive session (the scope check passed) and it has not ended
  interactive: boolean // session.start said the session is interactive
  user: string // $HOME, for a path that starts with ~
  home: string // thimble's home, as spelled
  homeReal: string // and resolved, '' when it does not resolve
  rules: Rules | null // what the file guard refuses (null until the scope check passed)
  file: boolean // local transport: the trusted folder, not the server (module note)
  peer: boolean // on local transport, a session that is not main: it registers the types, takes no requests, writes nothing
  rechecking: Promise<boolean> | null // launch.json read again (recheck), one look at a time
  ws: string // the workspace folder
  out: Out // what module.json holds, on local transport
  writing: Promise<void> // module.json's writes, one at a time
  stamps: Record<string, string> // the files' stamps (mtime and size) as last read, on local transport
  n: number // the ends written to module.json, on local transport
  cwd: string
  session: string // main's session id, as the server accepted it
  version: string
  gen: number // a poll whose generation is past stops
  server: Server | null
  roles: Record<string, Spec> // the roles as Settings name them (GET /api/module/roles)
  registered: Record<string, Spec> // what each role is registered with now
  efforts: Record<string, Effort> // agent id -> the effort turn.step sets (typed runs and their children)
  requests: Record<string, { role: string; values: Values; inline: boolean }> // typed starts waiting for main's Agent call; `inline`: trusted/inline/<id>.md holds its agent's whole prompt
  started: Set<string> // agents this module spawned: their turn.complete is posted
  checks: Map<string, string> // agents of thimble's check role, this module's spawns and main's Agent calls: each one's check (checkName)
  ours: Set<string> // agents of thimble's types this session started, this module's spawns and main's Agent calls (ownPointer)
  calls: Map<string, string> // agents of the call role this module spawned: the reason their dropped hand-back gives (callDone)
  completions: Map<string, AbortController> // the completions that run now, by their request's id (a cancel aborts one)
  queue: Promise<void> // the requests, one at a time
  helloing: { sid: string; said: Promise<Hello> } | null
  leaving: string // the session /clear or /resume is taking main away from, until the new one is known
  plan: boolean | null // whether main's session was in plan mode at the last look, as the server heard it
  turn: string // main's running model turn: the id its turn.start carried, '' once it completed
  turnEnded: (() => void)[] // what waits for the end of `turn` (abortTurn)
  dispatching: Map<string, number> // thimble's types an Agent or SendMessage call offers while it runs, with how many
  used: Set<string> // thimble's types an agent of which started in this session: offered from then on (agent.offer)
}

function fresh(): State {
  return {
    active: false, interactive: false, user: '', home: '', homeReal: '', rules: null,
    cwd: '', session: '', version: '', gen: 0, server: null, roles: {}, registered: {}, efforts: {},
    requests: {}, started: new Set(), checks: new Map(), ours: new Set(), calls: new Map(), completions: new Map(), queue: Promise.resolve(), helloing: null, leaving: '', plan: null, turn: '', turnEnded: [],
    dispatching: new Map(), used: new Set(),
    file: false, peer: false, rechecking: null, ws: '', writing: Promise.resolve(), stamps: {}, n: 0,
    out: { session: '', version: '', load: '', beat: 0, plan: null, plan_at: 0, problem: '', taken: [], answers: {}, ended: [] },
  }
}

/** Whether `type` is one of the types this module registers (thimble:<role>, the helper and the extensions' agents). */
const ours = (m: State, type: string): boolean => type.startsWith(`${PLUGIN}:`) && Object.prototype.hasOwnProperty.call(m.roles, type.slice(PLUGIN.length + 1))

/** Every type this module registers, as Claude Code names it. */
const allOurs = (m: State): string[] => Object.keys(m.roles).map(name => `${PLUGIN}:${name}`)

/** The types of thimble's a call offers while it runs (agent.offer): the one an Agent call names, and all of them for a
 *  SendMessage, which names an agent by its id and may resume it; none for any other call. */
function dispatched(m: State, e: Json): string[] {
  if (e.tool === 'SendMessage') return allOurs(m)
  if (e.tool !== 'Agent' && e.tool !== 'Task') return []
  const type = text(e.subagent_type)
  return ours(m, type) ? [type] : []
}

/** `go` (the call) with `types` offered while it runs: counted, since the orientation starts several helpers at once. */
async function offering<T>(m: State, types: string[], go: () => Promise<T>): Promise<T> {
  for (const type of types) m.dispatching.set(type, (m.dispatching.get(type) ?? 0) + 1)
  try {
    return await go()
  } finally {
    for (const type of types) {
      const left = (m.dispatching.get(type) ?? 1) - 1
      if (left > 0) m.dispatching.set(type, left)
      else m.dispatching.delete(type)
    }
  }
}

const where = (m: State): string => new URLSearchParams({ cwd: m.cwd, session: m.session }).toString()

function stop(m: State): void {
  m.active = false
  m.gen += 1
}

/** A refused hello (another session is main): through the workspace's files as a peer, which follow launch.json, so
 *  the module takes main's requests again once an explicit /thimble makes this session main (toFiles; bug hunt 7, H14);
 *  idle when launch.json cannot be read, and the end of main's next turn looks again. */
async function refuse($: Engine, m: State): Promise<void> {
  if (!(await toFiles($, m))) stop(m)
}

/** Over the server's transport, while the server asks for the hello again or refused it: when launch.json no longer
 *  makes this session main on the server's transport (main continued after a quit runs on the local transport,
 *  activate.continue_main; another session took main), the module goes on through the workspace's files, main or a peer
 *  by launch.json (fileBegin), which follow launch.json from then on, rather than saying hello every RETRY_MS for as
 *  long as the session runs (bug hunt 7, H13 and H17). True when it moved. */
async function toFiles($: Engine, m: State): Promise<boolean> {
  if (!m.active || m.file || !m.ws) return false
  const launch = await readJson($, `${m.ws}/trusted/launch.json`)
  if (!launch) return false
  const state = (await readJson($, `${m.ws}/trusted/subagents.json`)) ?? {}
  if (serverOf(launch) && isMain(launch, state, m.session)) return false
  m.gen += 1 // the polls over HTTP stop
  await fileBegin($, m, m.cwd, m.ws, launch)
  return true
}

// ------------------------------------------------------------------------------------------------ the server

async function call($: Engine, m: State, method: string, path: string, body?: Json): Promise<Reply | null> {
  const server = m.server ?? (m.server = await findServer($))
  if (!server) return null
  // app/hook_auth.py's headers: the nonce's time and the port make the proof good on that port alone, for a few minutes,
  // once, so a process that holds the recorded port while thimble's server runs on another gains nothing from it
  const nonce = `${Math.floor(Date.now() / 1000)}.${hex(crypto.getRandomValues(new Uint8Array(16)))}`
  const port = /:(\d+)$/.exec(server.base)?.[1] ?? '80'
  const headers: Record<string, string> = { 'x-thimble-nonce': nonce, 'x-thimble-auth': await hmac(server.token, `hook@${port}:${nonce}`) }
  let payload: string | undefined
  if (body !== undefined) {
    headers['content-type'] = 'application/json'
    payload = JSON.stringify(body)
  }
  let r
  try {
    r = await $.http.fetch(`${server.base}${path}`, { method, headers, body: payload })
  } catch {
    m.server = null // the next call reads server.json again: a restarted server may have another port or token
    return null
  }
  if ((r.headers['x-thimble-proof'] ?? '') !== (await hmac(server.token, `server:${nonce}`))) {
    m.server = null // not thimble's server: believe nothing it says
    return null
  }
  let data: unknown = {}
  try {
    data = r.text ? JSON.parse(r.text) : {}
  } catch {
    data = {}
  }
  return { status: r.status, data: isObj(data) ? data : {} }
}

/** One hello per session at a time: 'ok' when the server accepted this session, 'refused' when it never will, else
 *  'wait'. An answer for a session this module has since left (/clear came meanwhile) counts as 'wait'. */
function hello($: Engine, m: State, problem = ''): Promise<Hello> {
  const sid = m.session
  if (m.helloing && m.helloing.sid === sid && !problem) return m.helloing.said
  const said = (async (): Promise<Hello> => {
    const r = await call($, m, 'POST', '/api/module/hello', { cwd: m.cwd, session: sid, version: m.version, problem })
    if (m.session !== sid || !r) return 'wait'
    if (r.status === 200 && r.data.ok === true) return 'ok'
    if (r.status === 403) return sid === m.leaving ? 'wait' : 'refused' // the server moved main first
    // 404, a folder the server does not know yet: a server that is starting
    return 'wait'
  })().finally(() => {
    if (m.helloing?.said === said) m.helloing = null
  })
  if (!problem) m.helloing = { sid, said }
  return said
}

async function fetchRoles($: Engine, m: State): Promise<boolean> {
  const r = await call($, m, 'GET', `/api/module/roles?${where(m)}`)
  if (!r || r.status !== 200 || !isObj(r.data.roles)) return false
  const roles: Record<string, Spec> = {}
  for (const [name, spec] of Object.entries(r.data.roles)) {
    if (isObj(spec) && text(spec.model) && text(spec.prompt)) roles[name] = { ...spec, name, description: text(spec.description), prompt: text(spec.prompt), background: true } as Spec
  }
  m.roles = roles
  m.rules = parseRules(m, r.data.rules) ?? m.rules
  return true
}

/** What subagents.json holds: the per-run efforts, the typed starts, the agents this module started. The notes it
 *  answers for the running agents are returned, for a new main after /clear or /resume. */
async function fetchState($: Engine, m: State): Promise<string[]> {
  if (m.file) {
    await fetchStateFile($, m)
    return []
  }
  const r = await call($, m, 'GET', `/api/module/state?${where(m)}`)
  if (!r || r.status !== 200) return []
  if (isObj(r.data.efforts)) {
    for (const [id, effort] of Object.entries(r.data.efforts)) {
      if (typeof effort === 'string' || typeof effort === 'number') m.efforts[id] = effort
    }
  }
  if (isObj(r.data.requests)) {
    const requests: State['requests'] = {}
    for (const [id, req] of Object.entries(r.data.requests)) {
      if (isObj(req) && text(req.role)) requests[id] = { role: text(req.role), values: isObj(req.values) ? (req.values as Values) : {}, inline: req.inline === true }
    }
    m.requests = requests
  }
  if (isObj(r.data.agents)) {
    for (const [id, agent] of Object.entries(r.data.agents)) {
      if (!isObj(agent)) continue
      if (agent.plugin_started === true) m.started.add(id)
      offerAgain(m, agent.type) // the server lists the running agents only
    }
  }
  return Array.isArray(r.data.notes) ? r.data.notes.filter((n): n is string => typeof n === 'string' && n !== '') : []
}

async function registerAll($: Engine, m: State): Promise<void> {
  const problems: string[] = []
  m.registered = {}
  for (const [name, spec] of Object.entries(m.roles)) {
    try {
      await $.agent.register(spec as Parameters<Engine['agent']['register']>[0])
      m.registered[name] = spec
    } catch (err) {
      problems.push(`${PLUGIN}:${name}: ${String(err)}`)
    }
  }
  if (problems.length) await say($, m, `Claude Code did not register ${problems.join('; ')}`)
}

/** What the module could not do: in the hello's `problem` (over HTTP), or module.json's (local transport). */
async function say($: Engine, m: State, problem: string): Promise<void> {
  if (!m.file) {
    await hello($, m, problem)
    return
  }
  m.out.problem = problem
  await writeOut($, m)
}

// ------------------------------------------------------------------------------------------------ the session

/** Once the scope check passed (module note): thimble's home as spelled and resolved, and the file guard's rules until
 *  the server's come (only the token files). */
async function prepare($: Engine, m: State): Promise<void> {
  m.user = (await $.env.get('HOME')) ?? ''
  m.home = normal(m, await thimbleHome($))
  const st = await $.fs.stat(m.home, { resolve: true }).catch(() => undefined)
  m.homeReal = st?.realPath ?? ''
  if (!m.rules) m.rules = fallbackRules(m)
}

/** Main on the server's transport (start, or recheck at the switch): hello, roles and registrations, then the long poll.
 *  While no server accepts the hello it says it again every RETRY_MS: a server that died stays the transport (H7). */
async function begin($: Engine, m: State, cwd: string): Promise<void> {
  await prepare($, m)
  m.cwd = cwd
  m.session = await $.session.id()
  try {
    const manifest = JSON.parse(await $.fs.read(`${$.plugin.root}/.claude-plugin/plugin.json`))
    m.version = isObj(manifest) ? text(manifest.version) : ''
  } catch {
    m.version = ''
  }
  // a server that is up now: hello, roles and registrations before this returns, so the types are registered in the
  // turn that turned thimble on
  const first = await connect($, m)
  if (first === 'refused') return refuse($, m)
  const gen = m.gen
  void (async () => {
    let state: Hello = first
    while (state === 'wait' && m.active && gen === m.gen) {
      await $.clock.sleep(RETRY_MS)
      if (gen !== m.gen || (await toFiles($, m))) return
      state = await connect($, m)
    }
    if (gen !== m.gen) return
    if (state === 'ok') {
      void watchPlan($, m, gen)
      await poll($, m, gen)
    } else if (state === 'refused') await refuse($, m)
  })()
}

/** Every PLAN_POLL_MS: whether main's session is in plan mode now (Claude Code's decision for a write the module never
 *  makes, PLAN_REASON), posted to the server when it changed. */
async function watchPlan($: Engine, m: State, gen: number): Promise<void> {
  while (m.active && gen === m.gen) {
    await $.clock.sleep(PLAN_POLL_MS)
    if (!m.active || gen !== m.gen) return
    let plan: boolean
    try {
      const got = await $.tool.check({ tool: 'Write', input: { file_path: PLAN_PROBE, content: '' } } as Parameters<Engine['tool']['check']>[0])
      plan = PLAN_REASON.test(text((got as Json).reason))
    } catch {
      continue
    }
    if (plan === m.plan) continue
    if (m.file) {
      m.plan = plan
      m.out.plan = plan
      m.out.plan_at = Date.now()
      await writeOut($, m)
      continue
    }
    const r = await call($, m, 'POST', '/api/module/mode', { cwd: m.cwd, session: m.session, plan })
    if (r?.status === 200) m.plan = plan
  }
}

async function connect($: Engine, m: State): Promise<Hello> {
  const said = await hello($, m)
  if (said !== 'ok') return said
  await fetchState($, m)
  if (await fetchRoles($, m)) await registerAll($, m)
  else await hello($, m, 'thimble’s module could not fetch the roles it registers')
  return 'ok'
}

async function poll($: Engine, m: State, gen: number): Promise<void> {
  while (m.active && gen === m.gen) {
    const asked = Date.now()
    const r = await call($, m, 'GET', `/api/module/next?${where(m)}`)
    if (!m.active || gen !== m.gen) return
    if (r?.status === 200 && isObj(r.data.request)) {
      take($, m, r.data.request as Request)
      continue
    }
    if (r?.status === 204) {
      // a server holds a poll up to 25 s; one that answers at once is stopping, and is not asked again at once
      if (Date.now() - asked < QUICK_MS) await $.clock.sleep(RETRY_MS)
      continue
    }
    if (r?.status === 409 && m.leaving && m.session === m.leaving) {
      await $.clock.sleep(SESSION_TICK_MS) // main is moving: follow says hello under the new id
      continue
    }
    if (r?.status === 409) {
      // not the accepted session (a server that restarted, or main moved): say hello again
      const said = await hello($, m)
      if (said === 'refused') return refuse($, m)
      if (said === 'ok') continue
      if (await toFiles($, m)) return
    }
    await $.clock.sleep(RETRY_MS)
  }
}

function take($: Engine, m: State, req: Request): void {
  if (BESIDE.has(req.op)) {
    void (async () => {
      const answer = await modelCall($, m, req.id, req.op, isObj(req.args) ? req.args : {})
      if (req.op !== 'cancel') await call($, m, 'POST', '/api/module/result', { cwd: m.cwd, session: m.session, id: req.id, answer })
    })().catch(() => undefined)
    return
  }
  const received = Date.now()
  m.queue = m.queue
    .then(async () => {
      const late = typeof req.expires_in === 'number' && Date.now() - received > req.expires_in
      const answer = late ? { error: 'the request expired before thimble’s module reached it' } : await handle($, m, req)
      await call($, m, 'POST', '/api/module/result', { cwd: m.cwd, session: m.session, id: req.id, answer })
    })
    .catch(() => undefined)
}

async function handle($: Engine, m: State, req: Request): Promise<Answer> {
  const a = isObj(req.args) ? req.args : {}
  const values = isObj(a.values) ? (a.values as Values) : undefined
  try {
    switch (req.op) {
      case 'register':
        if (!(await (m.file ? readRoles($, m) : fetchRoles($, m)))) return { error: 'the roles could not be fetched' }
        await registerAll($, m)
        return { ok: true }
      case 'spawn':
        return await spawn($, m, text(a.role), text(a.prompt), text(a.description), values, text(a.note), text(a.drop))
      case 'send':
        return await send($, m, text(a.agent), text(a.text), text(a.role), values)
      case 'stop':
        return await stopAgent($, text(a.agent), Array.isArray(a.shells) ? a.shells.map(text).filter(Boolean) : [])
      case 'abort':
        return await abortTurn($, m)
      case 'note':
        return await note($, text(a.text))
      default:
        return { error: `thimble’s module has no op ${req.op}` }
    }
  } catch (err) {
    const why = String(err)
    return LIMIT.test(why) ? { limit: why } : { error: why }
  }
}

/** The role registered with `values` (the run's model and effort) when they differ from its registration now. */
async function ensure($: Engine, m: State, role: string, values: Values | undefined): Promise<void> {
  const base = m.roles[role]
  if (!base) throw new Error(`thimble’s role ${role} is not registered in this session`)
  const want: Spec = { ...base }
  if (values && text(values.model)) want.model = text(values.model)
  if (values && 'effort' in values) {
    if (values.effort === null || values.effort === undefined || values.effort === '') delete want.effort
    else want.effort = values.effort
  }
  const have = m.registered[role]
  if (have && have.model === want.model && have.effort === want.effort && have.prompt === want.prompt) return
  await $.agent.register(want as Parameters<Engine['agent']['register']>[0])
  m.registered[role] = want
}

async function spawn($: Engine, m: State, role: string, prompt: string, description: string, values: Values | undefined, line: string, drop = ''): Promise<Answer> {
  await ensure($, m, role, values)
  // no `model`: a spawn takes only an alias; the registration carries the full id
  const r = await $.agent.spawn({ subagentType: `${PLUGIN}:${role}`, prompt, description })
  if (r.deny !== undefined) return LIMIT.test(r.deny) ? { limit: r.deny } : { deny: r.deny }
  if (!r.agentId) return { error: 'Claude Code started no agent' }
  m.started.add(r.agentId)
  m.ours.add(r.agentId)
  if (role === 'check') m.checks.set(r.agentId, checkOf(description))
  // the card check's type stays out of every listing: no model starts one or sends to one (agent.offer)
  if (role === CALL) m.calls.set(r.agentId, drop || CALL_DONE)
  else m.used.add(`${PLUGIN}:${role}`)
  if (line) await note($, line.split('{agent}').join(r.agentId))
  return { agentId: r.agentId, model: r.model }
}

/** A model call's text blocks as $.model.complete takes them, from the server's (a string is one block); undefined for
 *  none. */
function blocks(v: unknown): { text: string; cache?: true }[] | undefined {
  const all = typeof v === 'string' ? [{ text: v }] : Array.isArray(v) ? v.filter(isObj) : []
  const out = all.filter(b => text(b.text) !== '').map(b => (b.cache === true ? { text: text(b.text), cache: true as const } : { text: text(b.text) }))
  return out.length ? out : undefined
}

/** What a model call resolved to, as the server reads it (module_bridge._model_answer): the reply's text and usage, or
 *  why there is none, with the HTTP status and the error's kind for an API error. */
export function modelAnswer(r: Json): Answer {
  if (r.isAnswered === true) return { text: text(r.text), usage: r.usage }
  const reason = text(r.reason) || 'empty-reply'
  const api = reason === 'api-error' ? { status: typeof r.status === 'number' ? r.status : null, kind: text(r.error) || 'unknown' } : {}
  return { failed: reason, ...api, ...(isObj(r.usage) ? { usage: r.usage } : {}) }
}

/** A model call's arguments on local transport: its request file in the trusted folder (module note). */
async function callArgs($: Engine, m: State, id: string): Promise<Json> {
  if (!CALL_ID.test(id)) throw new Error('the model call names no request file of its own')
  const got = await readJson($, trusted(m, `completions/${id}.json`))
  if (!got) throw new Error('the model call’s request file could not be read')
  return got
}

/** One model call (module note): `complete` through $.model.complete with an AbortController that a `cancel` naming the
 *  request aborts, `fork` through $.model.fork (which nothing aborts), `cancel` itself. Never throws: a request Claude
 *  Code refuses to send (a model the organization does not allow, a bad cap) is an `error`. */
async function modelCall($: Engine, m: State, id: string, op: string, a: Json): Promise<Answer> {
  if (op === 'cancel') {
    m.completions.get(text(a.request))?.abort()
    return { ok: true }
  }
  const stop = new AbortController()
  if (op === 'complete') m.completions.set(id, stop) // before any wait, so a cancel taken next finds it
  try {
    const args = text(a.call) ? await callArgs($, m, text(a.call)) : a
    if (stop.signal.aborted) return { failed: 'aborted' }
    if (op === 'fork') return modelAnswer((await $.model.fork({ prompt: text(args.prompt) })) as unknown as Json)
    const prompt = blocks(args.prompt)
    if (!prompt || !text(args.model)) return { error: 'a model call with no model or no prompt' }
    const system = blocks(args.system)
    const request = {
      model: text(args.model), prompt, ...(system ? { system } : {}),
      ...(typeof args.maxTokens === 'number' ? { maxTokens: args.maxTokens } : {}),
      ...(text(args.effort) ? { effort: text(args.effort) } : {}),
      ...(typeof args.timeoutMs === 'number' ? { timeoutMs: args.timeoutMs } : {}),
    }
    return modelAnswer((await $.model.complete(request as Parameters<Engine['model']['complete']>[0], { signal: stop.signal })) as unknown as Json)
  } catch (err) {
    return { error: String(err) }
  } finally {
    if (m.completions.get(id) === stop) m.completions.delete(id)
  }
}

async function send($: Engine, m: State, agent: string, message: string, role: string, values: Values | undefined): Promise<Answer> {
  if (role && m.roles[role]) await ensure($, m, role, values)
  const r = await offering(m, allOurs(m), () => $.tool.call({ tool: 'SendMessage', to: agent, message } as Parameters<Engine['tool']['call']>[0]))
  if (r.deny !== undefined) return { deny: r.deny }
  const said = text(r.text)
  if (r.isError) return { error: said || 'SendMessage failed', ...(GONE.test(said) ? { gone: true } : {}) }
  const result = (r as { result?: unknown }).result
  if (isObj(result) && result.success === false) {
    const why = text(result.message) || said
    return { error: why, ...(GONE.test(why) ? { gone: true } : {}) }
  }
  return { agentId: agent, text: said, queued: QUEUED.test(said) }
}

async function stopAgent($: Engine, agent: string, shells: string[] = []): Promise<Answer> {
  const r = await $.tool.call({ tool: 'TaskStop', task_id: agent } as Parameters<Engine['tool']['call']>[0])
  // the background shells the agent started, which Claude Code's TaskStop of the agent leaves running; one that has
  // ended already answers an error, which changes nothing
  for (const shell of shells) await $.tool.call({ tool: 'TaskStop', task_id: shell } as Parameters<Engine['tool']['call']>[0]).catch(() => undefined)
  if (r.deny !== undefined) return { deny: r.deny }
  const said = text(r.text)
  if (r.isError) return { error: said || 'TaskStop failed', ...(GONE.test(said) ? { gone: true } : {}) }
  return { agentId: agent, text: said }
}

/** The analyst's Stop of main: main's running turn ended as Esc in the terminal ends it, with $.turn.abort and the id its
 *  turn.start carried, answered once the turn completed or ABORT_WAIT_MS passed, and the commands the abort moved to the
 *  background stopped (stopMoved); `gone` when no turn of main's runs. */
async function abortTurn($: Engine, m: State): Promise<Answer> {
  const turn = m.turn
  if (!turn) return { error: 'main is not running a turn', gone: true }
  try {
    await $.turn.abort({ turnId: turn })
  } catch (err) {
    const why = String(err)
    return NO_TURN.test(why) ? { error: why, gone: true } : { error: why }
  }
  if (m.turn === turn) await Promise.race([new Promise<void>(resolve => m.turnEnded.push(resolve)), $.clock.sleep(ABORT_WAIT_MS)])
  await stopMoved($)
  return { ok: true }
}

/** Where Esc ends a command that runs, $.turn.abort moves it to the background (Claude Code's backgroundedByTurnAbort on
 *  the call's stored result), where it runs on and its end starts a new turn of main's (live check L4-12l). Once the
 *  stopped turn ended, each such command of it, read from main's messages back to the turn's prompt (a user message with
 *  no tool results), is stopped with TaskStop; one that has ended already answers an error, which changes nothing. */
async function stopMoved($: Engine): Promise<void> {
  const rows: unknown = await $.session.messages().catch(() => [])
  if (!Array.isArray(rows)) return
  const shells = new Set<string>()
  for (let i = rows.length - 1; i >= 0; i--) {
    const row = rows[i]
    if (!isObj(row)) continue
    const results = Array.isArray(row.toolResults) ? row.toolResults : []
    if (row.role === 'user' && !results.length) break
    for (const one of [...(Array.isArray(row.toolUses) ? row.toolUses : []), ...results]) {
      const result = isObj(one) ? one.result : undefined
      if (isObj(result) && result.backgroundedByTurnAbort === true && text(result.backgroundTaskId)) shells.add(text(result.backgroundTaskId))
    }
  }
  for (const shell of shells) await $.tool.call({ tool: 'TaskStop', task_id: shell } as Parameters<Engine['tool']['call']>[0]).catch(() => undefined)
}

async function note($: Engine, line: string): Promise<Answer> {
  if (!line) return { error: 'an empty note' }
  const r = await $.session.append({ message: { type: 'user', content: [{ type: 'text', text: line }] } })
  return r.deny !== undefined ? { deny: r.deny } : { ok: true }
}

/** The typed start a prompt's first line names, for `role`: from memory, else from the record fetched again. */
async function typedStart($: Engine, m: State, prompt: string, role: string): Promise<{ id: string; values: Values; inline: boolean } | null> {
  const words = (prompt.split('\n', 1)[0] ?? '').match(REQUEST_WORD) ?? []
  if (!words.length) return null
  const find = () => {
    for (const id of words) {
      const req = m.requests[id]
      if (req && req.role === role) return { id, values: req.values, inline: req.inline }
    }
    return null
  }
  const known = find()
  if (known) return known
  await fetchState($, m)
  return find()
}

/** After /clear or /resume: the new session id, a hello under it, the record again, and a note per running agent. */
async function follow($: Engine, m: State, old: string): Promise<void> {
  m.leaving = old
  let sid = old
  for (let waited = 0; waited < SESSION_WAIT_MS && sid === old; waited += SESSION_TICK_MS) {
    await $.clock.sleep(SESSION_TICK_MS)
    sid = await $.session.id()
  }
  if (m.leaving === old) m.leaving = ''
  if (!m.active || sid === old) return
  m.session = sid
  let said = await hello($, m)
  while (said === 'wait' && m.active && m.session === sid) {
    await $.clock.sleep(RETRY_MS)
    said = await hello($, m)
  }
  if (said === 'refused') return refuse($, m)
  if (said !== 'ok' || m.session !== sid) return
  for (const line of await fetchState($, m)) await note($, line)
}

/** The whole prompt the typed start `id` keeps for its agent (trusted/inline/<id>.md, app/subagent_files.py INLINE),
 *  which its agent gets in place of the short one main typed (bug hunt I12: a check main started read its task from
 *  files, a permission ask each in Manual mode). Only a file whose first line names the same request; '' without. */
async function inlinePrompt($: Engine, m: State, id: string): Promise<string> {
  if (!m.ws || !/^[A-Za-z0-9_-]+$/.test(id)) return ''
  try {
    const got = await $.fs.read(trusted(m, `inline/${id}.md`))
    return (got.split('\n', 1)[0] ?? '').includes(id) ? got : ''
  } catch {
    return ''
  }
}

/** What main's (or an agent's) Agent call starts with: a typed start's model, its whole prompt when the request keeps
 *  one (inlinePrompt), and the effort its agent and that agent's children of no thimble type run at. A typed start is
 *  found by the request its prompt's first line names, whoever makes the call: main, a subagent of main's own whose
 *  start tool call made the request, or the orientation for its critic. Never fails the call: a lookup that fails
 *  changes nothing. */
async function spawning($: Engine, m: State, e: { subagentType?: string; parentAgentId?: string; prompt?: string }): Promise<{ model?: string; effort?: Effort; typed?: string; prompt?: string }> {
  try {
    const type = e.subagentType ?? ''
    const role = roleOf(type)
    if (role) {
      const typed = await typedStart($, m, e.prompt ?? '', role)
      if (!typed) return {}
      const effort = typed.values.effort
      const prompt = typed.inline ? await inlinePrompt($, m, typed.id) : ''
      return {
        typed: typed.id,
        ...(prompt ? { prompt } : {}),
        ...(text(typed.values.model) ? { model: text(typed.values.model) } : {}),
        ...(effort !== null && effort !== undefined && effort !== '' ? { effort } : {}),
      }
    }
    if (e.parentAgentId && !type.startsWith(`${PLUGIN}:`) && m.efforts[e.parentAgentId] !== undefined) return { effort: m.efforts[e.parentAgentId] }
  } catch {
    // the call goes on as Claude Code made it
  }
  return {}
}

// ------------------------------------------------------------------------------------------------ local transport

async function readJson($: Engine, path: string): Promise<Json | null> {
  try {
    const data = JSON.parse(await $.fs.read(path))
    return isObj(data) ? data : null
  } catch {
    return null
  }
}

/** A file's stamp (mtime and size), '' when it is missing. */
async function stamp($: Engine, path: string): Promise<string> {
  try {
    const st = await $.fs.stat(path)
    return `${st.mtimeMs}:${st.size}`
  } catch {
    return ''
  }
}

const trusted = (m: State, name: string): string => `${m.ws}/trusted/${name}`

/** Session `sid` followed through the moves --rekey recorded (subagents.json `module.rekeyed`). */
function movedTo(state: Json, sid: string): string {
  const moves = isObj(state.module) && isObj(state.module.rekeyed) ? (state.module.rekeyed as Json) : {}
  const seen = new Set<string>()
  while (sid && typeof moves[sid] === 'string' && !seen.has(sid)) {
    seen.add(sid)
    sid = moves[sid] as string
  }
  return sid
}

/** module.json written whole, one write at a time, with a fresh heartbeat (module note); never by a peer. */
function writeOut($: Engine, m: State): Promise<void> {
  if (m.peer) return m.writing
  m.writing = m.writing
    .then(async () => {
      m.out.beat = Date.now()
      await $.fs.write(trusted(m, 'module.json'), JSON.stringify(m.out))
    })
    .catch(() => undefined)
  return m.writing
}

async function readRoles($: Engine, m: State): Promise<boolean> {
  const got = await readJson($, trusted(m, 'roles.json'))
  if (!got || !isObj(got.roles)) return false
  const roles: Record<string, Spec> = {}
  for (const [name, spec] of Object.entries(got.roles)) {
    if (isObj(spec) && text(spec.model) && text(spec.prompt)) roles[name] = { ...spec, name, description: text(spec.description), prompt: text(spec.prompt), background: true } as Spec
  }
  m.roles = roles
  m.rules = parseRules(m, got.rules) ?? m.rules
  return true
}

/** module_bridge._efforts: the per-run efforts of the typed starts and their children of no thimble type, then the
 *  record's own. */
function effortsOf(state: Json): Record<string, Effort> {
  const agents = isObj(state.agents) ? Object.entries(state.agents).filter((x): x is [string, Json] => isObj(x[1])) : []
  const out: Record<string, Effort> = {}
  for (const [id, e] of agents) {
    const effort = isObj(e.values) ? e.values.effort : undefined
    if (text(e.type).startsWith(`${PLUGIN}:`) && !e.plugin_started && (typeof effort === 'string' || typeof effort === 'number') && effort !== '') out[id] = effort
  }
  for (let changed = true; changed;) {
    changed = false
    for (const [id, e] of agents) {
      const parent = text(e.parent)
      if (!(id in out) && parent in out && !text(e.type).startsWith(`${PLUGIN}:`)) {
        out[id] = out[parent] as Effort
        changed = true
      }
    }
  }
  if (isObj(state.efforts)) for (const [id, v] of Object.entries(state.efforts)) if ((typeof v === 'string' || typeof v === 'number') && v !== '') out[id] = v
  return out
}

/** What fetchState fetches over HTTP, from subagents.json: the per-run efforts, the typed starts waiting for an Agent
 *  call (module_bridge._typed), the agents this module started. */
async function fetchStateFile($: Engine, m: State): Promise<Json> {
  const state = (await readJson($, trusted(m, 'subagents.json'))) ?? {}
  Object.assign(m.efforts, effortsOf(state))
  const requests: State['requests'] = {}
  for (const table of ['pending', 'requests']) {
    if (!isObj(state[table])) continue
    for (const [id, r] of Object.entries(state[table] as Json)) {
      if (!isObj(r) || r.route !== 'typed' || (text(r.kind) || 'start') !== 'start' || !TYPED_LIVE.has(text(r.state))) continue
      requests[text(r.id) || id] = { role: text(r.role).replace(/^thimble:/, ''), values: isObj(r.values) ? (r.values as Values) : {}, inline: r.inline === true }
    }
  }
  m.requests = requests
  if (isObj(state.agents)) {
    for (const [id, a] of Object.entries(state.agents)) {
      if (!isObj(a)) continue
      if (a.plugin_started === true) m.started.add(id)
      const status = text(a.status) || text(a.state)
      if (status ? !ENDED_STATES.has(status) : !a.ended) offerAgain(m, a.type) // as module_bridge._running reads it
    }
  }
  return state
}

/** A type of thimble's whose agent the record says runs is offered from now on (agent.offer), as if this load of the
 *  module had seen it start: after /plugin turned thimble off and on, the module's memory is new, and Claude Code checks
 *  the offer again when it resumes the agent, as when a helper of the orientation reports to it (bug hunt H19). */
function offerAgain(m: State, type: unknown): void {
  const role = roleOf(text(type))
  if (role && role !== CALL) m.used.add(`${PLUGIN}:${role}`)
}

/** The local transport's start (module note): main or a peer by launch.json, the roles from roles.json, the record,
 *  module.json (main's), then the poll of the files and, for main, the plan poll. */
async function fileBegin($: Engine, m: State, cwd: string, ws: string, launch: Json): Promise<void> {
  m.file = true
  m.ws = ws.replace(/\/+$/, '')
  m.cwd = cwd
  await prepare($, m)
  m.session = await $.session.id()
  const state = (await readJson($, trusted(m, 'subagents.json'))) ?? {}
  m.peer = !isMain(launch, state, m.session)
  m.stamps.launch = await stamp($, trusted(m, 'launch.json'))
  try {
    const manifest = JSON.parse(await $.fs.read(`${$.plugin.root}/.claude-plugin/plugin.json`))
    m.version = isObj(manifest) ? text(manifest.version) : ''
  } catch {
    m.version = ''
  }
  m.out = { ...m.out, session: m.session, version: m.version, load: hex(crypto.getRandomValues(new Uint8Array(8))), gone: false }
  await fetchStateFile($, m)
  m.stamps.roles = await stamp($, trusted(m, 'roles.json'))
  if (await readRoles($, m)) await registerAll($, m)
  else m.out.problem = 'thimble’s module could not read the roles it registers (trusted/roles.json)'
  await writeOut($, m)
  const gen = m.gen
  if (!m.peer) void watchPlan($, m, gen)
  void pollFiles($, m, gen)
}

const sids = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string' && x !== '') : [])

/** Whether session `sid` is main's by launch.json (its `session`, through the moves --rekey recorded), and neither a
 *  peer nor a session another took main from. */
function isMain(launch: Json, state: Json, sid: string): boolean {
  if (sids(launch.peers).includes(sid) || sids(launch.moved).includes(sid)) return false
  return text(launch.session) !== '' && movedTo(state, text(launch.session)) === sid
}

/** Whether launch.json makes main's transport the server's (app/subagent_files.py transport): `transport: server`, or
 *  0.8.0's `mode: browser`, or a record with neither. */
function serverOf(launch: Json): boolean {
  const kind = text(launch.transport)
  if (kind === 'local' || kind === 'server') return kind === 'server'
  return launch.mode !== 'terminal'
}

/** launch.json read again (module note): a peer that became main starts taking main's requests and writing
 *  module.json, main another took main from stops; main whose transport a press made the server's takes the requests
 *  still waiting in subagents.json (H5), then goes on over HTTP for the rest of the session. True when it switched. One
 *  look at a time. */
function recheck($: Engine, m: State): Promise<boolean> {
  if (!m.rechecking) m.rechecking = recheckNow($, m).finally(() => { m.rechecking = null })
  return m.rechecking
}

async function recheckNow($: Engine, m: State): Promise<boolean> {
  if (!m.active || !m.file) return false
  const launch = await readJson($, trusted(m, 'launch.json'))
  if (!launch) return false
  const state = (await readJson($, trusted(m, 'subagents.json'))) ?? {}
  const main = isMain(launch, state, m.session)
  if (main && serverOf(launch)) {
    if (m.peer) m.peer = false
    else await takeFile($, m)
    await m.queue
    m.gen += 1 // the files' polls stop
    m.file = false
    void begin($, m, m.cwd)
    return true
  }
  if (main && m.peer) {
    m.peer = false
    m.out = { ...m.out, session: m.session, version: m.version, load: hex(crypto.getRandomValues(new Uint8Array(8))), gone: false }
    await writeOut($, m)
    void watchPlan($, m, m.gen)
    await takeFile($, m)
  } else if (!main && !m.peer) {
    m.peer = true
  }
  return false
}

/** Every FILE_POLL_MS: launch.json read again when it changed (recheck), roles.json registered again when it changed,
 *  the requests subagents.json addresses to this module taken when it changed, and the heartbeat every FILE_BEAT_MS
 *  (module note). */
async function pollFiles($: Engine, m: State, gen: number): Promise<void> {
  let beat = Date.now()
  while (m.active && gen === m.gen) {
    try {
      const launch = await stamp($, trusted(m, 'launch.json'))
      if (launch !== m.stamps.launch) {
        m.stamps.launch = launch
        if (await recheck($, m)) return
      }
      const roles = await stamp($, trusted(m, 'roles.json'))
      if (roles && roles !== m.stamps.roles) {
        m.stamps.roles = roles
        if (await readRoles($, m)) {
          m.queue = m.queue.then(() => registerAll($, m)).catch(() => undefined)
          await m.queue
        }
      }
      const state = await stamp($, trusted(m, 'subagents.json'))
      if (state && state !== m.stamps.state) {
        m.stamps.state = state
        await takeFile($, m)
      }
      if (Date.now() - beat >= FILE_BEAT_MS) {
        beat = Date.now()
        await writeOut($, m)
      }
    } catch {
      // the next look tries again
    }
    await $.clock.sleep(FILE_POLL_MS)
  }
}

/** The requests subagents.json addresses to this module that it has not taken, oldest first, each taken (module.json
 *  `taken`) and handled in turn, its answer written under its id. */
async function takeFile($: Engine, m: State): Promise<void> {
  if (m.peer) return
  const state = await readJson($, trusted(m, 'subagents.json'))
  if (!state || !isObj(state.requests)) return
  const now = Date.now()
  const mine = Object.entries(state.requests)
    .filter((x): x is [string, Json] => isObj(x[1]) && x[1].kind === MODULE_KIND && x[1].module === 'pending' && !m.out.taken.includes(x[0])
      && (!text(x[1].session) || text(x[1].session) === m.session) && typeof x[1].expires_at === 'number' && x[1].expires_at * 1000 > now)
    .sort((a, b) => Number(a[1].asked_at ?? 0) - Number(b[1].asked_at ?? 0))
  if (!mine.length) return
  m.out.taken = [...m.out.taken, ...mine.map(([id]) => id)].slice(-KEPT)
  await writeOut($, m)
  for (const [id, r] of mine) {
    const req: Request = { id, op: text(r.op), args: isObj(r.args) ? r.args : {} }
    if (BESIDE.has(req.op)) {
      // a model call's answer is a file of its own beside its request's (module note)
      void (async () => {
        const answer = await modelCall($, m, id, req.op, req.args)
        const call = text(req.args.call)
        if (req.op !== 'cancel' && CALL_ID.test(call)) await $.fs.write(trusted(m, `completions/${call}.answer.json`), JSON.stringify(answer))
      })().catch(() => undefined)
      continue
    }
    const due = Number(r.expires_at) * 1000
    m.queue = m.queue
      .then(async () => {
        const answer = Date.now() > due ? { error: 'the request expired before thimble’s module reached it' } : await handle($, m, req)
        const answers = { ...m.out.answers, [id]: answer }
        m.out.answers = Object.fromEntries(Object.entries(answers).slice(-KEPT))
        await writeOut($, m)
      })
      .catch(() => undefined)
  }
}

/** After /clear or /resume on local transport: the new session id, the move --rekey recorded to it, module.json under
 *  it, the record again, and the notes --rekey left for the new main (subagents.json `module.notes`). */
async function followFile($: Engine, m: State, old: string): Promise<void> {
  let sid = old
  for (let waited = 0; waited < SESSION_WAIT_MS && sid === old; waited += SESSION_TICK_MS) {
    await $.clock.sleep(SESSION_TICK_MS)
    sid = await $.session.id()
  }
  if (!m.active || sid === old) return
  let state: Json = {}
  for (let waited = 0; waited < SESSION_WAIT_MS; waited += RETRY_MS / 4) {
    state = (await readJson($, trusted(m, 'subagents.json'))) ?? {}
    if (movedTo(state, old) === sid) break
    await $.clock.sleep(RETRY_MS / 4)
  }
  if (movedTo(state, old) !== sid) {
    stop(m) // no record says the new session is main's: idle, as a refused hello leaves it
    return
  }
  m.session = sid
  m.out.session = sid
  await writeOut($, m)
  await fetchStateFile($, m)
  const notes = isObj(state.module) && isObj(state.module.notes) ? (state.module.notes as Json) : {}
  if (text(notes.session) === sid && Array.isArray(notes.lines)) {
    for (const line of notes.lines) if (typeof line === 'string' && line) await note($, line)
  }
}

// ------------------------------------------------------------------------------------------------ the file guard

/** A path made absolute against the working directory, `~` read as $HOME, `.`, `..` and repeated slashes folded. */
function normal(m: State, path: string): string {
  let p = path.trim()
  if (p === '~') p = m.user
  else if (p.startsWith('~/')) p = `${m.user}${p.slice(1)}`
  if (!p.startsWith('/')) p = `${m.cwd}/${p}`
  const parts: string[] = []
  for (const part of p.split('/')) {
    if (part === '' || part === '.') continue
    if (part === '..') parts.pop()
    else parts.push(part)
  }
  return `/${parts.join('/')}`
}

/** Whether `path` is one of `roots` or inside one. */
function under(path: string, roots: string[]): boolean {
  return roots.some(r => {
    const root = r.replace(/\/+$/, '')
    return root !== '' && (path === root || path.startsWith(`${root}/`))
  })
}

/** Where a path lands, every link followed: its own realPath, else its folder's with its name (a file not there yet);
 *  '' when neither resolves. */
async function placed($: Engine, path: string): Promise<string> {
  const own = await $.fs.stat(path, { resolve: true }).catch(() => undefined)
  if (own?.realPath) return own.realPath
  const cut = path.lastIndexOf('/')
  const dir = await $.fs.stat(cut > 0 ? path.slice(0, cut) : '/', { resolve: true }).catch(() => undefined)
  return dir?.realPath ? `${dir.realPath.replace(/\/+$/, '')}/${path.slice(cut + 1)}` : ''
}

/** The rules before the server's: the token files in thimble's home, as spelled and as resolved. */
function fallbackRules(m: State): Rules {
  const homes = [m.home, m.homeReal].filter((h, i, all) => h !== '' && all.indexOf(h) === i)
  return { private: homes.flatMap(h => PRIVATE_NAMES.map(n => `${h}/${n}`)), records: [], corpus: null, web_off: false, reasons: { private: PRIVATE_FALLBACK } }
}

/** The rules GET /api/module/roles or roles.json carries (userconf.module_rules), with the token files of thimble's
 *  home as this module sees it kept; null when there are none. */
function parseRules(m: State, v: unknown): Rules | null {
  if (!isObj(v)) return null
  const paths = (x: unknown): string[] => (Array.isArray(x) ? x.filter((p): p is string => typeof p === 'string' && p.startsWith('/')) : [])
  const base = fallbackRules(m)
  const reasons: Record<string, string> = { ...base.reasons }
  if (isObj(v.reasons)) for (const [key, why] of Object.entries(v.reasons)) if (text(why)) reasons[key] = text(why)
  return {
    private: [...new Set([...base.private, ...paths(v.private)])],
    records: paths(v.records),
    corpus: text(v.corpus).startsWith('/') ? text(v.corpus) : null,
    web_off: v.web_off === true,
    reasons,
  }
}

/** The path a file tool's call names: Grep's and Glob's `path`, else the working directory; the others' `file_path`
 *  or `notebook_path`. '' for no file tool, or none named. */
function pathOf(m: State, e: Json): string {
  const tool = text(e.tool)
  if (!FILE_TOOLS.has(tool)) return ''
  return SEARCH_TOOLS.has(tool) ? text(e.path) || m.cwd : text(e.file_path) || text(e.notebook_path)
}

const reason = (rules: Rules, kind: string): string => rules.reasons[kind] || (kind === 'private' ? PRIVATE_FALLBACK : REFUSED)

/** Why the file guard refuses the call (module note), '' when it does not. */
async function refusal($: Engine, m: State, e: Json): Promise<string> {
  const tool = text(e.tool)
  if (tool === 'Bash') {
    if (!m.active || !text(e.command)) return ''
    if (!m.rules) await prepare($, m)
    return bashNamesPrivate(m, text(e.command)) ? reason(m.rules ?? fallbackRules(m), 'private') : ''
  }
  if (WEB_TOOLS.has(tool)) {
    if (!m.rules) await prepare($, m)
    const rules = m.rules ?? fallbackRules(m)
    return rules.web_off ? reason(rules, 'web') : ''
  }
  const raw = pathOf(m, e)
  if (!raw) return ''
  if (!m.rules) await prepare($, m)
  const rules = m.rules ?? fallbackRules(m)
  const spelled = normal(m, raw)
  const real = await placed($, spelled)
  const paths = real && real !== spelled ? [spelled, real] : [spelled]
  const homes = [m.home, m.homeReal].filter(Boolean)
  if (paths.some(p => under(p, rules.private) || (SEARCH_TOOLS.has(tool) && homes.includes(p)))) return reason(rules, 'private')
  if (!EDIT_TOOLS.has(tool)) return ''
  if (paths.some(p => under(p, rules.records))) return reason(rules, 'records')
  if (rules.corpus !== null && paths.some(p => under(p, [rules.corpus as string]))) return reason(rules, 'data')
  return ''
}

const escaped = (s: string): string => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')

/** Whether a Bash command names one of BASH_PRIVATE under thimble's home literally: the home as spelled, as resolved,
 *  as $THIMBLE_HOME, and for the default home as ~/.thimble and $HOME/.thimble (module note). */
function bashNamesPrivate(m: State, command: string): boolean {
  const homes = new Set([m.home, m.homeReal, '$THIMBLE_HOME', '${THIMBLE_HOME}'].filter(Boolean))
  if (m.user && m.home === `${m.user}/.thimble`) for (const h of ['~/.thimble', '$HOME/.thimble', '${HOME}/.thimble']) homes.add(h)
  const names = BASH_PRIVATE.map(escaped).join('|')
  return [...homes].some(h => new RegExp(`${escaped(h)}/+(?:${names})(?![A-Za-z0-9_.-])`).test(command))
}

/** For the guard's catch, with no file system call: whether the call names a token file as spelled. */
function namesPrivate(m: State, e: Json): boolean {
  const raw = pathOf(m, e)
  if (!raw) return false
  const p = normal(m, raw)
  const rules = m.rules ?? fallbackRules(m)
  return under(p, rules.private) || (SEARCH_TOOLS.has(text(e.tool)) && [m.home, m.homeReal].filter(Boolean).includes(p))
}

const moduleOn = async ($: Engine): Promise<boolean> => OFF.has(((await $.env.get('THIMBLE_NO_MODULE')) ?? '').trim().toLowerCase())

/** This session's marker, <home>/up/<session>.active (activation writes it, app/activate.py): the workspace it names,
 *  null when thimble is not on in the session. */
async function readMarker($: Engine): Promise<Activated | null> {
  const name = (await $.session.id()).replace(/[^A-Za-z0-9_-]/g, '')
  const got = name ? await readJson($, `${await thimbleHome($)}/up/${name}.active`) : null
  if (!got || !text(got.path)) return null
  return { ws: text(got.ws), path: text(got.path), cwd: text(got.cwd), via: text(got.via), role: got.role === 'peer' ? 'peer' : 'main', at: Number(got.at) || 0 }
}

/** Thimble on in this session (bridgeActivated, or the marker): over HTTP when launch.json makes this session's
 *  transport the server's, else through the files; the agent types are registered before it returns. Nothing in a
 *  session that is not interactive, with THIMBLE_NO_MODULE, when it is on already, or when the workspace has no
 *  launch.json to follow (the end of main's next turn looks again). */
async function start($: Engine, m: State, a: Activated): Promise<void> {
  if (m.active || !m.interactive || !(await moduleOn($))) return
  const ws = a.path.replace(/\/+$/, '')
  const launch = ws ? await readJson($, `${ws}/trusted/launch.json`) : null
  if (!launch || m.active) return
  m.active = true
  m.ws = ws
  const cwd = a.cwd || m.cwd
  const state = (await readJson($, `${ws}/trusted/subagents.json`)) ?? {}
  if (serverOf(launch) && isMain(launch, state, await $.session.id())) await begin($, m, cwd)
  else await fileBegin($, m, cwd, ws, launch)
}

// the module memory of the latest register (one per load of the module), for bridgeActivated
const live: { m: State | null } = { m: null }

/** thimble turned on in this session by the terminal UI (term/activate.ts, C13 of the 0.9.0 build): register thimble's
 *  agent types and turn the bridge on in this turn (start). A second call, or a call once the marker turned it on,
 *  changes nothing. */
export async function bridgeActivated($: Engine, a: Activated): Promise<void> {
  const m = live.m
  if (m) await start($, m, a)
}

/** The check's name in a check run's description, `check: <name> · <what it reads>` (backend/app/checks.py _launch). */
function checkOf(description: string): string {
  return /^check: (.+) · [^·]*$/.exec(description)?.[1]?.trim() || 'A thimble check'
}

/** The name of the check (`Judgment calls`) that `agentId` runs, when it is an agent of thimble's check role this session
 *  started; the terminal UI drops its hand-back unless main's own Agent call started it (typedCheck). */
export function checkName(agentId: string): string | undefined {
  return live.m?.checks.get(agentId)
}

/** Whether `agentId` runs a check that main's own Agent call started (run_check, a typed start), which reports to main as
 *  any of main's subagents does: its hand-back, or Claude Code's notification of its end, reaches main, which answers it
 *  in one line (backend/app/checks.py). The terminal UI drops those of the checks this module started (checkName). */
export function typedCheck(agentId: string): boolean {
  const m = live.m
  return Boolean(m && m.checks.has(agentId) && !m.started.has(agentId))
}

/** The reason Claude Code prints when the terminal UI drops the hand-back of `agentId`, when it is a model call's agent
 *  this module spawned (the server names it: `thimble checked the card "…"`); undefined for any other agent. */
export function callDone(agentId: string): string | undefined {
  return live.m?.calls.get(agentId)
}

/** The agent whose Claude Code task notification `text` is (`<task-notification>…<task-id>{id}</task-id>`), when it is
 *  an agent of thimble's check or call role that this session started (checkName, callDone), whose end thimble shows
 *  itself, so the terminal UI drops the notification as it does the agent's hand-back (bug hunt E10: a check that ended
 *  its turn with work of its own in the background sent main two). Undefined for any other text, and for a batch of
 *  notifications that names any other agent. */
export function ownNotice(text: string): string | undefined {
  const m = live.m
  const ids = [...text.matchAll(/<task-notification>\s*<task-id>\s*([^<\s]+)\s*<\/task-id>/g)].map(x => x[1] ?? '')
  if (!m || !ids.length || text.split('<task-notification>').length - 1 !== ids.length) return undefined
  return ids.every(id => m.checks.has(id) || m.calls.has(id)) ? ids[0] : undefined
}

/** The agent a `task_status` row of Claude Code's names (its text, as a request carries it: `Task <id> (type:
 *  local_agent) (status: completed) (description: …)`, `Background agent "…" (<id>) is still running`), when it is an
 *  agent of thimble's check or call role that this session started (checkName, callDone), whose end thimble shows
 *  itself; undefined for any other. */
export function ownTask(text: string): string | undefined {
  const m = live.m
  if (!m) return undefined
  return [...m.checks.keys(), ...m.calls.keys()].find(id => id !== '' && text.includes(id))
}

// the words of Claude Code's task notification that only points at the agent's hand-back, which main has already read
const POINTER = /<result>\s*This agent's report was delivered to you as a message from /
/** What main reads of such a notification (module note). */
export const POINTER_NOTE = "Write nothing about this notice: it is about one of thimble's agents, whose report you have already read."


/** The agent whose Claude Code task notification `text` only points at the report it handed back to main (`This
 *  agent's report was delivered to you as a message from "…" … it is not repeated here`), when it is an agent of
 *  thimble's types this session started (module note); undefined for any other text, and for a batch of notifications. */
export function ownPointer(text: string): string | undefined {
  const m = live.m
  const ids = [...text.matchAll(/<task-notification>\s*<task-id>\s*([^<\s]+)\s*<\/task-id>/g)].map(x => x[1] ?? '')
  if (!m || ids.length !== 1 || text.split('<task-notification>').length !== 2 || !POINTER.test(text)) return undefined
  return m.ours.has(ids[0]!) ? ids[0] : undefined
}

/** A stored row's text: its text blocks, or its content when that is a string. */
function rowText(content: unknown): string {
  if (typeof content === 'string') return content
  return Array.isArray(content) ? content.map(b => (isObj(b) && b.type === 'text' ? text(b.text) : '')).join('\n') : ''
}

export const register: Register = on => {
  const m = fresh()
  live.m = m

  on('session.start', async ($, e, next) => {
    const r = await next(e)
    m.cwd = e.cwd
    m.interactive = e.isInteractive === true
    // the scope check, before any fetch or registration (module note): a session thimble is on in already (a resumed
    // one, or an activation before this load of the module)
    const marker = m.interactive && (await moduleOn($)) ? await readMarker($) : null
    if (marker) await start($, m, marker)
    return r
  })

  // Claude Code's word to main of thimble's own check and card check agents, after a compaction: left out (module note)
  on('prompt.attachment', { type: 'task_status' }, async ($, e, next) => (e.agentId === undefined && ownTask(e.text) !== undefined ? { text: null } : next(e)))
    .catch(($, e, next) => next(e)) // not a guard: if it fails, main reads the row as Claude Code wrote it

  // Claude Code's notification of one of thimble's agents that only points at the hand-back main read: kept as
  // POINTER_NOTE alone, which asks main for no words and draws no row (module note)
  on('session.append', { door: 'prompt' }, async ($, e, next) =>
    e.agentId === undefined && e.origin.kind === 'task-notification' && ownPointer(rowText(e.message.content)) !== undefined
      ? next({ ...e, message: { ...e.message, content: [{ type: 'text', text: POINTER_NOTE }] } })
      : next(e))
    .catch(($, e, next) => next(e)) // not a guard: if it fails, main reads the notification as Claude Code wrote it

  // thimble's types are offered to a model only inside an Agent call that names them, or once one started (module note)
  on('agent.offer', async ($, e, next) => (ours(m, e.agent) && !m.dispatching.has(e.agent) && !m.used.has(e.agent) ? { isOffered: false } : next(e)))
    .catch(($, e, next) => next(e)) // not a guard: if it fails, the type is offered as Claude Code offers it

  // the file guard, in every session, and an Agent or SendMessage call with its types offered while it runs (module note)
  on('tool.call', async ($, e, next) => {
    const why = await refusal($, m, e as unknown as Json)
    if (why) return { deny: why }
    const types = dispatched(m, e as unknown as Json)
    return types.length ? offering(m, types, () => next(e)) : next(e)
  }).catch(($, e, next) => (next.called ? next(e) : namesPrivate(m, e as unknown as Json) ? { deny: reason(m.rules ?? fallbackRules(m), 'private') } : next(e)))

  on('agent.spawn', async ($, e, next) => {
    if (!m.active) return next(e)
    const got = await spawning($, m, e)
    const r = await next(got.model || got.prompt ? { ...e, ...(got.model ? { model: got.model } : {}), ...(got.prompt ? { prompt: got.prompt } : {}) } : e)
    if (r.agentId && ours(m, e.subagentType ?? '')) {
      m.used.add(e.subagentType ?? '') // offered from now on (module note)
      m.ours.add(r.agentId)
    }
    if (r.agentId) {
      if (got.effort !== undefined) m.efforts[r.agentId] = got.effort
      if (roleOf(e.subagentType ?? '') === 'check') m.checks.set(r.agentId, checkOf(e.description ?? ''))
      if (got.typed) delete m.requests[got.typed]
    }
    return r
  }).catch(($, e, next) => next(e)) // not a guard: if it fails, the call goes on as Claude Code made it

  on('turn.step', async function* ($, e, next) {
    const effort = m.active && e.agentId !== undefined ? m.efforts[e.agentId] : undefined
    // a request with no effort is to a model without one, which takes none
    return yield* next(effort !== undefined && e.effort !== undefined ? { ...e, effort: effort as typeof e.effort } : e)
  })

  // main's own turns, whatever the scope check found, so that a stop of main names the turn that runs (abortTurn)
  on('turn.start', async ($, e, next) => {
    const r = await next(e)
    if (e.agentId === undefined) m.turn = e.turnId
    return r
  })

  on('turn.complete', async ($, e, next) => {
    const r = await next(e)
    if (e.agentId === undefined && e.turnId === m.turn) {
      m.turn = ''
      for (const ended of m.turnEnded.splice(0)) ended()
    }
    if (m.active && e.agentId !== undefined && m.started.has(e.agentId)) {
      const refusal = e.reason === 'refusal' && isObj(e.refusal) ? { refusal: e.refusal } : {}
      if (m.file) {
        m.out.ended = [...m.out.ended, { n: ++m.n, agentId: e.agentId, answer: text(e.answer), reason: text(e.reason), ...refusal, at: Date.now() }].slice(-KEPT)
        void writeOut($, m)
      } else {
        void call($, m, 'POST', '/api/module/ended', { cwd: m.cwd, session: m.session, agentId: e.agentId, answer: e.answer, reason: e.reason, ...refusal })
      }
    } else if (e.agentId === undefined && m.interactive) {
      if (m.active && m.file) void recheck($, m) // launch.json at each of main's turns (module note)
      else if (!m.active && (await moduleOn($))) {
        // an activation made outside the terminal UI, which tells no one but the marker (module note)
        const marker = await readMarker($)
        if (marker) void start($, m, marker)
      }
    }
    return r
  })

  on('session.end', async ($, e, next) => {
    const r = await next(e)
    if (!m.active) return r
    if (e.reason === 'clear' || e.reason === 'resume') void (m.file ? followFile($, m, e.sessionId) : follow($, m, e.sessionId))
    else {
      stop(m)
      if (m.file) {
        m.out.gone = true
        await writeOut($, m)
      }
    }
    return r
  })
}

