// What main's chat draws under its rows, kept in the workspace so a resumed session draws it again. Claude Code keeps a
// row's uuid across `--continue` and `--resume`, and the drawings stand under rows by that uuid (their `requestId`), but
// the plugin's state lives only as long as its process. So each row's cards, its answer's footer, its `↳ thread` rows
// and its `↳ view` rows are written to `<workspace>/terminal/chat.json` as they are set, and read back
// into the state when thimble turns on or the session starts again. So is what the thimble line counts as the session's
// citations, by the session's id (`sessions`): its answers' chat citations (C13 citeIndex) and the cards the session
// drew (term.ts rt.shown), so a resumed session counts the same ones (bug hunt H7: 14 before `claude -c`, 9 after). The
// file names the workspace folder it was written for (`folder`): /thimble fresh and restore put another folder in the
// workspace's place, whose own file this process reads instead once it sees the change (swapKept; bug hunt 7, H11), and
// a file that names another folder is a write of the run before, made before the change was seen. The file is the
// terminal UI's own: the browser does not read it.
//
// No `$` here: register.tsx reads and writes through the context (hooks/ctx.ts).
import type { ChatSignal, CiteRow, TermAnswer, TermHome } from './types'
import type { Ctx } from './ctx'

/** What the file is read and written with. */
type Io = Pick<Ctx, 'read' | 'write'>

/** What one row of main's chat carries under it; `writer`, the writer run its `↳ The writer …` line reports (its chat)
 *  and whether it said that run's end first; `repeat`, its `↳` lines that answer a subagent run's second report after
 *  an earlier row answered the first, which are hidden. */
export type KeptRow = { cards?: string[]; answer?: TermAnswer; threads?: ChatSignal[]; views?: string[]; writer?: { chat: string; first: boolean }; repeat?: string[] }

/** What a session's citations are counted over (citesview.tsx citeItems): its answers' chat citations and the cards it
 *  drew, in the order it drew them. */
export type KeptSession = { cites: CiteRow[]; shown: string[] }

/** The file: each row's drawings by its uuid, oldest first, the last turn's text and cards (`/thimble cite` and
 *  `/thimble card` open them by number), what the workspace held when home was last seen (`seen`), so the row above
 *  the prompt counts what came after across a relaunch, each session's citations by its id, oldest first, and the
 *  workspace folder it is for (`folder`, `thimble state home`'s `instance`). */
export type Kept = { rows: Record<string, KeptRow>; last: { reply: string; cards: string[] }; seen?: TermHome; sessions?: Record<string, KeptSession>; folder?: string }

/** The workspace file, under the workspace folder. */
export const KEPT_FILE = 'terminal/chat.json'
/** The rows kept, the newest. */
const ROWS_MAX = 400
/** The sessions whose citations are kept, the newest; and of each, the chat citations (citeIndex keeps as many) and the
 *  cards. */
const SESSIONS_MAX = 8
const CITES_MAX = 2000
const SHOWN_MAX = 2000

export const keptEmpty = (): Kept => ({ rows: {}, last: { reply: '', cards: [] } })

const strings = (v: unknown): string[] => (Array.isArray(v) ? v.filter((x): x is string => typeof x === 'string' && x !== '') : [])

function signalsOf(v: unknown): ChatSignal[] {
  return Array.isArray(v) ? v.filter((s): s is ChatSignal => Boolean(s) && typeof (s as ChatSignal).thread === 'string' && typeof (s as ChatSignal).turn === 'number').map(s => ({ thread: s.thread, turn: s.turn })) : []
}

function answerOf(v: unknown): TermAnswer | undefined {
  const a = v as Partial<TermAnswer> | null | undefined
  if (!a || typeof a !== 'object' || typeof a.text !== 'string') return undefined
  return { rows: strings(a.rows), text: a.text, cards: strings(a.cards) }
}

/** The file's text as Kept: lenient, a part it cannot read is left out. */
export function parseKept(raw: string): Kept {
  let v: unknown
  try {
    v = JSON.parse(raw)
  } catch {
    return keptEmpty()
  }
  const o = (v ?? {}) as { rows?: unknown; last?: { reply?: unknown; cards?: unknown } }
  const rows: Record<string, KeptRow> = {}
  for (const [k, r] of Object.entries(o.rows && typeof o.rows === 'object' ? (o.rows as Record<string, unknown>) : {})) {
    const x = (r ?? {}) as Record<string, unknown>
    const row: KeptRow = {}
    const cards = strings(x.cards)
    const threads = signalsOf(x.threads)
    const views = strings(x.views)
    const answer = answerOf(x.answer)
    const writer = x.writer as { chat?: unknown; first?: unknown } | null | undefined
    if (writer && typeof writer === 'object' && typeof writer.chat === 'string' && writer.chat) row.writer = { chat: writer.chat, first: writer.first === true }
    const repeat = strings(x.repeat)
    if (repeat.length) row.repeat = repeat
    if (cards.length) row.cards = cards
    if (threads.length) row.threads = threads
    if (views.length) row.views = views
    if (answer) row.answer = answer
    if (Object.keys(row).length) rows[k] = row
  }
  const seen = seenOf((o as { seen?: unknown }).seen)
  const sessions = sessionsOf((o as { sessions?: unknown }).sessions)
  const folder = (o as { folder?: unknown }).folder
  return { rows, last: { reply: typeof o.last?.reply === 'string' ? o.last.reply : '', cards: strings(o.last?.cards) }, ...(seen ? { seen } : {}), ...(sessions ? { sessions } : {}), ...(typeof folder === 'string' && folder ? { folder } : {}) }
}

function citeRowsOf(v: unknown): CiteRow[] {
  if (!Array.isArray(v)) return []
  return v.flatMap((x): CiteRow[] => {
    const r = (x ?? {}) as Partial<Record<keyof CiteRow, unknown>>
    if (typeof r.id !== 'string' || typeof r.raw !== 'string' || typeof r.ref !== 'string' || typeof r.row !== 'string') return []
    return [{ id: r.id, raw: r.raw, display: typeof r.display === 'string' ? r.display : null, ref: r.ref, row: r.row, at: typeof r.at === 'number' ? r.at : 0 }]
  })
}

function sessionsOf(v: unknown): Record<string, KeptSession> | undefined {
  if (!v || typeof v !== 'object') return undefined
  const out: Record<string, KeptSession> = {}
  for (const [sid, x] of Object.entries(v as Record<string, unknown>)) {
    const o = (x ?? {}) as { cites?: unknown; shown?: unknown }
    if (sid) out[sid] = { cites: citeRowsOf(o.cites), shown: strings(o.shown) }
  }
  return Object.keys(out).length ? out : undefined
}

function seenOf(v: unknown): TermHome | undefined {
  const o = v as Partial<Record<keyof TermHome, unknown>> | null | undefined
  if (!o || typeof o !== 'object') return undefined
  const n = (x: unknown) => (typeof x === 'number' && Number.isFinite(x) ? x : 0)
  return { cards: n(o.cards), labels: n(o.labels), docs: n(o.docs), threads: n(o.threads), views: n(o.views), files: n(o.files), at: n(o.at) }
}

/** The file's text: the newest ROWS_MAX rows. */
export function keptJson(k: Kept): string {
  const keys = Object.keys(k.rows)
  const rows = Object.fromEntries(keys.slice(Math.max(0, keys.length - ROWS_MAX)).map(key => [key, k.rows[key]!]))
  const sids = Object.keys(k.sessions ?? {})
  const sessions = Object.fromEntries(sids.slice(Math.max(0, sids.length - SESSIONS_MAX)).map(sid => [sid, k.sessions![sid]!]))
  return JSON.stringify({ rows, last: k.last, ...(k.seen ? { seen: k.seen } : {}), ...(sids.length ? { sessions } : {}), ...(k.folder ? { folder: k.folder } : {}) })
}

/** `kept` with one row's part set (a row moves to the end, the newest). */
export function withRow(k: Kept, row: string, part: KeptRow): Kept {
  const rows = { ...k.rows }
  const cur = rows[row] ?? {}
  delete rows[row]
  rows[row] = { ...cur, ...part }
  return { ...k, rows }
}

// what this process holds of the file, and the writes in order
let kept: Kept = keptEmpty()
let writes: Promise<void> = Promise.resolve()

function pathOf(ws: string): string {
  return `${ws.replace(/\/+$/, '')}/${KEPT_FILE}`
}

/** The file as earlier sessions left it, merged under what this process set already (a reload keeps its own). */
export async function loadKept(cx: Io, ws: string): Promise<Kept> {
  const got = parseKept(await cx.read(pathOf(ws)).catch(() => ''))
  const seen = kept.seen ?? got.seen
  const sessions = { ...got.sessions, ...kept.sessions }
  const folder = kept.folder ?? got.folder
  kept = { rows: { ...got.rows, ...kept.rows }, last: kept.last.reply || kept.last.cards.length ? kept.last : got.last, ...(seen ? { seen } : {}), ...(Object.keys(sessions).length ? { sessions } : {}), ...(folder ? { folder } : {}) }
  return kept
}

/** The workspace folder this process's file is for, as the first read of home names it (term.ts followWorkspace):
 *  written with the file from now on. */
export function keptFolder(folder: string): void {
  if (folder) kept = { ...kept, folder }
}

/** Another folder took the workspace's place (/thimble fresh, /thimble restore: term.ts followWorkspace): what this
 *  process held goes, and the new folder's file is read once the writes under way have landed, unless it names another
 *  folder, a write of the run before made before the change was seen; none in a new folder. */
export async function swapKept(cx: Io, ws: string, folder: string): Promise<Kept> {
  await writes
  const got = parseKept(await cx.read(pathOf(ws)).catch(() => ''))
  kept = { ...(got.folder && got.folder !== folder ? keptEmpty() : got), folder }
  return kept
}

/** What session `sid`'s citations are counted over, kept (the newest of each), and the file written. */
export async function keepSession(cx: Io, ws: string, sid: string, part: Partial<KeptSession>): Promise<void> {
  if (!sid) return
  const sessions = { ...kept.sessions }
  const cur = sessions[sid] ?? { cites: [], shown: [] }
  delete sessions[sid]
  sessions[sid] = { cites: (part.cites ?? cur.cites).slice(-CITES_MAX), shown: (part.shown ?? cur.shown).slice(-SHOWN_MAX) }
  kept = { ...kept, sessions }
  await save(cx, ws)
}

/** What session `sid`'s citations were counted over, as the file read at the session's start (or this process) keeps
 *  it; null for a session it holds nothing of. */
export function keptSession(sid: string): KeptSession | null {
  return (sid && kept.sessions?.[sid]) || null
}

/** What the workspace held when home was last seen, kept. */
export async function keepSeen(cx: Io, ws: string, seen: TermHome): Promise<void> {
  const k = kept.seen
  if (k && (Object.keys(seen) as (keyof TermHome)[]).every(x => k[x] === seen[x])) return
  kept = { ...kept, seen }
  await save(cx, ws)
}

/** What the workspace held when home was last seen, as the file read at the session's start (or this process) keeps it. */
export function keptSeen(): TermHome | null {
  return kept.seen ?? null
}

/** One row's part kept, and the file written (one write at a time, in order). */
export async function keepRow(cx: Io, ws: string, row: string, part: KeptRow): Promise<void> {
  if (!row) return
  kept = withRow(kept, row, part)
  await save(cx, ws)
}

/** The last turn's text and cards kept. */
export async function keepLast(cx: Io, ws: string, reply: string, cards: string[]): Promise<void> {
  kept = { ...kept, last: { reply, cards } }
  await save(cx, ws)
}

async function save(cx: Io, ws: string): Promise<void> {
  const text = keptJson(kept)
  writes = writes.then(() => cx.write(pathOf(ws), text)).catch(() => undefined)
  await writes
}

/** For the tests: what this process holds, and a fresh start. */
export function keptNow(): Kept {
  return kept
}
export function resetKept(): void {
  kept = keptEmpty()
  writes = Promise.resolve()
}

