import type { LabelPatch } from './term'
import type { Ctx } from './ctx'
import { act } from './data'
import { closeView, onViewAct, openViewState, retryView, sendEvent, viewFaultOf, viewFor, viewProps } from './viewhost'
import { openInBrowser } from './offramp'
import type { ViewFrame } from './viewhost'
import { ENTRY_KEY, entryEl, entryHeight, entryPrompt } from './entry'

export type PaneEvent = MatchedEvent<'ui.render', { component: 'Pane'; requestId: string }>

type Obj = Record<string, unknown>
type El = { Box: ElementConstructor<BoxProps>; Text: ElementConstructor<TextProps>; Button: ElementConstructor<ButtonProps> }
export type Key = { key: string; hotkey: string; onPress: () => void }
const isObj = (v: unknown): v is Obj => Boolean(v) && typeof v === 'object' && !Array.isArray(v)
const str = (v: unknown): string => (typeof v === 'string' ? v : v === null || v === undefined ? '' : String(v))
const num = (n: number) => Math.round(n).toLocaleString('en-US')
const plural = (n: number, w: string, many = `${w}s`) => `${num(n)} ${n === 1 ? w : many}`
const dim = (s: string): Seg => ({ s, fg: COLORS.dim })

/** What the card pane's subtitle says of a card check that ended in an error: its revision of the card would not run,
 *  or it could not finish (it ran past its time, or the reading or the drawing failed). */
const CHECK_UNRUN = "its check's revision would not run"
const CHECK_UNFINISHED = 'its check could not finish'

// ------------------------------------------------------------------------------------------------ opening

/** The `element` of a thread asked about a whole answer, from the answer's footer. */
export const ANSWER_ELEMENT = 'answer'

/** What a new thread is told it was asked about, beside its anchor: `anchor` (a ref, or none for words on screen),
 *  `anchorText` (the words), `element` (where it was asked, a document's passage). */
export type AskOver = { anchor?: string | null; anchorText?: string; element?: string; about?: string }

/** What a new side thread about a target is told and named (the ask view's panel, and an entry box's thread): the
 *  target, its anchor and words, `about` (what names it), the thread on the panel's trail it hangs under, and where it
 *  was asked. */
export type AskAbout = { target: Target; anchor: string | null; anchorText: string; about: string; parent?: string; element?: string }

/** What a side thread about `t` is told and named. A thread asked from inside the panel hangs under the thread on the
 *  panel's trail. Its words: a passage's, a mark's name and value, a card by its question, a citation's sentence. */
export async function askAbout(cx: Ctx, t: Target, over: AskOver = {}): Promise<AskAbout> {
  const c = citationOf(t)
  const anchor = over.anchor !== undefined ? over.anchor : t.kind === 'sentence' ? null : t.cardId && t.kind !== 'record' && t.kind !== 'citation' ? `card:${t.cardId}` : c?.ref ?? (t.cardId ? `card:${t.cardId}` : null)
  const anchorText =
    over.anchorText !== undefined
      ? over.anchorText
      : t.kind === 'sentence'
        ? plainCites(t.text ?? '')
        : t.kind === 'card'
          ? t.cardId
            ? await cardName(cx, t.cardId)
            : ''
          : t.kind === 'citation'
            ? plainCites(claimSentence(t.claim)) || (c ? citeLabel(c) : '')
            : plainCites(t.label ? `${t.label}` : t.text ?? '')
  const parent = (await inPanelNow(cx)) ? threadOnTrail(((await cx.nav()) ?? NAV_EMPTY).trail) : ''
  // the subject as the thread and home name it (anchorName): a card by its question, a citation by its words
  const about = over.about ?? (t.kind === 'sentence' && t.label ? t.label : t.kind === 'card' && !t.text && anchorText ? anchorText : targetLabel(t, 60))
  return { target: t, anchor, anchorText, about, ...(parent ? { parent } : {}), ...(over.element ? { element: over.element } : {}) }
}

/** A side thread about a target: the ask view, its entry box first (a `?` beside a passage, a card's title, a
 *  selection, an answer's footer, a document's comment). */
export async function openAsk(cx: Ctx, t: Target, over: AskOver = {}): Promise<void> {
  await openPanel(cx, { view: 'ask', title: 'Ask', ...(await askAbout(cx, t, over)) })
}

/** A side thread started with question `q` about `a`, and opened in the panel: on top of the view it was asked from, so
 *  b goes back there, or (`replace`) in place of the ask view. '' once it opened, else why it did not start. */
export async function askNow(cx: Ctx, a: AskAbout, q: string, opts: { replace?: boolean } = {}): Promise<string> {
  // a thread about a citation is titled by the citation's words, as the browser titles a chip's thread: what names its
  // subject in the panel and on home (anchorName)
  const title = a.target.kind === 'citation' && a.about ? a.about : ''
  const got = await startThread(cx, a.anchor, a.anchorText, q, { ...(a.parent ? { parent: a.parent } : {}), ...(a.element ? { element: a.element } : {}), ...(title ? { title } : {}) })
  if ('error' in got) return got.error
  await openThread(cx, got.id, q, opts)
  return ''
}

/** An entry box (entry.tsx) whose question starts a side thread about `t`, opened over the view it was asked from; a
 *  thread that does not start says why in a toast. `a` gives it the keys (askKey). */
export function askEntry(cx: Ctx, e: PaneEvent, o: { key: string; placeholder: string; cols: number; target: Target; over?: AskOver; top?: boolean }): RenderElement {
  return entryEl(cx, e, {
    key: fieldKey(o.key),
    placeholder: o.placeholder,
    cols: o.cols,
    ...(o.top === false ? { top: false } : {}),
    onSubmit: q => {
      void (async () => {
        const why = await askNow(cx, await askAbout(cx, o.target, o.over ?? {}), q)
        if (why) cx.toast(`the side thread did not start: ${why}`)
      })()
    },
  })
}

/** The key that gives an entry box the keys (`a`), as Enter or `a` does in the threads panel: the hint row then names
 *  none, since a letter goes into the box. */
export function askKey(cx: Ctx, key: string): Key {
  return {
    key: 'ask',
    hotkey: 'a',
    onPress: () =>
      void (async () => {
        // the module's own move of the ring raises no ui.focus: the hint row follows once the ring is there
        if (!(await cx.focus(key))) return
        rt.panelFocus = key
        await cx.bumpPanel()
      })(),
  }
}

/** The views as home lists them (`thimble state home`): each by its slug and name, its state (built, building,
 *  proposed, failed), when it was proposed or built, the files it claims, and `fresh` once built and not yet opened. */
export async function homeViews(cx: Ctx): Promise<HomeView[]> {
  const homeRaw = await surfaceValue<Obj>(cx, 'home-full')
  if (!homeRaw?.ok || !Array.isArray(homeRaw.value.views)) return []
  return (homeRaw.value.views as unknown[]).filter(isObj).map(v => {
    const st = str(v.status)
    const state = st === 'built' ? 'built' : st === 'building' ? 'building' : st === 'failed' ? 'failed' : 'proposed'
    const slug = str(v.slug)
    const fresh = state === 'built' && !rt.viewsSeen.has(slug) && rt.viewsBuiltBefore !== null && !rt.viewsBuiltBefore.has(slug)
    return { slug, name: str(v.name) || slug, state, words: '', files: Array.isArray(v.files) ? (v.files as unknown[]).map(String) : [], unit: '', drawable: state === 'built', left: 0, at: Date.parse(str(v.ts)) || 0, ...(fresh ? { fresh: true } : {}), ...(v.term === true ? { term: true } : {}), ...(str(v.page) ? { page: str(v.page) } : {}), ...(str(v.page_why) ? { pageWhy: str(v.page_why) } : {}) }
  })
}

// ------------------------------------------------------------------------------------------------ the view proposal

/** The view proposal waiting for the analyst's answer, as home's state gives it (`offer`: null while none waits and
 *  while view proposals are off): its slug, name and description, the analyst's task it serves (none for a viewer of a
 *  file type), the files it claims, `refused`, why accept could not start its build and how to fix that, and
 *  `pressed`, the answer pressed here that thimble has not written yet (answerOffer). */
export type HomeOffer = { slug: string; name: string; description: string; task: string; claims: string[]; refused: string; pressed: '' | 'accept' | 'reject' }

// why the last answer pressed here did not reach thimble (`thimble act` failed, or thimble refused it), by the proposal's
// slug: the red row under the proposal says it until the next press, since no file changes to say it (bug hunt B11)
let offerFailed: { slug: string; why: string } | null = null

export async function homeOffer(cx: Ctx): Promise<HomeOffer | null> {
  const home = await surfaceValue<Obj>(cx, 'home-full')
  const o = home?.ok && isObj(home.value.offer) ? home.value.offer : null
  if (!o || !str(o.slug)) return null
  const pressed = o.pressed === 'accept' || o.pressed === 'reject' ? o.pressed : ''
  const failed = offerFailed?.slug === str(o.slug) ? offerFailed.why : ''
  return { slug: str(o.slug), name: str(o.name) || str(o.slug), description: str(o.description), task: str(o.task), claims: Array.isArray(o.claims) ? (o.claims as unknown[]).map(String) : [], refused: str(o.refused) || failed, pressed }
}

/** Every agent's open notices, as home's state gives them (`notices`, newest first): a failure with its fix, from the
 *  orientation and its helpers, the critic, writers, view builds, report checks, code tickets, card checks, labels or
 *  the view proposer. Each with its text, which names the agent and the failure, the agent's name, the acts that fix it
 *  where the terminal can take one (`try again`, `retry`, `turn off view proposals`), and how its own thread opens
 *  (`open`: a side thread, an agent's chat, or none). One dismissed here is left out at once, before thimble has
 *  written it. */
export type NoticeAct = { label: string; act: string; slug: string; config: string; text: string }
/** `ids`: the open notices this one row stands for, the newest (`id`) first: notices with the same words, agent and
 *  acts (three of an orientation's helpers switched to another model) show as one row with their count (bug hunt B5).
 *  `at`: when the newest was posted, in ms (0 when not known), which places it among the terminal's own (band.tsx). */
export type HomeNotice = { id: string; ids: string[]; text: string; agent: string; chat: string; open: '' | 'thread' | 'agent'; acts: NoticeAct[]; at: number; kind: string }

/** Whether a notice is a browser's sign-in told in an earlier session (bug hunt F12): it showed there, above that
 *  session's prompt and with its toast, and does not come back in a later one. A resumed session (`claude -c`) is the
 *  same session (rt.startedAt is its first launch). */
export function earlierSignIn(n: { kind?: unknown; at?: unknown }, startedAt: number): boolean {
  const at = Date.parse(str(n.at)) || 0
  return str(n.kind) === 'sign-in' && startedAt > 0 && at > 0 && at < startedAt
}

// the notices dismissed or fixed from here in this session, by id: a later notice of the same failure has an id of its own
const dismissed = new Set<string>()

/** The open notices as homeNotices gives them, or null while home's state has not been read: the toasts' first look
 *  must not take "none read yet" for "none there" (bug hunt F12: the band drew before the first read, and every notice
 *  already there toasted as new). */
export async function noticesRead(cx: Ctx): Promise<HomeNotice[] | null> {
  return (await surfaceValue<Obj>(cx, 'home-full'))?.ok ? homeNotices(cx) : null
}

export async function homeNotices(cx: Ctx): Promise<HomeNotice[]> {
  const home = await surfaceValue<Obj>(cx, 'home-full')
  const rows = home?.ok && Array.isArray(home.value.notices) ? (home.value.notices as unknown[]).filter(isObj) : []
  const out: HomeNotice[] = []
  const same = new Map<string, HomeNotice>()
  for (const n of rows) {
    if (!str(n.id) || !str(n.text) || dismissed.has(str(n.id)) || earlierSignIn(n, rt.startedAt)) continue
    const acts = Array.isArray(n.acts) ? (n.acts as unknown[]).filter(isObj).filter(a => str(a.act)) : []
    const open = n.open === 'thread' || n.open === 'agent' ? n.open : ''
    const row: HomeNotice = { id: str(n.id), ids: [str(n.id)], text: str(n.text), agent: str(n.agent), chat: str(n.chat), open: str(n.chat) ? open : '', acts: acts.map(a => ({ label: str(a.label).toLowerCase() || str(a.act), act: str(a.act), slug: str(a.slug), config: str(a.config), text: str(a.text) })), at: Date.parse(str(n.at)) || 0, kind: str(n.kind) }
    const key = JSON.stringify([row.text, row.agent, row.open, row.acts])
    const first = same.get(key)
    if (first) first.ids.push(row.id)
    else {
      same.set(key, row)
      out.push(row)
    }
  }
  return out
}

/** A notice row's words: its count first when it stands for several notices (`3× …`), where a cut does not hide it. */
export function noticeWords(n: HomeNotice): string {
  return n.ids.length > 1 ? `${n.ids.length}× ${n.text}` : n.text
}

/** How long an answer pressed on the view proposal shows as pressed, at most: the holder of the workspace's passes
 *  writes it a second or a few after the press, and home's state read then shows the proposal gone, or why its build
 *  could not start. */
export const OFFER_PRESS_MS = 20_000

/** Home's state with its view proposal marked `pressed` (or not, for ''), so the row above the prompt shows the answer
 *  as pressed until home's state is read again; with `only`, only while the mark is the one made at `only`. */
async function markOffer(cx: Ctx, slug: string, pressed: '' | 'accept' | 'reject', at: number, only?: number): Promise<void> {
  const home = await surfaceValue<Obj>(cx, 'home-full')
  const o = home?.ok && isObj(home.value.offer) ? home.value.offer : null
  if (!home?.ok || !o || str(o.slug) !== slug) return
  if (only !== undefined && o.pressedAt !== only) return
  await cx.setSurface('home-full', { ok: true, value: { ...home.value, offer: { ...o, pressed, pressedAt: pressed ? at : 0 } } })
}

/** The analyst's accept (`build it`) or reject (`don't build it`) of the view proposal, from the row above the prompt:
 *  `thimble act view-accept` or `view-reject` {slug}, which hands the answer to thimble and answers at once. The row
 *  shows the answer as pressed (`◌ starting the build`) until home's state is read again or OFFER_PRESS_MS pass; an act that failed or that thimble
 *  refused, or a proposal that no longer waits, brings the controls back with why in the red row under the proposal. */
export async function answerOffer(cx: Ctx, slug: string, verb: 'accept' | 'reject'): Promise<void> {
  if (!rt.sc) return
  const at = await cx.now()
  if (offerFailed?.slug === slug) offerFailed = null
  await markOffer(cx, slug, verb, at)
  const got = await act<{ queued?: boolean; reason?: string }>(cx, rt.sc, `view-${verb}`, { slug })
  if (!got.ok || got.value.queued === false) {
    const why = got.ok ? got.value.reason || 'the view proposal no longer waits' : got.error
    offerFailed = { slug, why: `thimble could not ${verb === 'accept' ? 'start building it' : 'decline it'}: ${why}` }
    await markOffer(cx, slug, '', at, at)
    return
  }
  cx.later(OFFER_PRESS_MS, () => void markOffer(cx, slug, '', at, at))
}

/** The view proposal's `dismiss`, after the row went at once: `thimble act view-dismiss` {slug} has thimble hide it for
 *  main's session, so the browser's card goes too; it is not answered, and a later session shows it again. */
export async function dismissOffer(cx: Ctx, slug: string): Promise<void> {
  if (!rt.sc) return
  const got = await act<{ queued?: boolean; reason?: string }>(cx, rt.sc, 'view-dismiss', { slug })
  if (!got.ok || got.value.queued === false) cx.toast(`the view proposal still shows in the browser: ${got.ok ? got.value.reason || 'it no longer waits' : got.error}`)
}

/** The view proposal's `stop suggesting pages`: view proposals off (`thimble act view-proposals-off`, `views.propose: false`
 *  in thimble's config), the row gone at once, and a toast that says how to turn them back on. */
export async function proposalsOff(cx: Ctx): Promise<void> {
  if (!rt.sc) return
  const got = await act<{ config?: string }>(cx, rt.sc, 'view-proposals-off', {})
  if (!got.ok) {
    cx.toast(`thimble still suggests pages: ${got.error}`)
    return
  }
  const home = await surfaceValue<Obj>(cx, 'home-full')
  if (home?.ok) await cx.setSurface('home-full', { ok: true, value: { ...home.value, offer: null } })
  cx.toast(`thimble will suggest no more pages. To turn suggestions back on, set "views": {"propose": true} in ${got.value.config || "thimble's config"}`)
}

/** A notice's act: `view-propose-now` (try again) or `view-retry` {slug} (retry), which name the notice, so that thimble
 *  dismisses it before the act runs and a failure that comes again shows as a new notice; `sign-out` {slug}, a sign-in
 *  notice's Sign it out, which signs that browser out and takes its notice away; or `view-proposals-off`, as
 *  don't ask again, which dismisses it. The notice goes at once; one that thimble refuses stays, with why in a toast.
 *  `settings` (open settings) says in a toast where thimble's config is, which the terminal has in place of the
 *  browser's Settings, and leaves the notice. A label's `label-open` opens its panel and leaves the notice; its
 *  `label-again` runs it again on the units its last run could not label, in its panel, which says how the run goes
 *  (a new failure brings a new notice); the orientation's `orient-again` asks main to start it again with its last
 *  request (bug hunt C17, C18: the analyst always has a next step). For main's reply Claude's safeguards stopped,
 *  `card-again` sends main the act's words, which ask it to make the card the reply did not add, and `ask-again` puts
 *  the act's words, the analyst's last message to main, in the prompt to change and send (bug hunt C23). The stopped
 *  page's `page-start` does what /thimble browser does (bug hunt H16). */
export async function noticeAct(cx: Ctx, n: HomeNotice, a: NoticeAct): Promise<void> {
  if (!rt.sc) return
  if (a.act === 'label-open') return openLabelAt(cx, a.slug, '')
  if (a.act === 'label-again') {
    await dismissNotice(cx, n)
    await openLabelAt(cx, a.slug, '')
    const name = (await cx.panel())?.title || 'label'
    void runLabel(cx, a.slug, name, 0, { changed: false, reads: '', again: true })
    return
  }
  if (a.act === 'orient-again') {
    await dismissNotice(cx, n)
    return orientAgain(cx, '', n.chat)
  }
  if (a.act === 'card-again' && a.text.trim()) {
    await dismissNotice(cx, n)
    await cx.submit(a.text)
    cx.toast('main was asked to make the card again')
    return
  }
  if (a.act === 'ask-again' && a.text.trim()) {
    await dismissNotice(cx, n)
    await cx.fill(a.text)
    cx.toast('your question is back in the prompt, to change and send')
    return
  }
  if (a.act === 'settings') {
    cx.toast(`Settings are in the browser workbench (/thimble browser) and in thimble's config: ${a.config || 'config.json in thimble\'s home'} (its keys: docs/config.md)`)
    return
  }
  if (a.act === 'view-proposals-off') {
    await dismissNotice(cx, n)
    return proposalsOff(cx)
  }
  // a code ticket that passed its checks waits for the analyst's Allow, which the browser's card asks (SPEC-v2 3.16)
  if (a.act === 'ticket-open') return void (await openInBrowser(cx, `ticket:${a.slug || n.id.replace(/^ticket:/, '')}`))
  // thimble's page stopped (the MCP shim's `page:stopped` notice): started again as /thimble browser starts it; the
  // notice goes once main is attached again (notices.page_back), so a start that fails leaves it, with its own notice
  if (a.act === 'page-start') return void (await openInBrowser(cx, 'home'))
  const got = await act<{ queued?: boolean; reason?: string }>(cx, rt.sc, a.act, { ...(a.slug ? { slug: a.slug } : {}), notice: n.id })
  if (!got.ok || got.value.queued === false) {
    cx.toast(got.ok ? got.value.reason || 'it could not start' : got.error)
    return
  }
  await hideNotice(cx, n.id)
  // the same notices this row stood for go with it: the act was the fix for each
  for (const id of n.ids.slice(1)) await dismissOne(cx, id)
  cx.toast(a.act === 'view-propose-now' ? 'checking for a view proposal' : a.act === 'sign-out' ? 'that browser is signed out' : 'building the view again')
}

/** The notice's row gone at once (home's state read again no longer has it once thimble has written why). */
async function hideNotice(cx: Ctx, id: string): Promise<void> {
  dismissed.add(id)
  const home = await surfaceValue<Obj>(cx, 'home-full')
  if (home?.ok && Array.isArray(home.value.notices)) await cx.setSurface('home-full', { ok: true, value: { ...home.value, notices: (home.value.notices as unknown[]).filter(x => !isObj(x) || str(x.id) !== id) } })
}

/** A notice dismissed, as its × does in the browser, with every notice its row stands for: gone at once, and `thimble
 *  act notice-dismiss` {id} has thimble write each, so they stay gone after a relaunch. */
export async function dismissNotice(cx: Ctx, n: HomeNotice): Promise<void> {
  for (const id of n.ids) await dismissOne(cx, id)
}

async function dismissOne(cx: Ctx, id: string): Promise<void> {
  await hideNotice(cx, id)
  if (!rt.sc) return
  const got = await act(cx, rt.sc, 'notice-dismiss', { id })
  if (!got.ok) cx.toast(`the notice was not dismissed: ${got.error}`)
}

/** The thread of the agent a notice names: a side thread in the threads panel, an agent's chat in its own panel. */
export async function openNoticeChat(cx: Ctx, n: HomeNotice): Promise<void> {
  if (n.open === 'thread') return openThread(cx, n.chat)
  if (n.open === 'agent') await openPanel(cx, { view: 'agent', title: n.agent || 'agent', thread: n.chat })
}

/** A document in the panel, under its title. Opened, it is no longer new. */
export async function openDoc(cx: Ctx, slug: string, title: string): Promise<void> {
  const docs = await surfaceValue(cx, 'docs')
  const d = docs?.ok ? docsOf(docs.value).find(x => x.slug === slug) : undefined
  if (d) rt.docsKnown.set(slug, d.generation)
  await openPanel(cx, { view: 'doc', title: d?.title || title || slug, slug })
}

/** A document opened at the section, slide or beat that holds `unit` (a sentence's, a heading's or a paragraph's id,
 *  `p<id>`), from a link to it (`report:<slug>#<unit>`). */
async function openDocAt(cx: Ctx, slug: string, unit: string): Promise<void> {
  await readDoc(cx, slug)
  const got = await surfaceValue<Obj>(cx, `doc:${slug}`)
  const doc = got?.ok ? got.value : {}
  const holds = (u: DocSection) => u.id === unit || (u.paragraphs ?? []).some(p => p.id === unit || `p${p.id}` === unit || (p.sentences ?? []).some(x => x.id === unit))
  const at = unit ? docUnits(doc).units.findIndex(holds) : -1
  const docs = await surfaceValue(cx, 'docs')
  const d = docs?.ok ? docsOf(docs.value).find(x => x.slug === slug) : undefined
  if (d) rt.docsKnown.set(slug, d.generation)
  await openPanel(cx, { view: 'doc', title: d?.title || str(doc.title) || slug, slug, ...(at > 0 ? { start: at } : {}) })
}

/** A view's line in the panel: the browser draws views. Opened, it is no longer new. */
export async function openView(cx: Ctx, slug: string, name: string): Promise<void> {
  rt.viewsSeen.add(slug)
  await openPanel(cx, { view: 'view', title: name || slug, slug })
}

/** A view opened from a link to it (`view:<slug>` or `view:<slug>/<key>`), at the unit the key names, under the view's
 *  name as the views list names it. */
async function openViewAt(cx: Ctx, slug: string, ref: string): Promise<void> {
  const got = await surfaceValue(cx, 'views')
  const views = got?.ok && Array.isArray((got.value as { views?: unknown })?.views) ? ((got.value as { views: { slug?: unknown; name?: unknown }[] }).views) : []
  const name = views.find(v => v?.slug === slug)?.name
  rt.viewsSeen.add(slug)
  await openPanel(cx, { view: 'view', title: typeof name === 'string' && name ? name : slug, slug, ...(ref !== `view:${slug}` ? { ref } : {}) })
}

/** A citation by its words, or, for a place cited without words, the place in words (`revisions.jsonl line 10879`, a
 *  card by its question): the citation panel's title and its step in the path. */
async function citeTitle(cx: Ctx, c: Citation): Promise<string> {
  if (c.display !== null) return c.display
  if (fileRef(c.ref) || /^call:/.test(c.ref)) return placeWords(c.ref)
  return /^(?:card|cell):/.test(c.ref) ? placeName(cx, c.ref) : chipWords(c)
}

/** A citation's panel, its step named by the cited value (or its place, for a citation that shows none); `sentence`
 *  the sentence it stands in, `quote` the passage an example's record quotes. */
export async function openCite(cx: Ctx, ref: string, display: string | null, more: { sentence?: string; quote?: string; of?: string } = {}): Promise<void> {
  // a label's link: the label's panel at the value it names (live check term-fix5, new quirk 2)
  const lr = labelRef(ref)
  if (lr) return openLabelAt(cx, lr.id, lr.value)
  // a document's link: the document, from the section that holds the passage
  const rr = reportRef(ref)
  if (rr) return openDocAt(cx, rr.slug, rr.unit)
  // a view's link: the view, at the unit its key names
  const vr = viewRef(ref)
  if (vr) return openViewAt(cx, vr.slug, ref)
  // its step in the path: its words cut at a word; for a place cited with no words, the words of the chip the reply
  // draws (`agent-chat.jsonl line 2`)
  const c = { raw: '', ref, display }
  const title = display === null && fileRef(ref) ? chipWords(c) : clip(await citeTitle(cx, c), 40)
  // opened anew, a file citation's window starts at the cited lines again, and only its bar shows under them
  citeTops.delete(ref)
  citeOpen.delete(citeKey(display, ref))
  await openPanel(cx, { view: 'cite', title, ref, display, ...(more.sentence ? { sentence: more.sentence } : {}), ...(more.quote ? { quote: more.quote } : {}), ...(more.of ? { of: more.of } : {}) })
}

export async function openCard(cx: Ctx, id: string, mode = ''): Promise<void> {
  // its step named by its question: a card no drawing read yet (one a side thread made) is read first (live check
  // term-fix8, low quirk: the path read `card "Card"` on its first open)
  if (!(await cx.card(id))?.data) await loadCards(cx, [id]).catch(() => undefined)
  const tc = await cx.card(id)
  await openPanel(cx, { view: 'card', title: clip((tc?.data as CardData | undefined)?.question ?? 'Card', 60), card: id, ...(mode ? { mode } : {}) })
}

/** A thread opens in the threads panel, selected under the tree; its step named by its first question (`question` when
 *  it was just asked), never thimble's slug of it. */
export async function openThread(cx: Ctx, id: string, question = '', opts: { replace?: boolean } = {}): Promise<void> {
  const row = (await cx.threads()).find(t => t.id === id)
  const tt = await cx.thread(id)
  const q = question || (tt?.events.length ? threadOf(tt.meta, tt.events).turns[0]?.q : '') || row?.question || row?.title || ''
  await openPanel(cx, { view: 'thread', title: q ? quoted(clip(plainCites(q), 60)) : 'thread', thread: id }, opts)
}

/** A file in the panel from line `start`, `line` the record a citation or a click chose, lit there. */
export async function openFile(cx: Ctx, path: string, start = 1, line?: number, record?: string): Promise<void> {
  await openPanel(cx, { view: 'file', title: path.split('/').at(-1) ?? path, path, start, ...(line ? { line } : {}), ...(record ? { record } : {}) })
}

/** A label's panel, as it opens: what a save or a run said there before is gone. With `value`, its counts and examples
 *  open, the value lit in them. */
export async function openLabel(cx: Ctx, id: string, name: string, value = ''): Promise<void> {
  // the labels list's `undo` of a delete is offered only until another label opens
  setLabelGone(null)
  const ui = await cx.labelUi()
  const said = { ...ui.said }
  if (ui.said[id] && !ui.runs[id]) delete said[id]
  const open = value ? [...new Set([...ui.open, `${id}:examples`])] : ui.open
  if (said[id] !== ui.said[id] || open !== ui.open) await cx.setLabelUi({ ...ui, said, open })
  await openPanel(cx, { view: 'label', title: name, label: id, ...(value ? { value } : {}) })
}

/** A label's panel opened from a link to it (`concept:<id>/<value>`), named as the labels list names it. */
async function openLabelAt(cx: Ctx, id: string, value: string): Promise<void> {
  await readSurface(cx, 'labels', 'labels')
  const got = await surfaceValue(cx, 'labels')
  const name = (got?.ok ? labelsOf(got.value) : []).find(l => l.id === id)?.name ?? 'label'
  await openLabel(cx, id, name, value)
}

/** What a click (or a right-click: it does what a click does) on a target does, as the mod's: open the place it cites
 *  (a citation's, a record's), or ask a side thread about a card's mark; plain words open nothing (only what is drawn as
 *  a link opens a panel). */
export async function onGesture(cx: Ctx, _gesture: Gesture, t: Target): Promise<void> {
  const place = placeOf(t)
  if (place) {
    // a citation of a reply: the sentence it stands in, and the card whose takeaway holds it; an example's record: the
    // passage the card quotes
    const sentence = t.kind === 'citation' ? claimSentence(t.claim) : ''
    const of = t.kind === 'citation' ? claimCard(t.claim) : ''
    let quote = ''
    if (t.kind === 'record' && t.cardId) {
      const card = (await cx.card(t.cardId))?.data as CardData | null | undefined
      quote = card?.examples?.find(x => x.ref === t.ref)?.quote ?? ''
    }
    return openCite(cx, place.ref, place.display, { ...(sentence ? { sentence } : {}), ...(quote ? { quote } : {}), ...(of ? { of } : {}) })
  }
  if (t.cardId) return openAsk(cx, t)
}

// ------------------------------------------------------------------------------------------------ the frame

/** Hotkeys with no label of their own (rule 26: the key-hint row says them): plain Buttons in a Box no row tall. Each
 *  is kept by its letter too, for the list's keys (listKeysEl), whose field takes the letters while it holds the ring;
 *  none is drawn while the panel's typing goes to the prompt and the pane still holds the keys (keysHidden), so the
 *  next letter reaches the prompt. */
export function hiddenKeys(cx: Ctx, e: PaneEvent, keys: Key[]): RenderElement | null {
  for (const k of keys) hotkeysDrawing.set(k.hotkey, k.onPress)
  if (!keys.length || e.surface === 'mobile' || keysHidden()) return null
  const { Box, Button } = cx.els(e)
  return (
    <Box key="hidden-keys" width={0} height={0} flexShrink={0} overflow="hidden" flexDirection="row">
      {keys.map(k => (
        <Button key={`hk-${k.key}`} label={k.hotkey} hotkey={k.hotkey} plain onPress={typedOr(cx, k.hotkey, k.onPress)} />
      ))}
    </Box>
  )
}

/** A hotkey's press, or, once the panel's typing goes to the prompt (typeThrough), its letter typed into the prompt: a
 *  key typed before the panel drew again without its hotkeys reached one (live check term-fix10: `table` typed into the
 *  prompt opened the threads at its `t` and reached main as `able`). */
function typedOr(cx: Ctx, hotkey: string, onPress: () => void): () => void {
  return () => (rt.typeThrough ? void cx.fill(hotkey) : onPress())
}

/** A Button's hotkey prop (`hotkey` for its key) and its press (typedOr), kept by its letter for the list's keys as
 *  hiddenKeys keeps one: no hotkey for a Button past the first nine, or while the panel's typing goes to the prompt. */
function hotkeyOf(cx: Ctx, hotkey: string | null, onPress: () => void): { hotkey?: string; onPress: () => void } {
  if (!hotkey) return { onPress }
  hotkeysDrawing.set(hotkey, onPress)
  return keysHidden() ? { onPress: typedOr(cx, hotkey, onPress) } : { hotkey, onPress: typedOr(cx, hotkey, onPress) }
}

/** What a step of the path says: a lower-case kind word and its name, or the name alone after the list it is in. */
function crumbText(s: ChatNavStep): string {
  switch (s.view) {
    case 'thread':
      return s.title
    case 'cite':
      return `citation ${s.title === 'Citation' ? '' : s.title}`.trim()
    case 'card':
      // its code view's step keeps ` · code` whole: the question inside its marks is cut, once (lib.ts cut)
      return panelOfStep(s)?.mode === 'code' ? `card ${quoted(s.title)} · code` : `card ${quoted(s.title)}`
    case 'label':
    case 'file':
    case 'agent':
    case 'view':
      return s.title
    case 'doc':
      return quoted(s.title)
    case 'docs':
      return 'documents'
    case 'ask':
      return 'new thread'
    case 'waiting':
      return s.title
    case 'coverage': {
      // a folder drilled into by its path, a group of its files by its pattern or type; the corpus's top as the view's
      // name
      const p = panelOfStep(s)
      return p?.path || p?.match ? coverageTitle(p.path ?? '', p.match) : 'coverage'
    }
    case 'checks':
      return panelOfStep(s)?.mode ? `checks › ${s.title}` : 'checks'
    default:
      return s.view
  }
}

/** The list a step stands in, which the path shows before it unless the step before it is that list. */
function upOf(s: ChatNavStep, earlier: readonly ChatNavStep[]): TermPanel | null {
  const before = earlier.at(-1)
  if (s.view === 'thread') return earlier.some(x => x.view === 'thread' || x.view === 'threads') ? null : { view: 'threads', title: 'Threads' }
  if (s.view === 'label') return before?.view === 'labels' ? null : { view: 'labels', title: 'Labels' }
  if (s.view === 'doc') return before?.view === 'docs' ? null : { view: 'docs', title: 'Documents' }
  if (s.view === 'view') return before?.view === 'views' ? null : { view: 'views', title: 'Views' }
  return null
}

// the cells of the title row's separator (` › `), and of its `↗` with the gap before it
const SEP_W = 3
const BROWSER_W = 3

// a list's step as the title names it where it is the current step (`home › Threads`); earlier on the path it reads as
// its lower-case kind word (`home › threads › "…"`)
const LIST_TITLES: Record<string, string> = { home: 'Home', threads: 'Threads', labels: 'Labels', docs: 'Documents', views: 'Views', ask: 'New thread', citations: 'Citations' }

/** The current step's words: a list's title; a thread by its question; else the step as the path names it, with the
 *  subject's name as the view gave it (a card's whole question). */
function hereText(s: ChatNavStep, title: string | undefined): string {
  const list = LIST_TITLES[s.view]
  if (list) return list
  // the Coverage view by the folder it shows; the Checks view by the check of the comment it shows
  if (s.view === 'coverage') return coverageTitle(panelOfStep(s)?.path ?? '', panelOfStep(s)?.match)
  if (s.view === 'checks') return title && title !== 'Checks' ? `checks › ${title}` : 'Checks'
  return s.view === 'thread' || !title ? crumbText(s) : crumbText({ ...s, title })
}

/** What a view opens in the browser where it names nothing itself (chrome.tsx setBrowser): the object it shows, as
 *  thimble open's refs name them (C12), else home. */
export function browserRef(p: TermPanel | null): string {
  if (!p) return 'home'
  switch (p.view) {
    case 'card':
      return p.card ? `card:${p.card}` : 'home'
    case 'cite':
      return p.ref || 'home'
    case 'thread':
      return p.thread ? `thread:${p.thread}` : 'home'
    case 'agent':
      return p.thread ? `thread:${p.thread}` : 'home'
    case 'label':
      return p.label ? `concept:${p.label}` : 'home'
    case 'doc':
      return p.slug ? `report:${p.slug}` : 'home'
    case 'view':
      return p.slug ? `view:${p.slug}` : 'home'
    case 'file':
      return p.path ? `files:${p.path}` : 'files:'
    case 'coverage':
      return `files:${p.path ?? ''}`
    case 'checks':
      return 'checks'
    default:
      return 'home'
  }
}

/** The title row (SPEC.md, "A panel's header"; Matt, 2026-10-07: "can just be one line for title"): the path from
 *  home, each earlier step dim and a click away, a dim ` › ` between steps, and the current step last, its title in the
 *  accent and bold (a citation's value its link); a thread's step followed by `new` in green while answers wait, one
 *  that answers starting with `◌`. Against R what the view puts there (`◌ loading…`), and on home `show all threads`
 *  and `N new` in green. No `‹ back`: b goes back. Where the path does not fit, the earlier steps shorten first, then
 *  the current one is cut with `…`. */
async function wayRow(cx: Ctx, e: PaneEvent, view: string): Promise<RenderElement> {
  const { Box, Text, Button } = cx.els(e)
  const els = cx.els(e) as El
  // the row's own width: never more than the pane gives it, or it wraps (live check term-fix9, quirk 3)
  const cols = Math.max(10, e.props.bodyColumns)
  const nav = (await cx.nav()) ?? NAV_EMPTY
  const back = backTarget(nav) !== null
  const head = takeHead()
  // `show all threads` only where the threads are the subject, home; the threads panel is the threads, and on a view,
  // a file, a card or a citation home is one step away (Matt, 2026-10-07: "does 'show all threads' really need to be
  // there when you're not in a thread?")
  const showThreads = view === 'home'
  const threads = (await cx.threads()) ?? []
  const fresh = ((await cx.news()) ?? { n: 0 }).n
  const { steps, skipped } = crumbSteps(nav.trail)
  type Crumb = { text: string; mark: string; go: () => void; here?: boolean; up?: boolean }
  const crumbs: Crumb[] = []
  for (const [i, s] of steps.entries()) {
    const up = upOf(s, steps.slice(0, i))
    // the list a step stands in goes back to that list: the trail up to the step, then the list, never a step pushed
    // after the step (`home › files › a.jsonl › files`)
    const upTrail = nav.trail.slice(0, i + skipped)
    if (up) crumbs.push({ text: up.view === 'docs' ? 'documents' : up.view, mark: '', up: true, go: () => void navGo(cx, { trail: [...upTrail, stepOf(up)], back: withBack(nav.back, nav.trail) }) })
    const t = s.view === 'thread' ? threads.find(x => x.id === s.thread) : undefined
    const here = i === steps.length - 1
    // a card's step taken before the card was read names it by its question once it is
    const card = s.view === 'card' && (s.title === 'Card' || (here && !head.title)) ? ((await cx.card(panelOfStep(s)?.card ?? ''))?.data as CardData | null | undefined) : null
    const named = card?.question ? { ...s, title: here ? card.question : clip(card.question, 60) } : s
    crumbs.push({ text: here ? hereText(named, head.title) : crumbText(named), mark: t?.running ? '◌' : t?.unread ? 'new' : '', go: () => void navGo(cx, { trail: nav.trail.slice(0, i + 1 + skipped), back: withBack(nav.back, nav.trail) }), here })
  }
  const home = !crumbs.length
  // the current step's own words, where the view draws them (a citation's value as its link), after the step's kind
  // word in the accent and bold (`citation`)
  const own: Line | null = head.line && crumbs.length ? head.line : null
  const kind = own && view === 'cite' ? 'citation ' : ''
  if (own) crumbs[crumbs.length - 1]!.text = `${kind}${own.map(x => x.s).join('')}`
  const marksW = crumbs.reduce((n, c) => n + (c.mark ? c.mark.length + 1 : 0), 0)
  // at R `show all threads` and `N new`, while the steps keep the room they need beside them (home, the last step at
  // up to 12 cells); else `threads` and `N new`, else `threads` alone, so the threads stay one click away in a narrow
  // pane; else neither. No letter opens them: `t` did, unnamed, and a word typed while the panel held the keys (`table`)
  // opened the threads and lost its first letter (live check term-fix10, new quirk 4)
  const labels = [home ? LIST_TITLES.home! : 'home', ...crumbs.map(c => c.text)]
  const rightW = head.right ? 2 + 12 : 0
  // the `↗` at the row's right end, which opens the view's object in the browser, as `o` does (SPEC-v2 3.8)
  const ref = takeBrowser() ?? browserRef(await cx.panel())
  const toBrowser = () => openInBrowser(cx, ref)
  const room = cols - marksW - rightW - BROWSER_W
  const newW = fresh ? `${fresh} new`.length : 0
  type Tail = { all: string; fresh: boolean; w: number }
  const tail0 = (all: string, withNew: boolean): Tail => ({ all, fresh: withNew, w: (all ? 2 + all.length : 0) + (withNew ? 2 + newW : 0) })
  const tails: Tail[] = !showThreads
    ? [tail0('', false)]
    : [tail0('show all threads', Boolean(fresh)), ...(fresh ? [tail0('threads', true)] : []), tail0('threads', false), tail0('', false)]
  const need = Math.min(pathWidth(labels.map((l, i) => (i < labels.length - 1 ? clip(l, 34) : l))), 4 + (labels.length > 2 ? 4 : 0) + (labels.length > 1 ? SEP_W + Math.min(12, width(labels.at(-1)!)) : 0))
  const tail = tails.find(t => room - t.w >= need) ?? tails.at(-1)!
  const fitted = fitPath(labels, Math.max(4, room - tail.w))
  const parts: RenderElement[] = []
  let drawn = false
  fitted.forEach((text, i) => {
    if (text === null) {
      if (drawn && fitted[i - 1] !== null) parts.push(<Text dimColor>{' › …'}</Text>)
      return
    }
    if (drawn) parts.push(<Text dimColor>{' › '}</Text>)
    drawn = true
    const c = i ? crumbs[i - 1]! : null
    if (c?.mark === '◌') parts.push(<Text>{'◌ '}</Text>)
    if (c?.here || (!c && home)) {
      // the current step: the title, in the accent and bold, or the view's own words for it, cut to the room
      if (!own) parts.push(lineEl(els, [{ s: text, fg: ACCENT, b: true }]))
      else {
        if (kind) parts.push(lineEl(els, [{ s: cut(kind, width(text)), fg: ACCENT, b: true }]))
        const line = fitTo(own, Math.max(1, width(text) - width(kind)))
        if (width(text) > width(kind)) parts.push(head.press ? linesEl(cx, e, head.key ?? 'way-here', [line], [{ y: 0, x0: 0, x1: lineWidth(line), row: false, run: head.press }], lineWidth(line)) : lineEl(els, line, head.key))
      }
    } else if (c) parts.push(<Button key={c.up ? `crumb-up-${i}` : `crumb-${i}`} label={text} plain dimColor onPress={c.go} />)
    else parts.push(<Button key="crumb-home" label={text} plain dimColor onPress={() => void openHome(cx)} />)
    if (c?.mark === 'new') parts.push(<Text color={FRESH}>{' new'}</Text>)
  })
  const showAll = () => void openPanel(cx, { view: 'threads', title: 'Threads' })
  return (
    <Box key="way" flexDirection="row">
      <Box flexShrink={1} flexDirection="row">
        {parts}
      </Box>
      <Box flexGrow={1} />
      {head.right ? <Box flexShrink={0}>{head.right}</Box> : null}
      {tail.all ? <Button key="threads" label={tail.all} plain onPress={showAll} /> : null}
      {tail.fresh ? <Text color={FRESH}>{`${tail.all ? '  ' : ''}${fresh} new`}</Text> : null}
      <Text>{'  '}</Text>
      <Button key="way-browser" label="↗" plain onPress={toBrowser} />
      {hiddenKeys(cx, e, [...(back ? [{ key: 'back', hotkey: 'b', onPress: () => void navBack(cx) }] : []), { key: 'close', hotkey: 'x', onPress: () => void closePanel(cx) }, { key: 'browser', hotkey: 'o', onPress: () => void toBrowser() }])}
      {listKeysEl(cx, e)}
      {restKeyEl(cx, e)}
    </Box>
  )
}

/** The title row, then the view's rows, each with an empty margin unless it brings its own (a key starting `m:`). */
async function withWay(cx: Ctx, e: PaneEvent, view: string, body: RenderElement): Promise<RenderElement> {
  const way = await wayRow(cx, e, view)
  const { Box } = cx.els(e)
  const b = body as unknown as { type?: string; props?: { flexDirection?: string }; children?: unknown[] }
  const kids = (b.type === 'Box' && b.props?.flexDirection === 'column' ? (b.children ?? []) : [body]).filter(k => Boolean(k)) as RenderElement[]
  const rows = [way, ...kids].map(k => (hasMargin(k) ? k : <Box paddingLeft={MARGIN_W} flexDirection="column">{k}</Box>))
  return (
    <Box flexDirection="column" paddingLeft={1} paddingRight={1}>
      {rows}
    </Box>
  )
}

/** A list's rows as lines: each item's glyph at A0 and its name at A2, its metadata dim at R, `❯` on the chosen one. */
function listLines(items: { key: string; glyph: Seg | null; name: string; right: Line; run: () => Promise<void> | void }[], pick: string, cols: number): { lines: Line[]; hits: LineHit[] } {
  const lines: Line[] = []
  const hits: LineHit[] = []
  for (const it of items) {
    hits.push({ y: lines.length, x0: MARGIN_W, x1: cols + MARGIN_W, row: true, run: it.run })
    lines.push(pointed(spread([it.glyph ?? { s: ' ' }, { s: ' ' }, { s: it.name }], it.right, cols), it.key === pick))
  }
  if (!items.length) lines.push(pointed([{ s: '  ' }, dim('none')], false))
  return { lines, hits }
}

// ------------------------------------------------------------------------------------------------ shared parts

/** Code as Claude Code colours it (its `Code` element), its dim gutter of line numbers from `startLine`. */
function codeRows(cx: Ctx, e: PaneEvent, source: string, max = 400, language = 'python', startLine: number | null = 1): RenderElement {
  const { Box, Text, Code } = cx.els(e)
  const lines = source.replace(/\t/g, '    ').split('\n')
  while (lines.length && !lines.at(-1)!.trim()) lines.pop()
  const shown = lines.slice(0, lines.length > max + 1 ? max : lines.length)
  return (
    <Box flexDirection="column">
      <Code source={shown.join('\n') || ' '} language={language} {...(startLine !== null ? { startLine } : {})} wrap="truncate-end" />
      {lines.length > shown.length ? <Text dimColor>{`… ${lines.length - shown.length} more`}</Text> : null}
    </Box>
  )
}

// the way's keys the panel binds now (wayRow): `b to go back` only when there is a way back, `x to close` always
let wayHints: string[] = ['x to close']
// whether the pane holds the keys as it is drawn (its `isFocused`)
let paneFocused = true
// the key handler of the list the view draws (lines.tsx takeListKeys), which the panel's own keys reach (listKeysEl)
let listRelay: ((k: string) => Promise<void> | void) | null = null
// the panel's hotkeys by their letters, as the drawing shown last bound them (hiddenKeys, hotkeyOf), and as the one being
// drawn does
let hotkeys = new Map<string, () => void>()
let hotkeysDrawing = new Map<string, () => void>()
// the list's own keys besides ↑↓ and Enter, as the view's hint row names them (endHints): Space folds, Backspace goes
// back; as the drawing shown last named them, and as the one being drawn does
let listExtra = { space: false, backspace: false }
let listExtraDrawing = { space: false, backspace: false }

/** The panel's own keys for the list a view draws (live checks term-fix7, quirk 2, and term-fix8, quirks 1, 2 and 7). A
 *  list is drawn by a Client, and a Client takes keys only from a click, which leaves the pane without them, so the
 *  list's keys are the pane's: an Input between two Buttons, all no row tall, the ring on the Input (`autoFocus`). While
 *  an Input holds the ring Claude Code moves the ring at ↑ and ↓ and never scrolls the pane, so the `ui.focus` hook
 *  (register.tsx) turns a move onto either Button into ↑ or ↓ for the list and keeps the ring where it is; Enter submits
 *  the Input; a letter, a digit or Space goes into it, and its change is that key (relayInput): the panel's hotkey by its
 *  letter, Space for the list where its hint names it, any other key typing for the prompt (typeThrough). ←, →, the page
 *  keys, Home and End reach no element while an Input holds the ring, so the hint row never names them. The Input holds
 *  a mark of its own, drawn anew after each key, so a Backspace changes it too. */
export const RELAY = { up: 'keys-up', pick: 'keys-pick', down: 'keys-down' } as const
const RELAY_KEYS: readonly string[] = Object.values(RELAY)
// the two marks the relay's Input holds in turn: drawing the other one gives it that text again (Claude Code keeps
// what the person typed until the hook draws another value)
const MARKS = ['\u200b', '\u200c'] as const
// the mark drawn last, whether a key came since (the next drawing draws the other one), and the text last seen
let relayMark = 0
let relayFlip = false
let relayLast = ''

/** The key a move of the panel's focus ring onto `element` stands for while it rests on the relay's Input (`up`,
 *  `down`), `park` for a move onto a neighbour from elsewhere (the ring goes to the Input), or '' for any other move. */
export function relayMove(from: string, element: string | undefined): 'up' | 'down' | 'park' | '' {
  if (element !== RELAY.up && element !== RELAY.down) return ''
  if (from !== RELAY.pick) return 'park'
  return element === RELAY.up ? 'up' : 'down'
}

/** Whether the panel shows a list whose keys the relay passes on. */
export function hasList(): boolean {
  return listRelay !== null
}

/** A key for the list the panel shows now, from the panel's own keys (the relay); false when it shows none. */
export async function relayKey(k: string): Promise<boolean> {
  if (!listRelay) return false
  await listRelay(k)
  return true
}

// while the ui.focus hook turns a move of the ring into ↑ or ↓ for the list (relayMoveKey), and the element that key
// moved the ring onto (ringOnto)
let ringMoving = false
let ringTo = ''

/** ↑ or ↓ for the list, from a move of the ring onto the relay's Button (register.tsx, the ui.focus hook): the element
 *  the key moved the ring onto instead, where the hook lands the person's move (the labels list's ↓ past its last
 *  label: its entry box), or '' while the ring stays on the relay. A `$.ui.focus` of its own from inside that move would
 *  not move the ring. */
export async function relayMoveKey(k: 'up' | 'down'): Promise<string> {
  ringMoving = true
  ringTo = ''
  try {
    await relayKey(k)
  } finally {
    ringMoving = false
  }
  const to = ringTo
  ringTo = ''
  return to
}

/** The ring onto the panel's element `key` (an entry box): during a move of the person's the list's key came from, the
 *  move lands there (relayMoveKey); else the module moves it, which raises no ui.focus, so the hint row follows once
 *  the ring is there. */
async function ringOnto(cx: Ctx, key: string): Promise<void> {
  if (ringMoving) {
    ringTo = key
    return
  }
  if (!(await cx.focus(key))) return
  rt.panelFocus = key
  await cx.bumpPanel()
}

/** What the person typed into the relay's Input, from its text now (`value`) and the text seen last (`last`): each
 *  character, or `backspace` when the text got shorter. Its text starts as the mark drawn; a key typed before the next
 *  drawing adds to what is there. */
export function relayTyped(value: string, last: string): string[] {
  const mark = (v: string) => (v && (MARKS as readonly string[]).includes(v[0]!) ? v[0]! : '')
  const m = mark(value)
  const before = mark(last) === m && m ? last : m
  if (value.length < before.length || (!m && !value)) return ['backspace']
  return [...value.slice(before.length)]
}

/** The mark the relay's Input holds as drawn now, for the tests. */
export function relayValue(): string {
  return MARKS[relayMark]!
}

/** A change of the relay's Input: each key typed is the panel's hotkey by its letter or digit, Space or Backspace for
 *  the list where its hint names them, else typing meant for the prompt (typeThrough), as is every key after it until
 *  the person gives the panel its keys back. A change of several characters at once is typing, not keys: a paste, or
 *  letters that came faster than the panel drew, all of it for the prompt (bug hunt D8: a burst's `o` opened the
 *  browser). The Input is drawn again with the other mark, so its next change starts afresh. */
export async function relayInput(cx: Ctx, value: string): Promise<void> {
  const typed = relayTyped(value, relayLast)
  relayLast = value
  relayFlip = true
  const text = typed.filter(ch => ch !== 'backspace')
  if (!rt.typeThrough && text.length > 1) {
    await typeThrough(cx, text.join(''))
    await cx.bumpPanel()
    return
  }
  for (const ch of typed) {
    if (rt.typeThrough) {
      if (ch !== 'backspace') await cx.fill(ch)
      continue
    }
    if (ch === 'backspace') {
      if (listExtra.backspace) await relayKey('backspace')
      continue
    }
    if (ch === ' ' && listExtra.space) {
      await relayKey('space')
      continue
    }
    const run = hotkeys.get(ch)
    if (run) {
      run()
      continue
    }
    await typeThrough(cx, ch)
  }
  await cx.bumpPanel()
}

// while a field of a terminal view takes typing (its search), the relay's Input is that field: it holds the field's
// text, each change of which goes to the view whole, and Enter ends it (drawView)
let viewField: { slug: string; text: string; send: (text: string) => Promise<void>; enter: () => Promise<void> } | null = null
// where the open view's frame stands in the panel as last drawn: the pane tree's row of the frame's first row (under the
// title row, the subtitle and the rule), the window's offset then, and the frame's seq (viewWheelAt); null with no
// frame. viewAtDrawing is the drawing being made's, which becomes viewAt once it is done
type ViewAt = { top: number; offset: number; seq: number }
let viewAt: ViewAt | null = null
let viewAtDrawing: ViewAt | null = null

/** The cell of the open view's frame under the person's wheel (`pointer`, the pane body's cell, as ui.scroll gives it):
 *  `{seq, x, y}`, `x` from the frame's left edge (its margin's two cells first) and `y` from its first row, as a click's
 *  cell, so that the view moves the list under the pointer alone; none where the panel shows no frame. */
export function viewWheelAt(pointer?: { row: number; column: number } | null): { seq?: number; x?: number; y?: number } {
  if (!viewAt || !pointer || !Number.isFinite(pointer.row) || !Number.isFinite(pointer.column)) return {}
  // the panel's cell of padding left of the frame (withWay)
  return { seq: viewAt.seq, x: pointer.column - 1, y: pointer.row + viewAt.offset - viewAt.top }
}
// while a field of a panel's own takes typing (the file browser's find), the relay's Input is that field as it is for a
// view's: the panel sets it on each drawing that types into it (relayField), and no other drawing keeps it
type PanelField = { text: string; send: (text: string) => Promise<void>; enter: () => Promise<void> }
let panelField: PanelField | null = null

/** The relay's Input as a field of the panel being drawn, which takes typing until a drawing sets none: it holds
 *  `text`, each change goes to `send` whole, Enter to `enter`; ↑↓ still move the list's choice. */
export function relayField(f: PanelField | null): void {
  panelField = f
}

/** The hint row while a field of the panel's own takes typing through the relay (relayField): what its keys do there,
 *  then `Esc to leave the field`; while the prompt holds the keys, only how to give the panel them. */
export function fieldHintsRow(els: El, hints: readonly string[], cols: number): RenderElement {
  endHints(hints)
  return hintsEl(els, paneFocused && !rt.typeThrough ? [...hints, 'Esc to leave the field'] : [keysAwayHint()], cols)
}

/** Whether the pane holds the keys as it is drawn, its typing not on the way to the prompt. */
export function panelHasKeys(): boolean {
  return paneFocused && !rt.typeThrough
}

/** Whether the panel draws neither its list's keys nor its hotkeys: its typing goes to the prompt (typeThrough) while
 *  the pane still holds the keys, so the next key, which nothing of the panel's takes, reaches the prompt. Once the
 *  prompt has the keys they are drawn again, for a click that gives the pane the keys to put the ring on the relay; a
 *  key that still reaches them goes to the prompt (relayInput, typedOr) until then (bug hunt D8). */
function keysHidden(): boolean {
  return rt.typeThrough && paneFocused
}

/** A slash command typed into an entry box (entry.tsx) goes to the prompt as typing the panel does not bind
 *  (typeThrough): the boxes then draw no field, so the next key, and the Enter that runs it, reach the prompt (bug hunt
 *  E13: `/exit` typed into the orientation's focus box became its brief). */
async function slashOut(cx: Ctx, text: string): Promise<void> {
  if (rt.typeThrough) await cx.fill(text)
  else await typeThrough(cx, text)
  await cx.bumpPanel()
}
entryPrompt(slashOut, keysHidden)

/** The pane's body rows as the drawing measured them, 0 when not known (a list is then drawn whole). */
export function paneRows(): number {
  return bodyRows
}

/** A panel view drawn by a module of its own (filesview.tsx: the file browser and a file), by its name. */
type Drawer = (cx: Ctx, e: PaneEvent, p: TermPanel) => Promise<RenderElement>
const drawers = new Map<string, Drawer>()
export function drawsView(view: string, draw: Drawer): void {
  drawers.set(view, draw)
}

/** Enter on the relay's Input: Enter for the list. */
export async function relaySubmit(cx: Ctx): Promise<void> {
  relayLast = ''
  relayFlip = true
  if (!rt.typeThrough) await relayKey('return')
  await cx.bumpPanel()
}

/** A key the panel does not bind, typed while its list held the keys: it goes to the prompt, as Claude Code sends a
 *  pane's unbound letter there. Until the prompt has the keys (the next key the person types, which no element and no
 *  hotkey of the panel takes now) the panel draws neither the relay nor its hotkeys, and its hint row says to click it
 *  for its keys. A key that reaches the relay or a hotkey after that (one typed before the panel drew again) goes to the
 *  prompt too, until the person gives the panel its keys back: a move of its ring, a click, or the pane given the keys
 *  once the prompt had them (register.tsx, term.ts takeKeys, drawPanel). */
async function typeThrough(cx: Ctx, ch: string): Promise<void> {
  rt.typeThrough = true
  rt.typeAway = false
  rt.panelFocus = NO_RING
  await cx.fill(ch)
}

// the ring on no element (register.tsx NO_FOCUS)
const NO_RING = '-'

// the pane's body rows as the drawing measured them (0: not known, and no list is cut)
let bodyRows = 0
// the list the drawing cut to the pane's rows (windowList), and the one the drawing shown last cut, which the wheel moves
let windowed = ''
let shownWindow = ''
// each cut list's first row shown, the row the keys chose then, how many rows it has and shows, and whether the wheel
// or a click on a count row moved it since the choice last moved (`free`), by the list's key
const windowTops = new Map<string, { top: number; at: number; len: number; room: number; free: boolean }>()

/** The rows of a cut list that `top` leaves for the list's own lines: a dim row counts the lines above, another those
 *  below. */
function windowFit(top: number, len: number, room: number): { up: number; down: number; n: number } {
  const up = top > 0 ? 1 : 0
  let n = room - up
  const down = top + n < len ? 1 : 0
  n -= down
  return { up, down, n }
}

/** A list's lines cut to `room` rows so that its chosen line (`at`, -1 for none) shows, the hits moved with them: a
 *  list taller than its pane pushed the chosen row and the hint row out of view, and ↑↓ scrolled the pane instead of
 *  choosing (live check term-fix8, quirk 1). The wheel and a click on a count row move the rows shown (wheelWindow)
 *  until the choice moves again; the lines cut off above and below are counted on a dim row each, which a click moves
 *  by a page. A list that fits, or a pane whose rows are not known, is drawn whole. */
export function windowList(key: string, lines: Line[], hits: LineHit[], at: number, room: number, bump: () => Promise<void>, lead?: number, count?: (top: number, end: number) => { above: number; below: number }): { lines: Line[]; hits: LineHit[] } {
  windowed = key
  const len = lines.length
  if (room < 5 || len <= room) {
    windowTops.delete(key)
    return { lines, hits }
  }
  const last = len - room + 1
  const prev = windowTops.get(key)
  const free = Boolean(prev?.free && prev.at === at)
  let top = Math.max(0, Math.min(prev?.top ?? 0, last))
  if (at >= 0 && !free) {
    for (let i = 0; i < 3; i++) {
      const f = windowFit(top, len, room)
      // a choice that moves up to the window's first row or above it: the window starts at the row that leads it (its
      // section's heading, or the list's top for its first row), so those rows can be reached by keys (live check
      // term-fix10, new quirk 5: ↑ back to home's first row left `↑ 4 more` and hid the Views and Documents headings)
      if (at < top || (lead !== undefined && lead < top && at === top)) top = lead !== undefined && lead <= at ? lead : at
      else if (at >= top + f.n) top = at - f.n + 1
      else break
      top = Math.max(0, Math.min(top, last))
    }
  }
  windowTops.set(key, { top, at, len, room, free })
  const f = windowFit(top, len, room)
  const page = Math.max(1, f.n - 1)
  const move = (to: number) => async () => {
    const cur = windowTops.get(key)
    if (cur) windowTops.set(key, { ...cur, top: Math.max(0, Math.min(to, last)), free: true })
    await bump()
  }
  const out: Line[] = []
  const outHits: LineHit[] = []
  // what the count rows count: the lines cut off, or with `count` the units its list counts (a transcript's turns, as
  // its header counts them, those of the pages not read with them too: bug hunt B29)
  const counted = count?.(top, top + f.n) ?? { above: top, below: len - top - f.n }
  if (f.up) {
    const words = `↑ ${num(counted.above)} more`
    outHits.push({ y: 0, x0: MARGIN_W + 2, x1: MARGIN_W + 2 + width(words), row: false, run: move(top - page) })
    out.push(pointed([{ s: '  ' }, dim(words)], false))
  }
  out.push(...lines.slice(top, top + f.n))
  for (const h of hits) if (h.y >= top && h.y < top + f.n) outHits.push({ ...h, y: h.y - top + f.up })
  if (f.down) {
    const words = `↓ ${num(counted.below)} more`
    outHits.push({ y: out.length, x0: MARGIN_W + 2, x1: MARGIN_W + 2 + width(words), row: false, run: move(top + page) })
    out.push(pointed([{ s: '  ' }, dim(words)], false))
  }
  return { lines: out, hits: outHits }
}

/** The wheel over the panel while it shows a cut list: the list's rows move by `by`, the choice where it is; false when
 *  the panel shows no cut list. */
export function wheelWindow(by: number): boolean {
  if (scrollShown && by) {
    scrollShown(by)
    return true
  }
  const cur = shownWindow ? windowTops.get(shownWindow) : undefined
  if (!cur || !by) return false
  const top = Math.max(0, Math.min(cur.top + by, cur.len - cur.room + 1))
  windowTops.set(shownWindow, { ...cur, top, free: true })
  return true
}

function listKeysEl(cx: Ctx, e: PaneEvent): RenderElement | null {
  if (!listRelay || e.surface === 'mobile' || keysHidden()) return null
  const { Box, Button, Input } = cx.els(e)
  const key = (k: string) => () => void relayKey(k)
  if (relayFlip) {
    relayMark = 1 - relayMark
    relayFlip = false
  }
  return (
    <Box key="list-keys" width={0} height={0} flexShrink={0} overflow="hidden" flexDirection="row">
      <Button key={RELAY.up} label="↑" plain onPress={key('up')} />
      {viewField || panelField ? (
        <Input key={RELAY.pick} value={(viewField ?? panelField)!.text} autoFocus onInput={v => {
          const f = viewField ?? panelField
          if (!f) return
          f.text = v
          void f.send(v)
        }} onSubmit={() => void (viewField ?? panelField)?.enter()} />
      ) : (
        <Input key={RELAY.pick} value={MARKS[relayMark]} autoFocus onInput={v => void relayInput(cx, v)} onSubmit={() => void relaySubmit(cx)} />
      )}
      <Button key={RELAY.down} label="↓" plain onPress={key('down')} />
    </Box>
  )
}

/** The ring's place in a view with no list (a card, a citation, a label): a Button no row tall that does nothing, which
 *  the panel puts the ring on as the view opens (term.ts giveKeys), so the ring rests on no text field and the view's
 *  letters are its hotkeys, as its hint row says. Without it the ring stayed wherever Claude Code left it, at times on
 *  the view's entry box, which then took `x` while the hint row said `x to close` (bug hunt L12). */
export const RING_REST = 'keys-rest'

function restKeyEl(cx: Ctx, e: PaneEvent): RenderElement | null {
  if (listRelay || e.surface === 'mobile' || keysHidden()) return null
  const { Box, Button } = cx.els(e)
  return (
    <Box key="rest-keys" width={0} height={0} flexShrink={0} overflow="hidden" flexDirection="row">
      <Button key={RING_REST} label="·" plain onPress={() => undefined} />
    </Box>
  )
}

/** Whether the panel's focus ring rests on its list's keys (the relay), as the last `ui.focus` put it. */
function listKeysHeld(): boolean {
  return paneFocused && !rt.typeThrough && RELAY_KEYS.includes(rt.panelFocus)
}

// a list's keys, which the relay passes on while the ring rests on it: ↑↓, Enter, Space and Backspace; ← and → reach no
// element of a pane, nor do the page keys while the relay's Input holds the ring
const LIST_HINT = /^(?:↑↓|←|→|Enter |Space |Backspace |PgUp|PgDn)/
const UNRELAYED_HINT = /^(?:←|→|PgUp|PgDn)/

/** The hint of a view whose keys are Claude Code's own ring over its fields and buttons, with no list (the label
 *  panel): with it, `↑↓ to choose` and it are named while the ring rests anywhere in the view. */
const RING_HINT = 'Enter to press or edit'

// the text fields the drawing being made draws, by their keys (rt.fields once it is shown)
let fieldsDrawing = new Set<string>()
// the field the drawing being made starts the ring on in place of a list's keys (rt.startRing once it is shown)
let startRingDrawing = ''

/** A text field's key, noted as drawn by the drawing being made: its ring's hint is named only while it is drawn. */
function fieldKey(key: string): string {
  fieldsDrawing.add(key)
  return key
}

// the panel's text fields by their keys, with what Enter does in each; an entry box (entry.tsx) says it itself
const FIELD_KEYS: [RegExp, string][] = [
  [ENTRY_KEY, 'Enter to ask'],
  [/^(?:lb-glob-|lb-values-)/, 'Enter to save'],
  [/^lb-name-/, 'Enter to rename'],
]

/** What Enter does in the text field that holds the panel's focus ring now; '' when no field holds it. */
export function focusedField(key: string): string {
  return FIELD_KEYS.find(([re]) => re.test(key))?.[1] ?? ''
}

/** A view's key hints with the way's after them, as bound now (rule 26: the hint row names only keys bound on it).
 *  While a text field holds the focus a letter goes into the field, so the hints are what Enter does there and that
 *  Esc leaves it; while an entry box holds it, none: like Claude Code's prompt box it says what it takes itself (Matt,
 *  2026-10-16: no `Enter to ask · Esc to leave the field` row). The list's Space and Backspace are bound as the view
 *  names them. */
function endHints(hints: readonly string[], autoFocus = ''): string[] {
  listExtraDrawing = { space: hints.some(h => h.startsWith('Space ')), backspace: hints.some(h => h.startsWith('Backspace ')) }
  // while the prompt holds the keys (Esc left a field, or a click on the prompt), a letter or Enter goes to the prompt,
  // and Enter would send it to main: no key of the panel's is named, only how to give the panel the keys; so too while
  // the panel's typing goes to the prompt (typeThrough)
  if (!paneFocused || rt.typeThrough) return [keysAwayHint()]
  // `autoFocus`: the view's field that takes the ring as it opens, before any ui.focus says where the ring is; a ring
  // on a field this drawing does not draw (one of the view before, live check term-fix9, quirk 1) is on none
  const ring = rt.panelFocus ? (fieldsDrawing.has(rt.panelFocus) ? rt.panelFocus : '') : autoFocus
  if (ring && ENTRY_KEY.test(ring)) return []
  const field = focusedField(ring)
  if (field) return [field, 'Esc to leave the field']
  // a list's keys only while the ring rests on them (listKeysHeld): until a ui.focus says so, ↑↓ walk the panel's
  // buttons and Enter presses the one the ring is on
  const held = listKeysHeld()
  // a view with no list whose ↑↓ walk its fields and buttons (the label panel) names them while the ring is anywhere
  const walks = hints.includes(RING_HINT)
  const own = hints
    .map(h => (h === 'Enter or a to ask' && !held ? 'a to ask' : h))
    .filter(h => h !== 'b to go back' && h !== 'x to close' && ((walks && /^(?:↑↓ |Enter )/.test(h)) || !(held ? UNRELAYED_HINT : LIST_HINT).test(h)))
  return [...own, ...wayHints]
}

/** The hint row while the panel does not hold the keys. */
export const UNFOCUSED_HINT = 'click the panel for its keys'
/** The hint row while the panel does not hold the keys and the prompt holds text: Claude Code then keeps the keys at the
 *  prompt, a click on the panel included (bug hunt L12: a click on a card left them there, and `a` and the question
 *  went to main's prompt). */
export const DRAFT_HINT = 'empty the prompt, then click the panel for its keys'

// whether the prompt held text as the panel was drawn without its keys
let draftHeld = false

/** How to give the panel its keys, while it is without them. */
function keysAwayHint(): string {
  return draftHeld ? DRAFT_HINT : UNFOCUSED_HINT
}

/** The key-hint row as bound now (endHints); none while an entry box holds the keys. */
export function hintsRow(els: El, hints: readonly string[], cols: number, autoFocus = ''): RenderElement {
  const named = endHints(hints, autoFocus)
  return named.length ? hintsEl(els, named, cols) : els.Box({ key: 'h-hints', flexDirection: 'column' })
}

/** The rows a view's key hints take as the panel draws them now (hintLines): what a list cut to the pane leaves them. */
export function hintHeight(hints: readonly string[], cols: number, autoFocus = ''): number {
  const named = endHints(hints, autoFocus)
  return named.length ? hintLines(named, cols).length : 0
}

/** The panel's bottom part (rule 25): the second rule, the actions 2 cells apart, the fields under them; then the
 *  key-hint row, the panel's last. */
export function bottomRows(cx: Ctx, e: PaneEvent, cols: number, controls: (RenderElement | null | false)[], fields: (RenderElement | null | false)[], hints: string[], rule = true, autoFocus = ''): RenderElement[] {
  const els = cx.els(e) as El
  const ctl = controlsEl(els, controls, 'bottom-controls')
  const fs = fields.filter((f): f is RenderElement => Boolean(f))
  return [...(rule && (ctl || fs.length) ? [ruleEl(els, cols, 'rule-bottom')] : []), ...(ctl ? [ctl] : []), ...fs, hintsRow(els, hints, cols, autoFocus)]
}

/** The bottom of a panel with an entry box (entry.tsx, rule 25): its actions 2 cells apart after a blank row, then the
 *  box, whose top rule is the panel's second rule, then the key-hint row; without a box, bottomRows. */
export function entryBottom(cx: Ctx, e: PaneEvent, cols: number, controls: (RenderElement | null | false)[], entry: RenderElement | null, hints: string[], fields: RenderElement[] = [], autoFocus = ''): RenderElement[] {
  if (!entry) return bottomRows(cx, e, cols, controls, fields, hints)
  const els = cx.els(e) as El
  const { Box } = els
  const ctl = controlsEl(els, controls, 'bottom-controls')
  const above = [...(ctl ? [ctl] : []), ...fields]
  return [...(above.length ? [<Box key="bottom-controls-row" marginTop={1} flexDirection="column">{above}</Box>] : []), entry, hintsRow(els, hints, cols, autoFocus)]
}

/** An empty region (rule 28): dim words at A2. */
export function none(cx: Ctx, e: PaneEvent, words = 'none'): RenderElement {
  const { Box, Text } = cx.els(e)
  return (
    <Box flexDirection="column" marginLeft={2}>
      <Text dimColor>{words}</Text>
    </Box>
  )
}

/** A field of the panel (rule 27): its label dim and lower case, the field after a gutter. */
function fieldRow(cx: Ctx, e: PaneEvent, label: string, field: RenderElement, key: string): RenderElement {
  const { Box, Text } = cx.els(e)
  return (
    <Box key={key} flexDirection="row">
      <Text dimColor>{`${label}  `}</Text>
      <Box flexGrow={1} flexShrink={1}>
        {field}
      </Box>
    </Box>
  )
}

// ------------------------------------------------------------------------------------------------ home

/** What the home panel lists, from what `thimble state` printed for its surfaces. */
export async function homeData(cx: Ctx): Promise<HomeData> {
  const views: HomeView[] = await homeViews(cx)
  const docs = await surfaceValue(cx, 'docs')
  const first = docs?.ok ? !rt.docsRead : false
  if (docs?.ok) rt.docsRead = true
  const reports: HomeReport[] = docs?.ok
    ? docsOf(docs.value).map(d => {
        // a document written since the session first read the list, and not opened since, is new
        const known = rt.docsKnown.get(d.slug)
        if (first) rt.docsKnown.set(d.slug, d.generation)
        return { slug: d.slug, title: d.title, form: d.renderer, state: d.status === 'generating' ? 'writing' : 'written', cards: 0, tools: 0, at: Date.parse(d.at) || 0, ...(!first && known !== d.generation && d.status !== 'generating' ? { fresh: true } : {}) }
      })
    : []
  const threads: HomeThread[] = []
  for (const t of (await cx.threads()) ?? []) {
    const st = t.running ? 'run' : rt.failed.has(t.id) ? 'problem' : t.answers ? 'ok' : 'dim'
    // its subject at R only when a card or a citation names it (a few words): a passage's sentence would cut the
    // question beside it
    const about = await anchorName(cx, t)
    const made = Date.parse(t.created ?? '') || 0
    threads.push({ id: t.id, title: quoted(clip(plainCites(t.question || t.title || t.anchorText || 'side thread'), 80)), about: about ? `about ${clip(about, 32)}` : '', words: t.running ? 'answering' : plural(t.answers, 'answer'), tone: st, unread: t.unread, earlier: Boolean(made && rt.startedAt && made < rt.startedAt), at: Date.parse(t.at) || 0 })
  }
  const canvas = await surfaceValue<Obj>(cx, 'canvas')
  const groups = canvas?.ok && Array.isArray(canvas.value.groups) ? (canvas.value.groups as unknown[]).filter(isObj) : []
  const cells = canvas?.ok && Array.isArray(canvas.value.cells) ? (canvas.value.cells as unknown[]).filter(isObj) : []
  // a card made since home was last seen is new on it (openHome)
  const cardOf = (c: Obj) => ({ id: str(c.id), kind: str(c.kind) || 'code', question: str(c.title) || 'a card', ...(rt.homeSince && madeAt(c) > rt.homeSince ? { fresh: true } : {}) })
  // a group by what it holds: a side thread's cards, a document's figures, or a group main named; a card no listed
  // group holds under `other cards`, last
  // a side thread's group by the thread's first question, as everywhere a thread is named (its title is a slug)
  const rowsNow = (await cx.threads()) ?? []
  const threadHead = (chat: string): string => {
    const r = rowsNow.find(t => t.id === chat)
    const q = r ? plainCites(r.question || r.title || '') : ''
    return q.trim() ? quoted(clip(q, 60)) : ''
  }
  const cardGroups: HomeCardGroup[] = groupCards(
    groups.map(g => {
      const from: HomeCardGroup['from'] = g.anchor || g.chat ? 'thread' : g.role === 'figures' ? 'report' : 'other'
      const head = (g.chat ? threadHead(str(g.chat)) : '') || str(g.title) || 'cards'
      return { head, from, cards: cells.filter(c => c.notebook === g.id).map(cardOf), at: Date.parse(str(g.ts)) || 0 }
    }),
    cells.map(cardOf),
  )
  const labelsRaw = await surfaceValue(cx, 'labels')
  const raw = labelsRaw?.ok ? labelsOf(labelsRaw.value) : []
  const labels = await homeLabels(cx, raw)
  // made since home was last seen, as a card is new (openHome)
  raw.forEach((x, i) => {
    const made = Date.parse(str((x as { ts?: unknown }).ts)) || 0
    if (rt.homeSince && made > rt.homeSince) labels[i]!.fresh = true
  })
  // 0.9.0 (SPEC-v2 J4): this session's coverage, its citations, the checks' comments on answers, each while its feature
  // is on
  const f = await featuresOf(cx)
  const coverage = f.coverage ? noControls((await cx.coverageSummary())?.line ?? '') : null
  const cites: HomeCite[] | null = f.citationMarks ? (await citeItems(cx)).map(c => ({ key: c.key, value: noControls(c.value), place: noControls(c.chip ?? citePlace(c.ref)), verdict: c.verdict, why: c.why, ref: c.ref, ...(c.card ? { card: c.card, n: c.n } : {}) })) : null
  const comments: HomeComment[] | null = f.checks ? (await openComments(cx)).map(c => ({ id: c.id, check: noControls(c.checkName), colour: hueOf(c.color || 2), quote: noControls(c.quote), ref: c.ref })) : null
  // on Claude Code's main screen, which takes no clicks, the rows above the prompt, first, with their acts on keys (bug
  // hunt F1); in fullscreen they take clicks there, and home leaves them out
  const waiting = classicScreen() ? (await waitItems(cx)).map(w => ({ key: w.key, label: w.label, title: w.name || w.words })) : null
  // a list not read yet says so, not `none` (bug hunt J9)
  const reading: SectionId[] = [...(canvas === undefined ? (['cards'] as const) : []), ...(labelsRaw === undefined ? (['labels'] as const) : [])]
  return { views, reports, threads, cardGroups, labels, coverage, cites, comments, noLabels: !f.labels, waiting, ...(reading.length ? { reading } : {}) }
}

/** The labels as home and the labels list draw them (home.ts labelBlocks): each with its values' counts and colors, its
 *  runs in words, and its records of no fit and unsure counted while labels are on. */
async function homeLabels(cx: Ctx, ls: readonly ThimbleLabel[]): Promise<HomeLabel[]> {
  const unsure = (await featuresOf(cx)).labels ? new Map((await cx.labelUnsure()).map(u => [u.id, u])) : new Map<string, LabelUnsure>()
  const runs = await cx.labelRuns()
  return ls.map(l => {
    // its runs as the labels list, its panel and its card say them (lib.ts labelState), a run's count live
    const st = labelState(l, runs)
    const colors = classColors(l.classes)
    const u = unsure.get(l.id)
    return {
      slug: l.id,
      name: l.name ?? l.id,
      kind: l.kind ?? '',
      trial: Boolean(l.trial),
      // as thimble.labels() reads the rows: a record the analyst set to another value under that value; while a run
      // goes on, as its file says them this second (term.ts runsLane)
      counts: runs.live[l.id]?.counts ?? l.verdicts?.counts ?? l.label_stats?.counts ?? {},
      values: l.labels ?? Object.keys(l.label_stats?.counts ?? {}),
      paths: (l.glob ?? '').split(/,\s*/).filter(Boolean),
      running: st.running,
      ran: st.ran,
      state: labelStateWords(st),
      // its values' colors as its classes have them, as its panel draws them
      ...(colors ? { colors } : {}),
      ...(u ? { noFit: u.noFit, unsure: u.unsure } : {}),
    }
  })
}

/** When a card was made (ms), as the canvas lists it. */
function madeAt(c: Obj): number {
  return Date.parse(str(c.created_ts) || str(c.ts)) || 0
}

/** Home opened from the row above the prompt (its `open ›`): the group that holds the first new card unfolded (its
 *  section shown whole when the group is past the first few), the choice on that card; with no new card, on the first
 *  new document, view or label (live check term-fix8, quirk 6: the new card stood folded, the choice on an old row). */
export async function openHomeNew(cx: Ctx): Promise<void> {
  const seen = await cx.homeSeen()
  const since = seen?.at ?? 0
  await Promise.all([readSurface(cx, 'canvas', 'cards', ['--since', new Date(0).toISOString()]), readSurface(cx, 'labels', 'labels'), readSurface(cx, 'docs', 'docs')])
  const canvas = await surfaceValue<Obj>(cx, 'canvas')
  const cells = canvas?.ok && Array.isArray(canvas.value.cells) ? (canvas.value.cells as unknown[]).filter(isObj) : []
  const fresh = new Set(cells.filter(c => since && madeAt(c) > since).map(c => str(c.id)))
  const d = await homeData(cx)
  let ui = (await cx.homeUi()) as HomeUi
  const without = (xs: string[], x: string) => xs.filter(y => y !== x)
  const gi = d.cardGroups.findIndex(g => g.cards.some(c => fresh.has(c.id)))
  if (gi >= 0) {
    const g = d.cardGroups[gi]!
    const fold = `cards:${g.from}:${g.head}`
    ui = { ...ui, folded: without(ui.folded, fold), unfolded: [...without(ui.unfolded, fold), fold], pick: `card:${g.cards.find(c => fresh.has(c.id))!.id}`, more: gi >= HOME_FIRST && !ui.more.includes('cards') ? [...ui.more, 'cards'] : ui.more }
  } else {
    const r = d.reports.find(x => x.fresh)
    const v = d.views.find(x => x.fresh)
    const newLabels = seen ? Math.max(0, d.labels.length - seen.labels) : 0
    const l = newLabels ? d.labels[d.labels.length - newLabels] : undefined
    const pick = v ? `view:${v.slug}` : r ? `report:${r.slug}` : l ? `label:${l.slug}` : ''
    if (pick) ui = { ...ui, pick }
  }
  await cx.setHomeUi(ui)
  await openHome(cx)
}

// the home panel's last layout, which a key steps through
let homeLast: HomeLayout | null = null

/** The home panel (SPEC.md, "Home"), drawn from home.ts's lines: a click on a row opens it, on a heading its
 *  section's panel, on a group or folder folds it; ↑↓ choose a row, Enter opens it and Space folds it. */
async function drawHome(cx: Ctx, e: PaneEvent): Promise<RenderElement> {
  const { Box, Text } = cx.els(e)
  if (e.surface !== 'terminal' && e.surface !== 'desktop') return <Text dimColor>The home panel needs the terminal or the desktop app.</Text>
  // the pane's own width, never more: a pane 40 columns wide cut each row's right part (live check term-fix10)
  const cols = e.props.bodyColumns
  const ui = (await cx.homeUi()) as HomeUi
  // its keys named only while it holds them, as every view's (endHints; live check term-fix6, new quirk 4: home opened
  // from the toast named its keys while they went to the prompt)
  const lay = homeLayout(await homeData(cx), ui, cols, endHints(HOME_HINTS))
  homeLast = lay
  const run = (a: HomeAct) => async () => {
    if (a.op === 'open') return homeOpen(cx, a.open)
    const cur = (await cx.homeUi()) as HomeUi
    const next = homeReduce(cur, a)
    // a section shown whole: the choice moves from its `… N more` onto the first row it showed
    await cx.setHomeUi(a.op === 'more' && a.next && cur.pick === `more:${a.sec}` ? { ...next, pick: a.next } : next)
  }
  const allHits: LineHit[] = lay.hits.map(h => ({
    y: h.y,
    x0: h.x0,
    x1: h.x1,
    row: h.row,
    run: async () => {
      if (h.pick) await cx.setHomeUi({ ...((await cx.homeUi()) as HomeUi), pick: h.pick })
      await run(h.act)()
    },
  }))
  // the sections cut to the pane's rows around the chosen row, the rule and the hint rows kept (windowList): the title
  // row, the rule and the hint rows take the rest
  const pick = ui.pick || lay.picks[0]?.key || ''
  const pickY = lay.hits.find(h => h.pick === pick)?.y ?? -1
  const last = lay.lines.length - lay.hintRows
  // the rows above the sections: the rule (the title is the title row's)
  const top = 1
  // the row that leads the chosen one: the top for the first row the keys choose, else its section's heading
  const lead = pick === lay.picks[0]?.key ? top : Math.max(top, ...lay.heads.filter(y => y <= pickY))
  const win = windowList('home', lay.lines.slice(top, last), allHits.filter(h => h.y >= top && h.y < last).map(h => ({ ...h, y: h.y - top })), pickY - top, bodyRows - 1 - top - lay.hintRows, () => cx.bumpPanel(), lead - top)
  const lines = [...lay.lines.slice(0, top), ...win.lines, ...lay.lines.slice(last)]
  const hits: LineHit[] = [...allHits.filter(h => h.y < top), ...win.hits.map(h => ({ ...h, y: h.y + top }))]
  const onKey = async (k: string) => {
    const cur = (await cx.homeUi()) as HomeUi
    const l = homeLast
    if (!l) return
    const pick = cur.pick || l.picks[0]?.key || ''
    const at = l.picks.find(x => x.key === pick)
    if (k === 'return' || k === 'enter') return at ? run(at.act)() : undefined
    if (k === 'space' || k === ' ') return at?.act.op === 'fold' || at?.act.op === 'more' ? run(at.act)() : undefined
    const next = homePick(l, cur, k)
    if (next !== cur.pick) await cx.setHomeUi({ ...cur, pick: next })
  }
  return <Box flexDirection="column">{linesEl(cx, e, marginKey('home'), lines, hits, cols + MARGIN_W, onKey)}</Box>
}

async function homeOpen(cx: Ctx, o: HomeOpen): Promise<void> {
  switch (o.kind) {
    case 'view': {
      const v = (await homeViews(cx)).find(x => x.slug === o.slug)
      return openView(cx, o.slug, v?.name ?? o.slug)
    }
    case 'report':
      return openDoc(cx, o.slug, o.title ?? o.slug)
    case 'thread':
      return openThread(cx, o.id)
    case 'card':
      return openCard(cx, o.id)
    case 'label': {
      const got = await surfaceValue(cx, 'labels')
      const hit = got?.ok ? labelsOf(got.value).find(l => l.name === o.name || l.id === o.name) : undefined
      return openLabel(cx, hit?.id ?? o.name, o.name)
    }
    case 'cite':
      return o.card ? openCard(cx, o.card) : openCite(cx, o.ref, o.display)
    case 'comment':
      return openChecks(cx, o.id)
    case 'waiting':
      return openPanel(cx, { view: 'waiting', title: o.label, slug: o.key })
    case 'pane': {
      // a section's list: its `new` on the summary line cleared (band.tsx)
      if (o.view === 'reports') return openSection(cx, 'docs')
      if (o.view === 'threads' || o.view === 'labels' || o.view === 'views') return openSection(cx, o.view)
      if (o.view === 'coverage') return openCoverage(cx)
      if (o.view === 'citations') return openCitations(cx)
      if (o.view === 'checks') return openChecks(cx)
      return openPanel(cx, { view: 'home', title: 'Home' })
    }
  }
}

// ------------------------------------------------------------------------------------------------ a card

/** A card in the panel (SPEC.md, "Cards", the card pane): its question is the panel's title; its kind, who made
 *  it, how its last run ended (`last run failed` in red) and a card check that ended in an error (CHECK_UNRUN or
 *  CHECK_UNFINISHED) the dim subtitle; the card in its border, its takeaway
 *  under it; at the bottom `code  run again` (`◌ running` while it runs) and the entry box, whose question starts a
 *  side thread about the card. Its code (`mode: code`) through the `Code` element with its gutter at A0, then `output`,
 *  the last 8 lines its run printed; `card  run again` and the entry box at the bottom. A run again goes to main, whose
 *  Bash runs a card (`thimble-run card`). */
async function drawCard(cx: Ctx, e: PaneEvent, p: TermPanel): Promise<RenderElement> {
  const els = cx.els(e) as El
  const { Box, Text, Button } = cx.els(e)
  const id = p.card ?? ''
  const tc = await cx.card(id)
  const cols = Math.max(30, e.props.bodyColumns)
  if (!tc) return none(cx, e, '◌ reading the card')
  if (!tc.data) return <Box flexDirection="column"><Text color={COLORS.problem} wrap="wrap">{`× this card cannot be drawn: ${tc.error || 'the card is not in this workspace'}`}</Text></Box>
  const data = tc.data as CardData
  const by = tc.by ? `made by ${/^(main|terminal|user)$/.test(tc.by) ? 'main' : /^chat:/.test(tc.by) ? 'a side thread' : tc.by}` : ''
  const ran: Seg | null = tc.ran === 'error' ? { s: 'last run failed', fg: COLORS.problem } : tc.ran === 'ok' ? dim('last run ok') : null
  // a card check that ended in an error says so in plain words, dim: the card itself is fine, and red is only for a
  // problem with the card (SPEC.md, Checks 3); why it ended is in the check's record, for main to read
  const checked: Seg | null = tc.check?.state === 'error' ? dim(tc.check.unrun ? CHECK_UNRUN : CHECK_UNFINISHED) : null
  const askKey0 = `ask-card-${id}`
  const entry = e.surface === 'mobile' ? null : askEntry(cx, e, { key: askKey0, placeholder: 'ask about this card', cols, target: { kind: 'card', ref: `card:${id}`, cardId: id, text: data.question } })
  // its run waits or runs; a card check that waits to start once the run ended is no run (bug hunt B19)
  const busy = Boolean(tc.busy) && tc.busy !== CHECK_WAITS
  const again = () => {
    if (busy) return
    void cx.submit(`Run this card again. Use Bash to run this command exactly as it is, with no \`cd\` before it: thimble-run card ${id}`)
  }
  const code = p.mode === 'code'
  // the subtitle opens with the card's id as its chips read it (`card:<name>`)
  const body: RenderElement[] = [...headerEls(els, { title: data.question, cols, sub: subLine([cardTag(id), code ? 'its code' : tc.kind, by, ran, checked]) })]
  const runEl = busy ? <Text key="card-running">◌ running</Text> : tc.code ? <Button key="card-again" label="run again" plain onPress={again} /> : null
  const keys: Key[] = [...(entry ? [askKey(cx, askKey0)] : []), ...(tc.code && !busy ? [{ key: 'again', hotkey: 'r', onPress: again }] : [])]
  const askHint = entry ? ['a to ask'] : []
  const runHint = tc.code && !busy ? ['r to run again'] : []
  if (code) {
    body.push(tc.code ? codeRows(cx, e, tc.code, 400) : none(cx, e, 'no code'))
    // what its last run printed: its last 8 lines
    const out = (tc.printed ?? '').split('\n').filter(l => l.trim()).slice(-8)
    body.push(
      fieldRow(
        cx,
        e,
        'output',
        out.length ? (
          <Box flexDirection="column">
            {out.map((l, i) => (
              <Text key={`out-${i}`} wrap="truncate-end">
                {demojibake(l)}
              </Text>
            ))}
          </Box>
        ) : (
          <Text dimColor>nothing printed</Text>
        ),
        'card-output',
      ),
    )
    keys.push({ key: 'card', hotkey: 'c', onPress: () => void openCard(cx, id) })
    body.push(...entryBottom(cx, e, cols, [<Button key="card-card" label="card" plain onPress={() => void openCard(cx, id)} />, runEl], entry, ['c for the card', ...runHint, ...askHint, 'b to go back', 'x to close']))
  } else {
    body.push(<Box key="card-box" flexDirection="column">{await cardBlock(cx, e, id, cols, 'pane', { pane: true })}</Box>)
    if (tc.code) keys.push({ key: 'code', hotkey: 'c', onPress: () => void openCard(cx, id, 'code') })
    body.push(...entryBottom(cx, e, cols, [tc.code ? <Button key="card-code" label="code" plain onPress={() => void openCard(cx, id, 'code')} /> : null, runEl], entry, [...(tc.code ? ['c for its code'] : []), ...runHint, ...askHint, 'b to go back', 'x to close']))
  }
  const hk = hiddenKeys(cx, e, keys)
  return <Box flexDirection="column">{[...(hk ? [hk] : []), ...body]}</Box>
}

// ------------------------------------------------------------------------------------------------ a citation

/** Where position `p` of a line lands once each tab is drawn as two spaces and its mojibake is mended. */
function shifted(raw: string, p: number): number {
  return demojibake(raw.slice(0, p)).replace(/\t/g, '  ').length
}

/** Whether a citation's cited lines are lit whole: none of them holds the value it shows (a place cited without words,
 *  `[[README.md#L5]]`, or a value the line does not hold), and no example's quote marks a passage, so the cited part is
 *  the lines themselves (Matt, 2026-10-07: "the part it cited isn't highlighted"). */
function wholeLit(hits: readonly TermVerdict['lines'][number][], quote: string): boolean {
  return !quote && !hits.some(l => l.spans?.length)
}

/** The cited lines nested at A2 (SPEC.md, section 7, "The citation panel"): each line's number right-aligned in
 *  a dim column (the cited one's in the text colour), its text after a gutter; a cited line wrapped over 3 to 8 rows
 *  (by the pane's rows) around the value or the quoted passage on the citation's purple (citeHighlight); two lines of context
 *  around the cited ones when a cited line wraps; a long context line cut with `…` around its value. */
function lineRows(cx: Ctx, e: PaneEvent, v: TermVerdict, cols: number, quote: string): RenderElement[] {
  const { Text } = cx.els(e)
  // at most 60 rows, never ending on part of a record: a record's rows after its first have no number
  let all = v.lines.slice(0, 60)
  if (v.lines.length > all.length && v.lines[all.length]!.n === 0) {
    let end = all.length
    while (end > 0 && all[end - 1]!.n === 0) end--
    if (all.slice(0, end - 1).some(l => l.hit)) all = all.slice(0, end - 1)
  }
  const gutter = Math.max(1, ...all.map(l => String(l.n || '').length))
  const room = Math.max(10, cols - gutter - 4)
  const hits = all.filter(l => l.hit)
  const hitRows = Math.max(3, Math.min(8, Math.floor(((e.props.scroll?.bodyRows || 20) - 14) / Math.max(1, hits.length))))
  const wraps = hits.some(l => l.text.length > room)
  const near = wraps ? 2 : 99
  const firstHit = all.findIndex(l => l.hit)
  const lastHit = all.length - 1 - [...all].reverse().findIndex(l => l.hit)
  const lines = firstHit < 0 ? all : all.filter((l, i) => l.hit || (i >= firstHit - near && i <= lastHit + near))
  const whole = wholeLit(hits, quote)
  const out: RenderElement[] = []
  for (const l of lines) {
    const text = demojibake(l.text).replace(/\t/g, '  ')
    const n = l.n ? String(l.n).padStart(gutter) : ' '.repeat(gutter)
    const spans = (l.spans ?? []).map(([a, b]) => [shifted(l.text, a!), shifted(l.text, b!)] as [number, number])
    if (!l.hit) {
      // a context line: cut around its value when it is wider than the room
      let t = text
      let sp = spans
      if (t.length > room) {
        // each end cut at a word, `…` right against the words: no space between them
        const w = windowAt(t, sp.length ? sp[0]![0] : 0, room)
        t = w.text
        sp = sp.map(([a, b]) => [a - w.shift, b - w.shift] as [number, number])
      }
      out.push(
        <Text wrap="truncate-end">
          <Text dimColor>{`  ${n}  `}</Text>
          <Text dimColor>{t || ' '}</Text>
        </Text>,
      )
      continue
    }
    const span: [number, number] | null = quote ? quoteSpan(text, quote) : (spans[0] ?? (whole ? [0, text.length] : null))
    wrapAround(text, span, room, hitRows).forEach((r, i) =>
      out.push(
        <Text wrap="truncate-end">
          <Text>{`  ${i === 0 ? n : ' '.repeat(gutter)}  `}</Text>
          <Text>{r.hi ? r.text.slice(0, r.hi[0]) : r.text || ' '}</Text>
          {r.hi ? <Text backgroundColor={citeHighlight()}>{r.text.slice(r.hi[0], r.hi[1])}</Text> : null}
          {r.hi ? <Text>{r.text.slice(r.hi[1])}</Text> : null}
        </Text>,
      ),
    )
  }
  return out
}

// where a file citation's window over its file starts once the analyst moved it, by the citation's ref: the `at` of
// its first row (citeWindow); none, and it starts a few lines above the cited one
const citeTops = new Map<string, number>()
// the pages of a file the window reads as it moves, by their surface key, while they are read
const citeReading = new Set<string>()
// what the wheel does to the window the drawing being made draws, and to the one the drawing shown last drew (wheelWindow)
let scrollDrawing: ((by: number) => void) | null = null
let scrollShown: ((by: number) => void) | null = null

/** A row of a file citation's window: a line of the file (`at` its number), or a row of the cited record (`at` its
 *  line and the row's place in it in thousandths; `n` 0 for a record's rows after its first). */
type WinRow = { at: number; line: number; n: number; text: string; hit: boolean; spans: number[][] }

/** A file citation's lines as a window over the whole file (Matt, 2026-10-07: "you can't see beyond the few lines it
 *  picks and the part it cited isn't highlighted"): the lines nested at A2 as lineRows draws them, the cited ones in
 *  the text colour with the value (the passage an example quotes, or the whole line for a citation that marks none) on
 *  the citation's purple (citeHighlight), the lines around them dim, one row each; `room` rows tall, opening with the cited lines
 *  a third of the way down, `↑ N more` and `↓ N more` dim on a row each for the file's lines above and below, a click on
 *  one a page. ↑↓ (the list's keys, through the relay) and the wheel (wheelWindow) move it a line; as it nears a page's
 *  end the next page of the file is read (term.ts citePage). Null until a page of the file is read, or when the file
 *  does not page as lines; lineRows draws the cited lines then. */
async function citeWindow(cx: Ctx, e: PaneEvent, key: string, v: TermVerdict, cols: number, quote: string, room: number): Promise<{ el: RenderElement; scrolls: boolean } | null> {
  const path = v.path ?? ''
  const hits = v.lines.filter(l => l.hit)
  if (!path || typeof v.line !== 'number' || !hits.length) return null
  const first = v.line
  const last = Math.max(first, ...hits.map(l => l.n))
  // the pages read around where the window stands (the first, the page term.ts loadPanel read for the cited lines),
  // and the page of the cited lines, so the window has rows while the page it moved to is read
  const stand = Math.floor(citeTops.get(key) ?? Math.max(1, first - 10))
  const known = new Map<number, string>()
  const held: number[] = []
  let total = 0
  const pages: number[] = []
  for (let at = citePage(stand - room - 100); at <= citePage(stand + 2 * room + 100); at += 100) pages.push(at)
  if (!pages.includes(citePage(first - 10))) pages.push(citePage(first - 10))
  for (const at of pages) {
    const got = await surfaceValue<Obj>(cx, `file:${path}:${at}`)
    if (!got?.ok || got.value.binary) continue
    const page = got.value
    if (typeof page.total_lines === 'number') total = Math.max(total, page.total_lines)
    const from = typeof page.start === 'number' ? page.start : at
    held.push(from)
    ;((Array.isArray(page.records) ? page.records : []) as unknown[]).forEach((r, i) => known.set(isObj(r) && typeof r.line === 'number' ? r.line : from + i, aroundLine(r)))
  }
  if (!held.length) return null
  // once the window moved (a key, the wheel, a click: never while it is drawn, which writes nothing), the page of each
  // line a window's height above or below where it stands that no page read holds, read once, so a line or a page more
  // is there as it moves on
  const readAround = (to: number) => {
    for (const l of [Math.max(1, to - room), to, to + 2 * room]) {
      const at = citePage(l)
      const k = `file:${path}:${at}`
      if ((total && l > total) || held.some(h => h <= l && l < h + 200) || citeReading.has(k)) continue
      citeReading.add(k)
      void (async () => {
        if (!(await surfaceValue(cx, k))) await readFilePage(cx, path, at)
        citeReading.delete(k)
        await cx.bumpPanel()
      })()
    }
  }
  // the lines around the cited ones as the check read them; then the run of lines without a gap where the window
  // stands (a page not read yet ends it), the cited record over its rows in its place when the run holds it
  for (const l of v.lines) if (!l.hit && l.n > 0) known.set(l.n, l.text)
  for (let n = first; n <= last; n++) if (!known.has(n)) known.set(n, '')
  const anchor = !citeTops.has(key) ? first : known.has(stand) ? stand : [...known.keys()].reduce((a, n) => (Math.abs(n - stand) < Math.abs(a - stand) ? n : a))
  let lo = anchor
  let hi = anchor
  while (known.has(lo - 1)) lo--
  while (known.has(hi + 1)) hi++
  const rows: WinRow[] = []
  const ctx = (n: number): WinRow => ({ at: n, line: n, n, text: known.get(n)!, hit: false, spans: [] })
  for (let n = lo; n <= Math.min(hi, first - 1); n++) rows.push(ctx(n))
  if (first >= lo && last <= hi) {
    let rec = first
    let part = 0
    for (const l of hits) {
      if (l.n) {
        rec = l.n
        part = 0
      }
      rows.push({ at: rec + part++ / 1000, line: rec, n: l.n, text: l.text, hit: true, spans: l.spans ?? [] })
    }
  }
  for (let n = Math.max(lo, last + 1); n <= hi; n++) rows.push(ctx(n))
  total = Math.max(total, rows.at(-1)!.line)
  const gutter = String(total).length
  const textRoom = Math.max(10, cols - gutter - 4)
  const hitRows = Math.max(3, Math.min(8, Math.floor(((e.props.scroll?.bodyRows || 20) - 14) / Math.max(1, hits.length))))
  const whole = wholeLit(hits, quote)
  // each row as the lines it takes: a line around the cited ones on one dim row, cut around its start; a cited row
  // wrapped over up to `hitRows` rows around its value
  const linesOf = (r: WinRow): Line[] => {
    const text = demojibake(r.text).replace(/\t/g, '  ')
    const n = r.n ? String(r.n).padStart(gutter) : ' '.repeat(gutter)
    if (!r.hit) return [pointed([dim(`  ${n}  `), dim((text.length > textRoom ? windowAt(text, 0, textRoom).text : text) || ' ')], false)]
    const spans = r.spans.map(([a, b]) => [shifted(r.text, a!), shifted(r.text, b!)] as [number, number])
    const span: [number, number] | null = quote ? quoteSpan(text, quote) : (spans[0] ?? (whole ? [0, text.length] : null))
    return wrapAround(text, span, textRoom, hitRows).map((w, i) =>
      pointed([{ s: `  ${i === 0 ? n : ' '.repeat(gutter)}  ` }, ...(w.hi ? [{ s: w.text.slice(0, w.hi[0]) }, { s: w.text.slice(w.hi[0], w.hi[1]), bg: citeHighlight() }, { s: w.text.slice(w.hi[1]) }] : [{ s: w.text || ' ' }])].filter(x => x.s !== ''), false),
    )
  }
  const height = rows.map(r => linesOf(r).length)
  // the last row the window can start at once the file's end is read: the end on its last row
  const endRead = rows.at(-1)!.line >= total
  let maxTop = rows.length - 1
  if (endRead) {
    let sum = height[maxTop]!
    while (maxTop > 0 && sum + height[maxTop - 1]! + (rows[maxTop - 1]!.line > 1 ? 1 : 0) <= room) sum += height[--maxTop]!
  }
  // where it opens: the cited rows a third of the way down, two lines above them at least where they fit
  const block = Math.max(0, rows.findIndex(r => r.hit))
  const blockH = height.slice(block, block + hits.length).reduce((a, b) => a + b, 0)
  const lead = Math.max(0, Math.min(block, Math.max(Math.min(2, room - 2 - blockH), Math.floor((room - 2 - blockH) / 3))))
  const want = citeTops.get(key)
  let top = want === undefined ? block - lead : rows.findIndex(r => r.at >= want)
  if (top < 0) top = rows.length - 1
  top = Math.max(0, Math.min(top, maxTop))
  const out: Line[] = []
  const outHits: LineHit[] = []
  const page = Math.max(1, room - 3)
  // where the window stands among the rows (below 0 or past the last: lines not read yet), moved by each key and turn
  // of the wheel until the panel draws again, never above the file's first line or past where its end shows
  let pos = top
  const scroll = (by: number) => {
    pos = Math.max(1 - rows[0]!.line, Math.min(pos + by, endRead ? maxTop : rows.length - 1 + total - rows.at(-1)!.line))
    const at = pos < 0 ? rows[0]!.line + pos : pos < rows.length ? rows[pos]!.at : rows.at(-1)!.line + pos - (rows.length - 1)
    citeTops.set(key, at)
    readAround(Math.floor(at))
  }
  const countRow = (words: string, by: number) => {
    outHits.push({ y: out.length, x0: MARGIN_W + 2, x1: MARGIN_W + 2 + width(words), row: false, run: () => scroll(by) })
    out.push(pointed([{ s: '  ' }, dim(words)], false))
  }
  const above = rows[top]!.line - 1
  if (above > 0) countRow(`↑ ${num(above)} more`, -page)
  let shownLast = top - 1
  for (let i = top; i < rows.length; i++) {
    const ls = linesOf(rows[i]!)
    // a row below for `↓ N more` unless this is the file's last
    const left = room - out.length - (i === rows.length - 1 && endRead ? 0 : 1)
    if (ls.length > left && i > top) break
    out.push(...ls.slice(0, Math.max(1, left)))
    shownLast = i
    if (ls.length > left) break
  }
  const below = total - rows[shownLast]!.line + (shownLast < rows.length - 1 && rows[shownLast + 1]!.line === rows[shownLast]!.line ? 1 : 0)
  if (below > 0) countRow(`↓ ${num(below)} more`, page)
  const onKey = (k: string) => {
    if (k === 'up' || k === 'k') return scroll(-1)
    if (k === 'down' || k === 'j') return scroll(1)
    if (k === 'pageup') return scroll(-page)
    if (k === 'pagedown') return scroll(page)
    return undefined
  }
  scrollDrawing = scroll
  return { el: linesEl(cx, e, marginKey('cite-lines'), out, outHits, cols + MARGIN_W, onKey), scrolls: above > 0 || below > 0 }
}

const sameKey = (a: string, b: string) => a === b || (a.trim() !== '' && b.trim() !== '' && Number(a) === Number(b)) || a.toLowerCase() === b.toLowerCase()

/** The item of a card's layout a verdict names (by the resolver's column and row): a table's cell, a bar, a line's
 *  point by its series and x, a timeline's event by its number, a diagram's node or edge; -1 for none. */
function citedItem(card: CardData, items: Item[], v: TermVerdict): number {
  if (!v.column || v.row === undefined || v.row === '') return -1
  if (card.kind === 'diagram' && v.column === 'edge') return items.findIndex(it => it.open === `card:${card.id}#edge/${v.row}`)
  if (card.kind === 'diagram' && v.column === 'node') return (card.nodes ?? []).slice(0, MAX_NODES).findIndex(n => String(n.id) === v.row)
  if (card.kind === 'timeline' && v.column === 'time') {
    const n = Number(v.row) - 1
    return n >= 0 && n < items.length ? n : -1
  }
  const pre = `card:${card.id}#${v.column}/`
  return items.findIndex(it => it.open.startsWith(pre) && sameKey(it.open.slice(pre.length), v.row!))
}

/** A card whose cited table or bar row is past the rows drawn, that row in place of the last one drawn (a bar's label
 *  with each of its groups' rows). */
function withCitedRow(card: CardData, v: TermVerdict): CardData {
  const cap = card.kind === 'table' ? MAX_TABLE_ROWS : card.kind === 'bar' || card.kind === 'label' ? MAX_BARS : 0
  const all = card.rows ?? []
  if (!cap || all.length <= cap || !v.row) return card
  if (card.kind !== 'table') {
    const bars = all as BarRow[]
    const labels = [...new Set(bars.map(b => b.label))]
    const at = labels.findIndex(l => sameKey(l, v.row!))
    if (at < cap) return card
    const keep = new Set([...labels.slice(0, cap - 1), labels[at]!])
    return { ...card, rows: bars.filter(b => keep.has(b.label)) as CardData['rows'] }
  }
  const r = all.findIndex(x => sameKey(fmt(card.kind === 'table' ? (x as Cell[])[0] : (x as BarRow).label), v.row!))
  return r < cap ? card : { ...card, rows: [...all.slice(0, cap - 1), all[r]!] as CardData['rows'] }
}

/** The cells of a layout that hit item `k`, on `bg`. */
function litItem(lay: Layout, k: number, bg: string): Line[] {
  if (k < 0) return lay.lines
  const spans: { line: number; x0: number; x1: number }[] = []
  lay.lines.forEach((l, y) => {
    const w = lineWidth(l)
    let x0 = -1
    for (let x = 0; x <= w; x++) {
      const on = x < w && lay.hit(x, y) === k
      if (on && x0 < 0) x0 = x
      if (!on && x0 >= 0) {
        spans.push({ line: y, x0, x1: x })
        x0 = -1
      }
    }
  })
  return shade(lay.lines, spans, bg)
}

/** A card with the cited mark on the citation's purple (citeHighlight), kept in view: a cited row past the drawn rows in place of
 *  the last; a table's column names, then the rows around the cited one when the card is taller than the pane's room;
 *  a total's `all` lit. */
function citedLines(card: CardData, v: TermVerdict, w: number, room: number): { card: CardData; lines: Line[] } {
  const shown = withCitedRow(card, v)
  const base = cardLayout(shown, w, -1, 8)
  const k = citedItem(shown, base.items, v)
  const hi = citeHighlight()
  let lines = k >= 0 ? litItem(base, k, hi) : base.lines
  if (k < 0 && (shown.kind === 'bar' || shown.kind === 'label') && v.row === 'all') {
    lines = lines.map(l => {
      const at = l.findIndex(x => x.s === 'all  ')
      return at < 0 ? l : l.map((x, j) => (j === at + 1 ? { ...x, bg: hi } : x))
    })
  }
  const ys = lines.flatMap((l, y) => (l.some(x => x.bg === hi) ? [y] : []))
  if (lines.length > room && ys.length && ys.at(-1)! >= room) {
    // a table's column names are the lines before its first row
    let head = 0
    if (shown.kind === 'table') while (head < lines.length && base.hit(0, head) < 0) head++
    const lo = Math.max(head, Math.min(ys[0]! - 1, lines.length - (room - head)))
    lines = [...lines.slice(0, head), ...lines.slice(lo, lo + room - head)]
  }
  return { card: shown, lines }
}

/** A card the panel draws itself, laid out as every card is (reply.tsx cardBlock): a full round border in the rule grey
 *  with a cell of padding; its title in bold with its id (`card:<name>`), a blank row, its body, then its label rows. */
function framedCard(cx: Ctx, e: PaneEvent, card: CardData, w: number, lines: Line[], key: string): RenderElement {
  const { Box, Text } = cx.els(e)
  const inner = Math.max(10, w - 4)
  return (
    <Box key={key} flexDirection="column" width={w} borderStyle="round" borderColor={COLORS.rule} paddingX={1}>
      {paintLines(Box, Text, [...titleLines(card.question, inner, cardTag(card.id)).lines, [], ...lines, ...labelHead(card, inner).lines])}
    </Box>
  )
}

/** The sentence a citation stands in, its value purple and underlined (a chip too, `[ card ]`), in quotation marks. */
function sourceSegs(sentence: string, c: Citation): Line {
  const flat = plainCites(sentence).replace(/\s+/g, ' ').trim()
  // a citation written without words stands in the sentence as its chip (`[ revisions.jsonl line 1 ]`)
  const shown = c.display ?? citeLabel(c)
  const at = shown ? flat.indexOf(shown) : -1
  // in quotation marks of the kind its words do not hold (lib.ts quoted)
  const [open, close] = quoted(flat) === flat ? ['', ''] : flat.includes('"') ? ['“', '”'] : ['"', '"']
  if (at < 0) return [{ s: `${open}${flat}${close}` }]
  // the cited span on the citation's purple, highlighted rather than underlined (the owner, 10-16 21:55)
  return [{ s: `${open}${flat.slice(0, at)}` }, { s: shown, bg: citeHighlight() }, { s: `${flat.slice(at + shown.length)}${close}` }]
}

/** The citation panel's entry box (entry.tsx). In a citation opened from a side thread, its question goes on in that
 *  thread, about the citation, and the panel then shows the thread; anywhere else it starts a side thread about the
 *  citation, opened over the citation. Its key, for `a`, and the rows it takes. */
async function citeEntry(cx: Ctx, e: PaneEvent, c: Citation, target: Target, sentence: string, cols: number): Promise<{ el: RenderElement | null; key: string; rows: number }> {
  if (e.surface === 'mobile') return { el: null, key: '', rows: 0 }
  const nav = (await cx.nav()) ?? NAV_EMPTY
  const tid = threadBehind(nav.trail)
  if (!tid) {
    const key = `ask-cite-${cid(c.raw)}`
    const el = askEntry(cx, e, { key, placeholder: 'Ask about this citation', cols, target, ...(sentence ? { over: { anchorText: plainCites(sentence) } } : {}) })
    return { el, key, rows: entryHeight(key, cols) }
  }
  const key = fieldKey(`follow-${cid(tid)}`)
  const el = entryEl(cx, e, {
    key,
    placeholder: 'Ask a follow-up question',
    cols,
    onSubmit: q => {
      void (async () => {
        const r = await threadMessage(cx, tid, `${q} (about ${c.raw})`)
        if (r.error) return cx.toast(r.error)
        const now = (await cx.nav()) ?? NAV_EMPTY
        let i = now.trail.length - 1
        while (i >= 0 && now.trail[i]!.thread !== tid) i--
        if (i >= 0) await navGo(cx, { trail: now.trail.slice(0, i + 1), back: withBack(now.back, now.trail) })
      })()
    },
  })
  return { el, key, rows: entryHeight(key, cols) }
}

/** The row of a card's data that holds a cited value (the resolver's column and row, as a mark's ref names them): the
 *  column names and that row's cells as the card writes them, and which cell is cited; null where the card keeps its
 *  data in no rows (a diagram, a timeline) or no row holds it. A table's row by its first cell, a bar by its label, a
 *  line's point by its series and x. */
export function citedRow(card: CardData, v: Pick<TermVerdict, 'column' | 'row' | 'value'>): { head: string[]; cells: string[]; at: number; num: boolean[] } | null {
  if (!v.column || v.row === undefined || v.row === '') return null
  const col = v.column
  const row = v.row
  const words = (x: Cell, h: string): string => (typeof x === 'number' ? (formatted(x, card.formats?.[h]) ?? fmt(x)) : fmt(x))
  if (card.kind === 'table') {
    const head = card.columns ?? []
    const r = ((card.rows ?? []) as Cell[][]).find(x => sameKey(fmt(x[0]), row))
    const at = head.findIndex(h => sameKey(h, col))
    if (!r || at <= 0) return null
    return { head, cells: head.map((h, i) => words(r[i] ?? null, h)), at, num: head.map((_, i) => typeof r[i] === 'number') }
  }
  if (card.kind === 'bar' || card.kind === 'label') {
    const y = card.y || 'value'
    const hits = ((card.rows ?? []) as BarRow[]).filter(b => sameKey(b.label, row))
    const b = hits.find(x => v.value !== undefined && sameKey(fmt(x.value), v.value)) ?? hits[0]
    if (!b) return null
    const grouped = Boolean(b.group && b.group !== b.label)
    const head = [card.x || 'label', ...(grouped ? ['group'] : []), y]
    const cells = [b.label, ...(grouped ? [b.group] : []), fmt(b.value)]
    return { head, cells, at: cells.length - 1, num: cells.map((_, i) => i === cells.length - 1) }
  }
  if (card.kind === 'line') {
    const series = (card.series ?? []).find(x => sameKey(x.name, col))
    const pt = series?.points.find(q => sameKey(String(q[0]), row))
    if (!series || !pt) return null
    return { head: [card.x || 'x', series.name], cells: [String(pt[0]), fmt(pt[1])], at: 1, num: [typeof pt[0] === 'number', true] }
  }
  return null
}

/** A card's cited data row as a small table (a card's table, laid out short): the column names bold with a rule in the
 *  rule gray under each, then the row, numbers right-aligned, the cited cell on the citation's purple. Where the columns
 *  do not fit in `room`, the row's name and the cited column stay and the others follow while they fit. */
export function dataLines(r: { head: string[]; cells: string[]; at: number; num: boolean[] }, room: number): Line[] {
  const GAP = 2
  const w = r.head.map((h, i) => Math.max(1, width(h), width(r.cells[i] ?? '')))
  const keep: number[] = []
  let used = 0
  for (const i of [0, r.at, ...r.head.map((_, k) => k)]) {
    if (keep.includes(i)) continue
    const need = (keep.length ? GAP : 0) + w[i]!
    if (keep.length >= 2 && used + need > room) continue
    keep.push(i)
    used += need
  }
  keep.sort((a, b) => a - b)
  // two columns wider than the room: each cut to its share
  const fit = (i: number) => (used > room ? Math.max(4, Math.floor((w[i]! * (room - GAP * (keep.length - 1))) / (used - GAP * (keep.length - 1)))) : w[i]!)
  const pad = (s: string, i: number) => {
    const t = cut(s, fit(i))
    const fill = ' '.repeat(Math.max(0, fit(i) - width(t)))
    return r.num[i] ? fill + t : t + fill
  }
  const line = (seg: (i: number) => Seg): Line => keep.flatMap((i, k) => [...(k ? [{ s: ' '.repeat(GAP) }] : []), seg(i)])
  return [
    line(i => ({ s: pad(r.head[i] ?? '', i), b: true })),
    line(i => ({ s: '─'.repeat(fit(i)), fg: COLORS.rule })),
    line(i => (i === r.at ? { s: pad(r.cells[i] ?? '', i), bg: citeHighlight() } : { s: pad(r.cells[i] ?? '', i) })),
  ]
}

/** Code as the citation panel shows it (a card's code, a command, a side thread's script): its lines numbered in a dim
 *  gutter, the cited value's literal on the citation's purple where the code types it; the rows around its first such
 *  line, else the code's first rows; `more` the lines left out. */
export function codeLines(code: string, value: string, room: number, max: number): { lines: Line[]; typed: boolean; more: number } {
  const all = code.replace(/\t/g, '    ').split('\n')
  while (all.length && !all.at(-1)!.trim()) all.pop()
  const hits = all.map(l => (value ? literalAt(l, value) : null))
  const first = hits.findIndex(Boolean)
  const from = first < 0 || all.length <= max ? 0 : Math.max(0, Math.min(first - 2, all.length - max))
  const shown = all.slice(from, from + max)
  const gutter = String(from + shown.length).length
  const textRoom = Math.max(8, room - gutter - 2)
  const lines = shown.map((raw, k): Line => {
    const n = dim(`${String(from + k + 1).padStart(gutter)}  `)
    const hit = hits[from + k]
    if (!hit) return [n, { s: width(raw) > textRoom ? windowAt(raw, 0, textRoom).text : raw || ' ' }]
    const w = width(raw) > textRoom ? windowAt(raw, hit[0], textRoom) : { text: raw, shift: 0 }
    const [a, b] = [hit[0] - w.shift, Math.min(w.text.length, hit[1] - w.shift)]
    return [n, ...[{ s: w.text.slice(0, a) }, { s: w.text.slice(a, b), bg: citeHighlight() }, { s: w.text.slice(b) }].filter(x => x.s !== '')]
  })
  return { lines, typed: first >= 0, more: all.length - shown.length }
}

/** The side thread asked for a citation's verification script from its panel (cite.ts SCRIPT_ASK), newest first. */
async function scriptThreadOf(cx: Ctx, ref: string): Promise<TermThreadRow | undefined> {
  return [...(await cx.threads())].reverse().find(t => t.anchor === ref && (t.question ?? '').startsWith(SCRIPT_ASK))
}

/** How a citation was verified, in words, for what its panel's state word opens (v9 review; MATT-NOTES "Mockup
 *  feedback"): what thimble read to check it, what computed or printed the value it found there, and what the card's
 *  links check got; while the check runs, that it runs. Words that show no value only name their place: the check reads
 *  that the place is there, and says so, never that a value was found. */
function howWords(c: Citation, v: TermVerdict | undefined, check: { state?: string; source?: string }): string {
  if (!v || v.status === 'pending') return `${SPIN} thimble is reading its place`
  if (v.status === 'missing') return 'thimble looked for its place and found none'
  const shows = c.display !== null && showsValue(c.display) && !v.placeOnly
  // words that show no value only name their place: the check reads that the place is there; so does a value whose
  // place gives nothing to check it against (placeOnly)
  const noValue = c.display === null ? '' : v.placeOnly ? `; ${v.placeOnly}, so only its place is checked` : '; its words show no value, so only its place is checked'
  const found = v.status === 'differs' ? 'did not find it' : 'found it'
  let words: string
  if (v.kind === 'cell') {
    const out = outputLine(c.ref)
    const where = v.column ? "the card's output" : out ? `line ${out.first} of what the card printed` : 'the card'
    words = shows ? `the card's code computed it, and thimble ${found} in ${where}` : `thimble found ${where}${noValue}`
    if (check.state === 'typed') words = "the card's code types it in rather than computes it"
  } else if (v.command) words = shows ? `the command printed it, and thimble ${found} in its output` : `thimble found the command's output${noValue}`
  else {
    const place = v.lines.filter(l => l.hit && l.n > 0).length > 1 ? 'the cited lines' : typeof v.line === 'number' ? 'the cited line' : 'its place'
    words = shows ? `thimble read ${place} and ${v.status === 'differs' ? 'did not find the value there' : 'found the value there'}` : `thimble read ${place}${noValue}`
  }
  if (check.state === 'running') return `${words}; ${SPIN} its card's links check is running`
  // the links check of words that show no value reads their place again: it adds nothing to what was found
  if (check.state === 'verified') return shows ? `${words}, and its card's links check found the same value` : words
  if (check.state === 'refuted') return `${words}, but its card's links check found ${check.source || 'another value'}`
  return words
}

// what a citation's panel shows above its bar, by the citation (citeKey): `how` it was verified (its state word
// opened it) or its `history`; none at rest, as the panel opens
const citeOpen = new Map<string, 'how' | 'history'>()

/** A citation's key among the panels' open parts: its words and its place. */
function citeKey(display: string | null, ref: string): string {
  return `${display ?? ''}|${ref}`
}

/** The citation panel (SPEC.md, section 7, "The citation panel"; MATT-NOTES "Mockup feedback", panel C): the title is
 *  the cited value, bold, purple and underlined (a link to its place; red once it failed), with no mark: the bar says
 *  its state. Under the rule `from the card` and the card's question for a citation in a card's takeaway, else `source`
 *  (the sentence it stands in, the value in it purple); then its place as a link (`↗ events.jsonl line 197`, purple
 *  and underlined, a press opens it); then where the value stands, on the citation's purple: a file's lines, a
 *  command's lines under the command, or for a value on a card the card's data row and the code that holds it (v9
 *  review: "the code or data holding the literal, not the plot"; a card whose data has no rows drawn with its mark
 *  lit). At the bottom, above the entry box, one bar: the state word (`checked ›` green, `◌ checking …` while it is
 *  checked, `failed × ›` red) and `history N ›`. A press on the state word (or `v`) opens how it was verified above
 *  the bar: what thimble read, what computed or printed the value, what the card's links check got, why it failed, and
 *  for a place no code verified `ask for a script` and the side thread's script; a press on `history` (or `h`) opens
 *  what Claude wrote, what the check made it and why. The entry box's question starts a side thread about the
 *  citation, or goes on in the side thread it was opened from. It reads its verdict and its card as they change, so
 *  the bar says when the check ends. */
async function drawCite(cx: Ctx, e: PaneEvent, p: TermPanel): Promise<RenderElement> {
  const els = cx.els(e) as El
  const { Box, Text, Button } = cx.els(e)
  const cols = Math.max(30, e.props.bodyColumns)
  if (!p.ref) return none(cx, e)
  const c = { raw: p.display === null || p.display === undefined ? `[[${p.ref}]]` : `[[${p.display}|${p.ref}]]`, ref: p.ref, display: p.display ?? null }
  const v = await cx.verdict(cid(c.raw))
  const status = v?.status ?? 'pending'
  const pending = !v || status === 'pending'
  const red = status === 'missing' || status === 'differs'
  const target: Target = { kind: 'citation', ref: c.raw, text: citeLabel(c) }
  const f = fileRef(c.ref)
  const cardId = /^(?:card|cell):([A-Za-z0-9_-]+)/.exec(c.ref)?.[1]
  // a place cited with no words keeps its line where its path is cut (`…/agent-ad502eca.jsonl line 20`)
  const label = c.display === null && fileRef(c.ref) ? cutRef(c.ref, Math.max(8, cols - 6)) : cut(await citeTitle(cx, c), Math.max(8, cols - 6))
  // the takeaway's card's links check, as the chat marks the citation: checking while it runs, failed when it got
  // another value or found the value typed in the card's code
  const ofCard = p.of ? await cx.card(p.of) : undefined
  const check = p.of ? linkCheck(ofCard?.links, c) : {}
  const look = chipLook(status, undefined, check.state)
  const bad = !look.spin && (red || look.state === 'failed')
  const checking = look.spin
  // the title: the value highlighted on the citation's purple (red once it failed), not underlined; no ◌ or × after
  // it, the bar says its state
  const titleSegs: Line = [bad ? { s: label, b: true, fg: COLORS.problem } : { s: label, b: true, bg: citeHighlight() }]
  // its file opens at the cited line, or at the record a pointer cites (`…json#/messages/<id>`), lit there (bug hunt B29:
  // a transcript's message opened its file at the first turn, the message neither shown nor marked)
  const at = f?.line ?? v?.fileLine
  const record = v?.kind === 'pointer' ? c.ref : undefined
  const opens = f ? () => openFile(cx, f.path, Math.max(1, (at ?? 1) - 5), at, record) : cardId ? () => openCard(cx, cardId) : null
  const body: RenderElement[] = []
  // the title row's current step: the value as its link, a click on it opening its place
  setHead({ line: titleSegs, key: 'cite-title', ...(opens ? { press: () => void opens() } : {}) })
  // why it failed: the resolver's reason, or the links check's (another value, a value the card's code types in)
  const why = red && v?.why ? await plainWhy(cx, v.why) : (check.state === 'refuted' || check.state === 'typed') && check.why ? await plainWhy(cx, check.why) : ''
  const tall = (words: string, w: number) => (words ? wrapRows(words, Math.max(1, w), 999).length : 0)
  body.push(ruleEl(els, cols, 'cite-rule'))
  // the rows the panel's parts take, but for the file's window (which takes the rest): the title row and the rule
  let used = 2
  // where the citation stands: the card whose takeaway holds it, or the sentence
  const question = ((ofCard?.data as CardData | null | undefined)?.question ?? '').trim()
  const head: [string, RenderElement | string, string?][] = []
  if (p.of && question) head.push(['from the card', question])
  else if (p.sentence) head.push(['source', lineEl(els, sourceSegs(p.sentence, c), 'cite-source', true)])
  if (head.length) {
    const [k, val] = head[0]!
    body.push(fieldEls(els, head, 'cite')!, <Text key="cite-from-gap"> </Text>)
    used += tall(typeof val === 'string' ? val : sourceSegs(p.sentence ?? '', c).map(x => x.s).join(''), cols - width(k) - 2) + 1
  }
  // its place as a link, in the citation's purple as every evidence link; not for a citation titled by its place
  const place = outputLine(c.ref) ? await placeName(cx, c.ref) : cardId ? await placeName(cx, `card:${cardId}`) : placeWords(c.ref)
  if (place !== (await citeTitle(cx, c))) {
    const placeLine: Line = [{ s: '↗', fg: COLORS.cite }, { s: ' ' }, { s: cut(place, Math.max(4, cols - 2)), fg: COLORS.cite, u: true }]
    const pw = lineWidth(placeLine)
    body.push(linesEl(cx, e, 'cite-place', [placeLine], opens ? [{ y: 0, x0: 0, x1: pw, row: false, run: () => void opens() }] : [], pw), <Text key="cite-place-gap"> </Text>)
    used += 2
  }
  // the code that computed or printed the value, its literal on the citation's purple where the code types it: a card's
  // code, the command, a side thread's script
  const value = c.display !== null && showsValue(c.display) ? (quotedWords(c.display) || c.display) : ''
  const tc = v?.card ? await cx.card(v.card) : undefined
  const src: [string, RenderElement | string, string?][] = []
  // the room right of the rows' labels (`command`, `data`, `code`)
  const srcRoom = cols - (v?.command ? width('command') : width('data')) - 2
  let codeRows = 0
  const codeOf = (code: string, max: number, room: number, key: string, more?: () => void): RenderElement => {
    const got = codeLines(code, value, room, max)
    codeRows += got.lines.length + (got.more ? 1 : 0)
    const moreEl = got.more ? (more ? <Button key={`${key}-more`} label={`… ${num(got.more)} more`} plain dimColor onPress={more} /> : <Text dimColor>{`… ${num(got.more)} more`}</Text>) : null
    return <Box flexDirection="column">{[...got.lines.map((l, i) => lineEl(els, l, `${key}-${i}`)), ...(moreEl ? [moreEl] : [])]}</Box>
  }
  if (v?.command) src.push(['command', lineEl(els, [{ s: `$ ${v.command}`, fg: COLORS.code }], 'cite-command', true)])
  // a value on a card: the card's data row that holds it, then its code (v9 review: never the plot)
  const card = tc?.data as CardData | null | undefined
  const dataRow = v?.card && !v.lines.length && card ? citedRow(card, v) : null
  if (dataRow) src.push(['data', <Box flexDirection="column">{dataLines(dataRow, srcRoom).map((l, i) => lineEl(els, l, `cite-data-${i}`))}</Box>])
  if (tc?.code?.trim() && v?.card && (value || outputLine(c.ref))) src.push(['code', codeOf(tc.code, 8, srcRoom, 'cite-code', () => void openCard(cx, v.card!, 'code'))])
  if (src.length) {
    body.push(fieldEls(els, src, 'cite-src')!)
    used += src.reduce((n, [k, val]) => n + (k === 'code' ? 0 : k === 'data' ? 3 : tall(typeof val === 'string' ? val : `$ ${v?.command ?? ''}`, srcRoom)), 0) + codeRows
  }
  // how it was verified, opened by the state word: what thimble read, and for a place no code verified a side
  // thread's script, or `ask for a script`
  const kept = !!v && (v.kind === 'cell' || Boolean(v.command) || /^(?:concept|report)$/.test(v.kind))
  const scriptT = !pending && !kept ? await scriptThreadOf(cx, c.ref) : undefined
  const askScript = () =>
    void (async () => {
      const got = await startThread(cx, c.ref, p.sentence ? plainCites(p.sentence) : citeLabel(c), scriptQuestion(c), { title: targetLabel(target, 60) })
      if ('error' in got) return cx.toast(got.error)
      await openThread(cx, got.id, scriptQuestion(c))
    })()
  const canAsk = !pending && !kept && !scriptT && c.display !== null && v?.status !== 'missing' && e.surface !== 'mobile'
  // its revisions: one where a check rewrote it in place (what Claude wrote, what the check made it, and why)
  const revisions = check.fixed ? 1 : 0
  const key = citeKey(c.display, c.ref)
  let open = citeOpen.get(key)
  if ((open === 'how' && checking) || (open === 'history' && !revisions)) open = undefined
  const toggle = (part: 'how' | 'history') => () => {
    if (citeOpen.get(key) === part) citeOpen.delete(key)
    else citeOpen.set(key, part)
    void cx.bumpPanel()
  }
  const detail: RenderElement[] = []
  let detailRows = 0
  if (open === 'how') {
    const how = howWords(c, v, check)
    const words = canAsk ? `${how}; no script recomputed it` : how
    // `ask for a script` on its own row under the words, a control at A0
    detail.push(
      <Box key="cite-how" flexDirection="column">
        <Text wrap="wrap" dimColor>{words}</Text>
        {canAsk ? (
          <Box flexDirection="row">
            <Button key="cite-script" label="ask for a script" plain onPress={askScript} />
          </Box>
        ) : null}
      </Box>,
    )
    detailRows += tall(words, cols) + (canAsk ? 1 : 0)
    if (bad && why) {
      detail.push(
        <Box key="cite-why" flexDirection="row">
          <Text wrap="wrap" dimColor>{why}</Text>
        </Box>,
      )
      detailRows += tall(why, cols)
    }
    // a side thread's script for a place no code verified: its first code block, once it answered
    if (scriptT) {
      const tt = await cx.thread(scriptT.id)
      const turn = tt?.events.length ? threadOf(tt.meta, tt.events).turns[0] : undefined
      const script = turn?.a ? firstCode(turn.a) : null
      const openIt = () => void openThread(cx, scriptT.id)
      const state = scriptT.running || turn?.state === 'running' ? `${SPIN} a side thread is writing it` : script ? "a side thread's script" : 'a side thread was asked for one'
      const rows: [string, RenderElement | string, string?][] = [['script', <Box flexDirection="row" columnGap={2}><Text dimColor>{state}</Text><Button key="cite-script-open" label="open ↳" plain onPress={openIt} /></Box>]]
      const before = codeRows
      if (script) rows.push(['', codeOf(script.code, 8, cols - 8, 'cite-script-code', openIt)])
      detail.push(fieldEls(els, rows, 'cite-script')!)
      detailRows += 1 + codeRows - before
    }
  } else if (open === 'history' && check.fixed) {
    const now = c.display !== null && check.fixed.was ? c.display : await placeName(cx, c.ref)
    const wrote = check.fixed.was || (await placeName(cx, check.fixed.from))
    const because = check.fixed.why ? await plainWhy(cx, check.fixed.why) : ''
    const lines: Line[] = [
      [dim('Claude wrote '), { s: wrote, b: true }],
      [dim('the check made it '), { s: now, b: true }, ...(because ? [dim(` · ${because}`)] : [])],
    ]
    detail.push(<Box key="cite-history-rows" flexDirection="column">{lines.map((l, i) => lineEl(els, l, `cite-history-${i}`, true))}</Box>)
    detailRows += lines.reduce((n, l) => n + tall(l.map(x => x.s).join(''), cols), 0)
  }
  // the bar: the state word, then the history, three cells apart; a part that opens ends `›`, `⌄` while it is open
  const arrow = (on: boolean) => (on ? ' ⌄' : ' ›')
  const stateEl = checking ? (
    <Text key="cite-state">
      <Text color={COLORS.cite}>{SPIN}</Text>
      <Text dimColor> checking …</Text>
    </Text>
  ) : (
    <Button key="cite-state" plain onPress={toggle('how')}>
      <Text>
        {bad ? <Text color={COLORS.problem} underline>failed</Text> : <Text color={COLORS.checked} underline>checked</Text>}
        {bad ? <Text color={COLORS.problem}> ×</Text> : null}
        <Text dimColor>{arrow(open === 'how')}</Text>
      </Text>
    </Button>
  )
  const historyEl = revisions ? (
    <Button key="cite-history" plain onPress={toggle('history')}>
      <Text>
        <Text color={ACCENT} underline>history</Text>
        <Text dimColor>{` ${revisions}${arrow(open === 'history')}`}</Text>
      </Text>
    </Button>
  ) : (
    <Text key="cite-history" dimColor>history 0</Text>
  )
  const bar = (
    <Box key="cite-bar-rows" flexDirection="column" marginTop={1}>
      {detail.length ? <Box key="cite-detail" flexDirection="column">{detail}</Box> : null}
      {detail.length ? <Text key="cite-detail-gap"> </Text> : null}
      <Text key="cite-bar-rule" color={COLORS.rule}>{'┄'.repeat(cols)}</Text>
      <Box key="cite-bar" flexDirection="row" columnGap={3}>
        {stateEl}
        {historyEl}
      </Box>
    </Box>
  )
  used += 1 + (detail.length ? detailRows + 1 : 0) + 2
  const quote = p.quote || quotedWords(c.display)
  // a card whose data keeps no rows (a diagram, a timeline): the card as it draws, the cited mark lit
  if (v?.card && !v.lines.length && card && !dataRow) {
    const w = Math.min(cols, 96)
    const lit = citedLines(card, v, Math.max(10, w - 4), Math.max(8, (e.props.scroll?.bodyRows || 20) - 14))
    body.push(framedCard(cx, e, lit.card, w, lit.lines, 'cite-card'))
  }
  const entry = await citeEntry(cx, e, c, target, p.sentence ?? '', cols)
  let hints = [...(entry.el ? ['a to ask'] : []), ...(f ? ['f for its file'] : []), ...(cardId ? ['c for the card'] : []), ...(checking ? [] : ['v for how it was verified']), ...(revisions ? ['h for its history'] : []), ...(canAsk ? ['s for a script'] : [])]
  if (!(v?.card && !v.lines.length) && v?.lines.length) {
    // the passage an example quotes, when the cited lines do not hold it
    const quotedRow = quote && status !== 'differs' && !v.lines.some(l => l.hit && quoteSpan(demojibake(l.text).replace(/\t/g, '  '), quote))
    // a file's lines: a window over the whole file, as tall as the rows the panel's other parts leave it (those above
    // it, a `quoted` row, the bar and what it opened, the entry box and its blank row, and the hint rows)
    used += (quotedRow ? tall(clip(demojibake(quote), 600), cols - 8) : 0) + entry.rows + hintHeight(['↑↓ to scroll', ...hints], cols)
    const win = v.path && typeof v.line === 'number' ? await citeWindow(cx, e, c.ref, v, cols, quote, Math.max(5, (bodyRows || 30) - used)) : null
    if (win?.scrolls) hints = ['↑↓ to scroll', ...hints]
    body.push(win?.el ?? <Box key="cite-lines" flexDirection="column">{lineRows(cx, e, v, cols, quote)}</Box>)
    if (quotedRow) body.push(fieldEls(els, [['quoted', <Text wrap="wrap" backgroundColor={citeHighlight()}>{clip(demojibake(quote), 600)}</Text>]], 'cite-quoted')!)
  } else if (!v) body.push(<Text key="cite-wait" dimColor>{`${SPIN} reading its place`}</Text>)
  body.push(bar)
  const keys: Key[] = [
    ...(entry.el ? [askKey(cx, entry.key)] : []),
    ...(f ? [{ key: 'files', hotkey: 'f', onPress: () => void opens?.() }] : []),
    ...(cardId ? [{ key: 'card', hotkey: 'c', onPress: () => void openCard(cx, cardId) }] : []),
    ...(checking ? [] : [{ key: 'how', hotkey: 'v', onPress: toggle('how') }]),
    ...(revisions ? [{ key: 'history', hotkey: 'h', onPress: toggle('history') }] : []),
    ...(canAsk ? [{ key: 'script', hotkey: 's', onPress: askScript }] : []),
  ]
  body.push(...bottomRows(cx, e, cols, [], [entry.el], hints, !entry.el))
  const hk = hiddenKeys(cx, e, keys)
  return <Box flexDirection="column">{[...(hk ? [hk] : []), ...body]}</Box>
}

// ------------------------------------------------------------------------------------------------ a thread's subject

// the rows of a side thread's subject shown before its `… N more`
const SUBJECT_ROWS = 6
// the subjects shown whole, by their key (a thread's id, or a new thread's anchor): `… N more` shows one whole
const subjectWhole = new Set<string>()

/** What a side thread is about: its anchor (a card, a value on one, a file's line, a document's passage, none for words
 *  on screen), the words it was asked about, and the card a new thread asks about. */
type Subject = { anchor: string; text: string; card?: string; lit?: string }

/** Whether words that name a thread's subject (`about "…"`) hold its passage whole, which then is not drawn again. */
function saidIn(about: string, words: string): boolean {
  const flat = plainCites(words).replace(/[#*_`>]/g, '').replace(/\s+/g, ' ').trim()
  return Boolean(flat) && about.includes(flat)
}

/** A passage's words as rows of `cols` cells: each line of it wrapped, a Markdown heading bold without its marks, the
 *  marks of bold, italic and code left out, citations as their words, blank lines left out. */
function passageRows(text: string, cols: number): Line[] {
  const out: Line[] = []
  for (const raw of plainCites(text).replace(/\[([^\[\]\n]*)\]\([^()\s]*\)/g, '$1').split('\n')) {
    const head = /^#{1,6}\s+/.test(raw)
    const words = plainMarks(raw.replace(/^#{1,6}\s+/, '')).replace(/\s+/g, ' ').trim()
    if (!words) continue
    for (const r of wrapRows(words, Math.max(10, cols), 999)) out.push([{ s: r, ...(head ? { b: true } : {}) }])
  }
  return out
}

/** The thing a side thread is about, above its chat and its field for as long as the thread shows (Matt, 2026-10-07:
 *  "keep that thing above the chat so I know what I'm referencing"): a card in its frame, a value cited on it lit; a
 *  file's cited line with up to two lines on each side, as the citation panel draws lines; a passage or a quote as its
 *  words. At most SUBJECT_ROWS rows of it, then `… N more`, which shows it whole; never `… 1 more`. */
async function subjectEls(cx: Ctx, e: PaneEvent, s: Subject, cols: number, key: string): Promise<RenderElement[]> {
  const els = cx.els(e) as El
  const { Box, Text, Button } = cx.els(e)
  const whole = subjectWhole.has(key)
  const showAll = () => {
    subjectWhole.add(key)
    void cx.bumpPanel()
  }
  const moreEl = (n: number) => (
    <Box key={`subject-more-row-${key}`} flexDirection="row">
      <Button key={`subject-more-${key}`} label={`… ${num(n)} more`} plain dimColor onPress={showAll} />
    </Box>
  )
  const anchor = (s.anchor ?? '').split(',')[0] ?? ''
  const cardId = s.card || /^(?:card|cell):([A-Za-z0-9_-]+)/.exec(anchor)?.[1] || ''
  if (cardId) {
    const data = (await cx.card(cardId))?.data as CardData | null | undefined
    const at = s.lit || (anchor.includes('#') ? anchor : '')
    const focus = data && at ? focusFromRef(data, at.replace(/^cell:/, 'card:')) : undefined
    const card = await cardBlock(cx, e, cardId, cols, `subject-${cid(key)}`, { ...(focus ? { focus } : {}), ...(whole ? {} : { clip: { rows: SUBJECT_ROWS, more: showAll } }) })
    return [
      <Box key={`subject-${key}`} flexDirection="column">
        {card}
      </Box>,
    ]
  }
  if (subjectFile(anchor)) {
    const c = { raw: `[[${anchor}]]`, ref: anchor, display: null }
    const v = await cx.verdict(cid(c.raw))
    if (!v) {
      queueCitations([c])
      return [<Text key={`subject-${key}`} dimColor>◌ reading its lines</Text>]
    }
    if (v.lines.length) {
      // the cited lines and two on each side; the others the citation read too once shown whole
      const first = v.lines.findIndex(l => l.hit)
      const last = v.lines.length - 1 - [...v.lines].reverse().findIndex(l => l.hit)
      const near = first < 0 ? v.lines : v.lines.filter((_l, i) => i >= first - 2 && i <= last + 2)
      const all = lineRows(cx, e, v, cols, '')
      const some = lineRows(cx, e, { ...v, lines: near }, cols, '')
      // never `… 1 more`: one row past them is drawn
      const rows = whole || all.length - Math.min(some.length, SUBJECT_ROWS) < 2 ? all : some
      const cutAt = rows === all || rows.length <= SUBJECT_ROWS + 1 ? rows.length : SUBJECT_ROWS
      const hidden = all.length - cutAt
      return [
        <Box key={`subject-${key}`} flexDirection="column">
          {rows.slice(0, cutAt)}
        </Box>,
        ...(hidden >= 2 ? [moreEl(hidden)] : []),
      ]
    }
  }
  const lines = passageRows(s.text, cols)
  if (!lines.length) return []
  const cutAt = whole || lines.length <= SUBJECT_ROWS + 1 ? lines.length : SUBJECT_ROWS
  return [
    <Box key={`subject-${key}`} flexDirection="column">
      {lines.slice(0, cutAt).map((l, i) => lineEl(els, l, `subject-${key}-${i}`))}
    </Box>,
    ...(cutAt < lines.length ? [moreEl(lines.length - cutAt)] : []),
  ]
}

// ------------------------------------------------------------------------------------------------ a new thread

let asking = ''

/** A new side thread (SPEC.md, section 7, "The threads panel", a thread with no question yet): `about <what>`
 *  as its dim subtitle, what it is about (subjectEls: the card, the cited lines, the passage), then the entry box, which
 *  has the keys. */
async function drawAsk(cx: Ctx, e: PaneEvent, p: TermPanel): Promise<RenderElement> {
  if (e.surface === 'mobile') return none(cx, e, 'A side thread needs a surface with text fields.')
  const els = cx.els(e) as El
  const { Box, Text } = cx.els(e)
  const cols = Math.max(30, e.props.bodyColumns)
  // a citation's words in quotation marks, as every subject (aboutName); a citation with no words by its place, as it
  // shows; a card and a passage come quoted already
  const cited = p.target?.kind === 'citation' ? citationOf(p.target) : null
  const about = cited?.display && p.about ? subjectWords(p.about) : (p.about ?? 'this')
  const body: RenderElement[] = [...headerEls(els, { title: 'New thread', cols, sub: subLine([`about ${about}`]) })]
  // what it is about, above the field: the card, the cited lines, the passage (its words, unless the subtitle holds them)
  const words = p.target?.kind === 'card' ? '' : p.anchorText ?? ''
  const said = saidIn(p.about ?? '', words)
  const lit = p.target?.kind === 'mark' && p.target.ref ? { lit: p.target.ref } : {}
  body.push(...(await subjectEls(cx, e, { anchor: p.anchor ?? '', text: said ? '' : words, ...(p.target?.kind === 'card' && p.target.cardId ? { card: p.target.cardId } : {}), ...lit }, cols, `ask:${p.anchor ?? ''}:${cid(words)}`)))
  if (asking) body.push(<Text key="ask-state" {...(asking.startsWith('×') ? { color: COLORS.problem } : { dimColor: true })}>{asking}</Text>)
  // the header's rule stands alone when nothing comes between it and the box: it is the box's top rule then
  const between = body.length > headerEls(els, { title: 'New thread', cols, sub: subLine(['x']) }).length
  // the entry box alone, its placeholder saying what it takes: Enter's word (`⏎ ask`) is the only `ask`
  const field = entryEl(cx, e, {
    key: fieldKey('ask-new'),
    placeholder: 'type your question',
    cols,
    autoFocus: true,
    top: between,
    onSubmit: q => {
      void (async () => {
        asking = '◌ asking'
        await cx.bumpPanel()
        const target: Target = p.target ?? { kind: 'sentence', text: p.anchorText ?? '' }
        // the thread takes the form's place on the way, so back leads where the form was asked from (live check
        // term-fix9, quirk 12: back from a thread just asked showed an empty form)
        const why = await askNow(cx, { target, anchor: p.anchor ?? null, anchorText: p.anchorText ?? '', about: p.about ?? '', ...(p.parent ? { parent: p.parent } : {}), ...(p.element ? { element: p.element } : {}) }, q, { replace: true })
        asking = why ? `× ${why}` : ''
        if (why) await cx.bumpPanel()
      })()
    },
  })
  body.push(...bottomRows(cx, e, cols, [], [field], ['Enter to ask'], false, 'ask-new'))
  return <Box flexDirection="column">{body}</Box>
}

// ------------------------------------------------------------------------------------------------ threads

/** A thread as the tree and the panel read it: its chat when read, else its row's question. */
async function threadOfRow(cx: Ctx, id: string): Promise<ChatThread | null> {
  const row = (await cx.threads()).find(t => t.id === id)
  const tt: TermThread | undefined = await cx.thread(id)
  if (tt && tt.events.length) return { ...threadOf(tt.meta, tt.events), ...(row?.parent && row.parent !== 'main' ? { parent: row.parent } : {}) }
  if (!row) return null
  // until its chat is read, its turn holds the state its row gives: answered, stopped, failed or running, never words
  // (live check term-fix6, new quirk 9: every row read `answered` for a few seconds, a stopped thread's too)
  const turn = row.running ? { state: 'running' } : row.turn === 'stopped' ? { state: 'error', stopped: true } : row.turn === 'failed' ? { state: 'error' } : row.turn === '' ? { state: 'running' } : { state: 'done' }
  const asked = Date.parse(row.created || row.at)
  return { id, label: row.anchorText || row.title, ref: row.anchor, context: '', agentId: '', engine: '', turns: [{ q: row.question || row.title, a: '', tools: 0, partial: '', ...turn, ...(Number.isFinite(asked) ? { at: asked } : {}) }], file: '', parent: row.parent === 'main' ? '' : row.parent, at: Date.parse(row.at) || 0, loading: true }
}

/** A thread title as thimble makes one from the anchor's words when none is given (agents._title_from): its first four
 *  words, lower case, joined by '-'. */
function slugOf(text: string): string {
  return (text.slice(0, 80).match(/[A-Za-z0-9]+/g) ?? []).slice(0, 4).join('-').toLowerCase()
}

type AboutRow = { anchor: string; anchorText: string; title?: string; element?: string; question?: string }

/** Whether a thread's title is its first question, as thimble names a thread asked with no title of its own
 *  (agents.question_title: one line, cut at a word with `…`), rather than the words of what it was asked about. */
function askedTitle(title: string, question: string | undefined): boolean {
  const q = (question ?? '').replace(/\[\[([^|\]]*)\|[^\]]*\]\]/g, '$1').replace(/\s+/g, ' ').trim()
  return Boolean(q) && (title === q || (title.endsWith('…') && q.startsWith(title.slice(0, -1))))
}

/** A citation's words as a thread's subject: in quotation marks, as someone's words are; a value alone (`4579`) as it
 *  is written. */
function subjectWords(words: string): string {
  return /^[\d.,%\s−-]+$/.test(words) ? words : quoted(words)
}

/** What names the thing a thread was asked about, when it is a card or a citation: a card by its question, a citation by
 *  its words (the thread's title, which openAsk gives it) or else its place; '' for words on screen or a passage. The ask
 *  view, the thread and home name the subject the same way. */
export async function anchorName(cx: Ctx, row: AboutRow | undefined): Promise<string> {
  const a = (row?.anchor ?? '').split(',')[0]!
  if (!row || !a || /^report:/.test(a)) return ''
  if (/^(?:card|cell):[A-Za-z0-9_-]+$/.test(a)) {
    // the card by its question; one not read in this session by the words it showed when the thread was asked
    if (((await cx.card(a.replace(/^(?:card|cell):/, '')))?.data as CardData | null | undefined)?.question || !row.anchorText) return placeName(cx, a)
    return clip(plainCites(row.anchorText).replace(/\s+/g, ' ').trim(), 60)
  }
  const slug = slugOf(row.anchorText)
  const t = (row.title ?? '').trim()
  // a citation's words in quotation marks; a chip by its place in words (`agent-chat.jsonl line 2`), as its thread was
  // titled (gestures.tsx targetLabel)
  const chip = { raw: `[[${a}]]`, ref: a, display: null }
  if (t && t !== slug && !t.startsWith(`${slug}-`) && !askedTitle(t, row.question)) return t === chipName(chip) || t === chipLabel(chip) ? t : subjectWords(t)
  return /^(?:card|cell):/.test(a) ? placeName(cx, a) : placeWords(a)
}

/** What a thread was asked about, in words: a card or a citation by its name (anchorName), else its passage's words. */
export async function aboutName(cx: Ctx, row: AboutRow | undefined): Promise<string> {
  if (!row) return ''
  // a thread asked about a whole answer (its footer's `ask about this answer`)
  if (row.element === ANSWER_ELEMENT) return 'this answer'
  const named = await anchorName(cx, row)
  if (named) return named
  if (row.anchorText) return quoted(clip(plainCites(row.anchorText).replace(/\s+/g, ' ').trim(), 60))
  if (/^report:/.test(row.anchor)) return `the report's passage`
  return ''
}

/** A thread's turn that runs and has taken no step yet: no tool call and no words (main has still to hand the question
 *  to the thread's agent, or the agent has not begun). */
function starting(turn: Pick<ChatThreadTurn, 'state' | 'tools' | 'partial'>): boolean {
  return turn.state === 'running' && !turn.tools && !turn.partial.trim()
}

/** The time since `at` (epoch ms) as Claude Code writes a turn's time: `0s`, `12s`, `1m 5s`. */
export function waited(at: number, now: number): string {
  const s = Math.max(0, Math.floor((now - at) / 1000))
  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m ${s % 60}s`
}

/** What a turn that has taken no step yet shows, from the moment it was asked (live feedback, 10-17: "wasn't sure if
 *  it was working or waiting"): `◌ starting · 12s`, the time drawn again each second (term.ts startingTick). */
function startingWords(turn: Pick<ChatThreadTurn, 'at'>, now: number): string {
  rt.starting = true
  return turn.at ? `◌ starting · ${waited(turn.at, now)}` : '◌ starting'
}

/** The first line of a thread's latest answer, or what it is doing. */
function threadLine(t: ChatThread, now: number): Seg {
  const last = t.turns.at(-1)
  if (!last) return dim('nothing asked yet')
  if (starting(last)) return dim(startingWords(last, now))
  if (last.state === 'running') return dim(`◌ ${plural(last.tools, 'tool call')}`)
  if (last.state === 'error') return stoppedTurn(last) ? dim('stopped') : { s: `× ${plainCites(last.a).split('\n')[0] || 'failed'}`, fg: COLORS.problem }
  const done = [...t.turns].reverse().find(x => x.state === 'done' && x.a.trim())
  const first = plainCites(done?.a ?? '').replace(/^#+\s*/gm, '').split('\n').find(l => l.trim()) ?? ''
  // an answer not read yet shows nothing until it is
  return dim(plainMarks(first).trim() || (t.loading ? '' : 'answered'))
}

// the threads whose subject shows whole under their `about` row, by the thread's id: v, or a press on the row
const subjectOpen = new Set<string>()

// a question asked in a thread's field that its chat does not hold yet (`thimble act thread-message` runs), by the
// thread's id, and when it was asked
const sentAsks = new Map<string, { q: string; at: number }>()

/** A thread with the question its field just sent as its last turn, starting, until its chat holds that question. */
function withAsking(t: ChatThread): ChatThread {
  const a = sentAsks.get(t.id)
  const last = t.turns.at(-1)
  if (!a || (last && last.q.trim() === a.q.trim() && last.state === 'running')) return t
  return { ...t, turns: [...t.turns, { q: a.q, a: '', state: 'running', tools: 0, partial: '', at: a.at }] }
}

/** What a thread's subject shows past its `about` row, in the word its key names (`v to show the passage`): `card`,
 *  `lines` (a file's), `answer` (a whole answer of main's), `passage`; '' when the row holds it whole. */
function subjectWord(row: TermThreadRow, about: string): string {
  const anchor = (row.anchor ?? '').split(',')[0] ?? ''
  if (/^(?:card|cell):[A-Za-z0-9_-]+/.test(anchor)) return 'card'
  if (subjectFile(anchor)) return 'lines'
  const words = row.anchorText ?? ''
  if (!passageRows(words, 999).length || saidIn(about, words)) return ''
  return row.element === ANSWER_ELEMENT ? 'answer' : 'passage'
}

/** The analyst's question in a side thread, as Claude Code draws a prompt in its chat: `❯` in the inactive color in the
 *  margin, the words wrapped at the type area, on the prompt's background across it, the blank lines between its
 *  paragraphs kept on that background as Claude Code keeps them. */
function promptEl(els: El, q: string, cols: number, key: string): RenderElement | null {
  const { Box, Text } = els
  const lines = plainCites(q).split('\n')
  const from = lines.findIndex(l => l.trim())
  if (from < 0) return null
  let to = lines.length - 1
  while (!lines[to]!.trim()) to--
  const rows = lines.slice(from, to + 1).flatMap(l => (l.trim() ? wrapRows(l, cols, 999) : ['']))
  return (
    <Box key={marginKey(key)} flexDirection="column">
      {rows.map((r, i) => (
        <Text key={`${key}-${i}`} backgroundColor={COLORS.prompt} wrap="truncate-end">
          <Text color={COLORS.dim} backgroundColor={COLORS.prompt}>{i ? '  ' : '❯ '}</Text>
          <Text backgroundColor={COLORS.prompt}>{`${r}${' '.repeat(Math.max(0, cols - width(r)))}`}</Text>
        </Text>
      ))}
    </Box>
  )
}

/** A side thread's turn while it works, as Claude Code draws a turn at work: `⏺` dim in the margin and what it does
 *  (`◌ starting · 12s` from the moment it was asked until its first step, then `◌ 2 tool calls`, or `◌ answering`
 *  while it writes before any), then its latest words dim on a row under it after `⎿`, cut at the row's end. */
function workingEl(els: El, turn: ChatThreadTurn, cols: number, key: string, now: number): RenderElement {
  const { Box, Text } = els
  const latest = turn.partial.split('\n').map(l => l.trim()).filter(Boolean).at(-1) ?? ''
  const doing = starting(turn) ? startingWords(turn, now) : `◌ ${turn.tools ? plural(turn.tools, 'tool call') : 'answering'}`
  return (
    <Box key={marginKey(key)} flexDirection="column">
      <Text dimColor wrap="truncate-end">
        {cut(`⏺ ${doing}`, cols + MARGIN_W)}
      </Text>
      {latest ? (
        <Text key={`${key}-latest`} dimColor wrap="truncate-end">
          {cut(`  ⎿  ${plainMarks(plainCites(latest))}`, cols + MARGIN_W)}
        </Text>
      ) : null}
    </Box>
  )
}

/** A row under a side thread's question that says how its turn ended without an answer, as Claude Code says an
 *  interrupt or an error under a prompt: `⎿` at A0, its words after two cells, wrapped there; dim, or in `color`. */
function underEl(els: El, words: string, key: string, color?: string): RenderElement {
  const { Box, Text } = els
  return (
    <Box key={key} flexDirection="row">
      <Box width={3} flexShrink={0}>
        <Text dimColor>⎿  </Text>
      </Box>
      <Box flexGrow={1} flexShrink={1}>
        <Text wrap="wrap" {...(color ? { color } : { dimColor: true })}>
          {words}
        </Text>
      </Box>
    </Box>
  )
}

/** The threads panel (SPEC.md, section 7, "The threads panel"): its title; under the rule the tree, a root per place
 *  a thread was asked from (`main`, or `report "…"`, its count of threads dim at R and `N new` in green) with a blank
 *  row between them, each thread
 *  under the thread it was asked from, its question in quotation marks with guides, the first line of its latest
 *  answer dim under it (none while a thread is open: the open thread's chat is below), `N questions` dim and `new` in
 *  green at R; the selected thread (`❯`, accent) under the second rule: what it is about on one dim row, then its chat
 *  as Claude Code draws one (each question after `❯` on the prompt's background, a blank row, its answer after `⏺` with
 *  the cards it cites where it cites them), `stop` (s) while it answers, then the `ask` field. A thread open alone,
 *  with no other thread, has no list: its question is the title row's last step and what it is about the row under
 *  it. ↑↓ or j k choose, Enter or a give the field the keys, v shows what the thread is about whole, 1-9 open the
 *  first nine. */
async function drawThreads(cx: Ctx, e: PaneEvent, selected = ''): Promise<RenderElement> {
  if (e.surface === 'mobile') return none(cx, e, 'Threads need a surface with text fields.')
  const els = cx.els(e) as El
  const { Box, Text, Button } = cx.els(e)
  const cols = Math.max(30, e.props.bodyColumns)
  const rows = (await cx.threads()) ?? []
  // the threads listed, and the one selected though the list does not hold it yet (one just asked)
  const ids = [...rows.map(r => r.id), ...(selected && !rows.some(r => r.id === selected) ? [selected] : [])]
  const threads = (await Promise.all(ids.map(id => threadOfRow(cx, id)))).filter((t): t is ChatThread => t !== null).map(withAsking)
  const unreadOf = (id: string) => rows.find(r => r.id === id)?.unread ?? 0
  const t = selected ? threads.find(x => x.id === selected) : undefined
  const now = await cx.now()
  // one thread, open: no list above it, which would repeat its question and its answer
  const alone = Boolean(t) && threads.length === 1
  // what it is about, on one dim row cut at the type area; the thing itself (a card, a file's lines, a passage) whole
  // under it on demand (v, or a press on the row)
  const row = t ? rows.find(r => r.id === t.id) : undefined
  const about = t ? await aboutName(cx, row) : ''
  const word = t && row ? subjectWord(row, about) : ''
  const subjectShown = Boolean(t && word && subjectOpen.has(t.id))
  const flip = t && word
    ? () => {
        if (subjectOpen.delete(t.id)) subjectWhole.delete(t.id)
        else {
          subjectOpen.add(t.id)
          subjectWhole.add(t.id)
        }
        void cx.bumpPanel()
      }
    : null
  const aboutWords = about ? cut(`about ${about}`, cols) : ''
  const aboutEl = !aboutWords ? null : flip ? (
    <Box key="thread-about" flexDirection="row">
      <Button key="thread-about-press" label={aboutWords} plain dimColor onPress={flip} />
    </Box>
  ) : (
    <Text key="thread-about" dimColor wrap="truncate-end">
      {aboutWords}
    </Text>
  )
  // no subtitle: each root's row holds how many threads stand under it and how many are new (Matt, 19:05: `2 threads`
  // on a line of its own under `main` read as one more row of the tree)
  const body: RenderElement[] = [...headerEls(els, { title: 'Threads', cols, ...(alone ? { more: aboutEl ? [aboutEl] : [] } : {}) })]
  // a root per place: the threads asked from a document under it, the rest under main
  const byId = new Map(threads.map(x => [x.id, x]))
  const rootOf = (x: ChatThread): ChatThread => {
    const seen = new Set<string>()
    let cur = x
    while (cur.parent && byId.has(cur.parent) && !seen.has(cur.id)) {
      seen.add(cur.id)
      cur = byId.get(cur.parent)!
    }
    return cur
  }
  const placeOf = (x: ChatThread) => {
    const el = rows.find(r => r.id === rootOf(x).id)?.element ?? ''
    return /^report:/.test(el) ? el.split('#')[0]! : 'main'
  }
  const docs = await surfaceValue(cx, 'docs')
  const docTitle = (slug: string) => (docs?.ok ? docsOf(docs.value).find(d => d.slug === slug)?.title : '') || slug
  const places = [...new Set(threads.map(placeOf))].sort((a, b) => (a === 'main' ? -1 : b === 'main' ? 1 : a.localeCompare(b)))
  const lines: Line[] = []
  const hits: LineHit[] = []
  const order: ChatThread[] = []
  const cap = selected ? 12 : 50
  let drawn = 0
  let more = 0
  for (const [pi, place] of places.entries()) {
    const tree = threadTree(threads.filter(x => placeOf(x) === place))
    if (!tree.length) continue
    if (pi > 0) lines.push([])
    const under = threads.filter(x => placeOf(x) === place)
    const news = under.filter(x => unreadOf(x.id)).length
    const counts: Line = [dim(plural(under.length, 'thread')), ...(news ? [{ s: '  ' }, freshSeg(news)] : [])]
    lines.push(pointed(spread([{ s: place === 'main' ? 'main' : `report ${quoted(clip(docTitle(place.slice(7)), 60))}` }], counts, cols), false))
    for (const r of tree) {
      if (drawn >= cap) {
        more++
        continue
      }
      drawn++
      const n = unreadOf(r.t.id)
      const asked = r.t.turns.length
      const guide = r.guide.replace(/(.)../g, (_m, ch: string) => `${ch} `)
      const lead = r.under.replace(/(.)../g, (_m, ch: string) => `${ch} `)
      const right: Line = [...(asked > 1 ? [dim(`${asked} questions`)] : []), ...(n ? [...(asked > 1 ? [{ s: '  ' }] : []), freshSeg()] : [])]
      const y = lines.length
      lines.push(pointed(spread([{ s: guide, fg: COLORS.rule }, { s: threadTitle(r.t) }], right, cols), r.t.id === selected))
      const open = () => openThread(cx, r.t.id)
      hits.push({ y, x0: MARGIN_W, x1: cols + MARGIN_W, row: true, run: open })
      // the first line of its answer, while no thread is open below the list
      if (!t) {
        const second = threadLine(r.t, now)
        lines.push(pointed([{ s: lead.slice(0, guide.length), fg: COLORS.rule }, { ...second, s: cut(second.s, Math.max(10, cols - guide.length)) }], false))
        hits.push({ y: y + 1, x0: MARGIN_W, x1: cols + MARGIN_W, row: true, run: open })
      }
      order.push(r.t)
    }
  }
  if (!threads.length) lines.push(pointed([{ s: '  ' }, dim('none')], false))
  if (more) {
    const words = `… ${num(more)} more`
    hits.push({ y: lines.length, x0: MARGIN_W + 2, x1: MARGIN_W + 2 + words.length, row: false, run: () => openPanel(cx, { view: 'threads', title: 'Threads' }) })
    lines.push(pointed([{ s: '  ' }, dim(words)], false))
  }
  const running = t?.turns.at(-1)?.state === 'running'
  const askField = t ? `ask-${cid(t.id)}` : ''
  // the module's own move of the ring raises no ui.focus: the hint row follows once the ring is there (live check
  // term-fix8, quirk 7: the hint still named b while a typed b went into the field)
  const focusAsk = async () => {
    if (!askField || !(await cx.focus(askField))) return
    rt.panelFocus = askField
    await cx.bumpPanel()
  }
  const step = async (d: number) => {
    if (!order.length) return
    const at = order.findIndex(x => x.id === selected)
    await openThread(cx, order[Math.max(0, Math.min(order.length - 1, at < 0 ? (d > 0 ? 0 : order.length - 1) : at + d))]!.id)
  }
  if (!alone) body.push(linesEl(cx, e, marginKey('threads-tree'), lines, hits, cols + MARGIN_W, k => (k === 'up' || k === 'k' ? step(-1) : k === 'down' || k === 'j' ? step(1) : k === 'return' || k === 'enter' ? focusAsk() : undefined)))
  // each thread a press away by its key too, for a surface that draws no Client: no row of its own
  body.unshift(
    <Box key="thread-presses" width={0} height={0} flexShrink={0} overflow="hidden" flexDirection="row">
      {order.map(x => (
        <Button key={`thread-open-${x.id}`} label={threadTitle(x)} plain onPress={() => void openThread(cx, x.id)} />
      ))}
    </Box>,
  )
  const keys: Key[] = alone ? [] : order.slice(0, 9).map((x, i) => ({ key: `t${i}`, hotkey: String(i + 1), onPress: () => void openThread(cx, x.id) }))
  const stop = t && running && rt.sc ? () => void act(cx, rt.sc!, 'stop', { agent: t.id }).then(r => (!r.ok ? cx.toast(`the thread was not stopped: ${r.error}`) : undefined)) : null
  let field: RenderElement | null = null
  if (t) {
    // a blank row between the parts of the chat, none right under a rule (rule 10)
    let underRule = true
    const gap = (key: string) => {
      if (!underRule) body.push(<Text key={key}> </Text>)
      underRule = false
    }
    if (!alone) {
      body.push(ruleEl(els, cols, 'rule-thread'))
      if (aboutEl) {
        body.push(aboutEl)
        underRule = false
      }
    }
    if (subjectShown && row) {
      const words = row.anchorText ?? ''
      const subject = await subjectEls(cx, e, { anchor: row.anchor ?? '', text: saidIn(about, words) ? '' : words }, cols, t.id)
      if (subject.length) {
        body.push(...subject)
        underRule = false
      }
    }
    let k = 0
    for (const turn of t.turns) {
      k++
      // the question, as Claude Code draws a prompt
      const q = promptEl(els, turn.q, cols, `thread-q-${k}`)
      if (q) {
        gap(`thread-gap-q-${k}`)
        body.push(q)
      }
      // its answer as Claude Code draws a turn: while it works, a blank row, then `⏺` and what it does (`◌ 2 tool
      // calls`), its latest words under it after `⎿`; a stop or a failure on a `⎿` row right under the question, as
      // Claude Code says an interrupt or an error; or, after a blank row, the answer after `⏺` with the cards it cites
      // where it cites them and the turn's other cards after it
      const status: { el: RenderElement; gap: boolean } | null =
        turn.state === 'running'
          ? { el: workingEl(els, turn, cols, `thread-run-${k}`, now), gap: true }
          : stoppedTurn(turn)
            ? { el: underEl(els, turn.a.trim().replace(/([^.!?])$/, '$1.'), `thread-err-${k}`), gap: false }
            : turn.state === 'error'
              ? { el: underEl(els, `× ${turn.a.trim()}`, `thread-err-${k}`, COLORS.problem), gap: false }
              : null
      const md = cardsInline(turn.state === 'done' ? turn.a.trim() : '', turn.cards ?? [])
      if (status) {
        if (status.gap) gap(`thread-gap-a-${k}`)
        else underRule = false
        body.push(status.el)
      }
      if (md) {
        gap(`thread-gap-c-${k}`)
        body.push(
          <Box key={marginKey(`thread-answer-${k}`)} flexDirection="column">
            {await drawReply(cx, e, md, cols, { margin: PANEL_MARGIN, first: turn.state === 'done', cardGaps: true, prefix: `t${k}-`, ask: tgt => void openAsk(cx, tgt), open: id => void openThread(cx, id) })}
          </Box>,
        )
      }
    }
    if (stop) keys.push({ key: 'stop', hotkey: 's', onPress: stop })
    if (flip) keys.push({ key: 'subject', hotkey: 'v', onPress: flip })
    // the entry box for the next question under the chat, its placeholder saying what it takes, as Claude Code's
    // prompt box stands under its transcript
    field = entryEl(cx, e, {
      key: fieldKey(askField),
      placeholder: 'Ask a follow-up question',
      cols,
      onSubmit: q => {
        void (async () => {
          // the question shows at once, `◌ starting · 0s` under it, until its chat holds it (sentAsks)
          if (!running) {
            sentAsks.set(t.id, { q, at: await cx.now() })
            await cx.bumpPanel()
          }
          // a question asked while the thread answers waits until its answer ends: thimble queues it
          const r = await threadMessage(cx, t.id, q)
          sentAsks.delete(t.id)
          await cx.bumpPanel()
          if (r.error) cx.toast(r.error)
          else if (r.queued || running) cx.toast('the side thread is still answering: your question waits until it ends')
        })()
      },
    })
    keys.push({ key: 'ask', hotkey: 'a', onPress: () => void focusAsk() })
  }
  const stopEl = stop ? <Button key="thread-stop" label="stop" plain onPress={stop} /> : null
  const subjectHint = word ? `v to ${subjectShown ? 'hide' : 'show'} the ${word}` : ''
  const hints = alone
    ? ['a to ask', ...(subjectHint ? [subjectHint] : []), ...(stop ? ['s to stop'] : [])]
    : ['↑↓ to choose', ...(t ? ['Enter or a to ask'] : []), ...(subjectHint ? [subjectHint] : []), ...(stop ? ['s to stop'] : [])]
  // `stop` under the chat after a blank row, then the entry box, whose top rule is the panel's second rule
  body.push(...entryBottom(cx, e, cols, [stopEl], field, hints))
  const hk = hiddenKeys(cx, e, keys)
  return <Box flexDirection="column">{[...(hk ? [hk] : []), ...body]}</Box>
}

// ------------------------------------------------------------------------------------------------ labels

/** A label as `thimble state label` prints it: the concept with its definition, its colours, its examples and rows. */
type LabelFull = ThimbleLabel

/** What a label's unit is called, many of them. */
function unitWords(unit: string | undefined): string {
  return unit === 'agent' ? 'files' : unit === 'run' ? 'run folders' : unit === 'cell' ? 'cards' : unit === 'span' ? 'sentences' : 'records'
}

// the label panel's columns (mockup labelpanel2): its labels' column, the name's and the glob's fields, a value's bar
const LABEL_COL = 'pattern:'.length + 2
const NAME_W = 40
const GLOB_W = 36
const BAR_W = 30
const KINDS = ['prompt', 'regex', 'code'] as const
// what a label labels, by its unit, as the browser's label editor offers it: a file's records, whole files, runs (each
// run's folder), the canvas's cards, the report's sentences
const UNIT_CHOICES = [['record', 'records of files'], ['agent', 'whole files'], ['run', 'runs'], ['cell', 'cards'], ['span', 'sentences']] as const
const ON_OFF = [['on', 'on'], ['off', 'off']] as const

/** A label's definition as its panel edits it: a prompt label's prompt, else its pattern or code. */
function definitionOf(l: LabelFull): string {
  return l.kind === 'prompt' ? str(l.spec).trim() || str(l.description).trim() : str(l.spec).trim()
}

/** The cards that use a label: its own label card and every card that read it, from the canvas as last read. */
async function cardsUsing(cx: Ctx, id: string): Promise<{ id: string; question: string }[]> {
  const canvas = await surfaceValue<Obj>(cx, 'canvas')
  const cells = canvas?.ok && Array.isArray(canvas.value.cells) ? (canvas.value.cells as unknown[]).filter(isObj) : []
  return cells
    .filter(c => (Array.isArray(c.labels) && (c.labels as unknown[]).map(String).includes(id)) || (isObj(c.payload) && str(c.payload.concept) === id))
    .map(c => ({ id: str(c.id), question: str(c.title) || 'a card' }))
}

// the text typed in a label's fields and not saved yet, by `<label>:<field>` (the run controls save it first)
const drafts = new Map<string, string>()

/** What the label panel holds unsaved for a label: the kind and the model picked, the words typed in its fields (its
 *  name, its definition, its glob). */
async function pendingEdits(cx: Ctx, l: LabelFull): Promise<LabelPatch> {
  const kind = (await cx.labelUi()).kind[l.id] ?? l.kind ?? 'prompt'
  const patch: LabelPatch = {}
  const body = drafts.get(`${l.id}:body`)?.trim()
  const glob = drafts.get(`${l.id}:glob`)?.trim()
  const model = drafts.get(`${l.id}:model`)
  const name = drafts.get(`${l.id}:name`)?.replace(/\s+/g, ' ').trim()
  if (name && name !== (l.name ?? l.id)) patch.name = name
  if (kind !== l.kind) patch.kind = kind
  if (body && (body !== definitionOf(l) || patch.kind)) patch.body = body
  if (glob && glob !== (l.glob ?? '')) patch.glob = glob
  if (kind === 'prompt' && model !== undefined && model !== (l.model ?? '')) patch.model = model
  return patch
}

/** Save the label panel's edits of label `id` with `extra` over them (`thimble act label`): `saved` when it saved an
 *  edit, `same` when no edit waited, false when it could not save. A kind picked is saved only with its definition. */
async function saveLabelEdits(cx: Ctx, id: string, extra: LabelPatch = {}): Promise<'saved' | 'same' | false> {
  const got = await surfaceValue(cx, `label:${id}`)
  const l = got?.ok ? (labelOf(got.value) as LabelFull | null) : null
  if (!l) return false
  const patch = { ...(await pendingEdits(cx, l)), ...extra }
  if (patch.kind && !patch.body) {
    const ui = await cx.labelUi()
    await cx.setLabelUi({ ...ui, said: { ...ui.said, [id]: `× give the ${patch.kind === 'regex' ? 'pattern' : patch.kind} before it is saved` } })
    await cx.bumpPanel()
    return false
  }
  if (!Object.keys(patch).length) {
    drafts.delete(`${id}:model`)
    return 'same'
  }
  const err = await saveLabel(cx, id, patch)
  if (!err) for (const k of ['body', 'glob', 'model', 'name']) drafts.delete(`${id}:${k}`)
  return err ? false : 'saved'
}

/** A post of field.tsx: the words typed in a field (a draft), or a save (Enter). */
export async function fieldMessage(cx: Ctx, name: string, text: string, save: boolean): Promise<void> {
  const m = /^label-body:(.+)$/.exec(name)
  if (!m) return
  drafts.set(`${m[1]}:body`, text)
  if (save && text.trim()) await saveLabelEdits(cx, m[1]!, { body: text.trim() })
}

// the label whose delete the label panel asks about (`delete label "…"? … y to delete · n to keep`), '' for none
let labelDeleting = ''
// the label whose `model:` shows the models to choose from, '' for none
let labelModelPicking = ''
// the value whose controls the label panel shows under it (`<label>\n<value>`), '' for none
let labelValueOpen = ''
// the value whose colors the label panel's counts show under it (`<label>\n<value>`), '' for none
let labelPainting = ''

/** The label panel, every field exposed and editable as in the browser's label editor (SPEC.md, section 7, "The label
 *  panel"; Matt's mockup labelpanel2): `name:` in a field, `kind:` (prompt, regex or code, the one in use on the
 *  selection background), a prompt label's `model:` (a choice, `thimble act label {model}`), `unit:`, `scope:` (the
 *  glob in a field, the files it matches and the records they hold), for a label over files `highlight:  on  off`
 *  (`thimble act label-show`); then the rule and the prompt (or pattern or code) in a bordered field
 *  to edit, Enter saving it (`thimble act label`); `values:` with each value's bar and count, a click on a value showing
 *  its `color`, `filter` (`thimble act label-filter`) and the values to edit; the last run, then the actions underlined
 *  in the accent, `delete` in red: `run on a sample` and `run on all`, which save what was typed first and run it
 *  (`thimble act label-run`), `rename` (the name's field) and `delete`, which asks once in the panel (y deletes, n
 *  keeps; `thimble act label-delete`). Then `▸ examples` and `▸ cards`, folded: the held-out agreement and `… N more`
 *  records in the examples. */
async function drawLabel(cx: Ctx, e: PaneEvent, p: TermPanel): Promise<RenderElement> {
  const els = cx.els(e) as El
  const { Box, Text, Button, Input } = cx.els(e)
  const cols = Math.max(30, e.props.bodyColumns)
  const got = await surfaceValue(cx, `label:${p.label ?? ''}`)
  if (!got) return none(cx, e, '◌ reading the label')
  if (!got.ok) return <Box flexDirection="column"><Text color={COLORS.problem} wrap="wrap">{`× ${got.error}`}</Text></Box>
  const l = labelOf(got.value) as LabelFull | null
  if (!l) return none(cx, e)
  const id = l.id
  const name = l.name ?? id
  // a delete asked about another label is not asked here, nor its models, a value's controls or its colors
  if (labelDeleting !== id) labelDeleting = ''
  if (labelModelPicking !== id) labelModelPicking = ''
  if (!labelValueOpen.startsWith(`${id}\n`)) labelValueOpen = ''
  if (!labelPainting.startsWith(`${id}\n`)) labelPainting = ''
  const ui = await cx.labelUi()
  const running = ui.runs[id]
  const said = ui.said[id] ?? ''
  // the counts as thimble.labels() reads the rows, each record the analyst set to another value under that value
  // (live check term-fix5, new quirk 5: one record set to `no` left the counts at 33/467); while a run goes on, as its
  // file says them this second (term.ts runsLane; bug hunt I2)
  const runs = await cx.labelRuns()
  const fresh = runs.live[id]
  const counts = fresh?.counts ?? l.verdicts?.counts ?? l.label_stats?.counts ?? {}
  const setByYou = l.verdicts?.set ?? 0
  const values = [...(l.labels ?? []), ...Object.keys(counts).filter(k => !(l.labels ?? []).includes(k))]
  const kind = ui.kind[id] ?? l.kind ?? 'prompt'
  const files = !l.unit || ['record', 'agent', 'run'].includes(l.unit)
  // each value's color as its class has it (the browser's label colors), else in the values' order
  const colors = classColors(l.classes)
  const shownOn = Boolean(l.shown)
  const filtered = typeof l.filter === 'string' && l.filter ? l.filter : ''
  const last = l.last_run ?? l.applications?.at(-1) ?? null
  // the records its scope holds: its last full run's count, else the count `thimble state` gives a label with no run
  // that ended (live check term-fix10, low quirk: `run on all` and `scope: pages.jsonl` showed no number after a first
  // run stopped part way)
  // (a run going on: its own scope's, as a run within another label counts it: bug hunt I4)
  const live = fresh?.matched_total ?? (l.run?.status === 'running' && typeof l.run.matched_total === 'number' ? l.run.matched_total : null)
  const scopeN = live ?? (typeof last?.matched_total === 'number' ? last.matched_total : typeof last?.total === 'number' && !l.trial ? last.total : typeof l.scope_total === 'number' ? l.scope_total : null)
  const sample = l.trial && last?.limit ? last.limit : 30
  // the units a run reads from: the scope's count, or for a label over whole files the files its glob matches; a
  // scope that holds no more units than a sample runs whole, so its sample's button gives way (bug hunt B31: `run on a
  // sample` of a label over 33 files asked main for "30 records")
  const unitsN = scopeN ?? (l.unit === 'agent' && typeof l.scope_files === 'number' ? l.scope_files : null)
  const sampleWhole = unitsN !== null && unitsN <= sample
  const unit = unitWords(l.unit)
  const opened = (part: string) => ui.open.includes(`${id}:${part}`)
  const flip = (part: string) => async () => {
    const cur = await cx.labelUi()
    const k = `${id}:${part}`
    await cx.setLabelUi({ ...cur, open: cur.open.includes(k) ? cur.open.filter(x => x !== k) : [...cur.open, k] })
    await cx.bumpPanel()
  }
  // the edits typed and not saved, and the kind picked: what a save or a run stores first
  const save = (extra: LabelPatch = {}) => saveLabelEdits(cx, id, extra)
  // a run says what it reads in main's prompt (runReads), and that the analyst changed the label only when this press
  // saved an edit (bug hunt B31)
  const run = (limit: number) => async () => {
    if (running) return
    const saved = await save()
    if (saved) await runLabel(cx, id, name, limit, { changed: saved === 'saved', reads: runReads(limit, unitsN, noun).prompt })
  }
  // go on with a stopped run: its `left` units, which an edit saved first would make a run on every unit
  const goOn = (left: number) => async () => {
    if (running) return
    const saved = await save()
    // an edit saved first makes it another definition, whose run labels every unit
    if (saved === 'saved') await runLabel(cx, id, name, 0, { changed: true, reads: runReads(0, unitsN, noun).prompt })
    else if (saved) await runLabel(cx, id, name, 0, { changed: false, reads: `the other ${num(left)} ${noun}`, resume: left })
  }
  // delete: asked once in the panel (labelDeleting), then `thimble act label-delete` and the labels list
  const askDelete = async () => {
    labelDeleting = id
    await cx.bumpPanel()
  }
  const keepIt = async () => {
    labelDeleting = ''
    await cx.bumpPanel()
  }
  const deleteIt = async () => {
    if (labelDeleting !== id) return
    labelDeleting = ''
    await deleteLabel(cx, id, name)
  }
  const rows: RenderElement[] = []
  const keys: Key[] = []
  // rename: the name's field takes the keyboard (`lb-name-<id>`, in the header), Enter saving the name (`thimble act
  // label`)
  const askRename = async () => {
    labelDeleting = ''
    const key = `lb-name-${id}`
    if (!(await cx.focus(key))) return
    rt.panelFocus = key
    await cx.bumpPanel()
  }
  const rename = async (v: string) => {
    const next = v.replace(/\s+/g, ' ').trim()
    drafts.delete(`${id}:name`)
    if (!next || next === name) return
    await save({ name: next })
  }
  // on or off in Files and the views, as the Labels pane's toggle (`thimble act label-show`)
  const turn = (on: boolean) => async () => {
    if (on !== shownOn) await showLabel(cx, id, { on })
  }
  // the model's choice: a click on it shows the models, a pick saves it with what else was typed ('' for the labels
  // role's, as the browser's label editor saves it)
  const pickModel = async (m?: string) => {
    if (m === undefined) labelModelPicking = labelModelPicking === id ? '' : id
    else {
      labelModelPicking = ''
      drafts.set(`${id}:model`, m === l.model_role ? '' : m)
      await save()
    }
    await cx.bumpPanel()
  }
  // the header block, every field exposed and editable as in the browser's label editor (Matt, mockup labelpanel2):
  // `name:`, `kind:`, a prompt label's `model:`, `unit:`, `scope:`, each on the label column, and for a label over files
  // `highlight:`; then the rule and the definition
  const L = LABEL_COL
  const fieldLine = (label: string, el: RenderElement) => (
    <Box key={`lf-${label}`} flexDirection="row">
      <Box width={L} flexShrink={0}>
        <Text dimColor>{label}</Text>
      </Box>
      <Box flexGrow={1} flexShrink={1} flexDirection="column">
        {el}
      </Box>
    </Box>
  )
  // a choice among a few: the one in use on the selection background, the others dim and a click away (`press`), or
  // dim and plain where they cannot be chosen; one cell around each word, one between them
  const choices = (prefix: string, opts: readonly (readonly [string, string])[], chosen: string, press?: (v: string) => void) => (
    <Box flexDirection="row" columnGap={1} flexWrap="wrap">
      {opts.map(([v, words]) =>
        v === chosen ? (
          <Text key={`${prefix}-${v}`} backgroundColor={COLORS.selected}>{` ${words} `}</Text>
        ) : press ? (
          <Button key={`${prefix}-${v}`} label={` ${words} `} plain dimColor onPress={() => press(v)} />
        ) : (
          <Text key={`${prefix}-${v}`} dimColor>{` ${words} `}</Text>
        ),
      )}
    </Box>
  )
  const editable = !running && e.surface !== 'mobile'
  // name: a field on the selection background, the label's ● in its color before the name; Enter renames
  rows.push(
    fieldLine(
      'name:',
      <Box width={Math.min(NAME_W, cols - L)} backgroundColor={COLORS.selected} paddingLeft={1} flexDirection="row">
        <Text color={labelHue(values, colors)}>{'● '}</Text>
        {editable ? (
          <Box flexGrow={1} flexShrink={1}>
            <Input key={fieldKey(`lb-name-${id}`)} value={drafts.get(`${id}:name`) ?? name} submitLabel="rename" onInput={v => void drafts.set(`${id}:name`, v)} onSubmit={v => void rename(v)} />
          </Box>
        ) : (
          <Text wrap="truncate-end">{name}</Text>
        )}
      </Box>,
    ),
  )
  // kind: prompt, regex or code; while a run goes, plain text, as the fields are
  rows.push(
    fieldLine(
      'kind:',
      choices(
        'lk',
        KINDS.map(k => [k, k] as const),
        kind,
        running
          ? undefined
          : k =>
              void (async () => {
                const cur = await cx.labelUi()
                const next = { ...cur.kind }
                if (k === l.kind) delete next[id]
                else next[id] = k
                await cx.setLabelUi({ ...cur, kind: next })
                await cx.bumpPanel()
              })(),
      ),
    ),
  )
  // model (a prompt label): the model its calls run on by its id, the label's own or the labels role's (Settings' row
  // for labels), a choice: a click shows the models under it, a pick saves it ('' for the role's, as the browser does)
  const modelDraft = drafts.get(`${id}:model`)
  const modelShown = modelDraft !== undefined ? modelDraft || l.model_role || '' : l.model_id || l.run_model || ''
  const modelChoices = l.model_choices ?? []
  if (kind === 'prompt' && modelShown) {
    const picking = labelModelPicking === id && !running && modelChoices.length > 1
    const look = [<Text key="lm-name" backgroundColor={COLORS.selected}>{` ${modelShown} `}</Text>, <Text key="lm-mark" backgroundColor={COLORS.selected} dimColor>{'▾'}</Text>, <Text key="lm-end" backgroundColor={COLORS.selected}>{' '}</Text>]
    rows.push(
      fieldLine(
        'model:',
        <Box flexDirection="column">
          <Box flexDirection="row">
            {running || modelChoices.length < 2 ? (
              look
            ) : (
              <Button key="lb-model" plain onPress={() => void pickModel()}>
                {look}
              </Button>
            )}
          </Box>
          {picking
            ? choices(
                'lb-model',
                modelChoices.map(m => [m, m] as const),
                modelShown,
                m => void pickModel(m),
              )
            : null}
        </Box>,
      ),
    )
  }
  // unit: what it labels, the one it has lit (a whole-file label's `whole files`, a run label's `runs`: bug hunt C14);
  // only that one, since its rows are of that unit (the browser's `Over`, fixed once made)
  rows.push(fieldLine('unit:', choices('lu', UNIT_CHOICES, UNIT_CHOICES.some(([u]) => u === l.unit) ? l.unit! : 'record')))
  // scope: a label over files, its glob in a field and how many files it matches and records they hold (Matt, 19:05: a
  // bare count read as a link); a label over cards or sentences, what it holds and how many
  const noun = files ? l.scope_unit || unit : unit
  const holds = scopeN !== null && l.unit !== 'agent' ? `${num(scopeN)} ${scopeN === 1 ? oneOf(noun) : noun}` : ''
  const matches = files && typeof l.scope_files === 'number' ? (l.scope_files === 1 ? '1 file matches' : `${num(l.scope_files)} files match`) : ''
  const counted = [matches, holds].filter(Boolean).join(' · ')
  if (files) {
    const globW = Math.max(12, Math.min(GLOB_W, cols - L - (counted ? width(counted) + 3 : 0)))
    rows.push(
      fieldLine(
        'scope:',
        <Box flexDirection="row">
          <Box width={globW} flexShrink={0} backgroundColor={COLORS.selected} paddingLeft={1}>
            {editable ? (
              <Input key={fieldKey(`lb-glob-${id}`)} value={drafts.get(`${id}:glob`) ?? l.glob ?? ''} submitLabel="save" onInput={v => void drafts.set(`${id}:glob`, v)} onSubmit={v => void (v.trim() ? save({ glob: v.trim() }) : undefined)} />
            ) : (
              <Text wrap="truncate-end">{l.glob ?? ''}</Text>
            )}
          </Box>
          {counted ? <Text dimColor wrap="truncate-end">{` · ${counted}`}</Text> : null}
        </Box>,
      ),
    )
  } else
    rows.push(
      fieldLine(
        'scope:',
        <Text wrap="wrap">
          <Text>{l.unit === 'cell' ? "the canvas's cards" : "the report's sentences"}</Text>
          {counted ? <Text dimColor>{` · ${counted}`}</Text> : null}
        </Text>,
      ),
    )
  // a label over files: `highlight:  on  off`, whether Files and the views mark its records with its values; f flips it
  if (files) rows.push(fieldLine('highlight:', choices('lo', ON_OFF, shownOn ? 'on' : 'off', running ? undefined : v => void turn(v === 'on')())))
  rows.push(ruleEl(els, cols, 'lb-rule'))
  // the definition, whole, in a field to edit (field.tsx) in a round border from the label column to the pane's edge,
  // its name (`prompt`, `pattern` or `code`) on its first row; a click gives it the keyboard, Enter saves it (in code,
  // ctrl+s); code has its keywords and strings colored; a pattern says under it what a match gives
  const defName = kind === 'prompt' ? 'prompt' : kind === 'regex' ? 'pattern' : 'code'
  const shownDef = kind === l.kind ? definitionOf(l) : ''
  const defW = Math.max(10, cols - L - 4)
  const { Client } = cx.els(e)
  const defBody =
    !running && (e.surface === 'terminal' || e.surface === 'desktop') ? (
      <Client key={`lb-def-${id}-${kind}`} module="./field.tsx" width={defW} props={JSON.parse(JSON.stringify({ name: `label-body:${id}`, text: shownDef, cols: defW, placeholder: `the ${defName}: click to write it`, multiline: kind === 'code', ...(kind === 'code' ? { code: { keyword: COLORS.cite, string: COLORS.fresh } } : {}) }))} />
    ) : kind === 'code' ? (
      <Box key="lb-def">{codeRows(cx, e, shownDef, 30)}</Box>
    ) : (
      <Text key="lb-def" wrap="wrap">{shownDef || ' '}</Text>
    )
  rows.push(
    <Box key={`lf-${defName}:`} flexDirection="row">
      <Box width={L} flexShrink={0} flexDirection="column">
        <Text> </Text>
        <Text dimColor>{`${defName}:`}</Text>
      </Box>
      <Box flexGrow={1} flexShrink={1} flexDirection="column" borderStyle="round" borderColor={COLORS.rule} paddingX={1}>
        {defBody}
        {kind === 'regex' ? <Text key="lb-def-note" dimColor wrap="wrap">{regexNote(values, shownDef || definitionOf(l))}</Text> : null}
      </Box>
    </Box>,
  )
  // values: each value's ● and bar in its color, the bar to the largest count, its count bold (the browser's classes);
  // a click on a value shows its controls under it: `color` (a label over files), `filter`, and the values to edit.
  // The counts apply the analyst's verdicts, as thimble.labels() reads the rows, and `values:` says how many they set
  rows.push(<Text key="lb-gap-values"> </Text>)
  const notes = [setByYou ? `${num(setByYou)} set by you` : '', filtered ? `filtered to ${filtered}` : ''].filter(Boolean).join(' · ')
  rows.push(fieldLine('values:', <Text dimColor wrap="truncate-end">{notes}</Text>))
  // its records of no fit and unsure, counted as home counts them (labelParts), while labels are on
  const u = (await featuresOf(cx)).labels ? (await cx.labelUnsure()).find(x => x.id === id) : undefined
  const parts = labelParts({ slug: id, name, kind, trial: Boolean(l.trial), counts, values: l.labels ?? Object.keys(counts), paths: [], running: Boolean(running), ...(u ? { noFit: u.noFit, unsure: u.unsure } : {}) })
  const extraNs = [parts.unsure, ...parts.parts.filter(x => x.mark === NO_FIT_MARK).map(x => x.n)].filter(n => n > 0)
  const most = Math.max(0, ...values.map(v => counts[v] ?? 0), ...extraNs)
  const vw = Math.min(Math.max(12, Math.floor(cols / 3)), Math.max(1, ...values.map(v => width(v)), ...(extraNs.length ? [width('unsure')] : [])))
  const cs = values.map(v => num(counts[v] ?? 0))
  const cw = Math.max(3, ...cs.map(c => c.length), ...extraNs.map(n => num(n).length))
  const barW = Math.max(4, Math.min(BAR_W, cols - L - 2 - vw - 2 - 1 - cw))
  const openValue = (v: string) => async () => {
    labelValueOpen = labelValueOpen === `${id}\n${v}` ? '' : `${id}\n${v}`
    if (!labelValueOpen) labelPainting = ''
    await cx.bumpPanel()
  }
  const paint = (v: string) => async () => {
    labelPainting = labelPainting === `${id}\n${v}` ? '' : `${id}\n${v}`
    await cx.bumpPanel()
  }
  const pick = (v: string, colorName: string) => async () => {
    labelPainting = ''
    await showLabel(cx, id, { colors: { [v]: colorName } })
  }
  values.forEach((v, i) => {
    const n = counts[v] ?? 0
    const cells = n > 0 && most > 0 ? Math.max(1, Math.round((barW * n) / most)) : 0
    const colour = valueColour(values, v, colors)
    const tone = colour && colour !== COLORS.dim ? { color: colour } : { dimColor: true }
    const on = filtered === v
    rows.push(
      <Box key={`lb-c-${v}`} flexDirection="row" marginLeft={L}>
        <Text {...tone}>{'● '}</Text>
        {/* the value a link to the label named, or the one the filter keeps, on the selection background */}
        <Button key={`lb-value-${v}`} plain onPress={() => void openValue(v)()}>
          <Text {...(v === p.value || on ? { backgroundColor: COLORS.selected } : {})}>{clip(v, vw).padEnd(vw)}</Text>
        </Button>
        <Text wrap="truncate-end">
          <Text>{'  '}</Text>
          <Text {...tone}>{'━'.repeat(cells)}</Text>
          <Text>{' '.repeat(barW + 1 - cells)}</Text>
          <Text bold>{cs[i]!.padStart(cw)}</Text>
        </Text>
      </Box>,
    )
    if (labelValueOpen !== `${id}\n${v}`) return
    // its controls: its colors (a label over files, whose colors Files and the views show) and the filter that keeps
    // its units, `clear filter` on the value the filter keeps; then the values, to edit
    rows.push(
      <Box key={`lb-c-${v}-controls`} flexDirection="row" columnGap={2} marginLeft={L + 2}>
        {files ? actionEl(els, `lb-color-${v}`, 'color', () => void paint(v)()) : null}
        {actionEl(els, `lb-filter-${v}`, on ? 'clear filter' : 'filter', () => void filterLabel(cx, id, on ? null : v))}
      </Box>,
    )
    // the eighteen label colors under the value whose `color` was pressed, around the color wheel as the browser's
    // pickers show them: a column per hue, its light place above its dark (LABEL_WHEEL), each `●` in its hue and its
    // name as show_label names it, the one it has on the selection background; a narrow pane wraps the columns, a
    // blank row between their rows
    if (files && labelPainting === `${id}\n${v}`) {
      const now = colors?.[v]
      const swatch = (k: number) => {
        const c = COLOR_NAMES[k - 1]!
        return (
          <Box key={`lb-pick-${v}-${c}`} flexDirection="row">
            <Text color={hueOf(k)}>{'● '}</Text>
            {now === k ? <Text backgroundColor={COLORS.selected}>{c}</Text> : <Button key={`lb-pick-${v}-${k}`} label={c} plain onPress={() => void pick(v, c)()} />}
          </Box>
        )
      }
      rows.push(
        <Box key={`lb-colors-${v}`} flexDirection="row" flexWrap="wrap" columnGap={2} rowGap={1} marginLeft={L + 2}>
          {LABEL_WHEEL.map(([light, dark]) => (
            <Box key={`lb-hue-${v}-${light}`} flexDirection="column">
              {swatch(light)}
              {swatch(dark)}
            </Box>
          ))}
        </Box>,
      )
    }
    // its values, editable here: Enter saves them
    if (editable)
      rows.push(
        <Box key="lb-values" flexDirection="row" marginLeft={L + 2}>
          <Text dimColor>{'values  '}</Text>
          <Box flexGrow={1} flexShrink={1}>
            <Input
              key={fieldKey(`lb-values-${id}`)}
              value={values.join(' · ')}
              submitLabel="save"
              onSubmit={x => {
                const vs = [...new Set(x.split(/\s*[·,]\s*/).map(y => y.trim()).filter(Boolean))]
                if (vs.length >= 2) void save({ values: vs })
              }}
            />
          </Box>
        </Box>,
      )
  })
  if (!values.length) rows.push(<Box key="lb-no-values" marginLeft={L}><Text dimColor>none</Text></Box>)
  // then the records it is unsure of (among its values' counts) and those no category fit that no value names, as home
  // and the Labels view count them (home.ts labelParts: bug hunt C14, home's `▒ unsure 18` missing here)
  const extra: [string, string, number][] = [
    ...(parts.unsure ? [[UNSURE_MARK, 'unsure', parts.unsure] as [string, string, number]] : []),
    ...parts.parts.filter(x => x.mark === NO_FIT_MARK).map((x): [string, string, number] => [NO_FIT_MARK, x.name, x.n]),
  ]
  for (const [mark, what, n] of extra) {
    const cells = most > 0 ? Math.max(1, Math.round((barW * n) / most)) : 0
    rows.push(
      <Box key={`lb-x-${what}`} flexDirection="row" marginLeft={L}>
        <Text dimColor>{`${mark} `}</Text>
        <Text dimColor>{clip(what, vw).padEnd(vw)}</Text>
        <Text wrap="truncate-end">
          <Text>{'  '}</Text>
          <Text dimColor>{mark.repeat(cells)}</Text>
          <Text>{' '.repeat(Math.max(0, barW + 1 - cells))}</Text>
          <Text dimColor>{num(n).padStart(cw)}</Text>
        </Text>
      </Box>,
    )
  }
  // the whole files or runs its last run read only in part, one dim line under the values as the browser's Labels pane
  // has it, until a run cuts none (backend concepts.read_cut)
  if (!running && last?.cut?.line) rows.push(<Box key="lb-cut" marginLeft={L}><Text wrap="wrap" dimColor>{last.cut.line}</Text></Box>)
  // run it: on a sample, or on every record; they save what was typed first. Its state as home, the list and its card
  // say it (lib.ts labelState): a run going on in any process (this panel's, main's, the browser's Run again) is
  // `◌ labeling 3,000 of 4,579`, its count live, and a first run stopped part way `stopped at 3,150 of 4,579`, never `not
  // run yet` beside its counts (live check term-fix9, quirk 4; bug hunt I2)
  const st = labelState(l, runs)
  const ranOn = (n: number) => `${num(n)} ${n === 1 ? oneOf(noun) : noun}`
  const lastWords = last && !st.stopped ? (l.trial || last.limit ? `last run on a sample of ${ranOn(last.labeled ?? 0)}` : `last run on all ${ranOn(last.labeled ?? 0)}`) : labelStateWords(st)
  // a run's stop, wherever it runs, goes as the browser's Stop run goes (`thimble act label-stop`), and the panel says
  // when it did not stop (bug hunt I1: a run main started ignored it)
  const stop = () => void stopLabel(cx, id)
  rows.push(<Text key="lb-gap-runs"> </Text>)
  if (running || st.running)
    rows.push(
      <Box key="lb-running" flexDirection="row" columnGap={3} flexWrap="wrap">
        <Text>{st.running ? labelStateWords(st) : `◌ labeling ${running!.limit ? `a sample of ${num(running!.limit)}` : `all ${scopeN !== null ? num(scopeN) : ''} ${noun}`.replace(/\s+/g, ' ')}`}</Text>
        {actionEl(els, 'lb-stop', 'stop', stop)}
      </Box>,
    )
  else {
    // the last run dim on its own row, the actions under it, underlined in the accent, `delete` in red (Matt, v9
    // review, item m; mockup labelpanel2)
    rows.push(<Text key="lb-last" dimColor wrap="wrap">{lastWords}</Text>)
    if (labelDeleting === id)
      // the delete asks once, in the actions' place: y deletes, n keeps
      rows.push(
        <Box key="lb-delete" flexDirection="row" flexWrap="wrap">
          <Text>{`delete label "${name}"? its marks and card go too · `}</Text>
          {actionEl(els, 'lb-delete-yes', 'y to delete', () => void deleteIt(), COLORS.problem)}
          <Text>{' · '}</Text>
          {actionEl(els, 'lb-delete-no', 'n to keep', () => void keepIt())}
        </Box>,
      )
    else
      rows.push(
        <Box key="lb-runs" flexDirection="row" columnGap={3} flexWrap="wrap">
          {/* a run stopped part way under the definition it has now goes on with the units it never read, its rows kept
              (bug hunt I3); `run on all` labels every unit again */}
          {l.resume ? actionEl(els, 'lb-resume', `label the other ${num(l.resume.left)}`, () => void goOn(l.resume!.left)()) : null}
          {sampleWhole ? null : actionEl(els, 'lb-sample', runReads(sample, unitsN, noun).button, () => void run(sample)())}
          {actionEl(els, 'lb-all', runReads(0, unitsN, noun).button, () => void run(0)())}
          {actionEl(els, 'lb-rename', 'rename', () => void askRename())}
          {actionEl(els, 'lb-delete', 'delete', () => void askDelete(), COLORS.problem)}
        </Box>,
      )
  }
  // what the last save or run said: `×` and `!` rows in red
  // `◌ stopping` goes once no run is going
  const saidNow = !running && !st.running && said.startsWith('◌ stopping') ? '' : said
  saidNow.split('\n').filter(Boolean).forEach((line, i) => rows.push(<Text key={`lb-said-${i}`} wrap="wrap" {...(/^[×!]/.test(line) ? { color: COLORS.problem } : { dimColor: true })}>{line}</Text>))
  const asking = labelDeleting === id && !running && !st.running
  if (asking) keys.push({ key: 'delete-yes', hotkey: 'y', onPress: () => void deleteIt() }, { key: 'delete-no', hotkey: 'n', onPress: () => void keepIt() })
  else if (!running && !st.running) keys.push({ key: 'sample', hotkey: 'r', onPress: () => void run(sampleWhole ? 0 : sample)() }, { key: 'rename', hotkey: 'n', onPress: () => void askRename() }, { key: 'delete', hotkey: 'k', onPress: () => void askDelete() })
  else keys.push({ key: 'stop', hotkey: 's', onPress: stop })
  // f shows or hides the marks of a label over files in Files and the views (o opens the label in the browser, as in
  // every view)
  if (files && !asking && !running) keys.push({ key: 'files-on', hotkey: 'f', onPress: () => void turn(!shownOn)() })
  // the examples and the cards, folded, under the actions
  const toggle = (part: string, words: string, n: number | null, note = '') => (
    <Box key={`lb-t-${part}`} flexDirection="row">
      <Button key={`lb-open-${part}`} label={`${opened(part) ? '▾' : '▸'} ${words}`} plain onPress={() => void flip(part)()} />
      {n !== null ? <Text dimColor>{`  ${num(n)}${note ? ` · ${note}` : ''}`}</Text> : null}
    </Box>
  )
  rows.push(<Text key="lb-gap"> </Text>)
  // the examples: the records the label gave each value, with the analyst's agree or another value
  const recs = (l.rows ?? []).filter(r => r.ref)
  // the label's agreement with the values the analyst set, those its runs took as examples apart (the browser's
  // agreement line above its examples)
  rows.push(toggle('examples', 'examples', recs.length, agreementLine(l.calibration)))
  keys.push({ key: 'examples', hotkey: 'e', onPress: () => void flip('examples')() })
  // a record's words: a JSON record as the field the rule reads first, its value in quotation marks and italic, then
  // its other fields on one dim row, never its JSON inside quotation marks; other words in quotation marks, up to three
  // rows
  const room = Math.max(120, (cols - 4) * 3 - 2)
  const recordRows = (ref: string, raw: string, match: string): RenderElement | null => {
    const text = demojibake(raw)
    if (!text.trim()) return null
    const f = recordFields(text, { kind: l.kind ?? '', spec: definitionOf(l), ...(match ? { match } : {}) })
    if (!f) return <Text italic wrap="wrap">{quoted(clip(text, room))}</Text>
    return (
      <Box flexDirection="column">
        {fieldEls(els, f.read.map(([k, v]): [string, RenderElement] => [k, <Text italic wrap="wrap">{quoted(clip(v, room - k.length - 2))}</Text>]), `lx-f-${cid(ref)}`)}
        {f.rest.length ? <Text dimColor wrap="truncate-end">{itemsRow(f.rest.map(([k, v]) => `${k} ${clip(v, 48)}`), Math.max(10, cols - 4))}</Text> : null}
      </Box>
    )
  }
  if (opened('examples')) {
    // first, the records with no category fit and those the label is unsure of (SPEC-v2 J6), UNSURE_PAGE at a time
    const u = (await featuresOf(cx)).labels ? (await cx.labelUnsure()).find(x => x.id === id) : undefined
    const gotU = u && u.noFit + u.unsure ? await surfaceValue(cx, unsureKey(id)) : undefined
    if (u && u.noFit + u.unsure && !gotU) wantUnsure(cx, id)
    const un = gotU?.ok ? unsureOf(gotU.value) : null
    if (un?.rows.length) {
      rows.push(
        <Text key="lb-u-h" wrap="truncate-end">
          <Text>{'  '}</Text>
          <Text color={COLORS.problem}>{'● '}</Text>
          <Text>no category fit or unsure</Text>
          <Text dimColor>{`  ${num(un.total)}`}</Text>
        </Text>,
      )
      for (const r of un.rows) {
        const place = placeWords(r.ref)
        const verdict = (value: string) => async () => {
          if (!rt.sc) return
          const got2 = await act(cx, rt.sc, 'verdict', { label: id, ref: r.ref, value })
          if (!got2.ok) cx.toast(`the verdict was not kept: ${got2.error}`)
          await readUnsure(cx, id)
          await readSurface(cx, `label:${id}`, 'label', labelArgs(id))
          await cx.bumpPanel()
        }
        rows.push(
          <Box key={`lb-u-${r.ref}`} flexDirection="column" marginLeft={4}>
            <Box flexDirection="row" columnGap={2}>
              <Box flexShrink={0}>{linesEl(cx, e, `lu-${cid(r.ref)}`, [[{ s: '↗', fg: LINK }, { s: ' ' }, linkSeg(cut(place, Math.max(8, cols - 40)))]], [{ y: 0, x0: 0, x1: 2 + width(cut(place, Math.max(8, cols - 40))), row: false, run: () => openCite(cx, r.ref, null) }], Math.min(cols - 4, 2 + width(cut(place, Math.max(8, cols - 40)))))}</Box>
              <Box flexShrink={1}>
                <Text dimColor wrap="truncate-end">{`${unsureWords(r)}${r.value ? ` · ${clip(r.value, 24)}` : ''}`}</Text>
              </Box>
              <Box flexGrow={1} />
              <Box flexDirection="row" columnGap={2} flexWrap="wrap">
                <Text dimColor>it is</Text>
                {values.map(o => (
                  <Button key={`lb-u-set-${r.ref}-${o}`} label={clip(o, 24)} plain onPress={() => void verdict(o)()} />
                ))}
              </Box>
            </Box>
            {recordRows(r.ref, r.text, '')}
          </Box>,
        )
      }
      const leftU = un.total - un.rows.length
      if (leftU > 0) rows.push(<Box key="lb-u-more" flexDirection="row" marginLeft={4}><Button key="lb-u-more" label={`… ${num(leftU)} more`} plain onPress={() => void moreUnsure(cx, id)} /></Box>)
    }
    // the value a link to the label named first, lit
    for (const v of p.value && values.includes(p.value) ? [p.value, ...values.filter(x => x !== p.value)] : values) {
      const xs = recs.filter(r => (typeof r.analyst === 'string' && r.analyst ? r.analyst : str(r.label)) === v)
      if (!xs.length) continue
      rows.push(
        <Text key={`lb-h-${v}`} wrap="truncate-end">
          <Text>{'  '}</Text>
          <Text color={valueColour(values, v, colors)}>{'● '}</Text>
          <Text {...(v === p.value ? { backgroundColor: COLORS.selected } : {})}>{v}</Text>
          <Text dimColor>{`  ${num(Math.max(xs.length, l.totals?.[v] ?? 0))}`}</Text>
        </Text>,
      )
      for (const x of xs) {
        const ref = x.ref!
        const place = placeWords(ref)
        const set = Boolean(x.analyst)
        const others = values.filter(o => o !== v)
        // each value a button as wide as the longest value, so `agree  it is  …` stands in one place for every value
        const vw = Math.max(1, ...values.map(o => width(clip(o, 24))))
        const verdict = (value: string) => async () => {
          if (!rt.sc) return
          const r = await act(cx, rt.sc, 'verdict', { label: id, ref, value })
          if (!r.ok) cx.toast(`the verdict was not kept: ${r.error}`)
          await readSurface(cx, `label:${id}`, 'label', [id])
          await cx.bumpPanel()
        }
        rows.push(
          <Box key={`lb-x-${ref}`} flexDirection="column" marginLeft={4}>
            <Box flexDirection="row" columnGap={2}>
              <Box flexShrink={1}>{linesEl(cx, e, `lx-${cid(ref)}`, [[{ s: '↗', fg: LINK }, { s: ' ' }, linkSeg(cut(place, Math.max(8, cols - 30)))]], [{ y: 0, x0: 0, x1: 2 + width(cut(place, Math.max(8, cols - 30))), row: false, run: () => openCite(cx, ref, null) }], Math.min(cols - 4, 2 + width(cut(place, Math.max(8, cols - 30)))))}</Box>
              <Box flexGrow={1} />
              {set ? <Text dimColor>{str(x.label) && str(x.label) !== v ? '✓ set by you' : '✓ agreed'}</Text> : null}
              {set ? null : <Button key={`lb-agree-${ref}`} label="agree" plain onPress={() => void verdict(v)()} />}
              {set ? null : (
                <Box flexDirection="row" columnGap={2} flexWrap="wrap">
                  <Text dimColor>it is</Text>
                  {others.map(o => (
                    <Button key={`lb-set-${ref}-${o}`} label={clip(o, 24).padEnd(vw)} plain onPress={() => void verdict(o)()} />
                  ))}
                </Box>
              )}
            </Box>
            {recordRows(x.ref!, str(x.text), str(x.match))}
            {x.rationale ? <Text dimColor wrap="wrap">{`why  ${clip(str(x.rationale), cols * 2)}`}</Text> : null}
          </Box>,
        )
      }
      // the value's records past those shown, as the browser's examples page through them: a click reads the next
      // MORE_ROWS (`thimble state label --rows`), and the last one with them rather than leave one behind
      const all = l.totals?.[v] ?? 0
      const left = all - xs.length
      if (left > 1) {
        const more = async () => {
          const k = `${id}\n${v}`
          const next = Math.min(all, (labelRows.get(k) ?? xs.length) + MORE_ROWS)
          labelRows.set(k, all - next === 1 ? all : next)
          await readSurface(cx, `label:${id}`, 'label', labelArgs(id))
          await cx.bumpPanel()
        }
        rows.push(
          <Box key={`lb-more-${v}`} flexDirection="row" marginLeft={4}>
            <Button key={`lb-more-${v}`} label={`… ${num(left)} more`} plain onPress={() => void more()} />
          </Box>,
        )
      }
    }
    if (!recs.length) rows.push(<Text key="lb-x-none" dimColor>{'  none'}</Text>)
  }
  // the cards that use it, each a click away
  const cards = await cardsUsing(cx, id)
  if (opened('examples')) rows.push(<Text key="lb-gap-cards"> </Text>)
  rows.push(toggle('cards', 'cards', cards.length))
  keys.push({ key: 'cards', hotkey: 'd', onPress: () => void flip('cards')() })
  if (opened('cards')) {
    for (const c of cards.slice(0, 8)) rows.push(<Box key={`lb-card-${c.id}`} flexDirection="row" marginLeft={2}><Button key={`lb-card-open-${c.id}`} label={`${clip(c.question, Math.max(20, cols - 6))} ›`} plain onPress={() => void openCard(cx, c.id)} /></Box>)
    if (cards.length > 8) rows.push(<Text key="lb-cards-more" dimColor>{`  … ${num(cards.length - 8)} more`}</Text>)
    if (!cards.length) rows.push(<Text key="lb-cards-none" dimColor>{'  none'}</Text>)
  }
  // the labels list with this label chosen (live check term-fix10, new quirk 8: it chose the list's remembered row)
  keys.push({ key: 'list', hotkey: 'l', onPress: () => {
    labelPick = l.id || p.label || labelPick
    void openList(cx, { view: 'labels', title: 'Labels' })
  } })
  // the keys (mockup labelpanel2): the ring walks every field and action, Enter presses one or gives a field the
  // keyboard; the letters stay bound (r, n, k, f, e, d, l) unnamed; s while a run goes
  rows.push(<Text key="lb-gap-hints"> </Text>)
  rows.push(hintsRow(els, ['↑↓ to choose', RING_HINT, ...(running || st.running ? ['s to stop'] : [])], cols))
  const hk = hiddenKeys(cx, e, keys)
  return <Box flexDirection="column">{[...(hk ? [hk] : []), ...rows]}</Box>
}

// the labels list's chosen row
let labelPick = ''

// the labels whose unsure records a drawing asked for and no read gave yet (a drawing writes no state: a timer reads them)
const unsureAsked = new Set<string>()

/** A label's records with no category fit and its unsure ones, read (`thimble state label-unsure --label`). */
async function readUnsure(cx: Ctx, id: string): Promise<void> {
  await readSurface(cx, unsureKey(id), 'label-unsure', unsureArgs(id))
}

/** A label's unsure records read from a timer, once, for a drawing that found none read yet. */
function wantUnsure(cx: Ctx, id: string): void {
  if (unsureAsked.has(id)) return
  unsureAsked.add(id)
  cx.later(0, () => void readUnsure(cx, id).then(() => cx.bumpPanel()).finally(() => unsureAsked.delete(id)))
}

/** `… N more` under the records the label panel lists first: UNSURE_PAGE more of them. */
async function moreUnsure(cx: Ctx, id: string): Promise<void> {
  unsureShown.set(id, (unsureShown.get(id) ?? UNSURE_PAGE) + UNSURE_PAGE)
  await readUnsure(cx, id)
  await cx.bumpPanel()
}

/** The unsure records the panel shows read again (the labels changed): the one label's in its editor (band.tsx
 *  refreshSummary calls it); the labels list draws only their counts. */
export async function refreshUnsure(cx: Ctx): Promise<void> {
  const p = await cx.panel()
  const ids = p?.view === 'label' && p.label ? [p.label] : []
  for (const id of ids) await readUnsure(cx, id)
  if (ids.length) await cx.bumpPanel()
}

/** The legend rows a label takes in the labels list, which has the room home leaves to other sections. */
const LIST_LEGEND_ROWS = 4
/** The key of the labels list's entry box, which describes a new label. */
const NEW_LABEL = 'make-label'

/** The labels (SPEC.md, "The label panel", the labels list): each label as home draws it, its name, its bar and total
 *  and its legend, `❯` on the chosen one while the entry box does not hold the keys; under them the entry box `describe
 *  a new label`, whose words go to main, its `❯` drawn only while it holds them, so one row shows the cursor. With no
 *  label the list has no keys: the box takes them (bug hunt C2: the list's keys took a letter of the description and
 *  sent the rest to main's prompt). */
async function drawLabels(cx: Ctx, e: PaneEvent): Promise<RenderElement> {
  const els = cx.els(e) as El
  const { Box, Button, Text } = cx.els(e)
  const cols = Math.max(30, e.props.bodyColumns)
  const got = await surfaceValue(cx, 'labels')
  const ls = (got?.ok ? labelsOf(got.value) : []) as LabelFull[]
  const body: RenderElement[] = [...headerEls(els, { title: 'Labels', cols, sub: subLine([plural(ls.length, 'label')]) })]
  const pick = ls.find(x => x.id === labelPick)?.id ?? ls[0]?.id ?? ''
  // one row shows the cursor: the chosen label's `❯` while the box does not hold the keys, the box's `❯` while it does
  const boxHeld = rt.panelFocus === NEW_LABEL && panelHasKeys()
  // the label deleted last from its panel: `undo` puts it back with its marks, its card and its filters, as the
  // browser's top bar's Undo (`thimble act label-undelete`); a refusal says why in red
  const gone = labelGone && !ls.some(x => x.id === labelGone!.id) ? labelGone : null
  const undo = gone && !gone.error ? () => void undeleteLabel(cx, gone.id, gone.name) : null
  // a list read and empty: its entry box takes the ring as the view opens (term.ts giveKeys), but where it offers to
  // undo a delete, whose `u` the box would take
  const empty = Boolean(got?.ok) && !ls.length && e.surface !== 'mobile' && !undo
  if (empty) startRingDrawing = NEW_LABEL
  // each label as home draws it (home.ts labelBlocks): its name row, its bar in the column every bar takes, its total,
  // then its legend, each value with its count, then the records it is unsure of and those no category fit; those
  // records are in its panel, a press away (SPEC-v2 J6)
  const blocks = labelBlocks(await homeLabels(cx, ls), cols, LIST_LEGEND_ROWS)
  const lines: Line[] = []
  const hits: LineHit[] = []
  let pickAt = -1
  ls.forEach((l, i) => {
    const b = blocks[i]!
    // a blank row between labels, which have the room here that home leaves to its other sections
    if (i) lines.push([])
    if (l.id === pick) pickAt = lines.length
    for (const [k, line] of [b.name, ...b.legend].entries()) {
      hits.push({ y: lines.length, x0: MARGIN_W, x1: cols + MARGIN_W, row: true, run: () => openLabel(cx, l.id, l.name ?? l.id) })
      lines.push(pointed(line, k === 0 && l.id === pick && !boxHeld))
    }
  })
  if (!ls.length) lines.push(pointed([{ s: '  ' }, dim('none')], false))
  // under the list, an entry box (entry.tsx) whose words go to main, which makes the label with a trial; ↓ past the last
  // label or a click gives it the keys
  const entry =
    e.surface === 'mobile'
      ? null
      : entryEl(cx, e, { key: fieldKey(NEW_LABEL), placeholder: 'describe a new label', submit: 'make it', cols, held: boxHeld || (empty && !rt.panelFocus && panelHasKeys()), ...(empty ? { autoFocus: true } : {}), onSubmit: v => void cx.submit(`Make a label with apply_label and try it on a sample of 30: ${v}`) })
  const step = (d: number) => {
    const at = ls.findIndex(x => x.id === pick)
    if (d > 0 && at >= ls.length - 1) return entry ? ringOnto(cx, NEW_LABEL) : undefined
    labelPick = ls[Math.max(0, Math.min(ls.length - 1, at + d))]?.id ?? ''
    return cx.bumpPanel()
  }
  const goneRow = gone ? (
    gone.error ? (
      <Text key="lbs-gone" color={COLORS.problem} wrap="wrap">{`× the label "${gone.name}" was not restored: ${gone.error}`}</Text>
    ) : (
      <Box key="lbs-gone" flexDirection="row">
        <Text dimColor>{`deleted the label "${gone.name}"  `}</Text>
        <Button key="lbs-undo" label="undo" plain onPress={undo!} />
      </Box>
    )
  ) : null
  const listHints = [...(ls.length ? ['↑↓ to choose', 'Enter to open'] : []), ...(undo ? ['u to undo'] : []), 'b to go back', 'x to close']
  // the title row, the header, the entry box (else the rule under the list), the undo row and the blank row above it,
  // and the hint rows aside
  const bottom = entry ? entryHeight(NEW_LABEL, cols, true, 'make it') + (goneRow ? 2 : 0) : 1 + (goneRow ? 1 : 0)
  const win = windowList('labels-list', lines, hits, pickAt, bodyRows - 1 - bottom - hintHeight(listHints, cols) - body.length, () => cx.bumpPanel())
  const listKeys = (k: string) => (k === 'up' || k === 'k' ? step(-1) : k === 'down' || k === 'j' ? step(1) : (k === 'return' || k === 'enter') && pick ? openLabel(cx, pick, ls.find(x => x.id === pick)?.name ?? pick) : undefined)
  body.push(linesEl(cx, e, marginKey('labels-list'), win.lines, win.hits, cols + MARGIN_W, ls.length ? listKeys : undefined))
  body.unshift(
    <Box key="label-presses" width={0} height={0} flexShrink={0} overflow="hidden" flexDirection="row">
      {ls.map((l, i) => {
        const go = () => void openLabel(cx, l.id, l.name ?? l.id)
        return <Button key={`label-open-${i}`} label={l.name ?? l.id} plain {...hotkeyOf(cx, i < 9 ? String(i + 1) : null, go)} />
      })}
    </Box>,
  )
  body.push(...entryBottom(cx, e, cols, [], entry, listHints, goneRow ? [goneRow] : [], empty ? NEW_LABEL : ''))
  const hk = undo ? hiddenKeys(cx, e, [{ key: 'undo', hotkey: 'u', onPress: undo }]) : null
  return <Box flexDirection="column">{[...(hk ? [hk] : []), ...body]}</Box>
}

// ------------------------------------------------------------------------------------------------ documents

// the documents list's chosen row
let docPick = ''

/** The documents (SPEC.md, section 7, "Documents"): one row per document, ◌ while its writer writes, ● written,
 *  its title, its kind dim at R; `❯` on the chosen row, ↑↓ or j k choose, Enter or a click opens it, 1-9 the first
 *  nine; at most 40. */
async function drawDocs(cx: Ctx, e: PaneEvent): Promise<RenderElement> {
  const els = cx.els(e) as El
  const { Box, Button } = cx.els(e)
  const cols = Math.max(30, e.props.bodyColumns)
  const got = await surfaceValue(cx, 'docs')
  const docs = (got?.ok ? docsOf(got.value) : []).sort((a, b) => (Date.parse(b.at) || 0) - (Date.parse(a.at) || 0)).slice(0, 40)
  const body: RenderElement[] = [...headerEls(els, { title: 'Documents', cols, sub: subLine([plural(docs.length, 'document')]) })]
  const pick = docs.find(d => d.slug === docPick)?.slug ?? docs[0]?.slug ?? ''
  if (pick) setBrowser(`report:${pick}`)
  const open = (d: (typeof docs)[number]) => openDoc(cx, d.slug, d.title)
  const { lines, hits } = listLines(
    docs.map(d => ({ key: d.slug, glyph: { s: d.status === 'generating' ? '◌' : '●' }, name: d.title, right: [dim(d.status === 'generating' ? `${d.renderer} · writing` : d.renderer)], run: () => open(d) })),
    pick,
    cols,
  )
  const step = (k: number) => {
    const at = docs.findIndex(d => d.slug === pick)
    docPick = docs[Math.max(0, Math.min(docs.length - 1, at + k))]?.slug ?? ''
    return cx.bumpPanel()
  }
  const listHints = docs.length ? ['↑↓ to choose', 'Enter to open'] : []
  const win = windowList('docs-list', lines, hits, docs.findIndex(d => d.slug === pick), bodyRows - 1 - hintHeight(listHints, cols) - body.length, () => cx.bumpPanel())
  body.push(linesEl(cx, e, marginKey('docs-list'), win.lines, win.hits, cols + MARGIN_W, k => (k === 'up' || k === 'k' ? step(-1) : k === 'down' || k === 'j' ? step(1) : (k === 'return' || k === 'enter') && pick ? open(docs.find(d => d.slug === pick)!) : undefined)))
  body.unshift(
    <Box key="doc-presses" width={0} height={0} flexShrink={0} overflow="hidden" flexDirection="row">
      {docs.map((d, i) => (
        <Button key={`doc-open-${i}`} label={d.title} plain {...hotkeyOf(cx, i < 9 ? String(i + 1) : null, () => void open(d))} />
      ))}
    </Box>,
  )
  body.push(hintsRow(els, listHints, cols))
  return <Box flexDirection="column">{body}</Box>
}

/** What a document's writer is doing while it writes: its tool calls, its latest words, and the request it was given. */
async function writerState(cx: Ctx): Promise<{ tools: number; words: string; request: string } | null> {
  const a = ((await cx.agents()) ?? []).find(x => x.role === 'writer' && x.state === 'running')
  const tt = a?.chat ? await cx.thread(a.chat) : undefined
  if (!a) return null
  let tools = 0
  let words = ''
  let request = ''
  for (const ev of tt?.events ?? []) {
    if (ev.type === 'user' && !request) request = str(ev.text)
    if (ev.type === 'tool_use') {
      tools++
      words = ''
    } else if (ev.type === 'text') words += str(ev.delta ?? ev.text)
  }
  return { tools, words: words.replace(/\s+/g, ' ').trim(), request: request || str(tt?.meta.title) }
}

/** The mark each figure of a story's beat lights: the rows, events or nodes its step names (story.step_of). */
function stepFocus(s: DocSection): Record<string, Focus> {
  const out: Record<string, Focus> = {}
  for (const f of (s.figures ?? []) as (DocFigure & { highlight?: unknown })[]) {
    const first = Array.isArray(f.highlight) ? str(f.highlight[0]) : ''
    const cell = str(f.cell).replace(/^(?:card|cell):/, '')
    if (cell && first) out[cell] = { row: first, event: first, node: first }
  }
  return out
}

/** One document, read only (SPEC.md, section 7, "A document"; SPEC-v2 3.14): the title in the accent and bold, wrapped;
 *  while its writer writes, `◌ writing · N tool calls · <its latest words>` (and the request until anything is written),
 *  else its comments' facts (`2 open comments · 1 resolved`, `◌ <check> checking` while a check runs on it). A report:
 *  `Contents` from three headings, each a click (or 1-9) away; each section drawn as main's chat draws a reply, its
 *  cards in their frames. A deck or a story steps one slide or beat at a time: `‹ 3 of 9 ›`, `previous  next` (p, n), a
 *  deck's `notes` (t), a story's `read as a page` (a), its figure lit at the beat's step. The comments (report.ts) stand
 *  under the passages they are on, as the browser's margin shows them: ↑↓ choose one (`❯`), r resolves it or opens it
 *  again, Enter or a asks a side thread about it, v shows the resolved ones too. At the bottom `edit in the browser ↗`
 *  (o, and the title row's `↗`: documents are written and edited in the browser workbench), `all documents ›` (l) and
 *  the retell controls, `as slides` (s) and `as a story` (y), which ask main to write it again in that form. A
 *  passage's "?" asks a side thread told the document, its section and the passage. */
async function drawDoc(cx: Ctx, e: PaneEvent, p: TermPanel): Promise<RenderElement> {
  const els = cx.els(e) as El
  const { Box, Text, Button } = cx.els(e)
  const cols = Math.max(30, e.props.bodyColumns)
  const got = await surfaceValue<Obj>(cx, `doc:${p.slug ?? ''}`)
  const listed = await surfaceValue(cx, 'docs')
  const entry = listed?.ok ? docsOf(listed.value).find(d => d.slug === p.slug) : undefined
  const writing = entry?.status === 'generating' ? await writerState(cx) : null
  if (!got && !writing) return none(cx, e, '◌ reading the document')
  if (got && !got.ok && !writing) return <Box flexDirection="column"><Text color={COLORS.problem} wrap="wrap">{`× ${got.error}`}</Text></Box>
  const doc = got?.ok ? got.value : {}
  const title = str(doc.title) || entry?.title || p.title
  const slug = p.slug ?? ''
  const form = str(doc.renderer) || str(doc.type) || entry?.renderer || 'document'
  const { units } = docUnits(doc)
  // the comments as the browser's margin shows them, the resolved ones too when asked
  const checksGot = await surfaceValue(cx, 'checks')
  const checks = checksOf(checksGot?.ok ? checksGot.value : [])
  const all = got?.ok ? commentsOf(doc, checks) : []
  const shown = shownComments(all, resolvedShown(slug))
  const chosen = shown.find(c => c.id === pickOf(slug))
  const checking = checks.filter(c => c.running.includes(slug)).map(c => `◌ ${c.name} checking`)
  const sub = writing ? subLine([`◌ writing · ${plural(writing.tools, 'tool call')}${writing.words ? ` · ${clip(writing.words, Math.max(20, cols - 30))}` : ''}`]) : all.length || checking.length ? subLine([...commentFacts(all), ...checking]) : undefined
  const body: RenderElement[] = [...headerEls(els, { title, cols, ...(sub ? { sub } : {}) })]
  if (writing && !units.length && writing.request) body.push(<Text key="doc-request" dimColor wrap="wrap">{`the request: ${clip(writing.request, 600)}`}</Text>)
  const keys: Key[] = []
  // a slide, a beat or a section chosen in place: back leads where the document was opened from
  const at = (k: number) => openPanel(cx, { ...p, start: k }, { replace: true })
  // a passage's thread is told the document, its section and the passage
  const askIn = (u: DocSection) => (tgt: Target) =>
    void openAsk(cx, tgt, tgt.kind === 'sentence' ? { anchor: `report:${slug}${u.id ? `#${u.id}` : ''}`, anchorText: `${quoted(title)} › ${plainCites(str(u.heading))}: ${plainCites(tgt.text ?? '')}`, element: `report:${slug}${u.id ? `#${u.id}` : ''}` } : { element: `report:${slug}${u.id ? `#${u.id}` : ''}` })
  // a block of comments under their passage: a click on one chooses it, a click on one of its chips opens the place
  const blockKey = (key: string) => marginKey(`doc-cm-${key}`)
  const commentBlock = (list: readonly DocComment[], key: string): RenderElement => {
    const lines: Line[] = []
    const hits: LineHit[] = []
    for (const c of list) {
      const { lines: ls, chips } = commentLines(c, c.id === chosen?.id, cols)
      const y0 = lines.length
      ls.forEach((_l, k) => hits.push({ y: y0 + k, x0: 0, x1: cols + MARGIN_W, row: true, run: () => choose(c, false) }))
      for (const ch of chips) hits.unshift({ y: y0 + ch.y, x0: ch.x0, x1: ch.x1, row: false, run: () => openCite(cx, ch.ref, null) })
      lines.push(...ls)
    }
    return linesEl(cx, e, blockKey(key), lines, hits, cols + MARGIN_W)
  }
  const drawUnit = async (u: DocSection, i: number, focus?: Record<string, Focus>): Promise<RenderElement[]> => {
    const out: RenderElement[] = []
    for (const [k, part] of unitParts(u, shown).entries()) {
      if (part.md.trim()) {
        const rows = await drawReply(cx, e, part.md, cols, { margin: PANEL_MARGIN, prefix: k ? `d${i}.${k}-` : `d${i}-`, ask: askIn(u), open: id => void openThread(cx, id), in: 'report', ...(focus ? { focus } : {}) })
        // a blank row between a passage's comments and the words after them; a card's border stands in for one
        out.push(k && !part.md.startsWith('[[card:') ? <Box key={`doc-part-${i}-${k}`} flexDirection="column" marginTop={1}>{rows}</Box> : <Box key={`doc-part-${i}-${k}`} flexDirection="column">{rows}</Box>)
      }
      if (part.after.length) out.push(commentBlock(part.after, `${i}-${k}`))
    }
    return out
  }
  const stepped = units.length > 0 && (form === 'slides' || (form === 'story' && p.mode !== 'page'))
  // the slide or beat shown, or the section the page starts at
  const current = Math.max(0, Math.min(units.length - 1, p.start ?? 0))
  // a comment chosen by the keys: the slide or section that holds it shown first, then its block scrolled into view
  // once the panel is drawn again (scrollPending; a block's key is its unit's place and the part of it the comment
  // stands under)
  const choose = async (c: DocComment, reveal: boolean) => {
    setPick(slug, c.id)
    const u = unitOf(doc, c.sid)
    const part = u >= 0 ? unitParts(units[u]!, shown).findIndex(x => x.after.some(y => y.id === c.id)) : 0
    if (reveal) docScrollKey = blockKey(u >= 0 ? `${u}-${part}` : 'title')
    if (reveal && u >= 0 && ((stepped && u !== current) || (!stepped && u < current))) await at(u)
    else await cx.bumpPanel()
  }
  const controls: (RenderElement | null)[] = []
  const hints: string[] = []
  // the comments on the title, under the header
  const onTitle = shown.filter(c => c.sid === TITLE_ID)
  if (onTitle.length) body.push(commentBlock(onTitle, 'title'))
  if (stepped) {
    const i = current
    const u = units[i]!
    body.push(<Box key={marginKey(`doc-unit-${i}`)} flexDirection="column">{await drawUnit(u, i, form === 'story' ? stepFocus(u) : undefined)}</Box>)
    const notes = str((u as { notes?: unknown }).notes)
    if (form === 'slides' && notes && p.mode === 'notes') body.push(<Box key="doc-notes" flexDirection="column" marginTop={1}><Text bold>Notes</Text><Text wrap="wrap">{notes}</Text></Box>)
    // the page row: ‹ and › a click away (p and n are its keys)
    const pageWords = `${i + 1} of ${units.length}`
    const pageLine: Line = [{ s: '‹', fg: i > 0 ? LINK : COLORS.dim }, { s: `  ${pageWords}  ` }, { s: '›', fg: i < units.length - 1 ? LINK : COLORS.dim }]
    const prev = () => (i > 0 ? at(i - 1) : undefined)
    const next = () => (i < units.length - 1 ? at(i + 1) : undefined)
    body.push(<Box key="doc-page" marginTop={1}>{linesEl(cx, e, 'doc-page', [pageLine], [{ y: 0, x0: 0, x1: 1, row: false, run: prev }, { y: 0, x0: width(pageWords) + 5, x1: width(pageWords) + 6, row: false, run: next }], cols)}</Box>)
    controls.push(i > 0 ? <Button key="doc-prev" label="previous" plain onPress={() => void prev()} /> : null, i < units.length - 1 ? <Button key="doc-next" label="next" plain onPress={() => void next()} /> : null)
    keys.push({ key: 'prev', hotkey: 'p', onPress: () => void prev() }, { key: 'next', hotkey: 'n', onPress: () => void next() })
    hints.push('p n to step')
    if (form === 'slides' && units.some(x => str((x as { notes?: unknown }).notes))) {
      const flip = () => void openPanel(cx, { ...p, mode: p.mode === 'notes' ? '' : 'notes' }, { replace: true })
      controls.push(<Button key="doc-notes-flip" label={p.mode === 'notes' ? 'hide notes' : 'notes'} plain onPress={flip} />)
      keys.push({ key: 'notes', hotkey: 't', onPress: flip })
      hints.push('t for notes')
    }
    if (form === 'story') {
      const page = () => void openPanel(cx, { ...p, mode: 'page', start: 0 }, { replace: true })
      controls.push(<Button key="doc-page-read" label="read as a page" plain onPress={page} />)
      keys.push({ key: 'page', hotkey: 'a', onPress: page })
      hints.push('a for the page')
    }
  } else {
    const from = current
    // the contents from three headings: each heading a click away (and 1-9), drawing the document from there; a section
    // with no heading (an opening summary) is not listed
    const headed = units.map((u, i) => ({ u, i })).filter(x => plainCites(str(x.u.heading)).trim())
    if (headed.length >= 3) {
      body.push(<Text key="doc-contents" bold>Contents</Text>)
      const shownToc = headed.slice(0, 24)
      const w = String(shownToc.length).length
      const lines: Line[] = shownToc.map((x, k) => [dim(`${String(k + 1).padStart(w)}  `), { s: plainCites(str(x.u.heading)), ...(x.i === from && from > 0 ? { fg: ACCENT } : {}) }])
      body.push(linesEl(cx, e, 'doc-toc', lines, shownToc.map((x, k) => ({ y: k, x0: 0, x1: cols, row: true, run: () => at(x.i) })), cols))
      shownToc.slice(0, 9).forEach((x, k) => keys.push({ key: `sec${k}`, hotkey: String(k + 1), onPress: () => void at(x.i) }))
      hints.push('1-9 for a section')
    }
    for (const [i, u] of units.entries()) {
      if (i < from) continue
      // one blank row between sections, and between the contents and the first; none above a first section under the
      // header's rule
      const top = i === from && headed.length < 3 && !onTitle.length ? 0 : 1
      body.push(<Box key={marginKey(`doc-sec-${i}`)} flexDirection="column" marginTop={top}>{await drawUnit(u, i)}</Box>)
    }
  }
  // the comments' keys: ↑↓ choose one (the list's keys, through the relay), r resolves or reopens the chosen one, Enter
  // or a asks about it, v shows or hides the resolved ones
  const story = stepped && form === 'story'
  if (shown.length && !writing) {
    setListKeys(k => {
      if (k === 'up' || k === 'k' || k === 'down' || k === 'j') {
        const to = stepPick(shown, chosen?.id ?? '', k === 'up' || k === 'k' ? -1 : 1)
        return to ? choose(to, true) : undefined
      }
      if ((k === 'return' || k === 'enter') && chosen) return focusEntry()
    })
    hints.push('↑↓ to choose a comment')
  }
  // the chosen comment's entry box (entry.tsx), whose question starts a side thread about the comment on its passage
  let askBox: RenderElement | null = null
  const entryKey = chosen ? `ask-cm-${cid(`${slug}:${chosen.id}`)}` : ''
  const focusEntry = async () => {
    if (!askBox || !(await cx.focus(entryKey))) return
    rt.panelFocus = entryKey
    await cx.bumpPanel()
  }
  if (chosen && !writing) {
    const flip = () => void resolveComment(cx, slug, chosen, shown)
    if (!chosen.tag) {
      controls.unshift(<Button key="doc-cm-resolve" label={chosen.open ? 'resolve' : 'reopen'} plain onPress={flip} />)
      keys.push({ key: 'resolve', hotkey: 'r', onPress: flip })
      hints.push(chosen.open ? 'r to resolve' : 'r to reopen')
    }
    if (e.surface !== 'mobile') {
      askBox = askEntry(cx, e, { key: entryKey, placeholder: 'ask about this comment', cols, ...commentAsk(doc, slug, chosen) })
      if (!story) keys.push({ key: 'cm-ask', hotkey: 'a', onPress: () => void focusEntry() })
      hints.push(story ? 'Enter to ask' : 'Enter or a to ask')
    }
  }
  const resolvedN = all.filter(c => !c.open).length
  if (resolvedN && !writing) {
    const flip = () => {
      flipResolved(slug)
      if (chosen && !chosen.open) setPick(slug, '')
      void cx.bumpPanel()
    }
    controls.push(<Button key="doc-cm-resolved" label={resolvedShown(slug) ? 'hide resolved' : `show resolved (${num(resolvedN)})`} plain onPress={flip} />)
    keys.push({ key: 'cm-resolved', hotkey: 'v', onPress: flip })
    hints.push(resolvedShown(slug) ? 'v to hide resolved' : 'v to show resolved')
  }
  // the terminal reads documents only: they are written and edited in the browser workbench (SPEC-v2 3.14), which `↗`
  // and `o` open on the document
  if (got?.ok && !writing) {
    controls.push(<Button key="doc-browser" label="edit in the browser ↗" plain onPress={() => void openInBrowser(cx, `report:${slug}`)} />)
    hints.push('o to edit in the browser')
  }
  // retell: main writes the document again in another form (thimble's writer)
  const retell = (to: 'slides' | 'story') => () => void cx.command('thimble:write', `${to} Retell the document "${title}" as ${to === 'slides' ? 'slides' : 'a story'}.`).catch(err => cx.toast(`could not start the writer: ${String(err).slice(0, 200)}`))
  if (units.length && !writing) {
    // each key with what it retells the document as, as the label panel's hint names what each key opens
    const forms: string[] = []
    if (form !== 'slides') {
      controls.push(<Button key="doc-as-slides" label="as slides" plain onPress={retell('slides')} />)
      keys.push({ key: 'slides', hotkey: 's', onPress: retell('slides') })
      forms.push('s slides')
    }
    if (form !== 'story') {
      controls.push(<Button key="doc-as-story" label="as a story" plain onPress={retell('story')} />)
      keys.push({ key: 'story', hotkey: 'y', onPress: retell('story') })
      forms.push('y story')
    }
    hints.push(forms.join(', '))
  }
  // the documents list with this document chosen (live check term-fix10, new quirk 8: it chose the other document)
  const allDocs = () => {
    docPick = p.slug ?? docPick
    void openList(cx, { view: 'docs', title: 'Documents' })
  }
  controls.push(<Button key="doc-all" label="all documents ›" plain onPress={allDocs} />)
  keys.push({ key: 'all', hotkey: 'l', onPress: allDocs })
  hints.push('l for all documents')
  const said = docSaid.get(slug)
  const saidEl = said ? [<Text key="doc-said" color={COLORS.problem} wrap="wrap">{`! ${said}`}</Text>] : []
  body.push(...(askBox ? entryBottom(cx, e, cols, controls, askBox, hints, saidEl) : bottomRows(cx, e, cols, controls, saidEl, hints)))
  const hk = hiddenKeys(cx, e, keys)
  return <Box flexDirection="column">{[...(hk ? [hk] : []), ...body]}</Box>
}

// why the last change of a document's comments did not go through, by its slug (shown red at the panel's bottom)
const docSaid = new Map<string, string>()

// the block of a document's comments the keys chose last, which the pane scrolls into view (scrollPending)
let docScrollKey = ''

/** After a key the list's relay passed on (register.tsx, with the hook's own context): the comment block it chose
 *  scrolled into the pane's view, once the panel is drawn again. */
export function scrollPending(cx: Ctx): void {
  if (!docScrollKey) return
  const key = docScrollKey
  docScrollKey = ''
  cx.later(60, () => void cx.scroll(key, 'center'))
}

/** A comment resolved (the margin's ✓) or opened again (`thimble act comment-resolve | comment-reopen`); the document
 *  read again. A comment resolved while the resolved ones are hidden leaves the choice on the next one shown. */
async function resolveComment(cx: Ctx, slug: string, c: DocComment, shown: readonly DocComment[]): Promise<void> {
  if (!rt.sc) return
  const why = await setComment(cx, rt.sc, slug, c)
  if (why) docSaid.set(slug, why)
  else docSaid.delete(slug)
  if (!why && c.open && !resolvedShown(slug)) {
    const at = shown.findIndex(x => x.id === c.id)
    setPick(slug, (shown[at + 1] ?? shown[at - 1])?.id ?? '')
  }
  await readDoc(cx, slug)
  await cx.bumpPanel()
}

/** What a side thread about a comment is told, as the browser's comment card's reply starts one: on the comment's
 *  passage, told the passage's words and the comment. */
function commentAsk(doc: Obj, slug: string, c: DocComment): { target: Target; over: AskOver } {
  const words = passageWords(doc, c.sid)
  const anchor = `report:${slug}#${c.sid}`
  return { target: { kind: 'sentence', text: words }, over: { anchor, anchorText: `${words}\n\n${commentWho(c)}: ${c.text}`, element: anchor, about: `comment ${quoted(clip(c.text, 50))}` } }
}

// ------------------------------------------------------------------------------------------------ agents and views

/** The states of an agent's run that ended: nothing to stop. */
const ENDED = new Set(['done', 'failed', 'stopped', 'error'])
// the agents' chats whose raw error the panel shows (`details`), by chat
const agentDetails = new Set<string>()

/** A failed run's raw error in a line of plain words, without its request and message ids: Claude's safeguards by name,
 *  else the error's first sentence. */
export function plainFailure(raw: string): string {
  const t = raw.replace(/\s+/g, ' ').trim()
  if (/safeguard|refus/i.test(t)) return "Claude's safeguards stopped its request."
  const head = t.split(/\b(?:Request ID|Message ID|Details):/)[0]!.trim()
  const first = /^.*?[.!?](?=\s|$)/.exec(head)?.[0] ?? head
  return clip(first || 'it failed', 160)
}

/** The words that add the analyst's focus to an orientation's brief. */
const FOCUS_WORDS = 'Narrower focus for this run:'

/** The brief of an orientation run again: its last run's brief with the focus typed added, an earlier focus replaced, so
 *  the analyst's question stays (bug hunt E11); the focus alone when the last run had no brief; the last brief when no
 *  focus is typed. */
export function focusedBrief(last: string, focus: string): string {
  const f = focus.trim()
  if (!f) return last.trim()
  const q = last.split(FOCUS_WORDS)[0]!.trim()
  if (!q) return f
  return `${/[.!?…:;]$/.test(q) ? q : `${q}.`} ${FOCUS_WORDS} ${f}`
}

/** The orientation started again by main (`start_orientation`), as the analyst asks it from the panel or its notice:
 *  with the request its last run had (its chat's `brief`, read when not read yet) and the focus they typed added. */
export async function orientAgain(cx: Ctx, focus: string, chat: string): Promise<void> {
  let last = ''
  if (chat) {
    const tt = (await cx.thread(chat)) ?? (rt.sc ? await readThreadMeta(cx, chat) : undefined)
    last = str(tt?.meta?.brief)
  }
  const brief = focusedBrief(last, focus)
  // the panel on this run shows the new one once it is listed (term.ts followRerun): a run listed now is not it
  if (chat) rt.rerun = { chat, known: [chat, ...(await cx.agents()).filter(a => ORIENT_ROLES.has(a.role) && a.chat).map(a => a.chat)] }
  await cx.submit(brief ? `Run the orientation again: call start_orientation with this brief, word for word: "${brief}".` : 'Run the orientation again: call start_orientation with no brief.')
  cx.toast('main was asked to start the orientation again')
  await cx.bumpPanel()
}

/** A chat's meta when no drawing read it yet. */
async function readThreadMeta(cx: Ctx, chat: string): Promise<TermThread | undefined> {
  await readThread(cx, chat)
  return cx.thread(chat)
}

async function drawAgent(cx: Ctx, e: PaneEvent, p: TermPanel): Promise<RenderElement> {
  const els = cx.els(e) as El
  const { Box, Text, Button } = cx.els(e)
  const cols = Math.max(30, e.props.bodyColumns)
  const agents = (await cx.agents()) ?? []
  // by its thread when the panel names one: a role's earlier run that ended (done) has the same name, and is listed first
  const a = p.thread ? agents.find(x => x.chat === p.thread) : agents.find(x => x.name === p.agent)
  const tt: TermThread | undefined = p.thread ? await cx.thread(p.thread) : undefined
  const meta = tt?.meta ?? {}
  const state = a ? a.state : str(meta.status) || 'done'
  const failed = state === 'failed' || state === 'error'
  const chat = a?.chat || p.thread || ''
  const body: RenderElement[] = [...headerEls(els, { title: a?.label ?? (str(meta.title) || p.title), cols, sub: subLine([state]) })]
  const steps: string[] = []
  let text = ''
  // a failed run's error as Claude Code gave it (request and message ids and all), and the failure in plain words (the
  // notice thimble wrote into its chat): the words show, the raw error only under `details` (bug hunt C18)
  let raw = ''
  let why = ''
  for (const ev of tt?.events ?? []) {
    if (ev.type === 'tool_use') {
      steps.push(await scrubIds(cx, stepWords(str(ev.name), ev.input)))
      text = ''
    } else if (ev.type === 'text' && ev.api_error) raw = str(ev.delta ?? ev.text)
    else if (ev.type === 'text') text += str(ev.delta ?? ev.text)
    else if (ev.type === 'done' && ev.result) {
      if (failed) raw = str(ev.result)
      else text = str(ev.result)
    } else if (ev.type === 'error' && ev.message) raw = raw || str(ev.message)
    else if (ev.type === 'notice' && str(ev.key).startsWith('agent:') && ev.text) why = str(ev.text)
  }
  if (failed && !raw) raw = str(meta.result)
  if (!(tt?.events ?? []).length) body.push(<Text key="agent-none" dimColor>{tt ? 'nothing yet' : '◌ reading its chat'}</Text>)
  if (steps.length) {
    body.push(<Text key="agent-steps"><Text bold>Steps</Text><Text dimColor>{` (${num(steps.length)})`}</Text></Text>)
    steps.slice(-12).forEach((s, i) => body.push(<Text key={`agent-step-${i}`} dimColor wrap="truncate-end">{cut(`  ${s}`, cols)}</Text>))
  }
  if (text.trim()) body.push(<Box key={marginKey('agent-text')} flexDirection="column" marginTop={steps.length ? 1 : 0}>{await drawReply(cx, e, text.trim(), cols, { margin: PANEL_MARGIN, prefix: 'agent-' })}</Box>)
  const details = agentDetails.has(chat)
  const toggle = () => {
    if (agentDetails.has(chat)) agentDetails.delete(chat)
    else agentDetails.add(chat)
    void cx.bumpPanel()
  }
  if (failed) {
    body.push(
      <Box key="agent-failed" flexDirection="column" marginTop={steps.length || text.trim() ? 1 : 0}>
        <Text color={COLORS.problem} wrap="wrap">{`× ${why || plainFailure(raw)}`}</Text>
        {raw && details ? <Text key="agent-raw" dimColor wrap="wrap">{raw.trim()}</Text> : null}
      </Box>,
    )
  }
  // `stop` only while the run goes on; an orientation that failed or was stopped runs again, with a focus if one is typed
  // a stop that did not stop says why (the chat that follows a label's run stops that run: bug hunt I1)
  const stop = a && rt.sc && !ENDED.has(state)
    ? () => void act<{ stopped?: boolean; reason?: string }>(cx, rt.sc!, 'stop', { agent: a.chat || a.name, name: a.name }).then(r => (!r.ok ? cx.toast(`not stopped: ${r.error}`) : r.value.stopped === false ? cx.toast(`not stopped: ${r.value.reason || 'it was not running'}`) : undefined))
    : null
  const orient = ORIENT_ROLES.has(a?.role || str(meta.role) || str(meta.key))
  const again = orient && (failed || state === 'stopped') && rt.sc ? () => void orientAgain(cx, '', chat) : null
  // once main is asked to run it again, until the new run shows here in its place (term.ts followRerun): a line says so,
  // and the focus box is gone, so the keys are the panel's again (bug hunt E13: the box kept them for 15 minutes, and
  // `x` and a later `/exit` went into it); `run again` stays, should main not start it
  const asked = Boolean(again && chat && rt.rerun?.chat === chat)
  if (asked) body.push(<Text key="agent-asked" dimColor wrap="wrap">{`${SPIN} main was asked to run it again; the new run shows here once it starts`}</Text>)
  const focusKey = `make-orient-again-${chat}`
  const entry = again && !asked && e.surface !== 'mobile' ? entryEl(cx, e, { key: fieldKey(focusKey), placeholder: 'run it again with a narrower focus', submit: 'run again', cols, onSubmit: v => void orientAgain(cx, v, chat) }) : null
  const controls = [
    again ? <Button key="agent-again" label="run again" plain onPress={again} /> : null,
    failed && raw ? <Button key="agent-details" label={details ? 'hide details' : 'details'} plain onPress={toggle} /> : null,
    stop ? <Button key="agent-stop" label="stop" plain onPress={stop} /> : null,
  ]
  const keys: Key[] = [
    ...(again ? [{ key: 'again', hotkey: 'r', onPress: again }] : []),
    ...(entry ? [{ key: 'focus', hotkey: 'f', onPress: () => void ringOnto(cx, focusKey) }] : []),
    ...(failed && raw ? [{ key: 'details', hotkey: 'd', onPress: toggle }] : []),
    ...(stop ? [{ key: 'stop', hotkey: 's', onPress: stop }] : []),
  ]
  const hints = [...(again ? ['r to run again'] : []), ...(entry ? ['f for a focus'] : []), ...(failed && raw ? [details ? 'd to hide details' : 'd for details'] : []), ...(stop ? ['s to stop'] : []), 'b to go back', 'x to close']
  body.push(...entryBottom(cx, e, cols, controls, entry, hints))
  const hk = keys.length ? hiddenKeys(cx, e, keys) : null
  return <Box flexDirection="column">{[...(hk ? [hk] : []), ...body]}</Box>
}

// the views list's chosen row
let viewPick = ''

/** The views pane (SPEC.md, section 7, "The views pane"): `N views · N built`; one row per view, newest first, its glyph
 *  (● built, ◌ building, ○ proposed, × failed in red) and its name, the files it claims dim at R and `new` in green
 *  until a built one is opened (no word that repeats the glyph); `❯` on the chosen row, ↑↓ or j k choose, Enter or a
 *  click opens it, 1-9 the first nine. */
async function drawViews(cx: Ctx, e: PaneEvent): Promise<RenderElement> {
  const els = cx.els(e) as El
  const cols = Math.max(30, e.props.bodyColumns)
  const vs = (await homeViews(cx)).sort((a, b) => b.at - a.at)
  const { Box, Button } = cx.els(e)
  const built = vs.filter(v => v.state === 'built').length
  const body: RenderElement[] = [...headerEls(els, { title: 'Views', cols, sub: subLine([plural(vs.length, 'view'), built ? `${num(built)} built` : '']) })]
  const glyph = (v: HomeView): Seg => (v.state === 'built' ? { s: '●' } : v.state === 'building' ? { s: '◌' } : v.state === 'failed' ? { s: '×', fg: COLORS.problem } : dim('○'))
  const pick = vs.find(v => v.slug === viewPick)?.slug ?? vs[0]?.slug ?? ''
  const open = (v: HomeView) => openView(cx, v.slug, v.name)
  const { lines, hits } = listLines(
    vs.map(v => ({ key: v.slug, glyph: glyph(v), name: v.name, right: [...(v.files.length ? [dim(v.files.join(', '))] : []), ...(v.fresh ? [{ s: '  ' }, freshSeg()] : [])], run: () => open(v) })),
    pick,
    cols,
  )
  const step = (d: number) => {
    const at = vs.findIndex(v => v.slug === pick)
    viewPick = vs[Math.max(0, Math.min(vs.length - 1, at + d))]?.slug ?? ''
    return cx.bumpPanel()
  }
  const listHints = vs.length ? ['↑↓ to choose', 'Enter to open'] : []
  const win = windowList('views-list', lines, hits, vs.findIndex(v => v.slug === pick), bodyRows - 1 - hintHeight(listHints, cols) - body.length, () => cx.bumpPanel())
  body.push(linesEl(cx, e, marginKey('views-list'), win.lines, win.hits, cols + MARGIN_W, k => (k === 'up' || k === 'k' ? step(-1) : k === 'down' || k === 'j' ? step(1) : (k === 'return' || k === 'enter') && pick ? open(vs.find(v => v.slug === pick)!) : undefined)))
  // each view a press away by its key too, for a surface that draws no Client: no row of its own
  body.unshift(
    <Box key="view-presses" width={0} height={0} flexShrink={0} overflow="hidden" flexDirection="row">
      {vs.map((v, i) => (
        <Button key={`view-open-${i}`} label={v.name} plain onPress={() => void open(v)} />
      ))}
    </Box>,
  )
  body.push(hintsRow(els, listHints, cols))
  const hk = hiddenKeys(cx, e, vs.slice(0, 9).map((v, i) => ({ key: `v${i}`, hotkey: String(i + 1), onPress: () => void open(v) })))
  return <Box flexDirection="column">{[...(hk ? [hk] : []), ...body]}</Box>
}

// the rows of a view's panel that are not the view's own: the title row, the rule and the hint row
const VIEW_CHROME = 3
// the panel's own keys, which a view never takes (term_kit/kit.mjs PANEL_KEYS): back, the threads, close
const PANEL_KEYS = ['b', 't', 'x']

// what thimble answered this open's ask for the terminal page of a view built for the browser, by the view's slug: null
// while it asks or once it builds; `why` when it is not built, with the fix, `failed` when Retry is the fix
const pageAsks = new Map<string, { why: string; failed: boolean } | null>()

/** Each open of a view built for the browser (the panel's load of it, term.ts loadPanel; a drawing writes nothing):
 *  thimble asked to build its terminal page (`thimble act view-term-page`), as the browser's first open of a
 *  terminal-built view builds that view's page (views.page_ask, ensure_page), unless home's row says it builds or failed. */
async function askTermPage(cx: Ctx, p: TermPanel): Promise<void> {
  const slug = p.slug ?? ''
  const find = async () => (await homeViews(cx)).find(x => x.slug === slug)
  // a view opened before home was read (open_view in a new session): home read first
  const v = (await find()) ?? (await readSurface(cx, 'home-full', 'home'), await find())
  const sc = rt.sc
  if (!v || v.term || v.state !== 'built' || (v.page && v.page !== 'missing') || !sc) return
  pageAsks.set(slug, null)
  const got = await act<{ queued?: boolean; reason?: string; failed?: boolean }>(cx, sc, 'view-term-page', { slug })
  pageAsks.set(slug, !got.ok ? { why: `thimble did not start the build of its terminal page: ${got.error}`, failed: false } : got.value.queued === false && got.value.reason ? { why: got.value.reason, failed: got.value.failed === true } : null)
  await cx.bumpPanel()
}

/** Where the terminal page of a view built for the browser stands, as the panel says it: why it is not built, with the
 *  fix (home's row: its build failed, or thimble has none for it; or thimble's answer to this open's ask), else `why`
 *  empty while it builds. */
function termPage(v: HomeView): { why: string; failed: boolean } {
  if (v.page === 'failed') return { why: `The build of its terminal page failed${v.pageWhy ? `: ${v.pageWhy.replace(/\.$/, '')}` : ''}. r builds it again.`, failed: true }
  if (v.page === 'none') return { why: v.pageWhy || 'thimble has no terminal page for this view.', failed: false }
  return (v.page !== 'building' && pageAsks.get(v.slug)) || { why: '', failed: false }
}

/** `r` on a terminal page whose build failed: the view built again with that change (`thimble act view-retry`). */
async function retryPage(cx: Ctx, v: HomeView): Promise<void> {
  if (!rt.sc) return
  const got = await act<{ queued?: boolean; reason?: string }>(cx, rt.sc, 'view-retry', { slug: v.slug })
  if (!got.ok || got.value.queued === false) {
    cx.toast(got.ok ? got.value.reason || 'it could not start' : got.error)
    return
  }
  pageAsks.delete(v.slug)
  cx.toast('building the terminal page again')
}

/** What the view page says under a frame too large for the panel to draw whole (viewhost.ts viewProps). */
export const VIEW_CUT_REGIONS = 'This page is too large for clicks in the terminal; its keys work. o opens it in the browser.'
export const VIEW_CUT_ROWS = 'This page is too large to draw whole in the terminal. o opens it in the browser.'

/** One view (docs/terminal-views.md): a view with a terminal page is drawn by its program (hooks/viewhost.ts) under
 *  the panel's header, its subtitle the facts the program gives, its hint row the keys it binds; its keys reach it
 *  through the list's relay (↑↓, Enter, Space, Backspace) and as hotkeys (a letter, a digit, a sign), every key while a
 *  field of it takes typing, and its clicks and drags through hooks/viewclient.tsx. A view built from the browser has no
 *  terminal page until its first open here builds one (SPEC-v2 3.13): one line says so while it builds, and `↗` opens the
 *  view in the browser. */
async function drawView(cx: Ctx, e: PaneEvent, p: TermPanel): Promise<RenderElement> {
  const els = cx.els(e) as El
  const { Box, Text, Button, Client } = cx.els(e)
  const cols = Math.max(30, e.props.bodyColumns)
  const slug = p.slug ?? ''
  const v = (await homeViews(cx)).find(x => x.slug === slug)
  if (!v?.term || !rt.sc || (e.surface !== 'terminal' && e.surface !== 'desktop')) {
    const page = v && !v.term && v.state === 'built' ? termPage(v) : null
    const retry = page?.failed ? hiddenKeys(cx, e, [{ key: 'page-retry', hotkey: 'r', onPress: () => void retryPage(cx, v!) }]) : null
    return (
      <Box flexDirection="column">
        {[
          ...(retry ? [retry] : []),
          ...headerEls(els, { title: p.title || slug || 'view', cols, sub: subLine(['view']) }),
          page?.why ? (
            <Text key="view-words" color={COLORS.problem} wrap="wrap">{`× ${page.why}`}</Text>
          ) : (
            <Text key="view-words" wrap="wrap">{page ? 'building the terminal page… The browser draws this view now: o or ↗ opens it there.' : 'The view is not built yet. Its row on home says when it is.'}</Text>
          ),
          ...(page?.why ? [<Text key="view-browser" wrap="wrap">The browser draws this view now: o or ↗ opens it there.</Text>] : []),
          hintsRow(els, [...(page?.failed ? ['r to build it again'] : []), 'o to open it in the browser', 'b to go back', 'x to close'], cols),
        ]}
      </Box>
    )
  }
  const shown = openViewState()
  const sub = shown?.slug === slug && shown.frame?.sub?.length ? shown.frame.sub : []
  // the hint row is one row (fitHints), so the view's rows are those the header and that row leave
  const rows = Math.max(6, (bodyRows || 34) - VIEW_CHROME - (sub.length ? 1 : 0))
  const ov = viewFor(rt.sc, slug, cols, rows, p.ref)
  const f: ViewFrame | null = ov.frame
  // `◌ loading…` against R on the title's row while a reader query of the program is out, so the rows stay put
  const right = f?.loading && f.lines.length ? <Text key="view-loading-r" dimColor>◌ loading…</Text> : null
  const head = headerEls(els, { title: p.title || v.name || slug, cols, right, ...(sub.length ? { sub: subLine(sub) } : {}) })
  const body: RenderElement[] = [...head]
  // the relay is drawn from the first drawing on, while the view opens too, so the open gives it the ring (term.ts
  // giveKeys) and the view's keys work as soon as its frame comes
  setListKeys(() => undefined)
  if (ov.error && !f?.lines?.length) {
    body.push(<Text key="view-error" color={COLORS.problem} wrap="wrap">{`× ${ov.error}`}</Text>)
    body.push(<Button key="view-again" label="open it again" plain onPress={() => { retryView(); void cx.bumpPanel() }} />)
    body.push(hintsRow(els, [], cols))
    return <Box flexDirection="column">{body}</Box>
  }
  if (!f) {
    // from the moment the view opens until its program draws its first frame: the host starting, the program reading
    body.push(<Text key="view-opening" dimColor>◌ starting the view…</Text>)
    body.push(hintsRow(els, [], cols))
    return <Box flexDirection="column">{body}</Box>
  }
  const key = (k: string) => sendEvent(cx, { t: 'key', key: k })
  // the view's keys reach it through the list's relay, which a view always draws: ↑↓, Enter, Space and Backspace, and a
  // sign typed into its field (a Button's hotkey is a letter or a digit)
  setListKeys(k => {
    const name = k === 'enter' ? 'return' : k
    if (f.keys.includes(name)) return key(name)
  })
  // while a field of the view takes typing, the relay's field is that field, holding its text (the view's, when it
  // began; then what the analyst typed, which is what it holds)
  if (!f.typing) viewField = null
  else {
    const text = viewField && viewField.slug === slug ? viewField.text : f.field?.text ?? ''
    viewField = { slug, text, send: t => sendEvent(cx, { t: 'text', value: t }), enter: () => key('return') }
  }
  // a first frame with no rows yet, while its first query is out
  if (!f.lines.length && f.loading) body.push(<Text key="view-loading" dimColor>◌ loading…</Text>)
  // the frame's rows bring their margin (`❯`); they stand under the title row (withWay) and the one row each element
  // above them in `body` takes, the hotkeys taking none (hiddenKeys); a frame its Client could not draw (register.tsx
  // ui.fault) is one dim row saying why, until the view draws another
  viewAtDrawing = { top: 1 + body.length, offset: e.props.scroll?.offset ?? 0, seq: f.seq }
  // its props within what a Client takes, or the engine draws no part of the panel (bug hunt J12): a frame too large
  // leaves out its cells' words first, then its regions, then its last rows, and a dim row says what that costs
  const fault = viewFaultOf(f.seq)
  const fit = viewProps(f, cols + MARGIN_W)
  if (fault) body.push(<Text key="view-fault" dimColor wrap="truncate-end">{`the view could not draw: ${fault}`}</Text>)
  else body.push(<Client key={marginKey('view-frame')} module="./viewclient.tsx" width={cols + MARGIN_W} height={Math.max(1, fit.props.lines.length)} props={JSON.parse(JSON.stringify(fit.props)) as never} />)
  if (!fault && (fit.cut === 'regions' || fit.cut === 'rows')) body.push(<Text key="view-cut" dimColor wrap="truncate-end">{fit.cut === 'rows' ? VIEW_CUT_ROWS : VIEW_CUT_REGIONS}</Text>)
  if (ov.error) body.push(<Text key="view-error" color={COLORS.problem} wrap="truncate-end">{`× ${ov.error}`}</Text>)
  // a sign's key works only from the relay's field, so its hint shows only while the ring rests there
  const isSign = (k: string) => [...k].length === 1 && !/[a-z0-9]/.test(k)
  const hints = f.hints.filter((_, i) => listKeysHeld() || !(f.hintKeys?.[i] ?? []).some(isSign))
  // while a field of the view takes typing every key is the field's, b and x among them: the row says only what Enter
  // and Backspace do there
  if (f.typing) {
    endHints(f.hints)
    body.push(hintsEl(els, paneFocused && !rt.typeThrough ? [...f.hints, 'Esc to leave the field'] : [keysAwayHint()], cols))
  } else body.push(hintsEl(els, fitHints(endHints(hints), cols), cols))
  // the list's Space and Backspace reach the view while it binds them, whether or not its one hint row names them
  listExtraDrawing = { space: f.keys.includes('space'), backspace: f.keys.includes('backspace') }
  // each letter or digit the view binds is a hotkey of the panel, a Button no row tall; a sign is one of the relay's
  // (relayInput finds it among the hotkeys); none while a field of the view takes typing
  const chars = f.typing ? [] : f.keys.filter(k => [...k].length === 1 && !PANEL_KEYS.includes(k))
  for (const c of chars.filter(isSign)) hotkeysDrawing.set(c, () => void key(c))
  const hk = hiddenKeys(cx, e, chars.filter(c => !isSign(c)).map(c => ({ key: `v${c.codePointAt(0)}`, hotkey: c, onPress: () => void key(c) })))
  return <Box flexDirection="column">{[...(hk ? [hk] : []), ...body]}</Box>
}

/** What the view's acts do in the panel: a record's place in the citation panel, a side thread about a row, a label's
 *  panel (views.ts registerPanelViews calls it once). */
export function registerViewActs(): void {
  loadsView('view', askTermPage)
  onViewAct(async (cx, a) => {
    if (a.kind === 'open' && a.ref) return openCite(cx, a.ref, null)
    if (a.kind === 'ask' && a.ref) return openAsk(cx, { kind: 'record', ref: a.ref, text: a.text ?? '' }, { anchor: a.ref, anchorText: a.text ?? '' })
    if (a.kind === 'label' && a.id) return openLabel(cx, a.id, a.name || a.id)
  })
}

// ------------------------------------------------------------------------------------------------ the panel

/** The panel's drawing: the title row, then the view `panel` names, on the panel's grid (a cell of padding at each side,
 *  then the 2-cell margin, then the type area). */
export async function drawPanel(cx: Ctx, pe: PaneEvent): Promise<RenderElement> {
  await cx.panelTick()
  const e = { ...pe, props: { ...pe.props, bodyColumns: Math.max(20, pe.props.bodyColumns - 2 - MARGIN_W) } } as PaneEvent
  const p = (await cx.panel()) ?? { view: 'home', title: 'Home' }
  wayHints = [...(backTarget((await cx.nav()) ?? NAV_EMPTY) !== null ? ['b to go back'] : []), 'x to close']
  // the keys as the pane's props and the engine's record say: a pane either says is without them names none of its keys
  // (an open the engine refused the keys, live check term-fix6, new quirk 4)
  paneFocused = pe.props.isFocused !== false && (await cx.panes()).find(x => x.id === PANEL)?.isFocused !== false
  // typing meant for the prompt goes on while the prompt has the keys: a key the relay's field took before then still
  // goes there (bug hunt D8). It ends once the pane has the keys again after that: the person gave them (a click on the
  // pane, ctrl+x tab)
  if (rt.typeThrough && !paneFocused) rt.typeAway = true
  else if (rt.typeThrough && rt.typeAway) keysBack()
  draftHeld = !paneFocused || rt.typeThrough ? Boolean((await cx.promptText().catch(() => '')).trim()) : false
  bodyRows = pe.props.scroll?.bodyRows || 0
  // the list this drawing draws, read off its drawing (lines.tsx), for the relay in its title row (listKeysEl)
  takeListKeys()
  setHead({})
  setBrowser(null)
  rt.starting = false
  hotkeysDrawing = new Map()
  listExtraDrawing = { space: false, backspace: false }
  fieldsDrawing = new Set()
  startRingDrawing = ''
  windowed = ''
  scrollDrawing = null
  panelField = null
  viewAtDrawing = null
  const body = await (async () => {
    switch (p.view) {
      case 'home':
        return drawHome(cx, e)
      case 'card':
        return drawCard(cx, e, p)
      case 'cite':
        return drawCite(cx, e, p)
      case 'ask':
        return drawAsk(cx, e, p)
      case 'thread':
        return drawThreads(cx, e, p.thread ?? '')
      case 'threads':
        return drawThreads(cx, e)
      case 'label':
        return drawLabel(cx, e, p)
      case 'labels':
        return drawLabels(cx, e)
      case 'docs':
        return drawDocs(cx, e)
      case 'doc':
        return drawDoc(cx, e, p)
      case 'agent':
        return drawAgent(cx, e, p)
      case 'views':
        return drawViews(cx, e)
      case 'view':
        return drawView(cx, e, p)
      default:
        return drawers.get(p.view)?.(cx, e, p) ?? none(cx, e)
    }
  })()
  // a terminal view's program lives while its view shows
  if (p.view !== 'view') {
    closeView()
    viewField = null
  }
  listRelay = takeListKeys()
  // a view with no list, and no field of its own the ring starts on, starts it on its resting place
  if (!listRelay && !startRingDrawing && e.surface !== 'mobile') startRingDrawing = RING_REST
  const tree = await withWay(cx, e, p.view, body)
  hotkeys = hotkeysDrawing
  listExtra = listExtraDrawing
  shownWindow = windowed
  scrollShown = scrollDrawing
  viewAt = viewAtDrawing
  rt.fields = fieldsDrawing
  rt.startRing = startRingDrawing
  return tree
}

