// What Claude's tool calls read of the data files (SPEC-v2 3.9, coverage): facts from the calls of main and its
// subagents, sent once per turn to `thimble act coverage --stdin` (C7), whose answer is the session's coverage summary
// and the line under the turn's answer. Programmatic only: a fact is what a call did to a file, never what a model wrote.
//
// A fact: a file seen whole or in part (its lines, or a PDF's pages), or searched (its contents touched by a search or a
// program without being shown: grep, rg, wc, awk, jq with a filter other than `.`, a script, a database shell, a binary
// Read), or a folder searched by a
// recursive grep or rg. Listing names (ls, find, fd) reads no contents and gives none; neither does an output argument.
// Only data files count (activate.ts isDataFile, the twin of the backend's rule), only paths inside the session folder,
// stored relative to it, and never the command's text. A refused or failed call gives none.
//
// Before thimble is on the facts stay in memory (a coding session keeps none: its files are not data); they go with
// the first turn end after it is on.
//
// The backend's call_facts.py is the twin of factsOf and bashReads for the calls thimble stored (the orientation's
// coverage line); a change to a reader here changes it there, and both read the case list tests/bash-read-cases.ts.
import type { CoverageSummary } from './contracts'
import type { Ctx } from './ctx'
import { actStdin } from './data'
import type { Pre } from './activate'
import { absolute, isDataFile, relInside } from './activate'
import { rt } from './term'

export type Fact = { path: string; how: 'whole' | 'part' | 'searched'; lines?: [number, number]; pages?: [number, number]; total?: number; folder?: true; by: 'Read' | 'Bash' | 'search' | 'agent'; at: number }

/** A file a Bash command reads, by the reader that names it: how (whole, part with lines, searched), and for grep and
 *  rg whether the search recurses (a folder there means every data file under it) or prints file names. */
export type BashRead = { reader: string; path: string; how: Fact['how']; lines?: [number, number]; recursive?: boolean }

/** The readers whose file arguments the tracker counts, and how each reads. jq searches, except with the bare filter
 *  `.`, which prints the whole file. */
const WHOLE = new Set(['cat', 'less'])
const PART = new Set(['head', 'tail', 'sed'])
const SEARCH = new Set(['wc', 'grep', 'egrep', 'fgrep', 'rg', 'awk', 'gawk', 'jq'])
const PROGRAMS = new Set(['python', 'python3', 'duckdb', 'sqlite3', 'csvcut', 'mlr'])
/** Words before a command that run it (`sudo cat x`), skipped. */
const PREFIXES = new Set(['sudo', 'time', 'command', 'nice', 'nohup', 'env', 'exec'])
/** Extensions a path inside a program's code is taken for (`pd.read_csv('events.csv')`). */
const QUOTED_DATA = /['"]([^'"\s]+\.(?:csv|tsv|jsonl|ndjson|parquet|arrow|feather|xlsx|sqlite|db|duckdb|json|log|txt|md|pdf|xml|html?|vtt|srt|eml))['"]/g
const BINARY = new Set(['db', 'sqlite', 'duckdb', 'parquet', 'arrow', 'feather', 'xlsx'])

/** A shell command as words, cut into its simple commands at `|`, `;`, `&&`, `||`, `&` and newlines; quotes and
 *  backslashes kept apart from the words they quote. A heredoc's body is one word of the command before it. */
export function shellWords(command: string): string[][] {
  const out: string[][] = []
  let cur: string[] = []
  let word = ''
  let has = false
  const end = () => {
    if (has) cur.push(word)
    word = ''
    has = false
  }
  const cut = () => {
    end()
    if (cur.length) out.push(cur)
    cur = []
  }
  for (let i = 0; i < command.length; i++) {
    const ch = command[i]!
    if (ch === "'") {
      const j = command.indexOf("'", i + 1)
      word += command.slice(i + 1, j < 0 ? command.length : j)
      has = true
      i = j < 0 ? command.length : j
    } else if (ch === '"') {
      let j = i + 1
      while (j < command.length && command[j] !== '"') j += command[j] === '\\' ? 2 : 1
      word += command.slice(i + 1, j).replace(/\\(.)/g, '$1')
      has = true
      i = j
    } else if (ch === '\\' && i + 1 < command.length) {
      word += command[i + 1] === '\n' ? '' : command[i + 1]
      has = command[i + 1] !== '\n' || has
      i++
    } else if (ch === '<' && command.startsWith('<<', i)) {
      // a heredoc: its body, up to the line that ends it, is one word of this command
      end()
      const m = /^<<-?\s*(['"]?)([A-Za-z_][A-Za-z0-9_]*)\1/.exec(command.slice(i))
      if (!m) {
        i++
        continue
      }
      const bodyAt = command.indexOf('\n', i)
      if (bodyAt < 0) {
        i += m[0].length - 1
        continue
      }
      const stop = new RegExp(`\\n[\\t ]*${m[2]}[\\t ]*(?:\\n|$)`).exec(command.slice(bodyAt))
      const bodyEnd = stop ? bodyAt + stop.index : command.length
      // the rest of the heredoc's first line belongs to the command (`python3 - <<'EOF' > out.txt`)
      const rest = command.slice(i + m[0].length, bodyAt)
      cur.push(...shellWords(rest).flat())
      cur.push(command.slice(bodyAt + 1, bodyEnd))
      i = stop ? bodyEnd + stop[0].length - 1 : command.length
      cut()
    } else if (ch === '|' || ch === ';' || ch === '&' || ch === '\n') {
      if (ch === '&' && command[i + 1] === '>') {
        word += ch
        has = true
        continue
      }
      cut()
      if ((ch === '|' || ch === '&') && command[i + 1] === ch) i++
    } else if (/\s/.test(ch)) end()
    else {
      word += ch
      has = true
    }
  }
  cut()
  return out
}

/** The value a short or long option takes: the next word, or what follows `=` or the letter. */
function optionValue(words: readonly string[], i: number, short: string, long: string[]): { value: string; next: number } | null {
  const w = words[i]!
  for (const l of long) {
    if (w === l) return { value: words[i + 1] ?? '', next: i + 1 }
    if (w.startsWith(`${l}=`)) return { value: w.slice(l.length + 1), next: i }
  }
  if (short && w === short) return { value: words[i + 1] ?? '', next: i + 1 }
  if (short && w.startsWith(short) && w.length > short.length && !w.startsWith('--')) return { value: w.slice(short.length), next: i }
  return null
}

const OUTPUT_LONG = /^--(?:out|output)[\w-]*$/

/** The files a Bash command's readers name, never an output argument (after `>`, `>>`, `-o`, `--out*`, `--output*`, or
 *  a `tee`, which is no reader), never a glob the shell would expand. */
export function bashReads(command: string): BashRead[] {
  const out: BashRead[] = []
  for (const all of shellWords(command)) {
    const words = [...all]
    while (words.length && (/^[A-Za-z_][A-Za-z0-9_]*=/.test(words[0]!) || PREFIXES.has(words[0]!))) words.shift()
    const name = (words[0] ?? '').split('/').pop() ?? ''
    if (!WHOLE.has(name) && !PART.has(name) && !SEARCH.has(name) && !PROGRAMS.has(name)) continue
    const args: string[] = []
    const opts: string[] = []
    let nArg: string | undefined
    let lines: [number, number] | undefined
    let scriptGiven = false
    let quiet = false
    let filter: string | undefined
    for (let i = 1; i < words.length; i++) {
      const w = words[i]!
      // redirections: what follows a `>` is written; what follows a `<` is read
      if (/^\d*>{1,2}$|^&>$/.test(w)) {
        i++
        continue
      }
      if (/^\d*>{1,2}\S|^&>\S/.test(w)) continue
      if (w === '<') {
        if (words[i + 1]) args.push(words[i + 1]!)
        i++
        continue
      }
      if (OUTPUT_LONG.test(w)) {
        i++
        continue
      }
      if (/^--(?:out|output)[\w-]*=/.test(w)) continue
      if (w === '-o' && name !== 'grep' && name !== 'rg' && name !== 'egrep' && name !== 'fgrep') {
        i++
        continue
      }
      if (name === 'head' || name === 'tail') {
        const n = optionValue(words, i, '-n', ['--lines'])
        if (n) {
          nArg = n.value
          i = n.next
          continue
        }
        if (/^-\d+$/.test(w)) {
          nArg = w.slice(1)
          continue
        }
        const c = optionValue(words, i, '-c', ['--bytes'])
        if (c) {
          i = c.next
          continue
        }
      }
      if (name === 'sed') {
        if (w === '-n' || w === '--quiet' || w === '--silent') {
          quiet = true
          continue
        }
        if (w === '-i' || w.startsWith('-i') || w === '--in-place') {
          // an edit, not a reading
          args.length = 0
          opts.push('-i')
          break
        }
        const e = optionValue(words, i, '-e', ['--expression'])
        if (e) {
          scriptGiven = true
          lines = sedLines(e.value) ?? lines
          i = e.next
          continue
        }
      }
      if (name === 'awk' || name === 'gawk' || name === 'jq') {
        const f = optionValue(words, i, '-f', ['--from-file'])
        if (f) {
          scriptGiven = true
          i = f.next
          continue
        }
      }
      if (name === 'jq') {
        // options that take a name and a value: neither is the filter or a file
        if (/^--(?:arg|argjson|slurpfile|rawfile)$/.test(w)) {
          i += 2
          continue
        }
        if (w === '--indent') {
          i++
          continue
        }
      }
      if (name === 'grep' || name === 'egrep' || name === 'fgrep' || name === 'rg') {
        const e = optionValue(words, i, '-e', ['--regexp'])
        const f = e ? null : optionValue(words, i, '-f', ['--file'])
        if (e || f) {
          scriptGiven = true
          i = (e ?? f)!.next
          continue
        }
        // options that take a value: their value is no path
        const takes = optionValue(words, i, '', ['--glob', '--type', '--type-not', '--max-count', '--context', '--after-context', '--before-context', '--max-depth', '--include', '--exclude', '--exclude-dir', '--color', '--colour', '--sort', '--threads'])
        if (takes) {
          i = takes.next
          continue
        }
        if (/^-[gtTmABCM]$/.test(w)) {
          i++
          continue
        }
      }
      if (w.startsWith('-') && w !== '-') {
        opts.push(w)
        continue
      }
      args.push(w)
    }
    if (opts.includes('-i') && name === 'sed') continue
    let files = args
    if (name === 'sed' || name === 'awk' || name === 'gawk' || name === 'jq' || name === 'grep' || name === 'egrep' || name === 'fgrep' || name === 'rg') {
      // the first plain word is the script, the filter or the pattern, unless an option gave it
      if (!scriptGiven && files.length) {
        if (name === 'sed') lines = sedLines(files[0]!) ?? lines
        filter = files[0]
        files = files.slice(1)
      }
    }
    const isGrep = name === 'grep' || name === 'egrep' || name === 'fgrep'
    const recursive = name === 'rg' ? !opts.some(o => o === '--files') : isGrep && opts.some(o => /^-[A-Za-z]*[rR]/.test(o) || o === '--recursive' || o === '--dereference-recursive')
    if (name === 'rg' && opts.includes('--files')) continue
    if ((name === 'rg' || (isGrep && recursive)) && !files.length) files = ['.']
    const how: Fact['how'] = WHOLE.has(name) || (name === 'jq' && filter?.trim() === '.') ? 'whole' : PART.has(name) ? (name === 'sed' && !quiet ? 'whole' : 'part') : 'searched'
    if (name === 'head') {
      const n = Number((nArg ?? '10').replace(/^\+/, ''))
      if (Number.isInteger(n) && n > 0) lines = [1, n]
    }
    if (name === 'tail' && nArg?.startsWith('+')) lines = undefined
    for (const f of files) {
      if (!f || f === '-' || /[*?[\]{}$`]/.test(f)) continue
      out.push({ reader: name, path: f, how, ...(how === 'part' && lines ? { lines } : {}), ...(recursive ? { recursive: true } : {}) })
    }
    // a program's code that names a data file (`python3 -c "…read_csv('x.csv')"`, a heredoc, a SQL string)
    if (PROGRAMS.has(name)) {
      for (const w of words.slice(1)) for (const m of w.matchAll(QUOTED_DATA)) if (!/[*?[\]{}$`]/.test(m[1]!)) out.push({ reader: name, path: m[1]!, how: 'searched' })
    }
  }
  return out
}

/** The lines a sed script prints (`A,Bp`, `Ap`, `A,B{p;…}`), or undefined. */
function sedLines(script: string): [number, number] | undefined {
  const m = /^\s*(\d+)(?:\s*,\s*(\d+))?\s*(?:p|\{\s*p)/.exec(script)
  if (!m) return undefined
  const a = Number(m[1])
  const b = Number(m[2] ?? m[1])
  return a > 0 && b >= a ? [a, b] : undefined
}

// ------------------------------------------------------------------------------------------------ facts of a call

/** A call's input and answer as `tool.call` sees them. */
type Call = { tool: string; input: Record<string, unknown>; agentId?: string; result?: unknown; text?: string; deny?: string; isError?: boolean }

/** The facts one call gives (data files inside the session folder only; none for a refused or failed call). */
export async function factsOf(cx: Ctx, pre: Pre, c: Call): Promise<Fact[]> {
  if (c.deny !== undefined || c.isError) return []
  const at = (await cx.now()) / 1000
  const by = (own: Fact['by']): Fact['by'] => (c.agentId !== undefined ? 'agent' : own)
  const out: Fact[] = []
  // a file's path inside the folder (by its realpath), when it is data; with its kind ('dir' for a folder)
  const placed = async (p: string): Promise<{ rel: string; kind: string } | null> => {
    const st = await cx.real(absolute(pre, p))
    const real = st?.realPath
    if (!real) return null
    const rel = real === pre.real ? '.' : relInside(pre.real, real)
    if (rel === null) return null
    return { rel, kind: st.kind }
  }
  if (c.tool === 'Read') {
    const path = typeof c.input.file_path === 'string' ? c.input.file_path : ''
    const where = path ? await placed(path) : null
    if (!where || where.kind !== 'file' || !isDataFile(pre.real, where.rel, pre.codeTree, pre.never)) return []
    const r = (c.result ?? {}) as { type?: unknown; file?: { numLines?: unknown; startLine?: unknown; totalLines?: unknown; truncatedByTokenCap?: unknown; count?: unknown }; firstPage?: unknown; totalPages?: unknown }
    const f = r.file ?? {}
    const ext = where.rel.split('.').pop()?.toLowerCase() ?? ''
    if (r.type === 'file_unchanged') return []
    if (r.type === 'text' && !BINARY.has(ext)) {
      const n = Number(f.numLines)
      const start = Number(f.startLine) || 1
      const total = Number(f.totalLines)
      if (Number.isFinite(n) && Number.isFinite(total) && n >= total && f.truncatedByTokenCap !== true && start <= 1) out.push({ path: where.rel, how: 'whole', by: by('Read'), at })
      else out.push({ path: where.rel, how: 'part', ...(Number.isFinite(n) && n > 0 ? { lines: [start, start + n - 1] as [number, number] } : {}), ...(Number.isFinite(total) ? { total } : {}), by: by('Read'), at })
    } else if (r.type === 'pdf') out.push({ path: where.rel, how: 'whole', by: by('Read'), at })
    else if (r.type === 'parts') {
      const first = Number(r.firstPage) || 1
      const count = Number(f.count)
      out.push({ path: where.rel, how: 'part', ...(Number.isFinite(count) && count > 0 ? { pages: [first, first + count - 1] as [number, number] } : {}), ...(typeof r.totalPages === 'number' ? { total: r.totalPages } : {}), by: by('Read'), at })
    } else out.push({ path: where.rel, how: 'searched', by: by('Read'), at })
    return out
  }
  if (c.tool === 'Bash' && typeof c.input.command === 'string') {
    const reads = bashReads(c.input.command)
    const named = new Set<string>()
    for (const r of reads) {
      const where = await placed(r.path)
      if (!where) continue
      if (where.kind === 'dir') {
        if (r.recursive) out.push({ path: where.rel, how: 'searched', folder: true, by: by('search'), at })
        continue
      }
      if (where.kind !== 'file' || !isDataFile(pre.real, where.rel, pre.codeTree, pre.never)) continue
      named.add(where.rel)
      out.push({ path: where.rel, how: r.how, ...(r.lines ? { lines: r.lines } : {}), by: by(r.how === 'searched' && (r.reader === 'grep' || r.reader === 'rg') ? 'search' : 'Bash'), at })
    }
    // the files a `grep -l` or `rg -l` printed: searched
    const lists = shellWords(c.input.command).some(w => /^(?:grep|egrep|fgrep|rg)$/.test((w[0] ?? '').split('/').pop() ?? '') && w.some(x => /^-[A-Za-z]*l[A-Za-z]*$|^--files-with-matches$/.test(x)))
    if (lists) {
      const printed = typeof (c.result as { stdout?: unknown } | undefined)?.stdout === 'string' ? (c.result as { stdout: string }).stdout : (c.text ?? '')
      for (const line of printed.split('\n').slice(0, 200_000)) {
        const p = line.trim()
        if (!p || named.has(p)) continue
        const rel = p.startsWith('/') ? relInside(pre.real, p) : p.replace(/^\.\/+/, '')
        if (!rel || !isDataFile(pre.real, rel, pre.codeTree, pre.never)) continue
        named.add(rel)
        out.push({ path: rel, how: 'searched', by: by('search'), at })
      }
    }
    return out
  }
  if (c.tool === 'Grep') {
    // Claude Code's search tool in builds that have one: searched; a folder means every data file under it
    const path = typeof c.input.path === 'string' && c.input.path ? c.input.path : '.'
    const where = await placed(path)
    if (!where) return []
    if (where.kind === 'dir') return [{ path: where.rel, how: 'searched', folder: true, by: by('search'), at }]
    return where.kind === 'file' && isDataFile(pre.real, where.rel, pre.codeTree, pre.never) ? [{ path: where.rel, how: 'searched', by: by('search'), at }] : []
  }
  return []
}

// ------------------------------------------------------------------------------------------------ the turn's facts

/** The facts since the last flush (one per path and kind, the latest), the turn they go with. */
const held = { facts: [] as Fact[] }

/** Facts of a call kept for the turn's end. */
export function keepFacts(facts: readonly Fact[]): void {
  for (const f of facts) held.facts.push(f)
  if (held.facts.length > 250_000) held.facts.splice(0, held.facts.length - 250_000)
}

/** Whether facts wait for the turn's end. */
export function factsHeld(): number {
  return held.facts.length
}

/** A fresh session: no facts. */
export function resetTracker(): void {
  held.facts = []
}

/** The turn's facts sent (`thimble act coverage --stdin`, once per turn that has any): the session's summary, or null
 *  when there were none or the act failed. `turn` is the row the coverage line stands under. */
export async function flushFacts(cx: Ctx, session: string, turn: string): Promise<CoverageSummary | null> {
  if (!rt.sc || !held.facts.length) return null
  const facts = held.facts
  held.facts = []
  const got = await actStdin<{ summary?: CoverageSummary }>(cx, rt.sc, 'coverage', { session, turn, facts })
  if (!got.ok) {
    cx.log(`thimble: the turn's coverage was not recorded: ${got.error}`)
    return null
  }
  return summaryOf(got.value.summary)
}

/** A summary as C7 prints it, or null. */
export function summaryOf(v: unknown): CoverageSummary | null {
  const s = v as Partial<CoverageSummary> | null | undefined
  if (!s || typeof s !== 'object' || typeof s.line !== 'string') return null
  const n = (x: unknown) => (typeof x === 'number' && Number.isFinite(x) ? x : 0)
  const files = (s.files ?? {}) as Partial<CoverageSummary['files']>
  const records = (s.records ?? {}) as Partial<CoverageSummary['records']>
  const unit = records.unit === 'lines' || records.unit === 'entries' ? { unit: records.unit } : {}
  const searched = typeof records.searched === 'number' ? { searched: n(records.searched) } : {}
  // the corpus's totals per unit and by size, which the summary line and the Coverage view read
  const totals = Array.isArray(s.totals) ? { totals: s.totals.filter(t => t && typeof t === 'object' && typeof t.unit === 'string') } : {}
  const size = s.size === null ? { size: null } : s.size && typeof s.size === 'object' ? { size: { read: n(s.size.read), searched: n(s.size.searched), total: n(s.size.total) } } : {}
  return { files: { seen: n(files.seen), searched: n(files.searched), never: n(files.never), total: n(files.total) }, records: { ...unit, seen: n(records.seen), ...searched, total: n(records.total), counted: records.counted === true }, ...totals, ...size, line: s.line }
}

files.hooks/term/offramp.ts:
// The press: thimble's page opened in the browser on one object, signed in, on this session (SPEC-v2 3.15, C12).
// `thimble open --session <sid> --cwd <dir> --ref <ref> --json` starts the page when it is not running and opens the
// person's browser through a redirect file only they can read; it prints status alone, never a sign-in code. This file
// shows what happens: the toast `starting thimble's page…` at once; then, on this machine, a watch of the claim file for
// 12 s, which ends in the toast `opened in the browser · 127.0.0.1:<port>` or the notice `open:not-claimed`; over SSH
// or with no display, where no browser opens, the one row above the prompt that says so in plain words (remoteWords:
// run the tunnel command on your own computer, then copy link), whose `copy link` copies a one-time link that the open
// wrote to a file only the person can read; the row goes once a browser claims the link (watchLink). On Claude Code's
// main screen, which takes no clicks, the panel also opens on that row with its acts on keys (waitview.tsx).
// `/thimble browser` says which of these happened (openInBrowser's answer, register.tsx). A failure posts its notice
// (notices.tsx) with the acts that fix it. Where a signed-in tab of thimble's page is open and live, the open hands the
// object to it and opens no other tab (`reused`; bug hunt round 9, J8): the toast says the open tab shows it.
//
// Callers: `/thimble browser`, `o` and the title row's `↗` in every panel view (panel.tsx wayRow), a card's `↗`, the
// checks' `open in the browser`, a notice's `open ›` for a code ticket.
import type { Ctx } from './ctx'
import type { Links } from './types'
import { noControls } from './lib'
import { dismissModNotice, onNoticeAct, postNotice } from './notices'
import { classicScreen, openPanel, rt } from './term'

/** The key of the SSH row as home and the panel's `waiting` view name it (band.tsx waitItems, waitview.tsx). */
export const BROWSER_ITEM = 'browser'

/** How long the claim of a sign-in is watched for, and how often. */
export const CLAIM_MS = 12_000
const CLAIM_STEP_MS = 500
/** How long the SSH row waits for a browser to claim its one-time link (the link works for 5 minutes), and how often it
 *  looks. */
export const LINK_MS = 5 * 60_000
const LINK_STEP_MS = 1000
/** A second press on the same object this soon after the first runs no second open. */
const AGAIN_MS = 5_000

/** What `thimble open --json` prints (C12). */
export type OpenResult =
  | { ok: true; port: number; url: string; opened: boolean; remote: boolean; tunnel: string | null; et: string | null; link_file: string | null; claim_file: string; proxy: boolean; reused?: boolean }
  | { ok: false; error: { code: string; message: string; fix: string } }

// the one-time link's file of the last remote open (the SSH row's `copy link`), never shown
let linkFile = ''
// a browser claimed a sign-in of this session's: thimble's page shows there
let claimed = false

/** Whether a browser opened thimble's page from this session (a press's sign-in was claimed). */
export function browserShown(): boolean {
  return claimed
}
// the ref of the last open, for a notice's `try again` and `copy link`
let lastRef = 'home'
// the claim file of the SSH row's latest one-time link and until when it is watched (watchLink), and whether a watch runs
let remoteClaim: { file: string; until: number } | null = null
let watchingLink = false

/** What happened on a press: the page opens in a browser here (`opening`), the tab of the page already open shows it
 *  (`shown`), no browser opens here and the SSH row says what to do (`remote`), it failed and a notice says why
 *  (`failed`), or a press on the same object a moment ago still runs (`again`). */
export type OpenOutcome = 'opening' | 'shown' | 'remote' | 'failed' | 'again'

/** The toast once a press is in the browser: a new tab, or the tab already open (`reused`). */
export function openedWords(port: number, reused = false): string {
  return reused ? `shown in the thimble tab already open in your browser · 127.0.0.1:${port}` : `opened in the browser · 127.0.0.1:${port}`
}

/** The SSH row's words (bug hunt F11: `opening thimble's page in the browser` said nothing of what to do): no browser
 *  opens here, the tunnel command to run on your own computer, then copy link. */
export function remoteWords(l: Pick<Links, 'tunnel' | 'et'>): string {
  return `No browser here. On your own computer, run ${l.et ?? l.tunnel}, then press copy link and open the link there.`
}

/** What `/thimble browser` says after a press that opened no browser here: the command to run on your own computer, and
 *  where the one-time link is copied from: `copy link` above the prompt, or on Claude Code's main screen, which takes
 *  no clicks, `2` in the panel (waitview.tsx). */
export function remoteReply(l: Pick<Links, 'tunnel' | 'et'>, classic: boolean): string {
  const host = /<your ssh host>/.test(l.et ?? l.tunnel) ? ' Put the host you reach this machine by in place of <your ssh host> (THIMBLE_SSH_HOST fills it in).' : ''
  const copy = classic ? "press 2 in thimble's panel to copy a one-time link" : 'press copy link above the prompt to copy a one-time link'
  return `thimble: no browser opens here (a remote terminal, or no display). On your own computer, run ${l.et ?? l.tunnel}, then ${copy} and open it in your browser there; it works once, for 5 minutes.${host}`
}

/** The SSH row's one-time link in `file` watched until a browser claims it, from timers: then the row goes, since the
 *  browser is signed in (bug hunt F11). A newer link's file takes the place of an older one's; the watch ends with the
 *  row, or LINK_MS after the newest link. */
async function watchLink(cx: Ctx, file: string | null | undefined): Promise<void> {
  if (!file) return
  remoteClaim = { file, until: (await cx.now()) + LINK_MS }
  if (watchingLink) return
  watchingLink = true
  const look = (): void => {
    cx.later(LINK_STEP_MS, () => {
      void (async () => {
        const w = remoteClaim
        if (!w || !(await cx.links())) return void (watchingLink = false)
        if (await cx.stat(w.file).then(() => true, () => false)) {
          watchingLink = false
          remoteClaim = null
          claimed = true
          linkFile = ''
          await cx.setLinks(null)
          return
        }
        if ((await cx.now()) > w.until) return void (watchingLink = false)
        look()
      })().catch(() => void (watchingLink = false))
    })
  }
  look()
}

/** What a run of `thimble open` printed, as C12's answer; a run that printed no JSON is an error of its own. */
export function openResult(r: { exitCode: number; stdout: string; stderr: string }): OpenResult {
  try {
    const v = JSON.parse(r.stdout.trim()) as OpenResult
    if (v && typeof v === 'object' && typeof (v as { ok?: unknown }).ok === 'boolean') return v
  } catch {
    // not JSON
  }
  const why = r.stderr.trim().split('\n').filter(Boolean).at(-1) || (r.stdout.trim() ? 'it printed no JSON' : 'it printed nothing')
  return { ok: false, error: { code: 'START', message: noControls(why).slice(0, 300), fix: '' } }
}

async function runOpen(cx: Ctx, ref: string, more: string[] = []): Promise<OpenResult> {
  const sc = rt.sc
  if (!sc) return { ok: false, error: { code: 'NO_SESSION', message: 'thimble is not on in this session', fix: 'type /thimble' } }
  const sid = await cx.sessionId()
  try {
    const r = await cx.run([sc.bin, 'open', ...(sid ? ['--session', sid] : []), '--cwd', sc.cwd, '--ref', ref, ...more, '--json'], { cwd: sc.cwd, env: sc.env, timeoutMs: 60_000 })
    return openResult(r)
  } catch (err) {
    return { ok: false, error: { code: 'START', message: noControls(String(err)).slice(0, 300), fix: '' } }
  }
}

/** The one-time link a file holds (the open's `link_file`): its `url` or `link`, or its first line that is an address. */
export function linkIn(text: string): string {
  try {
    const v = JSON.parse(text) as { url?: unknown; link?: unknown }
    const u = typeof v?.url === 'string' ? v.url : typeof v?.link === 'string' ? v.link : ''
    if (/^https?:\/\//.test(u)) return u
  } catch {
    // a plain file
  }
  return text.split('\n').map(l => l.trim()).find(l => /^https?:\/\//.test(l)) ?? ''
}

/** A one-time link to thimble's page copied (it works once, for 5 minutes): the remote open's link file, else a link a
 *  new open writes (`--link`). The link is never drawn, logged or said. */
export async function copyLink(cx: Ctx, ref = lastRef): Promise<void> {
  let file = linkFile
  if (!file) {
    const got = await runOpen(cx, ref, ['--link'])
    if (!got.ok) return postFailed(cx, ref, got.error)
    file = got.link_file ?? ''
    // the SSH row goes once a browser claims this new link
    if (await cx.links()) await watchLink(cx, got.claim_file)
  }
  const link = file ? linkIn(await cx.read(file).catch(() => '')) : ''
  // a link works once: the next copy needs a new one
  linkFile = ''
  if (!link) return cx.toast('no link to copy: press o in the panel to open the page again')
  const r = await cx.copy(link)
  cx.toast(r.isCopied ? 'copied a link to thimble\'s page: it works once, for 5 minutes' : `could not copy the link: ${r.reason ?? 'no clipboard'}`)
}

function postFailed(cx: Ctx, ref: string, error: { code: string; message: string; fix: string }): void {
  if (error.code === 'NO_OPENER') {
    onNoticeAct('open:no-opener', 'copy link', () => copyLink(cx, ref))
    postNotice(cx, 'open:no-opener', 'No browser opener found. Use copy link, then paste the link into a browser on this machine.', ['copy link'])
    return
  }
  onNoticeAct('open:failed', 'try again', async () => {
    await dismissModNotice(cx, 'open:failed')
    await openInBrowser(cx, ref)
  })
  const why = [error.message, error.fix].filter(Boolean).join(' · ')
  postNotice(cx, 'open:failed', `thimble's page did not start: ${why || error.code}`, ['try again', 'doctor'])
}

/** The claim file watched every CLAIM_STEP_MS until it is there or CLAIM_MS pass (from timers, outside any hook); a tab
 *  already open that took the press (`reused`) wrote it at once. */
function watchClaim(cx: Ctx, file: string, port: number, ref: string, left = CLAIM_MS, reused = false): void {
  cx.later(CLAIM_STEP_MS, () => {
    void (async () => {
      const there = await cx.stat(file).then(() => true, () => false)
      if (there) {
        claimed = true
        await cx.setPressing(null)
        cx.toast(openedWords(port, reused))
        return
      }
      if (left - CLAIM_STEP_MS > 0) return watchClaim(cx, file, port, ref, left - CLAIM_STEP_MS, reused)
      await cx.setPressing(null)
      onNoticeAct('open:not-claimed', 'copy link', () => copyLink(cx, ref))
      postNotice(cx, 'open:not-claimed', "The browser did not open thimble's page.", ['copy link'])
    })()
  })
}

/** thimble's page opened in the browser on `ref` (SPEC-v2 C13): see the file's head. Never a code in a row, a toast or
 *  a log; the SSH row shows the tunnel command alone. */
export async function openInBrowser(cx: Ctx, ref: string): Promise<OpenOutcome> {
  if (!rt.sc) return 'failed'
  const now = await cx.now()
  const pressing = await cx.pressing()
  if (pressing && pressing.ref === ref && now - pressing.at < AGAIN_MS) return 'again'
  lastRef = ref
  await cx.setPressing({ at: now, ref })
  cx.toast("starting thimble's page…")
  const got = await runOpen(cx, ref)
  if (!got.ok) {
    await cx.setPressing(null)
    postFailed(cx, ref, got.error)
    return 'failed'
  }
  if (got.proxy) postNotice(cx, 'open:proxy', 'A proxy is set for this session; the browser link may not reach thimble. Set NO_PROXY=127.0.0.1,localhost.', [])
  if (got.remote) {
    await cx.setPressing(null)
    linkFile = got.link_file ?? ''
    const tunnel = noControls(got.tunnel ?? `ssh -N -L ${got.port}:127.0.0.1:${got.port} <your ssh host>`)
    await cx.setLinks({ tunnel, et: got.et ? noControls(got.et) : null, url: noControls(got.url) })
    await watchLink(cx, got.claim_file)
    // Claude Code's main screen takes no clicks, so the SSH row's `copy link` cannot be pressed there: the panel shows
    // the row with its acts on keys (waitview.tsx; bug hunt F1)
    if (classicScreen()) await openPanel(cx, { view: 'waiting', title: 'browser', slug: BROWSER_ITEM })
    return 'remote'
  }
  if (!got.opened) {
    await cx.setPressing(null)
    postFailed(cx, ref, { code: 'NO_OPENER', message: '', fix: '' })
    return 'failed'
  }
  watchClaim(cx, got.claim_file, got.port, ref, CLAIM_MS, !!got.reused)
  return got.reused ? 'shown' : 'opening'
}

/** The SSH row's `copy`: the tunnel command (its Eternal Terminal form when the open gave one). */
export async function copyTunnel(cx: Ctx): Promise<void> {
  const l = await cx.links()
  if (!l) return
  const r = await cx.copy(l.et ?? l.tunnel)
  cx.toast(r.isCopied ? 'copied the tunnel command: run it on your own computer, then open the link' : `could not copy: ${r.reason ?? 'no clipboard'}`)
}

/** The SSH row's `copy link`: the one-time link of the remote open. */
export async function copyRemoteLink(cx: Ctx): Promise<void> {
  await copyLink(cx)
}

/** The SSH row gone. */
export async function dismissLinks(cx: Ctx): Promise<void> {
  linkFile = ''
  remoteClaim = null
  await cx.setLinks(null)
}

files.hooks/term/checksview.tsx:
// The Checks view (SPEC-v2 J7, 3.12): the checks' comments on passages of Claude's answers (C13 `answerComments`, read by
// the transcript's lane from `thimble state answer-comments`), one at a time:
//
//   home › checks › Important details                                    ‹ 1 of 2 ›  ↗
//   on your answer at 16:06 · it looks for what a reader would likely miss
//   ───────────────────────────────────────────────────────────────────────────────
//   ⚑ passage   After 19 June there are 0 new messages to other agents on any page.
//     comment   The label could not read 899 revisions whose text the dump hides …
//
//   put in the prompt   dismiss   open in the browser
// ─────────────────────────────────────────────────────────────────────────────────
// ❯ ask about this comment
//
// ─────────────────────────────────────────────────────────────────────────────────
//
// The entry box (entry.tsx) asks a side thread about the passage, told the comment (`a` gives it the keys); `m` puts a
// draft in the prompt (nothing is sent); `d` dismisses the comment (`thimble act answer-comment-resolve`): its tint and
// flag go and the view moves to the next one; `o` and the title row's `↗` open the comment in the browser
// (`answer:<turn>#s<n>`); `n` and `p` step. While a comment
// shows, `$.state.checksOpen` names it (the transcript lights its passage more). With no open comment the view lists the
// checks (`thimble state checks`): each one's name, on or off, and its comments; `o` opens the browser's Checks pane.
import type { RenderElement } from 'claude-code'

import type { AnswerComment, TermPanel } from './types'
import { markSeen, hiddenComments, openComments } from './band'
import { MARGIN_W, controlsEl, fieldEls, headerEls, marginKey, pointed, setBrowser, spread, subLine } from './chrome'
import type { Ctx } from './ctx'
import { act } from './data'
import type { Line, Seg } from './draw'
import { hueOf } from './labels'
import { plainProse } from './cite'
import { clip, noControls, quoted } from './lib'
import { linesEl } from './lines'
import { COLORS } from './paint'
import type { PaneEvent } from './panel'
import { askEntry, askKey, drawsView, entryBottom, hiddenKeys, hintsRow, none } from './panel'
import type { AskOver } from './panel'
import { checksOf } from './report'
import { loadsView, openPanel, readSurface, rt, surfaceValue } from './term'
import { openInBrowser } from './offramp'

/** The flag a commented passage carries in the reply's margin (the transcript's paint.ts FLAG). */
export const FLAG = '⚑'
/** The most characters of the passage a draft in the prompt quotes, on one line (SPEC-v2 S20): main finds its own
 *  words by them; the comment and its details go whole. */
const QUOTE_MAX = 80

const dim = (s: string): Seg => ({ s, fg: COLORS.dim })

/** When a comment was made, as the rest of the terminal says a time (`16:06`, the notices' `at 01:16`): the local
 *  clock's hours and minutes. */
export function timeWords(at: string): string {
  const t = Date.parse(at)
  if (!Number.isFinite(t)) return ''
  const d = new Date(t)
  const two = (n: number) => String(n).padStart(2, '0')
  return `${two(d.getHours())}:${two(d.getMinutes())}`
}

/** Words put into the prompt: one line. */
function oneLine(s: string): string {
  return noControls(s).replace(/\s+/g, ' ').trim()
}

/** The draft `m` puts in the prompt, which the person edits before sending: the passage by its first words, and the
 *  check's comment and its details whole, so main reads all the check said (bug hunt B10: the comment was cut
 *  mid-sentence and its details left out, and main did the check's work again). */
export function promptDraft(c: AnswerComment): string {
  const when = timeWords(c.at)
  const details = oneLine(c.details)
  return `About "${clip(oneLine(c.quote), QUOTE_MAX)}" in your answer${when ? ` at ${when}` : ''}, the ${oneLine(c.checkName)} check says: "${oneLine(c.text)}"${details ? ` Its details: "${details}"` : ''}`
}

// the comment the view shows, by its id ('' for the first open one)
let shownId = ''

/** The Checks view opened in the panel (SPEC-v2 C13), on comment `commentId` when given, else on the first open one;
 *  the checks' `new` cleared. */
export async function openChecks(cx: Ctx, commentId?: string): Promise<void> {
  const open = await openComments(cx)
  const c = open.find(x => x.id === commentId) ?? open.find(x => x.id === shownId) ?? open[0]
  shownId = c?.id ?? ''
  await markSeen(cx, ['checks'])
  await cx.setChecksOpen(c?.id ?? null)
  await openPanel(cx, { view: 'checks', title: c ? noControls(c.checkName) : 'Checks', ...(c ? { mode: 'comment' } : {}) })
}

/** The view moved to comment `c` (n, p, a dismiss), its step's title that comment's check, in place of the step. */
async function stepTo(cx: Ctx, c: AnswerComment | undefined): Promise<void> {
  shownId = c?.id ?? ''
  await cx.setChecksOpen(c?.id ?? null)
  const p = await cx.panel()
  await openPanel(cx, { ...(p ?? { view: 'checks' }), view: 'checks', title: c ? noControls(c.checkName) : 'Checks', ...(c ? { mode: 'comment' } : { mode: '' }) }, { replace: true })
}

/** A comment dismissed (`thimble act answer-comment-resolve`): gone at once, the view on the next one. */
async function dismiss(cx: Ctx, c: AnswerComment): Promise<void> {
  if (!rt.sc) return
  const before = await openComments(cx)
  const at = before.findIndex(x => x.id === c.id)
  const got = await act(cx, rt.sc, 'answer-comment-resolve', { comment: c.id, reopen: false })
  if (!got.ok) return cx.toast(`the comment was not dismissed: ${got.error}`)
  hiddenComments.add(c.id)
  const left = await openComments(cx)
  await markSeen(cx, ['checks'])
  await stepTo(cx, left[Math.min(at, left.length - 1)])
}

/** What a side thread about a comment is told: its passage, and the comment. */
function askOver(c: AnswerComment): AskOver {
  const quote = noControls(c.quote)
  return { anchor: c.ref, anchorText: `${quote}\n\nThe ${noControls(c.checkName)} check's comment on this passage of the answer: ${noControls(c.text)}`, element: c.ref, about: `comment ${quoted(clip(noControls(c.text), 50))}` }
}

async function loadChecks(cx: Ctx): Promise<void> {
  // the checks, which the view lists when no comment is open
  await readSurface(cx, 'checks', 'checks')
}

async function drawChecks(cx: Ctx, e: PaneEvent, _p: TermPanel): Promise<RenderElement> {
  const els = cx.els(e)
  const { Box, Text, Button } = els
  const cols = Math.max(30, e.props.bodyColumns)
  const open = await openComments(cx)
  const i = Math.max(0, open.findIndex(x => x.id === shownId))
  const c = open[i]
  if (!c) return drawCheckList(cx, e, cols, open)
  setBrowser(c.ref)
  const hue = hueOf(c.color || 2)
  const when = timeWords(c.at)
  const prev = () => (i > 0 ? stepTo(cx, open[i - 1]) : undefined)
  const next = () => (i < open.length - 1 ? stepTo(cx, open[i + 1]) : undefined)
  // `‹ 1 of 2 ›` against R on the title row: an arrow a click away where there is a comment to step to, else dim (n and
  // p step too)
  const arrow = (key: string, words: string, go: (() => unknown) | null) =>
    go ? <Button key={key} plain onPress={() => void go()}><Text color={COLORS.link}>{words}</Text></Button> : <Text key={key} dimColor>{words}</Text>
  const right = (
    <Box key="checks-page" flexDirection="row">
      {arrow('checks-prev', '‹ ', i > 0 ? prev : null)}
      <Text>{` ${i + 1} of ${open.length} `}</Text>
      {arrow('checks-next', ' ›', i < open.length - 1 ? next : null)}
    </Box>
  )
  const body: RenderElement[] = [...headerEls(els as never, { title: noControls(c.checkName), cols, right, sub: subLine([`on your answer${when ? ` at ${when}` : ''}`, noControls(c.about)]) })]
  // the passage with the check's flag in its color, the comment, its details
  const rows: [string, RenderElement | string, string?][] = [
    ['passage', <Text wrap="wrap">{plainProse(c.quote)}</Text>],
    ['comment', <Text wrap="wrap">{plainProse(c.text)}</Text>],
    ...(c.details ? [['details', <Text dimColor wrap="wrap">{plainProse(c.details)}</Text>] as [string, RenderElement]] : []),
  ]
  body.push(
    <Box key={marginKey('checks-comment')} flexDirection="row">
      <Box width={MARGIN_W} flexShrink={0} flexDirection="column">
        <Text color={hue}>{`${FLAG} `}</Text>
      </Box>
      <Box flexGrow={1} flexShrink={1} flexDirection="column">
        {fieldEls(els as never, rows, 'checks')}
      </Box>
    </Box>,
  )
  const draft = () => void cx.fill(promptDraft(c))
  const browse = () => void openInBrowser(cx, c.ref)
  // the entry box, whose question starts a side thread about the passage, told the comment
  const askAt = `ask-check-${c.id}`
  const entry = e.surface === 'mobile' ? null : askEntry(cx, e, { key: askAt, placeholder: 'ask about this comment', cols, target: { kind: 'sentence', text: noControls(c.quote) }, over: askOver(c) })
  const acts = controlsEl(els as never, [
    <Button key="checks-prompt" label="put in the prompt" plain onPress={draft} />,
    <Button key="checks-dismiss" label="dismiss" plain onPress={() => void dismiss(cx, c)} />,
    <Button key="checks-browser" label="open in the browser" plain onPress={browse} />,
  ], 'checks-acts')
  const hints = [...(entry ? ['a to ask'] : []), 'm to put it in the prompt', 'd to dismiss', 'o to open in the browser', ...(open.length > 1 ? ['n p for the next or previous'] : []), 'b to go back', 'x to close']
  if (entry) body.push(...entryBottom(cx, e, cols, [acts], entry, hints))
  else body.push(acts!, hintsRow(els as never, hints, cols))
  const hk = hiddenKeys(cx, e, [
    ...(entry ? [{ ...askKey(cx, askAt), key: 'checks-a' }] : []),
    { key: 'checks-m', hotkey: 'm', onPress: draft },
    { key: 'checks-d', hotkey: 'd', onPress: () => void dismiss(cx, c) },
    { key: 'checks-n', hotkey: 'n', onPress: () => void next() },
    { key: 'checks-p', hotkey: 'p', onPress: () => void prev() },
  ])
  return <Box flexDirection="column">{[...(hk ? [hk] : []), ...body]}</Box>
}

/** No open comment: the checks, each one's name in its color, on or off, and its comments on answers. */
async function drawCheckList(cx: Ctx, e: PaneEvent, cols: number, open: readonly AnswerComment[]): Promise<RenderElement> {
  const els = cx.els(e)
  const { Box } = els
  setBrowser('checks')
  const got = await surfaceValue(cx, 'checks')
  const checks = checksOf(got?.ok ? got.value : [])
  const running = (await cx.checksRunning()) > 0
  const body: RenderElement[] = [...headerEls(els as never, { title: 'Checks', cols, sub: subLine(['no comment on an answer is open', running ? '◌ a check reads an answer' : '']) })]
  const lines: Line[] = checks.map(k => {
    const n = open.filter(x => x.check === k.id).length
    return pointed(spread([{ s: '●', fg: hueOf(k.colour) }, { s: ' ' }, { s: noControls(k.name) }], [dim(`${k.shown ? 'on' : 'off'}${n ? ` · ${n} open comment${n === 1 ? '' : 's'}` : ''}`)], cols), false)
  })
  body.push(lines.length ? linesEl(cx, e, marginKey('checks-list'), lines, [], cols + MARGIN_W) : none(cx, e, got ? 'no checks' : '◌ reading the checks'))
  body.push(hintsRow(els as never, ['o to open the Checks pane in the browser', 'b to go back', 'x to close'], cols))
  return <Box flexDirection="column">{body}</Box>
}

/** The Checks view's read and drawing registered with the panel (views.ts registerPanelViews). */
export function registerChecksView(): void {
  loadsView('checks', loadChecks)
  drawsView('checks', drawChecks)
}

