// A thimble card (a cell of a group file, workspaces/<c>/notebooks/<group>.json, as `thimble state card` prints it) in
// the drawing form of hooks/draw.ts (CardData), so its layouts draw it in the terminal. No `$`.
//
// The map of card kinds (the two-modes study): a table, a timeline, a diagram, an example and a label draw directly; a
// simple bar or line chart (one Altair layer, x and y fields; a bar's groups stacked or side by side; a line per `detail`
// value) draws as text, at most MAX_LINE_POINTS points of its lines, a stacked area chart as its bands, a start-to-end
// chart as its spans, a dots chart as its rows of dots with the words a text layer writes beside them, a heatmap as its
// grid of cells shaded on its color scale with the numbers a text layer writes on them, and a faceted chart as one of
// these per panel; any other chart draws as a table of its rows when they are few, else as a short note that the
// browser draws it; a note is prose; a code card, a card type's card and a matplotlib figure draw as their printed text;
// a custom HTML card draws as its text. A label card's counts and records come from the label (`thimble state label`).
import type { TermLinks } from './types'
import type { BarRow, CardData, CardExample, Cell, DiagramEdge, DiagramNode, DotRow, HeatScale, Panel, PlanStep } from './draw'
import { MAX_TABLE_ROWS, amount } from './draw'
import { labelState, labelStateWords } from './lib'
import { classColors } from './labels'
import type { LabelClass } from './labels'

/** A cell as the workspace stores it: the fields the drawing reads. */
export type ThimbleCell = {
  id: string
  kind?: string
  title?: string
  /** its name, a slug of its question (backend notebook.slug_of), which its chip shows: `[ card:prs-merged-week ]` */
  slug?: string
  takeaway?: string
  status?: string
  text?: string
  code?: string
  notebook?: string
  created_by?: string
  labels?: string[]
  payload?: Record<string, unknown> | null
  outputs?: Record<string, unknown>[]
  run?: { state?: string; by?: string; script?: string }
  /** its latest card check (backend checkstore.py): `pending` while cardrun waits to start it, then its record, which
   *  ends `ok`, `fixed`, `error` or `stopped` with a `reason` for the last two */
  check?: string | { id?: string; status?: string; reason?: string; phase?: string } | null
  regenerating_for?: string[]
  label_revs?: Record<string, number>
  verification?: { status?: string; links?: { status?: string; checked?: boolean; resolved?: unknown[]; broken?: unknown[]; typed?: unknown[] } | null } | null
}

/** One run of a label as the concept keeps it: the records it ran over (`total`), those its scope holds
 *  (`matched_total`), those labeled, its sample size (`limit`, none for every record), when it began. */
/** A run of a label as the concept keeps it; `cut`, the whole files or runs a prompt label read only in part, with the
 *  line that says it (backend concepts.read_cut). */
export type LabelRun = { total?: number; matched_total?: number | null; labeled?: number; failed?: number; skipped?: number; status?: string; paths?: string[]; limit?: number | null; ts?: string; stopped?: boolean; cut?: { n?: number; line?: string } | null }

/** A label's run going on, in whichever process runs it (`thimble state`'s `run`, backend concepts.current_run): its
 *  units read so far (`done`) of its own size (`total`, null while it is counted); any other status is a run that
 *  ended. */
export type LabelLiveRun = { status?: string; done?: number; total?: number | null; matched_total?: number | null; labeled?: number; failed?: number; skipped?: number; limit?: number | null; run_id?: string }

/** A label (`thimble state label <id>`, the concept route's shape), with a page of its rows when the backend gives
 *  one (`rows`, as GET /concepts/<id>/rows?text=1 answers). */
export type ThimbleLabel = {
  id: string
  name?: string
  kind?: string
  unit?: string
  glob?: string
  labels?: string[]
  trial?: boolean
  label_stats?: { counts?: Record<string, number>; n_labeled?: number }
  /** the counts with the analyst's verdicts applied, as thimble.labels() reads the rows, and how many records the analyst
   *  set to another value (`thimble state label`, local._label) */
  verdicts?: { counts?: Record<string, number>; set?: number }
  description?: string
  spec?: string
  applications?: LabelRun[]
  last_run?: LabelRun | null
  /** its run going on, in any process (bug hunt I2) */
  run?: LabelLiveRun | null
  /** what its Run again goes on with after a stop: the units the stopped run read and those it never read, of its
   *  scope's; null when a run labels every unit again (the definition changed since: backend concepts.resumable) */
  resume?: { read: number; left: number; total: number } | null
  rows?: { ref?: string; label?: string; rationale?: string; analyst?: unknown; text?: string; confidence?: number; match?: string }[]
  /** its revision, which steps whenever its rows or its definition change (concepts.note_change) */
  rev?: number
  /** the records its scope holds, given for a label with rows and no run that ended (backend local._scope_total) */
  scope_total?: number
  /** how many files its glob matches, for a label over files (`thimble state label`, local._scope_facts) */
  scope_files?: number
  /** what its records are called in its scope's files (`lines`, `rows`, `pages`, `entries`, `records`; `files` for a
   *  label over whole files), for a label over files (`thimble state label`, local._record_noun) */
  scope_unit?: string
  /** the model a prompt label's calls run on, by the name the analyst reads (`thimble state label`) */
  run_model?: string
  /** the model its calls run on, by its id: its own, else the labels role's (`model_role`); and the models the panel's
   *  `model:` offers, by their ids (`thimble state label`, local._scope_facts) */
  model_id?: string
  model_role?: string
  /** the model of its own, by its id, '' for none (the concept's `model`) */
  model?: string
  model_choices?: string[]
  /** its values in order with their color (1 to 12, 0 for none) and whether Files marks them while it is on */
  classes?: LabelClass[]
  /** on in Files and the views (a label over files) */
  shown?: boolean
  /** its agreement with the values the analyst set, the values its runs took as examples apart */
  calibration?: { n?: number; agreed?: number; taught?: number } | null
  /** how many records have each value (`thimble state label`), so its examples say how many more there are */
  totals?: Record<string, number>
  /** the value of it its scope's filter keeps, null for none (`thimble state label`) */
  filter?: string | null
}

export const FRAME = 'application/vnd.thimble.frame+json'
export const DIAGRAM = 'application/vnd.thimble.diagram+json'
export const TIMELINE = 'application/vnd.thimble.timeline+json'
export const ERROR = 'application/vnd.thimble.error+json'
export const CARD_TYPE = 'application/vnd.thimble.card+json'
const READS = 'application/vnd.thimble.reads+json'

type Frame = { columns?: string[]; index?: string | null; label?: string; rows?: Cell[][]; total?: number; view?: { columns?: string[]; formats?: Record<string, string> } }
type Enc = { field?: string; type?: string; aggregate?: string; sort?: unknown; axis?: { values?: unknown } | null; stack?: unknown; scale?: { type?: unknown; exponent?: unknown; constant?: unknown } | null; title?: unknown; format?: unknown }
type VegaLite = {
  mark?: string | { type?: string; opacity?: unknown }
  encoding?: Record<string, Enc | undefined>
  data?: { name?: string; values?: Record<string, unknown>[] }
  datasets?: Record<string, Record<string, unknown>[]>
  layer?: VegaLite[]
  facet?: unknown
  resolve?: { scale?: Record<string, unknown> }
  spec?: VegaLite
  hconcat?: VegaLite[]
  vconcat?: VegaLite[]
  concat?: VegaLite[]
}

export type Drawn = { card: CardData; error: string }

/** The words of a chart the terminal draws no picture of, whose rows are too many for a short table; the link under
 *  them opens it in the browser (reply.tsx cardBlock). */
export const BROWSER_CHART = 'The terminal cannot draw this chart. The browser shows it.'

function blank(cell: ThimbleCell, kind: string): CardData {
  return { id: cell.id, kind, question: cell.title ?? '', x: '', y: '', note: '', source: {} }
}

function bundles(cell: ThimbleCell): Record<string, unknown>[] {
  return (cell.outputs ?? []).filter((b): b is Record<string, unknown> => Boolean(b) && typeof b === 'object' && !(READS in b))
}

function first(cell: ThimbleCell, pick: (k: string) => boolean): unknown {
  for (const b of bundles(cell)) for (const [k, v] of Object.entries(b)) if (pick(k)) return v
  return undefined
}

function asText(v: unknown): string {
  if (typeof v === 'string') return v
  if (Array.isArray(v)) return v.map(x => String(x)).join('')
  return ''
}

/** What the cell printed: its streams and plain text outputs that are not a chart's fallback, in order. */
export function printed(cell: ThimbleCell): string {
  const out: string[] = []
  for (const b of bundles(cell)) {
    if (ERROR in b) continue
    const rich = Object.keys(b).some(k => k !== 'text/plain' && k.includes('/') && !k.startsWith('text/'))
    if (rich) continue
    if ('text/html' in b && !('_stream' in b)) continue
    const t = asText(b['text/plain'])
    if (t && !/^<(VegaLite|Figure|AxesSubplot|matplotlib)\b/.test(t.trim())) out.push(t.replace(/\s+$/, ''))
  }
  return out.join('\n')
}

function unquote(s: string): string {
  return s
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')
}

/** The rows of the first HTML table in `html` (pandas' DataFrame display), its header row first; [] for none. */
export function htmlTable(html: string): string[][] {
  const table = /<table[\s\S]*?<\/table>/i.exec(html)?.[0]
  if (!table) return []
  const rows: string[][] = []
  const heads: boolean[] = [] // the row's cells are all <th>
  for (const tr of table.matchAll(/<tr[^>]*>([\s\S]*?)<\/tr>/gi)) {
    const found = [...tr[1]!.matchAll(/<(t[dh])[^>]*>([\s\S]*?)<\/\1>/gi)]
    const cells = found.map(m => unquote(m[2]!.replace(/<[^>]+>/g, '')).trim())
    if (cells.length) (rows.push(cells), heads.push(found.every(m => m[1]!.toLowerCase() === 'th')))
  }
  // pandas writes the index's name on a second header row of its own (`<tr><th>name</th><th></th>…`), and the columns'
  // name, when they have one (a crosstab's), in the first cell of the row above it: the index's name heads the first
  // column, and the columns' name goes (bug hunt B23: it headed the index, over an empty row of the index's name)
  if (rows.length > 1 && heads[1] && rows[1]![0] !== '' && rows[1]!.slice(1).every(c => c === '')) rows.splice(0, 2, [rows[1]![0]!, ...rows[0]!.slice(1)])
  return rows
}

function numberOr(s: string): Cell {
  const t = s.replace(/,/g, '')
  return t !== '' && /^-?\d+(\.\d+)?$/.test(t) ? Number(t) : s
}

function frameCard(cell: ThimbleCell, f: Frame): CardData {
  const cols = f.columns ?? []
  const label = f.label && cols.includes(f.label) ? f.label : cols[0] ?? ''
  const shown = (f.view?.columns ?? cols).filter(c => c !== label && cols.includes(c))
  const order = [label, ...shown].filter(Boolean)
  const at = order.map(c => cols.indexOf(c))
  const unnamed = !f.label || /^(index|level_\d+)$/.test(f.label) ? label === f.index : false
  const columns = order.map((c, i) => (i === 0 && unnamed ? '' : c))
  // each number column's format, by the name the table shows it under, as the browser's table formats it
  const formats: Record<string, string> = {}
  order.forEach((c, i) => {
    const spec = f.view?.formats?.[c]
    if (typeof spec === 'string') formats[columns[i]!] = spec
  })
  return { ...blank(cell, 'table'), columns, rows: (f.rows ?? []).map(r => at.map(j => (r[j] ?? null) as Cell)), total: f.total, ...(Object.keys(formats).length ? { formats } : {}) }
}

function vegaRows(spec: VegaLite, root: VegaLite): Record<string, unknown>[] {
  if (Array.isArray(spec.data?.values)) return spec.data!.values!
  const name = spec.data?.name
  const sets = root.datasets ?? spec.datasets ?? {}
  if (name && sets[name]) return sets[name]!
  return []
}

/** The start of the name thimble.chart(..., show=False) gives its own rows (backend kernel_thimble CHART_ROWS_NAME). */
const CHART_ROWS_NAME = 'thimble-chart-'

/** The rows of thimble.chart's own part of a chart the code layered its marks on, wherever that part stands. */
function chartRows(spec: VegaLite): Record<string, unknown>[] | null {
  if (spec.data?.name?.startsWith(CHART_ROWS_NAME) && Array.isArray(spec.data.values)) return spec.data.values
  for (const sub of [...(spec.layer ?? []), ...(spec.hconcat ?? []), ...(spec.vconcat ?? []), ...(spec.concat ?? [])]) {
    const got = chartRows(sub)
    if (got) return got
  }
  return null
}

/** The rows of a chart's table, as the backend reads them (cite._main_part): thimble.chart's own rows (chartRows), else
 *  a part's own rows, else of its layers' or concatenated charts' rows the most, the first on a tie (the marks a
 *  chart's code layers on and a panel of text set beside it take a row or a few, the data many), else its inner
 *  spec's. */
function anyRows(spec: VegaLite, root: VegaLite = spec): Record<string, unknown>[] {
  if (spec === root && !spec.data) {
    const marked = chartRows(spec)
    if (marked?.length) return marked
  }
  const own = vegaRows(spec, root)
  if (own.length) return own
  const parts = [...(spec.layer ?? []), ...(spec.hconcat ?? []), ...(spec.vconcat ?? []), ...(spec.concat ?? []), ...(spec.spec ? [spec.spec] : [])]
  const most = parts.map(sub => anyRows(sub, root)).reduce((a, b) => (b.length > a.length ? b : a), [])
  if (most.length) return most
  const sets = Object.values(root.datasets ?? {})
  return sets.find(s => s.length) ?? []
}

/** A field name as the data's column names it: Vega-Lite reads `.` and `[ ]` in a field as a path into nested data, so a
 *  column whose name holds them is written escaped (Altair writes `revisions linking to jqp\.vercel\.app`); the
 *  rows hold the name unescaped (bug hunt B9: such a bar chart drew as a table). */
export function columnOf(field: string): string {
  return field.replace(/\\(.)/g, '$1')
}

/** The spec with each encoding's field (and a sort's) as the data's column names it (columnOf), in every layer and
 *  part, so a chart matches its fields to its rows' columns. */
function plainFields(spec: VegaLite): VegaLite {
  const enc = (e: Enc | undefined): Enc | undefined => {
    if (!e || typeof e !== 'object') return e
    const sort = e.sort && typeof e.sort === 'object' && !Array.isArray(e.sort) && typeof (e.sort as { field?: unknown }).field === 'string' ? { ...(e.sort as object), field: columnOf((e.sort as { field: string }).field) } : e.sort
    return { ...e, ...(typeof e.field === 'string' ? { field: columnOf(e.field) } : {}), ...(sort !== e.sort ? { sort } : {}) }
  }
  const parts = (xs: VegaLite[] | undefined) => (Array.isArray(xs) ? xs.map(plainFields) : xs)
  return {
    ...spec,
    ...(spec.encoding ? { encoding: Object.fromEntries(Object.entries(spec.encoding).map(([k, e]) => [k, enc(e)])) } : {}),
    ...(spec.layer ? { layer: parts(spec.layer) } : {}),
    ...(spec.hconcat ? { hconcat: parts(spec.hconcat) } : {}),
    ...(spec.vconcat ? { vconcat: parts(spec.vconcat) } : {}),
    ...(spec.concat ? { concat: parts(spec.concat) } : {}),
    ...(spec.spec ? { spec: plainFields(spec.spec) } : {}),
  }
}

function markOf(spec: VegaLite): string {
  return typeof spec.mark === 'string' ? spec.mark : spec.mark?.type ?? ''
}

/** Two values of a field as Vega-Lite orders them: numbers by size, anything else by its words, code point by code
 *  point. */
function ascending(a: unknown, b: unknown): number {
  if (typeof a === 'number' && typeof b === 'number') return a - b
  const x = String(a ?? '')
  const y = String(b ?? '')
  return x < y ? -1 : x > y ? 1 : 0
}

/** A bar chart's rows in the order its label axis sorts them, as Vega-Lite draws them: `sort` on the label's channel is a
 *  channel to sort by (`-y` high to low, `y` low to high), `ascending` or `descending` by the label itself, a list of
 *  labels in order (the others after it, in the data's order), or `{field, op, order}`; null keeps the data's order; with
 *  no sort a label axis runs A to Z. A label's rows stay together, in the data's order. */
export function sortedBars(rows: Record<string, unknown>[], enc: Record<string, Enc | undefined>, channel: string, lab: string): Record<string, unknown>[] {
  const sort = enc[channel]?.sort
  if (sort === null) return rows
  const labels = [...new Set(rows.map(r => String(r[lab] ?? '')))]
  const first = new Map<string, Record<string, unknown>>()
  for (const r of rows) if (!first.has(String(r[lab] ?? ''))) first.set(String(r[lab] ?? ''), r)
  let order: string[]
  if (Array.isArray(sort)) {
    const at = new Map(sort.map((v, i) => [String(v), i]))
    order = labels.map((l, i) => ({ l, i })).sort((a, b) => (at.get(a.l) ?? Infinity) - (at.get(b.l) ?? Infinity) || a.i - b.i).map(x => x.l)
  } else {
    // what each label is sorted by, and which way
    let field = lab
    let op = ''
    let desc = false
    if (typeof sort === 'string') {
      desc = sort.startsWith('-') || sort === 'descending'
      const name = sort.replace(/^-/, '')
      if (name !== 'ascending' && name !== 'descending') field = enc[name]?.field ?? lab
    } else if (sort && typeof sort === 'object') {
      const o = sort as { field?: unknown; op?: unknown; order?: unknown; encoding?: unknown }
      field = typeof o.encoding === 'string' ? enc[o.encoding]?.field ?? lab : typeof o.field === 'string' ? o.field : lab
      op = typeof o.op === 'string' ? o.op : ''
      desc = o.order === 'descending'
    }
    const key = (l: string): unknown => {
      const mine = rows.filter(r => String(r[lab] ?? '') === l)
      if (op === 'count') return mine.length
      if (field === lab) return first.get(l)?.[lab]
      // a number field summed over the label's rows (its bars stacked), as Vega-Lite's default op does
      const nums = mine.map(r => r[field]).filter((v): v is number => typeof v === 'number')
      return nums.length === mine.length && nums.length ? nums.reduce((a, b) => a + b, 0) : mine[0]?.[field]
    }
    const keys = new Map(labels.map(l => [l, key(l)]))
    order = labels.map((l, i) => ({ l, i })).sort((a, b) => (desc ? -1 : 1) * ascending(keys.get(a.l), keys.get(b.l)) || a.i - b.i).map(x => x.l)
  }
  const rank = new Map(order.map((l, i) => [l, i]))
  return rows.map((r, i) => ({ r, i })).sort((a, b) => rank.get(String(a.r[lab] ?? ''))! - rank.get(String(b.r[lab] ?? ''))! || a.i - b.i).map(x => x.r)
}

/** A grouped bar chart's rows (sortedBars' order, a label's rows together) with each label's bars in the order the
 *  offset channel sets them side by side, as Vega-Lite draws them: its `sort` (else the color's, on the same field),
 *  else A to Z. */
function sideBySide(rows: Record<string, unknown>[], enc: Record<string, Enc | undefined>, channel: string, field: string, lab: string): Record<string, unknown>[] {
  const own = enc[channel]?.field === field && enc[channel]?.sort !== undefined
  const by = own || enc.color?.field !== field ? channel : 'color'
  const groups = [...new Set(sortedBars(rows, { ...enc, [by]: { ...enc[by], field } }, by, field).map(r => String(r[field] ?? '')))]
  const rank = new Map(groups.map((g, i) => [g, i]))
  const labels = new Map<string, number>()
  for (const r of rows) if (!labels.has(String(r[lab] ?? ''))) labels.set(String(r[lab] ?? ''), labels.size)
  const key = (r: Record<string, unknown>) => [labels.get(String(r[lab] ?? ''))!, rank.get(String(r[field] ?? ''))!]
  return rows.map((r, i) => ({ r, i, k: key(r) })).sort((a, b) => a.k[0]! - b.k[0]! || a.k[1]! - b.k[1]! || a.i - b.i).map(x => x.r)
}

/** The bar layer of a chart whose other layers write the bars' values on them (Altair's `bars + bars.mark_text()`: a
 *  text mark on the same x and y), each layer with the encoding and the data it takes from the chart; else null. */
function labeledBars(spec: VegaLite): VegaLite | null {
  const layers = (spec.layer ?? []).map(l => ({ ...l, encoding: { ...spec.encoding, ...l.encoding } }))
  const bars = layers.filter(l => markOf(l) === 'bar')
  if (bars.length !== 1 || layers.some(l => markOf(l) !== 'bar' && markOf(l) !== 'text')) return null
  const bar = bars[0]!
  const same = layers.every(l => l === bar || (l.encoding.x?.field === bar.encoding.x?.field && l.encoding.y?.field === bar.encoding.y?.field && !l.layer))
  return same ? { ...bar, data: bar.data ?? spec.data, datasets: { ...spec.datasets, ...bar.datasets } } : null
}

/** The fields of a chart's `detail` channel, one definition or a list of them. */
function detailFields(d: unknown): string[] {
  return (Array.isArray(d) ? d : [d]).flatMap(e => (e && typeof e === 'object' && typeof (e as Enc).field === 'string' ? [columnOf((e as Enc).field!)] : []))
}

/** The points a line card keeps at most, over its series and its panels' series. A card's drawing data goes to Claude
 *  Code with the card, which draws at most 100,000 characters of one reply's tree and cuts every row after them, so a
 *  chart of 33 lines of 480 points each drew as an empty box and took the cards and words after it with it (bug hunt
 *  K2). A thousand points draw any line the terminal's few hundred dots across can show. */
export const MAX_LINE_POINTS = 1000

/** A point's x as a number to put points in order by: a number, a time's instant; NaN for any other. */
function xOrder(x: string | number): number {
  return typeof x === 'number' ? x : /^\d{4}-\d{2}-\d{2}/.test(x) ? Date.parse(x) : NaN
}

/** At most `n` of a line's points, in x order, its shape kept: its first and its last, and in each of as many runs of its
 *  points as fit, the lowest and the highest. A line whose x values are not numbers or times keeps its order. */
function thinLine(points: [string | number, number][], n: number): [string | number, number][] {
  if (points.length <= n) return points
  const keys = points.map(p => xOrder(p[0]))
  const sorted = keys.every(k => !Number.isNaN(k)) ? points.map((p, i) => ({ p, k: keys[i]! })).sort((a, b) => a.k - b.k).map(x => x.p) : points
  const keep = new Set([0, sorted.length - 1])
  const runs = Math.max(1, Math.floor((n - 2) / 2))
  const inner = sorted.length - 2
  for (let b = 0; b < runs; b++) {
    const [i0, i1] = [1 + Math.floor((b * inner) / runs), 1 + Math.floor(((b + 1) * inner) / runs)]
    let lo = -1
    let hi = -1
    for (let i = i0; i < i1; i++) {
      if (lo < 0 || sorted[i]![1] < sorted[lo]![1]) lo = i
      if (hi < 0 || sorted[i]![1] > sorted[hi]![1]) hi = i
    }
    if (lo >= 0) keep.add(lo).add(hi)
  }
  return sorted.filter((_, i) => keep.has(i))
}

/** A line card (or a panels card of line cards) with at most about MAX_LINE_POINTS points: each line keeps its share of
 *  them, at least 8 (thinLine); a stack keeps the same x values in each of its bands, every so many of them and its
 *  last, so its bands still stack. Any other card as it is. */
export function thinLines(card: CardData, max = MAX_LINE_POINTS): CardData {
  const lines = card.kind === 'panels' ? (card.panels ?? []).map(p => p.card) : [card]
  const total = lines.reduce((a, c) => a + (c.kind === 'line' ? (c.series ?? []).reduce((b, s) => b + s.points.length, 0) : 0), 0)
  if (total <= max) return card
  const thin = (c: CardData): CardData => {
    if (c.kind !== 'line' || !c.series) return c
    if (c.stack) {
      const xs = [...new Set(c.series.flatMap(s => s.points.map(p => String(p[0]))))]
      const every = Math.ceil(total / max)
      const kept = new Set(xs.filter((_, i) => i % every === 0 || i === xs.length - 1))
      return { ...c, series: c.series.map(s => ({ ...s, points: s.points.filter(p => kept.has(String(p[0]))) })) }
    }
    return { ...c, series: c.series.map(s => ({ ...s, points: thinLine(s.points, Math.max(8, Math.floor((s.points.length * max) / total))) })) }
  }
  return card.kind === 'panels' ? { ...card, panels: (card.panels ?? []).map(p => ({ ...p, card: thin(p.card) })) } : thin(card)
}

/** A one-layer bar or line chart as a bar or line card, a bar chart with its values written on its bars too; null for
 *  any other chart. */
export function chartCard(cell: ThimbleCell, spec: VegaLite): CardData | null {
  if (spec.layer && !spec.facet) {
    const bars = labeledBars(spec)
    return bars ? chartCard(cell, bars) : null
  }
  if (spec.layer || spec.facet || spec.hconcat || spec.vconcat || spec.concat || spec.spec) return null
  const mark = markOf(spec)
  const x = spec.encoding?.x
  const y = spec.encoding?.y
  const color = spec.encoding?.color
  if (!x?.field || !y?.field || x.aggregate || y.aggregate) return null
  const rows = vegaRows(spec, spec)
  // an axis whose field the chart computes (a ridgeline's places) is in no row: the rows' table draws instead
  const xf = x.field
  const yf = y.field
  if (!rows.some(r => xf in r && yf in r)) return null
  if (mark === 'bar') {
    // the quantitative axis is the value, the other the label
    const horizontal = x.type === 'quantitative' && y.type !== 'quantitative'
    const [lab, val] = horizontal ? [y.field, x.field] : [x.field, y.field]
    const enc = spec.encoding ?? {}
    // a label's bars side by side, each from 0 (bug hunt L1: Altair's `xOffset`, thimble.chart's stack=False, drew as one
    // stacked bar per label): an offset channel across the labels' axis, or a value axis told not to stack
    const offset = enc[horizontal ? 'yOffset' : 'xOffset']?.field ?? ''
    const unstacked = (horizontal ? x : y).stack === null || (horizontal ? x : y).stack === false
    const gf = color?.field ?? offset
    const grouped = Boolean(gf) && (Boolean(offset) || unstacked)
    // in the order the label axis sorts them (its `sort`, else A to Z), as the browser draws them
    let sorted = sortedBars(rows, enc, horizontal ? 'y' : 'x', lab)
    if (grouped) sorted = sideBySide(sorted, enc, horizontal ? 'yOffset' : 'xOffset', offset || gf, lab)
    const bars: BarRow[] = sorted.map(r => ({ label: String(r[lab] ?? ''), value: Number(r[val] ?? 0), group: gf ? String(r[gf] ?? '') : '' }))
    if (bars.some(b => !Number.isFinite(b.value))) return null
    return { ...blank(cell, 'bar'), x: lab, y: val, rows: bars, ...(grouped ? { grouped: true } : {}) }
  }
  // a dots chart's rows are names down its y axis, which no line card draws: its rows' table instead
  if ((mark === 'line' || mark === 'point' || mark === 'area' || mark === 'circle') && y.type !== 'nominal' && y.type !== 'ordinal') {
    // the series in the order the color field's own list gives (its legend's), else as the rows first name them
    const by = new Map<string, [string | number, number][]>()
    const ordered = color?.field && Array.isArray(color.sort) ? sortedBars(rows, spec.encoding ?? {}, 'color', color.field) : rows
    // a `detail` field splits the rows into a line per value, each in its color value's hue (Altair's
    // `detail='transcript:N'` beside `color='agent:N'`; bug hunt K2: 33 lines drew as three lines zigzagging across them)
    const details = detailFields(spec.encoding?.detail)
    const hueOf = (r: Record<string, unknown>) => (color?.field ? String(r[color.field] ?? '') : '')
    const lineOf = (r: Record<string, unknown>) => details.map(f => String(r[f] ?? '')).join(' ')
    for (const r of ordered) {
      const s = details.length ? `${hueOf(r)}\u0000${lineOf(r)}` : color?.field ? hueOf(r) : y.field
      const xv = r[x.field]
      by.set(s, [...(by.get(s) ?? []), [typeof xv === 'number' ? xv : String(xv ?? ''), Number(r[y.field] ?? 0)]])
    }
    const xTicks = axisValues(x)
    if (details.length) {
      // each line by its detail value, and by its color value too where one detail value has lines of two colors
      const keys = [...by.keys()].map(k => k.split('\u0000') as [string, string])
      const twice = new Set(keys.map(k => k[1]).filter((d, i, all) => all.indexOf(d) !== i))
      const series = [...by].map(([k, points], i) => {
        const [group, line] = keys[i]!
        return { name: twice.has(line) && group ? `${group} ${line}` : line, group, points }
      })
      const hues = color?.field ? [...new Set(keys.map(k => k[0]))] : []
      return { ...blank(cell, 'line'), x: x.field, y: y.field, series, ...(hues.length ? { hues } : {}), ...(xTicks.length ? { xTicks } : {}) }
    }
    const series = [...by].map(([name, points]) => ({ name, points }))
    // an area chart of several series stacks them, as Vega-Lite does unless its y says not to: by its `order` field,
    // else by the series' names, the first lowest; `normalize` stacks each x to the whole (bug hunt J10)
    const stacked = mark === 'area' && Boolean(color?.field) && by.size > 1 && y.stack !== null && y.stack !== false
    if (stacked) {
      const of = spec.encoding?.order?.field
      const key = (name: string) => {
        const vs = rows.filter(r => String(r[color!.field!] ?? '') === name).map(r => r[of ?? ''])
        return of && vs.length && vs.every(v => typeof v === 'number') ? Math.min(...(vs as number[])) : name
      }
      const keys = new Map(series.map(s => [s.name, key(s.name)]))
      const hues = series.map(s => s.name)
      series.sort((a, b) => ascending(keys.get(a.name), keys.get(b.name)))
      return { ...blank(cell, 'line'), x: x.field, y: y.field, series, stack: y.stack === 'normalize' ? 'share' : 'zero', hues, ...(xTicks.length ? { xTicks } : {}) }
    }
    return { ...blank(cell, 'line'), x: x.field, y: y.field, series, ...(xTicks.length ? { xTicks } : {}) }
  }
  return null
}

/** A chart of bars or rules from a start to an end (Altair's `mark_bar` or `mark_rule` with `x` and `x2` along times or
 *  numbers and its rows' names down `y`, a Gantt chart; or the same on its side, `y` and `y2`), alone or with a dot at
 *  each end (thimble.chart's range), as a dots card whose rows hold spans: each row's spans on one axis over their starts
 *  and ends, colored by the chart's color field, in the order the names' axis sorts them (bug hunt C9: it drew as a
 *  table of raw ISO times). A span with dots at its ends is marked `ends`, and the card names its end field (`x2`). A
 *  time written as a number is the instant it counts in ms, as Vega-Lite reads one. Null for any other chart. */
export function spansCard(cell: ThimbleCell, spec: VegaLite): CardData | null {
  if (spec.facet || spec.hconcat || spec.vconcat || spec.concat || spec.spec) return null
  const layers = (spec.layer ?? [spec]).map(l => ({ ...l, encoding: { ...(spec.layer ? spec.encoding : {}), ...l.encoding }, data: l.data ?? spec.data }))
  if (layers.some(l => l.layer || l.facet || l.hconcat || l.vconcat || l.concat || l.spec)) return null
  const along = (e: Enc | undefined) => Boolean(e?.field) && !e!.aggregate && (e!.type === 'temporal' || e!.type === 'quantitative')
  const discrete = (e: Enc | undefined) => Boolean(e?.field) && (e!.type === 'nominal' || e!.type === 'ordinal')
  const chOf = (enc: Record<string, Enc | undefined>) =>
    enc.x2?.field && along(enc.x) && discrete(enc.y) ? (['x', 'x2', 'y'] as const) : enc.y2?.field && along(enc.y) && discrete(enc.x) ? (['y', 'y2', 'x'] as const) : null
  // the one layer of bars or rules from a start to an end (bug hunt L2: thimble.chart's range, a rule with a dot at each
  // end, drew as the dots at its starts alone)
  const spans = layers.filter(l => SPAN_MARKS.has(markOf(l)) && chOf(l.encoding))
  if (spans.length !== 1) return null
  const span = spans[0]!
  const enc = span.encoding
  const [a, a2, d] = chOf(enc)!
  const from = enc[a]!.field!
  const to = enc[a2]!.field!
  const name = enc[d]!.field!
  // its other layers: dots on its rows at its starts or ends (a dumbbell's), and rules across the chart (a mark's);
  // a chart of any other layer is no start-to-end chart
  const others = layers.filter(l => l !== span)
  const ends = others.filter(l => DOT_MARKS.has(markOf(l)) && l.encoding[d]?.field === name && [from, to].includes(l.encoding[a]?.field ?? ''))
  if (!others.every(l => ends.includes(l) || (markOf(l) === 'rule' && !l.encoding[d]?.field))) return null
  const time = enc[a]!.type === 'temporal'
  // the color field: the span's own, else its ends' (thimble.chart's range colors its ends and leaves its line muted)
  const color = [enc, ...ends.map(l => l.encoding)].map(e => e.color?.field).find(f => f && f !== name) ?? ''
  // a value along the axis: a time as written, or a number (a time's ms as its ISO time); '' for none
  const at = (v: unknown): string | number => (typeof v === 'number' && Number.isFinite(v) ? (time ? new Date(v).toISOString() : v) : typeof v === 'string' && v.trim() ? v : '')
  const rows = sortedBars(vegaRows(span, spec).filter(r => at(r[from]) !== '' && at(r[to]) !== ''), enc, d, name)
  if (!rows.length) return null
  const strips = new Map<string, DotRow>()
  for (const r of rows) {
    const key = String(r[name] ?? '')
    const row = strips.get(key) ?? strips.set(key, { name: key, dots: [], notes: [] }).get(key)!
    row.dots.push({ x: at(r[from]), x2: at(r[to]), group: color ? String(r[color] ?? '') : '', ...(ends.length ? { ends: true } : {}) })
  }
  return { ...blank(cell, 'dots'), x: from, y: name, strips: [...strips.values()], ...(ends.length ? { x2: to } : {}) }
}

// the marks a start-to-end chart draws its spans with, and those a dots chart draws its dots with
const SPAN_MARKS = new Set(['bar', 'rule'])
const DOT_MARKS = new Set(['point', 'circle', 'square', 'tick'])

/** A dots chart (thimble.chart("dots"), or any chart of dots along rows: x numbers or times, y the rows' names) as a
 *  dots card: each row's dots, in the order its axis sorts the rows, colored by the chart's color field, with the words
 *  a text layer on the same x and y writes beside them (bug hunt B15: the rows' table drew 281 raw rows, and the agents
 *  a text layer named never showed). Its other layers may be dots no one sees (a tooltip's, opacity 0) and rules (an
 *  interval's, a mark's); null for any other chart, which draws as its rows' table. */
export function dotsCard(cell: ThimbleCell, spec: VegaLite): CardData | null {
  if (spec.facet || spec.hconcat || spec.vconcat || spec.concat || spec.spec) return null
  const layers = (spec.layer ?? [spec]).map(l => ({ ...l, encoding: { ...(spec.layer ? spec.encoding : {}), ...l.encoding }, data: l.data ?? spec.data }))
  if (layers.some(l => l.layer || l.facet || l.hconcat || l.vconcat || l.concat || l.spec)) return null
  if (!layers.every(l => DOT_MARKS.has(markOf(l)) || markOf(l) === 'text' || markOf(l) === 'rule')) return null
  const rowsOf = (l: VegaLite) => vegaRows(l, spec)
  const seen = (l: VegaLite) => typeof l.mark !== 'object' || l.mark.opacity !== 0
  const discrete = (e: Enc | undefined) => Boolean(e?.field) && (e!.type === 'nominal' || e!.type === 'ordinal')
  const along = (e: Enc | undefined) => Boolean(e?.field) && !e!.aggregate && (e!.type === 'quantitative' || e!.type === 'temporal')
  // the dots: thimble.chart's own layer, else the seen dot layer with the most rows; rows down y, values along x
  const shaped = layers.filter(l => DOT_MARKS.has(markOf(l)) && seen(l) && discrete(l.encoding.y) && along(l.encoding.x) && rowsOf(l).length)
  const dots = shaped.find(l => l.data?.name?.startsWith(CHART_ROWS_NAME)) ?? shaped.reduce<(typeof shaped)[number] | null>((a, b) => (!a || rowsOf(b).length > rowsOf(a).length ? b : a), null)
  if (!dots) return null
  const enc = dots.encoding
  const xf = enc.x!.field!
  const yf = enc.y!.field!
  const gf = enc.color?.field && enc.color.field !== yf ? enc.color.field : ''
  const valued = (r: Record<string, unknown>) => (typeof r[xf] === 'number' && Number.isFinite(r[xf])) || (typeof r[xf] === 'string' && r[xf] !== '')
  const rows = sortedBars(rowsOf(dots).filter(valued), enc, 'y', yf)
  if (!rows.length) return null
  const strips = new Map<string, DotRow>()
  const strip = (name: string) => strips.get(name) ?? strips.set(name, { name, dots: [], notes: [] }).get(name)!
  for (const r of rows) strip(String(r[yf] ?? '')).dots.push({ x: r[xf] as number | string, group: gf ? String(r[gf] ?? '') : '' })
  // the words each text layer on the dots' x and y writes, beside the dots of their row
  for (const l of layers) {
    const t = l.encoding.text?.field
    if (markOf(l) !== 'text' || !t || l.encoding.x?.field !== xf || l.encoding.y?.field !== yf) continue
    for (const r of rowsOf(l)) {
      const words = r[t] === null || r[t] === undefined ? '' : String(r[t]).trim()
      const row = strips.get(String(r[yf] ?? ''))
      if (words && row && valued(r)) row.notes.push({ x: r[xf] as number | string, text: words })
    }
  }
  return { ...blank(cell, 'dots'), x: xf, y: yf, strips: [...strips.values()] }
}

// the marks a heatmap draws its cells with
const CELL_MARKS = new Set(['rect', 'square'])

/** The scale a chart's color takes its numbers by, when it is not linear: Vega-Lite's `log`, `symlog` (with its
 *  `constant`, 1 by default), `sqrt` and `pow` (with its `exponent`); undefined for a linear scale or any other. */
function colorScale(enc: Enc): HeatScale | undefined {
  const sc = enc.scale && typeof enc.scale === 'object' ? enc.scale : null
  const type = sc?.type
  const num = (v: unknown, d: number) => (typeof v === 'number' && Number.isFinite(v) && v > 0 ? v : d)
  if (type === 'log' || type === 'sqrt') return { type }
  if (type === 'symlog') return { type, constant: num(sc?.constant, 1) }
  if (type === 'pow') return { type, exponent: num(sc?.exponent, 1) }
  return undefined
}

/** A text layer's value as the chart writes it on its mark: a number as the mod writes a count (amount), or in percent
 *  where its format says so (`.0%`); words as they are. */
function textWord(v: unknown, format: unknown): string | null {
  if (v === null || v === undefined) return null
  if (typeof v === 'number' && Number.isFinite(v)) {
    const pct = typeof format === 'string' ? /\.(\d+)%$|%$/.exec(format) : null
    return pct ? `${(v * 100).toFixed(pct[1] ? Number(pct[1]) : 0)}%` : amount(v)
  }
  const s = String(v).trim()
  return s || null
}

/** A heatmap (thimble.chart("heatmap"), or any chart of rect marks on two discrete axes colored by a number) as a heat
 *  card: its x values across, its y values down, each in the order its axis sorts them, and each cell's number; the
 *  scale its color takes the numbers by (log, symlog, sqrt, pow), its color's title, and the words a text layer on the
 *  same x and y writes on each cell (bug hunt K1: a log heatmap drew on a linear scale, its numbers left out). Null for
 *  any other chart, and for one whose cells have no number (bug hunt J10: a heatmap of 110 cells drew as 110 rows of a
 *  table). `index` is each row's place in the chart's own rows, when these are a panel's part of them, so a mark cites
 *  the row it shows. */
export function heatCard(cell: ThimbleCell, spec: VegaLite, index?: Map<Record<string, unknown>, number>): CardData | null {
  if (spec.facet || spec.hconcat || spec.vconcat || spec.concat || spec.spec) return null
  const layers = (spec.layer ?? [spec]).map(l => ({ ...l, encoding: { ...(spec.layer ? spec.encoding : {}), ...l.encoding }, data: l.data ?? spec.data }))
  if (layers.some(l => l.layer || l.facet || l.hconcat || l.vconcat || l.concat || l.spec)) return null
  if (!layers.every(l => CELL_MARKS.has(markOf(l)) || markOf(l) === 'text')) return null
  const cells = layers.filter(l => CELL_MARKS.has(markOf(l)))
  if (cells.length !== 1) return null
  const enc = cells[0]!.encoding
  const discrete = (e: Enc | undefined) => Boolean(e?.field) && !e!.aggregate && (e!.type === 'nominal' || e!.type === 'ordinal')
  const color = enc.color
  if (!discrete(enc.x) || !discrete(enc.y) || !color?.field || color.aggregate || color.type !== 'quantitative') return null
  const xf = enc.x!.field!
  const yf = enc.y!.field!
  const vf = color.field
  const rows = vegaRows(cells[0]!, spec).filter(r => xf in r && yf in r)
  if (!rows.length) return null
  const order = (ch: string, f: string) => [...new Set(sortedBars(rows, enc, ch, f).map(r => String(r[f] ?? '')))]
  const xs = order('x', xf)
  const ys = order('y', yf)
  const v: (number | null)[][] = ys.map(() => xs.map(() => null))
  const at: (number | null)[][] = ys.map(() => xs.map(() => null))
  rows.forEach((r, i) => {
    const n = r[vf]
    const value = typeof n === 'number' && Number.isFinite(n) ? n : typeof n === 'string' && n.trim() !== '' && Number.isFinite(Number(n)) ? Number(n) : null
    if (value === null) return
    const yi = ys.indexOf(String(r[yf] ?? ''))
    const xi = xs.indexOf(String(r[xf] ?? ''))
    v[yi]![xi] = value
    at[yi]![xi] = index?.get(r) ?? i
  })
  if (v.every(row => row.every(n => n === null))) return null
  // the words a text layer on the cells' x and y writes on each cell, where it writes some
  const said = layers.find(l => markOf(l) === 'text' && l.encoding.text?.field && l.encoding.x?.field === xf && l.encoding.y?.field === yf)
  let words: (string | null)[][] | undefined
  if (said) {
    const tf = said.encoding.text!.field!
    const w: (string | null)[][] = ys.map(() => xs.map(() => null))
    for (const r of vegaRows(said, spec)) {
      const yi = ys.indexOf(String(r[yf] ?? ''))
      const xi = xs.indexOf(String(r[xf] ?? ''))
      if (yi >= 0 && xi >= 0) w[yi]![xi] = textWord(r[tf], said.encoding.text!.format)
    }
    if (w.some(row => row.some(x => x !== null))) words = w
  }
  const scale = colorScale(color)
  const title = typeof color.title === 'string' && color.title.trim() ? color.title.trim() : undefined
  return { ...blank(cell, 'heat'), x: xf, y: yf, grid: { xs, ys, v, at, name: vf, ...(scale ? { scale } : {}), ...(title ? { title } : {}), ...(words ? { words } : {}) } }
}

/** The fields a faceted chart's panels split its rows by, and the chart each panel draws: Vega-Lite's facet operator
 *  (`{facet: {row, column}, spec}`, Altair's `.facet(column=…)`; or `{facet: field, columns, spec}`, a wrapped facet),
 *  or a chart with a `row`, `column` or `facet` channel (thimble.chart's `panels`). Null for a chart of no panels. */
function facetParts(spec: VegaLite): { inner: VegaLite; by: { field: string; def: Enc }[] } | null {
  const named = (d: unknown): d is Enc & { field: string } => Boolean(d) && typeof d === 'object' && typeof (d as Enc).field === 'string'
  if (spec.facet && spec.spec) {
    const f = spec.facet as Record<string, unknown>
    const by = named(f) ? [f] : [f.row, f.column].filter(named)
    return by.length ? { inner: spec.spec, by: by.map(d => ({ field: d.field, def: d })) } : null
  }
  const enc = spec.encoding ?? {}
  const by = (['row', 'column', 'facet'] as const).map(ch => enc[ch]).filter(named)
  if (!by.length || spec.facet || spec.spec) return null
  const rest = Object.fromEntries(Object.entries(enc).filter(([ch]) => ch !== 'row' && ch !== 'column' && ch !== 'facet'))
  return { inner: { ...spec, encoding: rest }, by: by.map(d => ({ field: d.field, def: d })) }
}

/** The card a chart draws as with its rows: a start-to-end chart, a simple bar or line chart, a dots chart or a
 *  heatmap; null for any other. */
function pictureCard(cell: ThimbleCell, spec: VegaLite, index?: Map<Record<string, unknown>, number>): CardData | null {
  return spansCard(cell, spec) ?? chartCard(cell, spec) ?? dotsCard(cell, spec) ?? heatCard(cell, spec, index)
}

// the panels a faceted chart draws at most; the others are counted under them
const MAX_PANELS = 12

/** A faceted chart (facetParts) as a panels card: the chart of each panel as its own card (pictureCard), the panels in
 *  the order their fields sort them, each named by its values; null when the panels' chart has no picture, which then
 *  draws as its rows' table or a note (bug hunt J10: three charts faceted by model drew as 636, 1,159 and 45 rows).
 *  Every panel takes its marks' order from the chart over all the rows, as the browser shares one scale between
 *  panels: a bar card's labels (each panel lists every label, so panels side by side line up), a heatmap's rows and
 *  columns, and the color field's values (`hues`), so a value has one color in every panel. */
export function facetCard(cell: ThimbleCell, spec: VegaLite): CardData | null {
  const parts = facetParts(spec)
  if (!parts) return null
  const rows = vegaRows(spec, spec)
  if (!rows.length) return null
  const index = new Map(rows.map((r, i) => [r, i]))
  const inner: VegaLite = { ...parts.inner, data: { values: rows } }
  delete inner.datasets
  const whole = pictureCard(cell, inner, index)
  if (!whole) return null
  // each panel's values: every combination of the fields' values, in each field's order, that holds rows
  const keyOf = (r: Record<string, unknown>) => parts.by.map(b => String(r[b.field] ?? '')).join('\u0000')
  const orders = parts.by.map(b => [...new Set(sortedBars(rows, { f: b.def }, 'f', b.field).map(r => String(r[b.field] ?? '')))])
  const combos = orders.reduce<string[][]>((acc, vals) => acc.flatMap(a => vals.map(v => [...a, v])), [[]])
  const groups = new Map<string, Record<string, unknown>[]>()
  for (const r of rows) groups.set(keyOf(r), [...(groups.get(keyOf(r)) ?? []), r])
  // the color field's values in the whole chart's order, which every panel colors by
  const hues =
    whole.hues ??
    (whole.kind === 'line' && (whole.series ?? []).length > 1 && !(whole.series ?? []).some(s => s.group !== undefined)
      ? (whole.series ?? []).map(s => s.name)
      : whole.kind === 'bar'
        ? [...new Set((whole.rows as BarRow[]).map(r => r.group).filter(Boolean))]
        : whole.kind === 'dots'
          ? [...new Set((whole.strips ?? []).flatMap(s => s.dots.map(d => d.group)).filter(Boolean))]
          : [])
  const labels = whole.kind === 'bar' ? [...new Set((whole.rows as BarRow[]).map(r => r.label))] : []
  const panels: Panel[] = []
  let more = 0
  for (const combo of combos) {
    const mine = groups.get(combo.join('\u0000'))
    if (!mine?.length) continue
    if (panels.length >= MAX_PANELS) {
      more++
      continue
    }
    let card = pictureCard(cell, { ...inner, data: { values: mine } }, index)
    if (!card || card.kind !== whole.kind) continue
    if (card.kind === 'bar') {
      // every label of the whole chart, in its order, a label this panel has no row of at 0
      const own = card.rows as BarRow[]
      card = { ...card, rows: labels.flatMap(l => (own.some(r => r.label === l) ? own.filter(r => r.label === l) : [{ label: l, value: 0, group: '' }])) }
    }
    if (card.kind === 'heat' && card.grid && whole.grid) {
      const g = card.grid
      const all = whole.grid
      const pick = <T,>(m: (T | null)[][]): (T | null)[][] => all.ys.map(y => all.xs.map(x => (g.ys.includes(y) && g.xs.includes(x) ? m[g.ys.indexOf(y)]![g.xs.indexOf(x)]! : null)))
      card = { ...card, grid: { ...g, xs: all.xs, ys: all.ys, v: pick(g.v), at: pick(g.at), ...(g.words ? { words: pick(g.words) } : {}) } }
    }
    panels.push({ title: combo.join(' · '), card: { ...card, ...(hues.length ? { hues } : {}) } })
  }
  if (!panels.length) return null
  const free = spec.resolve?.scale ?? {}
  const own = (['x', 'y'] as const).filter(ch => free[ch] === 'independent')
  return { ...blank(cell, 'panels'), x: whole.x, y: whole.y, panels, ...(hues.length ? { hues } : {}), ...(own.length ? { own } : {}), ...(more ? { total: panels.length + more } : {}) }
}

/** The values an axis names itself (Vega-Lite's `axis.values`, which thimble.chart sets at each time of weekly or
 *  monthly data): numbers and text as written, a DateTime as its wall clock written out (`2026-05-18T00:00:00`), as a
 *  row's time is. */
function axisValues(enc: Enc): (string | number)[] {
  const values = enc.axis?.values
  if (!Array.isArray(values)) return []
  const two = (n: unknown) => String(typeof n === 'number' ? n : 0).padStart(2, '0')
  return values.flatMap(v => {
    if (typeof v === 'number' || typeof v === 'string') return [v]
    const d = v as { year?: unknown; month?: unknown; date?: unknown; hours?: unknown; minutes?: unknown; seconds?: unknown } | null
    if (!d || typeof d.year !== 'number' || [d.month, d.date].some(n => n !== undefined && typeof n !== 'number')) return []
    return [`${d.year}-${two(d.month ?? 1)}-${two(d.date ?? 1)}T${two(d.hours)}:${two(d.minutes)}:${two(d.seconds)}`]
  })
}

/** A chart's rows in the order its axes put them where a chart says how (a heatmap's `sort=days`), as the browser
 *  draws them: by the axis of the table's first column, then by the other; each a discrete axis (ordinal or nominal)
 *  with a `sort` of its own. A chart that says no order keeps its data's: its rows are a table, not its picture
 *  (README capture 10-17: a heatmap's days, grouped as text, read `Jul 01, Jul 02, Jun 01`). */
function axisOrder(rows: Record<string, unknown>[], spec: VegaLite): Record<string, unknown>[] {
  const enc = spec.encoding ?? {}
  const columns = rows.length ? Object.keys(rows[0]!) : []
  const axes = (['x', 'y'] as const).filter(ch => {
    const e = enc[ch]
    return e?.field && columns.includes(e.field) && (e.type === 'ordinal' || e.type === 'nominal') && e.sort !== undefined && e.sort !== null
  })
  // the minor axis first: a stable sort by the major one keeps its order within each of the major's values
  return axes
    .sort((a, b) => columns.indexOf(enc[b]!.field!) - columns.indexOf(enc[a]!.field!))
    .reduce((out, ch) => sortedBars(out, enc, ch, enc[ch]!.field!), rows)
}

function rowsTable(cell: ThimbleCell, rows: Record<string, unknown>[]): CardData | null {
  const columns = rows.length ? Object.keys(rows[0]!) : []
  if (!columns.length) return null
  const cellOf = (v: unknown): Cell => (v === null || v === undefined ? null : typeof v === 'object' ? JSON.stringify(v) : (v as Cell))
  return { ...blank(cell, 'table'), columns, rows: rows.map(r => columns.map(c => cellOf(r[c]))), total: rows.length }
}

function diagramOf(cell: ThimbleCell, d: { nodes?: unknown[]; edges?: unknown[] }): CardData {
  const nodes: DiagramNode[] = (d.nodes ?? []).map(n => {
    if (typeof n === 'string') return { id: n, label: n }
    const o = n as { id?: unknown; label?: unknown; name?: unknown; detail?: unknown }
    const id = String(o.id ?? o.name ?? o.label ?? '')
    return { id, label: String(o.label ?? id), ...(typeof o.detail === 'string' && o.detail ? { detail: o.detail } : {}) }
  })
  const edges: DiagramEdge[] = (d.edges ?? []).flatMap(e => {
    const o = (Array.isArray(e) ? { source: e[0], target: e[1], label: e[2] } : e) as { source?: unknown; target?: unknown; from?: unknown; to?: unknown; label?: unknown }
    const source = o.source ?? o.from
    const target = o.target ?? o.to
    if (source === undefined || target === undefined) return []
    return [{ source: String(source), target: String(target), ...(o.label !== undefined && o.label !== null && String(o.label) ? { label: String(o.label) } : {}) }]
  })
  // a node an edge names but the list leaves out is drawn by its name
  const known = new Set(nodes.map(n => n.id))
  for (const e of edges) for (const id of [e.source, e.target]) if (!known.has(id)) (known.add(id), nodes.push({ id, label: id }))
  return { ...blank(cell, 'diagram'), nodes, edges }
}

function timelineOf(cell: ThimbleCell, t: { events?: unknown[] }): CardData {
  const events = (t.events ?? []).flatMap(e => {
    const o = (Array.isArray(e) ? { time: e[0], label: e[1] } : e) as { time?: unknown; label?: unknown; ref?: unknown }
    return o.time === undefined ? [] : [{ time: String(o.time), label: String(o.label ?? ''), ref: typeof o.ref === 'string' ? o.ref : '' }]
  })
  return { ...blank(cell, 'timeline'), events }
}

/** HTML as its words: tags dropped, blocks on lines of their own. */
export function htmlText(html: string): string {
  return unquote(
    html
      .replace(/<(script|style)[\s\S]*?<\/\1>/gi, '')
      .replace(/<br\s*\/?>/gi, '\n')
      .replace(/<\/(div|p|h\d|li|tr|section|article)>/gi, '\n')
      .replace(/<[^>]+>/g, ''),
  )
    .split('\n')
    .map(l => l.replace(/\s+/g, ' ').trim())
    .filter(Boolean)
    .join('\n')
}

/** A plan card's steps as the card draws them (draw.ts planLayout; backend notebook.plan_step_of): each step's words,
 *  status, what it makes, its note, and its time, the one the agent gave or, for a step that ended, the time it took. */
export function planSteps(steps: unknown): PlanStep[] {
  const list = Array.isArray(steps) ? steps.filter((s): s is Record<string, unknown> => Boolean(s) && typeof s === 'object') : []
  const took = (s: Record<string, unknown>): string => {
    if (typeof s.time === 'string' && s.time.trim()) return s.time.trim()
    const a = Date.parse(String(s.started ?? '')), b = Date.parse(String(s.ended ?? ''))
    if (Number.isNaN(a) || Number.isNaN(b)) return ''
    const sec = Math.max(0, Math.round((b - a) / 1000))
    if (sec < 60) return `${sec} s`
    if (sec < 3600) return `${Math.floor(sec / 60)} m`
    const h = Math.floor(sec / 3600), m = Math.floor(sec / 60) % 60
    return m ? `${h} h ${m} m` : `${h} h`
  }
  return list.map(s => ({
    text: String(s.text ?? '').replace(/\s+/g, ' ').trim(),
    status: String(s.status ?? '').trim() || 'not started',
    makes: (Array.isArray(s.makes) ? s.makes : s.makes ? [s.makes] : []).map(String).filter(m => m.trim()),
    note: typeof s.note === 'string' ? s.note.trim() : '',
    time: took(s),
  }))
}

/** The card a cell draws as, and the error its last run ended in ('' for none). */
export function cardOfCell(cell: ThimbleCell, label?: ThimbleLabel | null): Drawn {
  const err = first(cell, k => k === ERROR) as { ename?: string; evalue?: string } | undefined
  const error = err ? `${err.ename ?? 'Error'}: ${err.evalue ?? ''}`.trim() : ''
  const kind = cell.kind ?? 'code'
  const payload = cell.payload && typeof cell.payload === 'object' ? cell.payload : null
  if (kind === 'note') return { card: { ...blank(cell, 'note'), note: String(payload?.text ?? cell.text ?? '') }, error }
  if (kind === 'custom') {
    // HTML the terminal cannot draw: its table, else its words (a value and what it means); the card's link opens the
    // whole card in the browser (reply.tsx cardBlock)
    const html = String(payload?.html ?? '')
    const rows = htmlTable(html)
    if (rows.length > 1) return { card: { ...blank(cell, 'table'), columns: rows[0]!, rows: rows.slice(1).map(r => r.map(numberOr)), total: rows.length - 1 }, error }
    return { card: { ...blank(cell, 'note'), note: htmlText(html) }, error }
  }
  if (kind === 'plan') return { card: { ...blank(cell, 'plan'), steps: planSteps(payload?.steps) }, error }
  if (kind === 'example') {
    const refs = Array.isArray(payload?.refs) ? (payload!.refs as unknown[]) : []
    // the words add_card kept beside each ref (`quotes`, one per ref), which the card quotes from its record
    const quotes = Array.isArray(payload?.quotes) ? (payload!.quotes as unknown[]) : []
    const examples: CardExample[] = refs.map((r, i) => {
      const kept = typeof quotes[i] === 'string' ? (quotes[i] as string).trim() : ''
      return typeof r === 'string'
        ? { ref: r.replace(/^\[\[|\]\]$/g, ''), quote: '', note: '', ...(kept ? { kept } : {}) }
        : { ref: String((r as { ref?: unknown }).ref ?? ''), quote: String((r as { quote?: unknown }).quote ?? ''), note: '' }
    })
    return { card: { ...blank(cell, 'example'), examples }, error }
  }
  if (kind === 'label') return { card: labelCard(cell, label ?? null), error }
  if (payload && (kind === 'diagram' || kind === 'timeline')) {
    const ds = (payload.dataset ?? {}) as { nodes?: unknown[]; edges?: unknown[]; events?: unknown[] }
    return { card: kind === 'diagram' ? diagramOf(cell, ds) : timelineOf(cell, ds), error }
  }
  const frame = first(cell, k => k === FRAME) as Frame | undefined
  if (frame?.columns) return { card: frameCard(cell, frame), error }
  const dg = first(cell, k => k === DIAGRAM) as { nodes?: unknown[]; edges?: unknown[] } | undefined
  if (dg?.nodes) return { card: diagramOf(cell, dg), error }
  const tl = first(cell, k => k === TIMELINE) as { events?: unknown[] } | undefined
  if (tl?.events) return { card: timelineOf(cell, tl), error }
  const spec = first(cell, k => k.startsWith('application/vnd.vegalite')) as VegaLite | undefined
  if (spec && typeof spec === 'object') {
    const vl = plainFields(spec)
    const chart = facetCard(cell, vl) ?? pictureCard(cell, vl)
    if (chart) return { card: thinLines(chart), error }
    // a chart the terminal has no picture of: its rows' table while it is short, else a note that the browser draws it
    // (bug hunt J10: never a long table of a chart's rows)
    const rows = anyRows(vl)
    const table = rows.length <= MAX_TABLE_ROWS ? rowsTable(cell, axisOrder(rows, vl)) : null
    if (table) return { card: table, error }
    if (rows.length) return { card: { ...blank(cell, 'note'), note: BROWSER_CHART, browser: true }, error }
  }
  // a card type's card and a figure: the listing they print
  const typed = bundles(cell).find(b => CARD_TYPE in b)
  if (typed) return { card: { ...blank(cell, 'text'), note: asText(typed['text/plain']) || 'a card of a card type: the browser draws it' }, error }
  const html = first(cell, k => k === 'text/html')
  if (typeof html === 'string' || Array.isArray(html)) {
    const rows = htmlTable(asText(html))
    if (rows.length > 1) return { card: { ...blank(cell, 'table'), columns: rows[0]!, rows: rows.slice(1).map(r => r.map(numberOr)), total: rows.length - 1 }, error }
  }
  const text = printed(cell)
  const figure = bundles(cell).some(b => Object.keys(b).some(k => k.startsWith('image/')))
  if (text || error) return { card: { ...blank(cell, 'text'), note: [text, figure ? '(a figure: the browser draws it)' : ''].filter(Boolean).join('\n') || error }, error }
  if (figure) return { card: { ...blank(cell, 'note'), note: 'A figure: the browser draws it.' }, error }
  return { card: { ...blank(cell, 'text'), note: '' }, error }
}

/** A label card: its count per value in the label's order, with the records of the label's rows (each its value, its
 *  words and why, and whether the analyst set it), drawn as a bar card with the label's row. */
export function labelCard(cell: ThimbleCell, label: ThimbleLabel | null): CardData {
  const card = blank(cell, 'label')
  if (!label) return { ...card, kind: 'note', note: 'The label is being read.' }
  // the counts as the label panel and thimble.labels() read the rows: each record the analyst set to another value under
  // that value (live check term-fix6, new quirk 1: the card's bars kept the label's own 33 after a verdict)
  const counts = label.verdicts?.counts ?? label.label_stats?.counts ?? {}
  const values = [...(label.labels ?? []), ...Object.keys(counts).filter(k => !(label.labels ?? []).includes(k))]
  const rows: BarRow[] = values.map(v => ({ label: v, value: counts[v] ?? 0, group: '' }))
  const run = label.last_run ?? label.applications?.at(-1) ?? null
  const labeled = label.label_stats?.n_labeled ?? rows.reduce((a, r) => a + r.value, 0)
  const total = typeof run?.total === 'number' ? run.total : labeled
  const examples: CardExample[] = (label.rows ?? [])
    .filter(r => r.ref)
    .slice(0, 6)
    .map(r => {
      const set = Boolean(r.analyst)
      const value = set && typeof r.analyst === 'string' ? r.analyst : String(r.label ?? '')
      return { ref: r.ref!, quote: String(r.text ?? ''), note: '', value, why: String(r.rationale ?? ''), set, ...(set && r.label && r.label !== value ? { was: String(r.label) } : {}) }
    })
  const paths = run?.paths ?? (label.glob ? label.glob.split(/,\s*/).filter(Boolean) : [])
  const colors = classColors(label.classes)
  const info = { slug: label.id, name: label.name ?? label.id, kind: label.kind ?? '', values, labeled, total, trial: Boolean(label.trial), paths, ...(colors ? { colors } : {}) }
  // a label with no run says so, as home and its panel do, with no bars and no counts (live check term-fix8, quirk 8:
  // the card a stopped thread left showed yes 0, no 0 and all 0); one whose run stopped part way shows the counts it has,
  // and says where it stopped (live check term-fix9, quirk 4; bug hunt H3); one whose run goes on, in any process, shows
  // the counts so far and how far it has read of its own size (`◌ labeling 301 of 4,556`, as the browser counts it: bug
  // hunts I2, I4)
  const st = labelState(label)
  if (st.running) return { ...card, question: card.question || label.name || '', x: 'value', y: label.unit ?? 'record', rows: labeled ? rows : [], total: labeled, examples, note: labelStateWords(st), label: { ...info, total: st.total ?? labeled, ...(label.run?.run_id ? { runId: label.run.run_id } : {}) } }
  if (!run && !st.stopped) return { ...card, question: card.question || label.name || '', x: 'value', y: label.unit ?? 'record', rows: [], examples: [], note: 'not run yet', label: { ...info, total: st.total ?? labeled } }
  if (!run || st.stopped) return { ...card, question: card.question || label.name || '', x: 'value', y: label.unit ?? 'record', rows, total: labeled, examples, note: labelStateWords(st), label: { ...info, total: st.total ?? labeled } }
  return {
    ...card,
    question: card.question || label.name || '',
    x: 'value',
    y: label.unit ?? 'record',
    rows,
    total: labeled,
    examples,
    label: info,
  }
}

/** What thimble's links check left of a card's takeaway (backend verify.py), or undefined when it never ran. */
export function linksOf(cell: ThimbleCell): TermLinks | undefined {
  const l = cell.verification?.links
  if (!l || typeof l !== 'object') return undefined
  const entries = (v: unknown) => (Array.isArray(v) ? v.filter((x): x is Record<string, unknown> => Boolean(x) && typeof x === 'object') : [])
  const key = (x: Record<string, unknown>) => `${x.value === null || x.value === undefined ? '' : String(x.value)}|${String(x.ref ?? '')}`
  // a value the check corrected in place (heal.py `corrected`, `was` what Claude wrote) is right now: not broken
  const corrected = (b: Record<string, unknown>) => b.corrected === true && typeof b.was === 'string'
  const fixed = [
    ...entries(l.broken).filter(corrected).map(b => ({ key: key(b), was: String(b.was), from: '', why: String(b.why ?? '') })),
    // a value re-pointed at the place that shows it (`from` the place Claude cited)
    ...entries(l.resolved).filter(r => typeof r.from === 'string' && r.from && r.from !== r.ref).map(r => ({ key: key(r), was: '', from: String(r.from), why: 'the value stands at another place' })),
  ]
  return {
    pending: l.status === 'pending',
    checked: Boolean(l.checked),
    ok: [...entries(l.resolved).map(key), ...entries(l.broken).filter(corrected).map(key)],
    broken: entries(l.broken).filter(b => !corrected(b)).map(b => ({ key: key(b), why: String(b.why ?? ''), source: b.source === null || b.source === undefined ? '' : String(b.source) })),
    typed: entries(l.typed).map(t => ({ key: key(t), why: String(t.why ?? '') })),
    ...(fixed.length ? { fixed } : {}),
  }
}

/** busyWords' words for a card whose run ended and whose card check waits to start: no run, so the card pane offers
 *  `run again` beside them. */
export const CHECK_WAITS = '◌ checking'

/** The words the card's title row says about it while it is not done: its run waits or runs, or it runs again because
 *  a label it read changed, or its card check waits to start (CHECK_WAITS). */
export function busyWords(cell: ThimbleCell): string {
  const st = cell.run?.state
  if (st === 'waiting') return 'waiting for its run'
  if (st === 'running' || cell.status === 'running' || cell.status === 'queued') return '◌ running'
  if (cell.regenerating_for?.length) return '◌ running again'
  // cardrun's mark that the card's check waits to start (a running check's record is the check's own business)
  if (cell.check === 'pending') return CHECK_WAITS
  return ''
}

/** The card check's latest rewrite of a card that stands (its last `fixes` entry, `applied`): the parts it rewrote and
 *  why; null when it rewrote none. */
export function fixOf(cell: ThimbleCell): { fields: string[]; why: string } | null {
  const fixes = (cell as { fixes?: unknown }).fixes
  const last = Array.isArray(fixes) ? fixes.filter(f => f && typeof f === 'object' && (f as { state?: unknown }).state === 'applied').at(-1) : null
  if (!last) return null
  const f = last as { fields?: unknown; reason?: unknown }
  const fields = Array.isArray(f.fields) ? f.fields.filter((x): x is string => typeof x === 'string') : []
  return fields.length ? { fields, why: typeof f.reason === 'string' ? f.reason.trim() : '' } : null
}

/** How the card's latest check stands: `pending`, `ok`, `fixed`, `error` or `stopped` ('' when none ran), why it
 *  ended in an error or a stop, and `unrun` when it ended so because its revision of the card would not run (a fix of
 *  its own that it recorded `rejected`, backend checkstore.record_rejected). */
export function checkOf(cell: ThimbleCell): { state: string; why: string; unrun: boolean } {
  const c = cell.check
  if (typeof c === 'string') return { state: c, why: '', unrun: false }
  if (!c || typeof c !== 'object') return { state: '', why: '', unrun: false }
  const fixes = (cell as { fixes?: unknown }).fixes
  const unrun = Boolean(c.id) && Array.isArray(fixes) && fixes.some(f => f && typeof f === 'object' && (f as { state?: unknown }).state === 'rejected' && (f as { check?: unknown }).check === c.id)
  return { state: typeof c.status === 'string' ? c.status : '', why: typeof c.reason === 'string' ? c.reason : '', unrun }
}

